import{a as Ye,b as P,c as x,d as H}from"./c-IMWUPVMG.js";import{Ka as V,La as L,l as T}from"./c-OC5VEB3I.js";import{g as b}from"./c-IAOKQHNA.js";import"./c-GLOPYFSS.js";import{a as q}from"./c-4TIYSYRS.js";import{a as R}from"./c-QPIU5F2X.js";import{a as Xe}from"./c-GCNXBE3O.js";import{c as S}from"./c-LV7NOCMP.js";var f=S(Xe(),1);var O={id:"fpc-airway-assessment",domain:"airway",ref:"III.1",title:"Airway assessment: predicting the difficult airway",summary:"Separate the four kinds of difficulty \u2014 laryngoscopy, mask ventilation, supraglottic device and surgical airway \u2014 and add the physiological difficulty that kills more transport patients than anatomy does.",objectives:["Assess for difficult laryngoscopy, bag-mask ventilation, supraglottic airway and cricothyrotomy using structured mnemonics.","Recognise the physiologically difficult airway: hypoxaemia, hypotension, severe acidosis and right-ventricular failure.","Turn an assessment into a plan with a stated backup at every step, before the drugs go in."],sections:[{id:"four",title:"Four different difficulties",core:!0,body:['A "difficult airway" is not one thing. Four separate tasks can be hard, and a patient can be easy for one and impossible for another. Difficult laryngoscopy means you cannot see the glottis. Difficult bag-mask ventilation means you cannot move air with a mask. A difficult supraglottic airway means a rescue device will not seat or seal. A difficult cricothyrotomy means you cannot find or reach the cricothyroid membrane.',"Assess all four, because the plan depends on which ones are threatened. A bearded, edentulous patient with a normal neck may be a poor mask but an easy laryngoscopy. A patient with a radiation-scarred neck may be an easy mask and an easy view but an impossible surgical airway. The most dangerous patient is the one in whom several fail together: the plan has no safe exit.","In transport medicine, add a fifth: the environment. Poor lighting, a patient on the ground or in a wreck, limited access to the head, vibration, noise that defeats auscultation, and a small team all make every task harder. Many programmes prefer to secure an airway before loading rather than in an aircraft cabin where positioning and access are compromised."],table:{caption:"Common mnemonics for the four difficulties",head:["Task","Mnemonic","What it reminds you to look for"],rows:[["Laryngoscopy","LEMON","Look externally, Evaluate 3-3-2, Mallampati, Obstruction or obesity, Neck mobility"],["Bag-mask ventilation","ROMAN","Radiation or restriction, Obstruction / obesity / OSA, Mask seal (beard, trauma), Age over 55, No teeth"],["Supraglottic airway","RODS","Restricted mouth opening, Obstruction at or below the larynx, Distorted airway, Stiff lungs or cervical spine"],["Cricothyrotomy","SMART","Surgery or disruption, Mass (haematoma, abscess), Access or anatomy (obesity, oedema), Radiation, Tumour"]]}},{id:"lemon",title:"Laryngoscopy: LEMON in practice",body:["Look externally first: facial trauma, a short thick neck, a small mandible, large incisors, or the overall gestalt that this will be hard. Gestalt from experienced operators is a useful predictor and should not be dismissed.","The 3-3-2 rule estimates whether the mouth, mandible and larynx line up. Three of the patient's fingerbreadths of mouth opening allow the blade and tube in. Three fingerbreadths from the chin to the hyoid suggest enough mandibular space to displace the tongue into. Two fingerbreadths from the hyoid to the thyroid notch suggest the larynx is not sitting too high.","Mallampati grading needs a cooperative, sitting patient, so in emergency and transport practice it is often unobtainable. Obstruction \u2014 blood, vomit, angioedema, epiglottitis, an expanding haematoma, a foreign body \u2014 and obesity both reduce the view and the time available. Neck mobility matters when you need to extend for direct laryngoscopy; a patient in spinal motion restriction has lost it.","Video laryngoscopy changes the weight of several predictors. A hyperangulated blade sees around a curve that a direct blade cannot, so mouth opening and blood in the airway become the dominant limits rather than mandibular space. Blood and secretions on the camera can turn a good video view into no view at all, which is why suction must be ready before the blade goes in."],list:{caption:"Cormack\u2013Lehane view grades",items:["Grade 1: most of the glottis visible.","Grade 2: posterior glottis or arytenoids only (2a partial cords, 2b arytenoids only).","Grade 3: epiglottis only.","Grade 4: no laryngeal structures, not even the epiglottis."],ordered:!1}},{id:"physiological",title:"The physiologically difficult airway",core:!0,body:["Most peri-intubation deaths in critically ill patients are not caused by failure to place the tube. They are caused by hypoxaemia, hypotension and cardiac arrest around induction. The physiologically difficult airway is the patient in whom the act of intubation \u2014 apnoea, induction drugs and positive pressure \u2014 is itself dangerous.","Hypoxaemia: a patient who starts desaturated, or who has a small or shunted functional residual capacity, will desaturate within seconds of apnoea. Optimise pre-oxygenation, consider non-invasive ventilation to pre-oxygenate, and plan to ventilate gently during the apnoeic period if saturation falls.","Hypotension: induction agents blunt sympathetic tone, and positive pressure reduces venous return. A patient with a shock index above about 0.9, a low systolic pressure, or a high vasopressor requirement may arrest at induction. Resuscitate first where possible: volume or blood for the hypovolaemic, a push-dose or infusion vasopressor ready, and a reduced induction dose of a haemodynamically gentler agent.",'Severe metabolic acidosis: a patient compensating with a minute ventilation of 20 litres or more depends on that ventilation to hold the pH. A period of apnoea and then "normal" ventilator settings can drop the pH sharply and precipitate arrest. Match their pre-intubation minute ventilation on the ventilator and keep apnoea as short as possible.',"Right-ventricular failure: pulmonary hypertension, massive pulmonary embolism and RV infarction leave a ventricle that tolerates neither hypotension nor the rise in afterload from hypoxia, hypercapnia and high intrathoracic pressure. These patients can collapse at induction; avoid hypotension and hypoxia, and use modest tidal volumes and PEEP."],example:{case:"A 64-year-old with septic shock from pneumonia: SpO\u2082 86 % on a non-rebreather, BP 82/48, HR 128, RR 34, pH 7.18. The team wants to intubate before a 40-minute flight.",steps:["Name the threats: hypoxaemia (shunt from pneumonia), hypotension (shock index 1.6), and a compensatory respiratory rate defending an acidotic pH.","Resuscitate before induction: fluid as indicated, start or increase norepinephrine, have a push-dose vasopressor drawn up.","Pre-oxygenate with NIV or high-flow plus a tightly sealed mask, sitting up, for at least three minutes; leave nasal oxygen on for apnoeic oxygenation.","Choose a reduced-dose, haemodynamically stable induction agent and a full-dose paralytic; plan first-pass success with a video laryngoscope and a bougie.","After the tube: set a high minute ventilation to match the patient's own, confirm with waveform capnography, and recheck blood pressure every few minutes."]}},{id:"plan",title:"From assessment to a plan",core:!0,body:["An airway assessment is only useful if it changes what you do. Before induction, state aloud the plan: who intubates, with which device, what the first-attempt backup is (a bougie, a different blade), the rescue oxygenation device (supraglottic airway size chosen and opened), and the point at which the team moves to a surgical airway.","Use a checklist. Challenge-response checklists before rapid sequence intubation reduce omissions \u2014 suction on, pre-oxygenation adequate, drugs drawn and labelled, monitoring with waveform capnography ready, the backup devices in reach, the patient positioned. Checklists are especially valuable in transport, where teams may be small and environments unfamiliar.","If the predicted difficulty is high and the patient is maintaining oxygenation, consider whether the airway needs to be secured now, by you, in this environment. Options include an awake approach with topical anaesthesia and light sedation, delaying until a better setting, or transporting with the patient's own airway and a clear plan for deterioration."],list:{caption:"Positioning before every attempt",items:["Ear to sternal notch: the external auditory meatus level with the sternal notch, face plane parallel to the ceiling.","Head up 20\u201330\xB0 (or reverse Trendelenburg if spinal precautions): improves FRC and view, reduces aspiration.","Ramp the obese patient with blankets under shoulders and head.","Bed or stretcher at the operator's waist height, 360\xB0 access if possible."]}},{id:"aspiration",title:"Aspiration risk and the full stomach",body:["Every emergency patient is treated as having a full stomach. Risk is higher with bowel obstruction, upper GI bleeding, recent food or alcohol, pregnancy, obesity, diabetic gastroparesis, and bag-mask ventilation with high pressures that inflate the stomach.","Reduce it: head-up positioning, gentle mask ventilation (low pressures, low rates) only when needed, decompression of an obviously distended stomach with a gastric tube before induction in high-risk patients, and large-bore suction running and in hand. Cricoid pressure is no longer routine in many guidelines because evidence of benefit is weak and it can worsen the view; if used, release it when it impairs laryngoscopy or ventilation."]}],keyPoints:["Assess four tasks separately: laryngoscopy (LEMON), mask ventilation (ROMAN), supraglottic device (RODS), cricothyrotomy (SMART).","The physiologically difficult airway \u2014 hypoxaemia, hypotension, severe acidosis, RV failure \u2014 causes most peri-intubation arrests.","Resuscitate before you intubate: oxygen, volume or blood, and vasopressors ready.","Match the minute ventilation of a patient compensating for a metabolic acidosis.","State the plan and the backup aloud with a checklist before the drugs go in."],pearls:['A gestalt that "this will be hard" from an experienced operator is a valid predictor.',"Blood and vomit defeat video laryngoscopes: suction before the blade.","Mark the cricothyroid membrane before induction when difficulty is predicted."],pitfalls:["Focusing on anatomy and inducing a hypotensive, hypoxic patient without resuscitation.",'Ventilating an acidotic patient at "normal" settings after intubation.',"Relying on Mallampati in a patient who cannot cooperate."],live:[{id:"pop-apnoea",label:"Apnoea: how long the oxygen lasts"},{id:"abg-resp-vs-metabolic",label:"Respiratory vs metabolic acidosis"}],questions:[{q:"Which finding most predicts difficult bag-mask ventilation?",options:["Mallampati class II","A full beard and no teeth","Thyromental distance of four fingerbreadths","Isolated tibial fracture"],answer:1,why:"Beards and edentulism defeat the mask seal (the M and N of ROMAN)."},{q:'In LEMON, the "3" of the hyoid-to-chin distance assesses:',options:["Mouth opening","Mandibular space to displace the tongue","Laryngeal height","Neck extension"],answer:1,why:"Three fingerbreadths from mentum to hyoid suggests room to compress the tongue into the submandibular space."},{q:"A septic patient with BP 78/40 needs intubation. Which step most reduces the risk of peri-intubation arrest?",options:["Larger induction dose to ensure amnesia","Resuscitation and a vasopressor ready before induction","Delaying pre-oxygenation to save time","Using cricoid pressure"],answer:1,why:"Hypotension is a leading cause of peri-intubation arrest; resuscitate and prepare vasopressors first."},{q:"A DKA patient breathing 36 times a minute (PaCO\u2082 16) is intubated. Best initial ventilator approach?",options:["RR 12, VT 6 mL/kg","Match the pre-intubation minute ventilation","Permissive hypercapnia","Pressure support only"],answer:1,why:"Removing respiratory compensation can drop the pH precipitously; match their minute ventilation."},{q:"Cormack\u2013Lehane grade 3 means:",options:["Full glottis visible","Arytenoids only","Epiglottis only","No structures"],answer:2,why:"Grade 3 is epiglottis only."},{q:"Which mnemonic assesses difficulty placing a supraglottic airway?",options:["LEMON","ROMAN","RODS","SMART"],answer:2,why:"RODS: Restricted opening, Obstruction, Distorted airway, Stiff lungs or spine."},{q:"A neck previously treated with radiation primarily threatens which task?",options:["Laryngoscopy only","Surgical airway and mask ventilation","Supraglottic insertion only","None of these"],answer:1,why:"Radiation appears in both ROMAN and SMART: fibrosis stiffens tissue and distorts landmarks."},{q:"Best position for intubating an obese patient with no spinal concern:",options:["Flat supine","Ramped with ear level to sternal notch, head up","Trendelenburg","Left lateral"],answer:1,why:"Ramping aligns the axes and head-up improves FRC and the view."},{q:"Which statement about cricoid pressure is most accurate?",options:["It reliably prevents aspiration and is mandatory","Evidence is weak; release it if it worsens the view","It should be increased if ventilation is difficult","It improves video laryngoscopy views"],answer:1,why:"Many guidelines no longer mandate it; it can impair laryngoscopy and ventilation."},{q:"A patient with massive PE needs intubation. Greatest risk at induction is:",options:["Bronchospasm","RV failure and cardiovascular collapse","Hyperkalaemia","Laryngospasm"],answer:1,why:"Hypotension, hypoxia and positive pressure all worsen a failing RV."}],sources:[{title:"Difficult Airway Society: guidelines for tracheal intubation in critically ill adults (2018)",url:"https://das.uk.com/guidelines/icu_guidelines2017"},{title:"Mosier JM et al. The physiologically difficult airway. West J Emerg Med (2015)",url:"https://pubmed.ncbi.nlm.nih.gov/26759643/"}]},E={id:"fpc-airway-anatomy",domain:"airway",ref:"III.2",title:"Airway anatomy and physiology",summary:"The structures you see and cut through, how the adult and paediatric airway differ, and the physiology of oxygen stores, dead space and airway reflexes that decides how much time you have.",objectives:["Identify the laryngeal landmarks used for laryngoscopy and cricothyrotomy.","Explain the anatomical differences of the paediatric airway and their consequences.","Relate FRC, dead space and shunt to desaturation during apnoea."],sections:[{id:"upper",title:"The upper airway and larynx",core:!0,body:["Air passes the nose or mouth, the pharynx (naso-, oro- and laryngopharynx), then the larynx. The epiglottis sits at the base of the tongue; the space between them is the vallecula, where a curved Macintosh blade tip sits to lift the epiglottis indirectly through the hyoepiglottic ligament. A straight Miller blade lifts the epiglottis directly.","The glottic opening is bounded by the vocal cords. Posteriorly lie the arytenoid cartilages and the interarytenoid notch \u2014 the landmark most often seen in a poor view, and the reason a bougie aimed just anterior to the arytenoids usually finds the trachea. The piriform recesses sit on either side of the larynx; a tube or bougie that slides into one meets resistance and does not produce tracheal clicks.","The thyroid cartilage forms the laryngeal prominence. Below it, the cricothyroid membrane spans the gap to the cricoid cartilage \u2014 the only complete ring of cartilage in the airway. The membrane is about 1 cm high and 2\u20133 cm wide in adults, avascular in its midline, and the site of an emergency surgical airway. The cricothyroid arteries run across its upper part, which is why the incision is made through the lower half."],list:{caption:"Finding the membrane: laryngeal handshake",items:["Identify the hyoid and the thyroid laminae between thumb and middle finger.","Slide down to the cricoid ring and stabilise the larynx.","Feel the membrane with the index finger in the gap between thyroid and cricoid.","In obese or swollen necks, ultrasound can identify it before induction."],ordered:!0}},{id:"peds",title:"The paediatric airway",core:!0,body:["Infants and young children have a proportionally larger occiput that flexes the neck when supine \u2014 place a towel under the shoulders, not the head. The tongue is large relative to the mouth, the larynx sits higher (around C3\u2013C4 in infants versus C5\u2013C6 in adults) and more anterior, and the epiglottis is floppy and omega-shaped, which is why a straight blade lifting it directly is often preferred in infants.","The narrowest functional point in young children has traditionally been taught as the cricoid ring; imaging suggests the glottis is narrowest in some, but the cricoid remains the narrowest complete, non-expandable ring. A tube that passes the cords but is tight at the cricoid can cause mucosal injury and post-extubation stridor. Cuffed tubes are now standard in most children, sized smaller, with cuff pressures monitored.","Small radius magnifies resistance. Resistance to laminar flow rises with the fourth power of the radius, so one millimetre of oedema in a 4 mm airway raises resistance about sixteen-fold. Children have less oxygen reserve per kilogram and roughly double the oxygen consumption, so they desaturate fast, and bradycardia from hypoxia is a pre-arrest sign."],table:{caption:"Adult versus infant airway",head:["Feature","Infant","Adult"],rows:[["Occiput","Large: flexes neck supine","Proportionate"],["Larynx level","C3\u2013C4, anterior","C5\u2013C6"],["Epiglottis","Long, floppy, omega-shaped","Broad, flat, firm"],["Narrowest complete ring","Cricoid","Cricoid (glottis functionally narrowest)"],["Cricothyroid membrane","Tiny: needle approach under ~10\u201312 years","Surgical approach feasible"],["O\u2082 consumption","\u2248 6\u20138 mL/kg/min","\u2248 3\u20134 mL/kg/min"]]}},{id:"stores",title:"Oxygen stores and the apnoeic clock",core:!0,body:["During apnoea the patient lives on the oxygen already in the body. The largest modifiable store is the functional residual capacity (FRC) \u2014 the gas left in the lungs at the end of a normal breath, about 2\u20132.5 litres in an adult. Breathing air, that gas is about 21 % oxygen; after thorough pre-oxygenation it can approach 90 %, multiplying the reserve several-fold.","FRC falls when supine, with obesity, in pregnancy, with abdominal distension and with lung disease such as pneumonia or ARDS. Oxygen consumption rises with sepsis, fever, pregnancy and in children. Each change shortens the time to desaturation. A healthy, well pre-oxygenated adult may remain above 90 % for several minutes; a critically ill or obese patient may desaturate within a minute.","Shunt \u2014 blood passing unventilated alveoli \u2014 limits how much pre-oxygenation can achieve, because those alveoli never fill with oxygen. Patients with large shunts may not reach an end-tidal oxygen above 85\u201390 % with a mask alone; positive pressure (NIV or PEEP) to recruit lung improves pre-oxygenation in these patients.","The oxyhaemoglobin dissociation curve explains the shape of desaturation. While alveolar oxygen is high, saturation sits on the flat upper part of the curve and barely changes. Once arterial PO\u2082 falls to about 60 mmHg, the curve is steep and saturation falls quickly. Pulse oximeters also lag behind central desaturation, particularly with poor peripheral perfusion."]},{id:"deadspace",title:"Dead space, reflexes and the lower airway",body:["Anatomical dead space \u2014 the conducting airways that do not take part in gas exchange \u2014 is about 2 mL/kg (around 150 mL in an adult). Alveolar dead space adds ventilated but unperfused alveoli (pulmonary embolism, low cardiac output, overdistension). Equipment adds more: a filter, a catheter mount and a long elbow can add significant dead space, which matters in children and when ventilating small tidal volumes.","The airway is protected by reflexes. Laryngeal stimulation can produce laryngospasm, coughing, bradycardia (vagal, especially in children) and a sympathetic surge with hypertension and tachycardia. That surge is undesirable in raised intracranial pressure, aortic dissection and ischaemic heart disease, and is blunted by adequate depth of anaesthesia and analgesia.","Below the cords the trachea runs about 10\u201312 cm to the carina at roughly the level of the angle of Louis (T4\u2013T5). The right main bronchus is shorter, wider and more vertical, so a tube advanced too far usually enters it. In an adult, a tube depth of roughly three times the tube size at the teeth, or about 21\u201323 cm at the incisors, places the tip mid-trachea; confirm with capnography, bilateral breath sounds and imaging."]}],keyPoints:["Bougie just anterior to the arytenoids; incise the lower half of the cricothyroid membrane.","Infants: large occiput, high anterior larynx, floppy epiglottis, cricoid the narrowest ring, double the oxygen consumption.","FRC is the oxygen tank during apnoea; obesity, pregnancy, supine position and lung disease shrink it.","Shunt limits pre-oxygenation \u2014 PEEP or NIV helps.","Saturation stays flat, then falls fast once PaO\u2082 nears 60 mmHg."],pearls:["Use the laryngeal handshake and mark the membrane before a predicted difficult intubation.","A towel under an infant's shoulders, not the head, aligns the airway.","Tube depth roughly three times the tube size at the lips in adults and children over about two years."],pitfalls:["Pillow under an infant's head, which flexes the neck further.","Assuming normal saturation means time remains when FRC is small.","Long equipment dead space when ventilating small volumes."],live:[{id:"peds-airway",label:"The child's airway: radius to the fourth power"},{id:"o2path",label:"Oxygen: from air to mitochondria"}],questions:[{q:"A Macintosh blade tip is placed in the:",options:["Piriform recess","Vallecula","Glottis","Interarytenoid notch"],answer:1,why:"The curved blade lifts the epiglottis indirectly via the hyoepiglottic ligament."},{q:"Why is the cricothyroid incision made in the lower half of the membrane?",options:["The membrane is thicker there","The cricothyroid arteries cross the upper part","The vocal cords lie below","It is closer to the skin"],answer:1,why:"Avoid the cricothyroid vessels running along the upper membrane."},{q:"In an infant, the larynx lies at about:",options:["C1","C3\u2013C4","C6\u2013C7","T1"],answer:1,why:"The infant larynx is higher and more anterior than the adult's (C5\u2013C6)."},{q:"An infant airway of 4 mm develops 1 mm of circumferential oedema. Resistance rises roughly:",options:["2-fold","4-fold","16-fold","100-fold"],answer:2,why:"Diameter halves (radius halves); resistance \u221D 1/r\u2074 \u2192 16\xD7."},{q:"Which most shortens safe apnoea time?",options:["Sitting up 30\xB0","Pregnancy at term","Pre-oxygenation for 3 minutes","Apnoeic nasal oxygen"],answer:1,why:"Pregnancy reduces FRC and increases oxygen consumption."},{q:"Why can a patient with a large shunt fail to pre-oxygenate with a mask?",options:["Oxygen toxicity","Unventilated alveoli never fill with oxygen","CO\u2082 rises too fast","The mask leaks"],answer:1,why:"Shunted blood bypasses ventilated alveoli; recruitment with PEEP helps."},{q:"Anatomical dead space in an adult is approximately:",options:["50 mL","150 mL","500 mL","1 L"],answer:1,why:"About 2 mL/kg."},{q:"A tube advanced too far most often enters the:",options:["Left main bronchus","Right main bronchus","Oesophagus","Piriform recess"],answer:1,why:"The right main bronchus is shorter, wider and more vertical."},{q:"Where should padding go to position a supine infant for intubation?",options:["Under the head","Under the shoulders","Under the knees","No padding"],answer:1,why:"The large occiput flexes the neck; a shoulder roll aligns the axes."},{q:"Saturation begins to fall quickly when arterial PO\u2082 reaches about:",options:["200 mmHg","100 mmHg","60 mmHg","20 mmHg"],answer:2,why:"Below about 60 mmHg the dissociation curve is steep."}],sources:[{title:"StatPearls: Anatomy, head and neck, larynx",url:"https://www.ncbi.nlm.nih.gov/books/?term=Anatomy%2C+head+and+neck%2C+larynx+StatPearls"},{title:"StatPearls: Pediatric airway management",url:"https://www.ncbi.nlm.nih.gov/books/?term=Pediatric+airway+management+StatPearls"}]};var B={id:"fpc-airway-pharm",domain:"airway",ref:"III.3",title:"RSI, analgesia and sedation pharmacology",summary:"Induction agents, neuromuscular blockers and reversal, and post-intubation analgesia and sedation: what each does to the blood pressure, the brain and the potassium, and how to choose for the patient in front of you.",objectives:["Choose an induction agent and dose for the haemodynamic and neurological state of the patient.","Compare succinylcholine and rocuronium, including contraindications and reversal with sugammadex.","Plan analgesia-first sedation after intubation and recognise awareness under paralysis."],sections:[{id:"sequence",title:"The sequence",core:!0,body:["Rapid sequence intubation gives an induction agent and a neuromuscular blocker in quick succession to a pre-oxygenated patient, then intubates without bag-mask ventilation unless saturation falls. The aim is the best intubating conditions in the shortest time while protecting against aspiration and physiological collapse.","Doses below are typical adult intravenous teaching values; programmes publish their own protocols and those govern practice. In shock, induction doses are commonly reduced \u2014 often by half \u2014 while paralytic doses are kept full or increased, because a slower circulation delays the onset of the blocker and an under-dosed paralytic produces poor conditions."],list:{caption:"Seven Ps of RSI",items:["Preparation (team, drugs, equipment, plan)","Pre-oxygenation","Pre-intubation optimisation (resuscitation)","Paralysis with induction","Positioning","Placement with proof (waveform capnography)","Post-intubation management"],ordered:!0}},{id:"induction",title:"Induction agents",core:!0,body:["Ketamine is an NMDA antagonist producing dissociative anaesthesia with analgesia. It releases catecholamines, so blood pressure and heart rate are usually maintained or rise, and it preserves airway reflexes and respiratory drive at sub-anaesthetic doses and causes bronchodilation. In a catecholamine-depleted patient its direct myocardial depressant effect can appear, so profound shock still calls for a reduced dose. Older concerns that it raises intracranial pressure are not supported by modern evidence when ventilation is controlled.","Etomidate is an imidazole with minimal cardiovascular effects. It causes transient adrenal suppression by inhibiting 11-\u03B2-hydroxylase after a single dose; whether this changes outcomes in sepsis remains debated. It provides no analgesia and can cause myoclonus.","Propofol is a GABA-A agonist with rapid onset and offset. It causes vasodilation and myocardial depression, so hypotension is common, especially in hypovolaemia; it is a poor choice in shock. It has antiemetic and anticonvulsant properties and suits haemodynamically stable patients and status epilepticus.","Midazolam is slower in onset at induction doses, causes dose-dependent hypotension, and is less reliable as a sole RSI induction agent; it is used more for sedation and seizures."],table:{caption:"Induction agents (typical adult IV doses)",head:["Agent","Dose","Onset","BP effect","Notes"],rows:[["Ketamine","1\u20132 mg/kg (reduce in shock)","30\u201360 s","Maintained or \u2191","Analgesia, bronchodilation; emergence reactions"],["Etomidate","0.3 mg/kg","30\u201360 s","Neutral","Adrenal suppression, myoclonus, no analgesia"],["Propofol","1\u20132.5 mg/kg","15\u201345 s","\u2193\u2193","Avoid in shock; anticonvulsant"],["Midazolam","0.1\u20130.3 mg/kg","1\u20133 min","\u2193","Slower; better for sedation"]]}},{id:"nmb",title:"Neuromuscular blockers and reversal",core:!0,body:["Succinylcholine (1.5 mg/kg IV) is a depolarising blocker: it binds acetylcholine receptors, causes fasciculations, then a block lasting about 6\u201310 minutes. Onset is about 45\u201360 seconds. It raises serum potassium by around 0.5 mmol/L in normal patients, and much more where receptors have up-regulated or spread across the muscle membrane.","Contraindications include known or suspected hyperkalaemia, a personal or family history of malignant hyperthermia, neuromuscular disease (muscular dystrophies, myopathies), and conditions with receptor up-regulation such as burns, crush injury, prolonged immobilisation, stroke or spinal cord injury older than about 24\u201372 hours. Repeat doses can cause bradycardia, especially in children.","Rocuronium (1\u20131.2 mg/kg IV, some protocols higher in shock) is a non-depolarising aminosteroid. At these doses onset approaches that of succinylcholine, and the block lasts 45\u201370 minutes or longer. It has no hyperkalaemia risk and few contraindications, which is why many transport programmes use it first-line. Its long duration means a failed airway cannot be rescued by waiting for spontaneous breathing to return \u2014 but that rarely happens in time with succinylcholine either, before dangerous desaturation.",`Sugammadex encapsulates rocuronium (and vecuronium). A dose of 16 mg/kg reverses a deep block within about three minutes. It does not reverse succinylcholine or the induction agent, and reversal does not fix an obstructed airway: in a "can't intubate, can't oxygenate" situation the priority remains oxygenation and a surgical airway.`]},{id:"post",title:"After the tube: analgesia first",core:!0,body:["Paralysis is not sedation. After a long-acting paralytic, a patient can be fully aware, in pain and unable to move. Awareness during paralysis is a recognised harm of emergency airway management, and it is associated with later psychological injury. Start analgesia and sedation promptly after confirming the tube, before the induction agent wears off \u2014 etomidate and propofol last only minutes.","Use an analgesia-first approach: an opioid such as fentanyl (typically 1 mcg/kg boluses or an infusion, adjusted to effect) to treat the pain of the tube, injuries and procedures, then add a sedative \u2014 propofol in the haemodynamically stable, ketamine or midazolam when blood pressure is tenuous. Tachycardia and hypertension under paralysis may signal awareness or pain; treat them as such before attributing them to anything else.","Reassess often. Transport adds stimuli \u2014 noise, vibration, movement, cold \u2014 and drugs given on the ground may wear off in the air. Document sedation scores before paralysis is redosed, and avoid redosing a paralytic without ensuring sedation."],example:{case:"A 30-year-old with a severe head injury (GCS 6), BP 138/80, HR 96, intubated with rocuronium and a reduced dose of ketamine. Twenty minutes into the flight, HR is 128 and BP 172/96.",steps:["Rocuronium is still working; ketamine has probably worn off. The patient may be aware and in pain.","The sympathetic surge also raises intracranial pressure \u2014 treat it promptly.","Give an opioid bolus, then start or increase sedation (propofol if BP allows, otherwise more ketamine or midazolam).","Recheck: HR and BP should settle. Continue an infusion so the gap does not recur; maintain MAP to protect cerebral perfusion pressure."]}},{id:"adjuncts",title:"Adjuncts and special situations",body:["Push-dose vasopressors (for example phenylephrine in small boluses, or dilute epinephrine) treat post-induction hypotension while infusions are prepared. Have them drawn and labelled before induction in any patient with borderline blood pressure.","In bronchospasm, ketamine is favoured for its bronchodilation. In status epilepticus, propofol or a benzodiazepine adds anticonvulsant effect \u2014 remember that paralysis hides seizures, so continuous EEG is unavailable in the field and a long-acting paralytic should be paired with adequate anticonvulsant therapy. In suspected raised ICP, the goal is to avoid both hypotension and the sympathetic surge of laryngoscopy: adequate depth, an opioid, and a blood-pressure-neutral agent.","Delayed sequence intubation gives ketamine to an agitated, hypoxaemic patient who will not tolerate pre-oxygenation, then pre-oxygenates with NIV or a mask before paralysis. It is a deliberate procedural sedation to allow pre-oxygenation, not RSI with a delay."]}],keyPoints:["Ketamine maintains blood pressure and gives analgesia; etomidate is haemodynamically neutral; propofol drops pressure \u2014 avoid it in shock.","In shock: halve the induction dose, keep the paralytic dose full.","Succinylcholine: hyperkalaemia, malignant hyperthermia, neuromuscular disease and late burns/crush/immobility are contraindications.","Rocuronium 1\u20131.2 mg/kg is reversible with sugammadex 16 mg/kg \u2014 reversal never replaces oxygenation.","Paralysis is not sedation: start analgesia and sedation right after tube confirmation."],pearls:["Tachycardia and hypertension under rocuronium usually mean the patient feels it.","Draw up push-dose pressors before induction, not after the pressure falls.","Delayed sequence intubation enables pre-oxygenation in the agitated hypoxic patient."],pitfalls:["Succinylcholine in a patient with chronic renal failure and an unknown potassium.","Full-dose propofol in a septic patient.","Letting a short-acting induction agent wear off with no sedation running."],live:[{id:"moa-ketamine",label:"Ketamine: mechanism of action"},{id:"moa-rocuronium",label:"Rocuronium: mechanism of action"},{id:"moa-succinylcholine",label:"Succinylcholine: mechanism of action"}],questions:[{q:"Which induction agent is most likely to worsen hypotension in septic shock?",options:["Ketamine","Etomidate","Propofol","Fentanyl at 1 mcg/kg"],answer:2,why:"Propofol causes vasodilation and myocardial depression."},{q:"Succinylcholine is contraindicated in a patient with:",options:["A burn 6 hours old","A burn 5 days old","Asthma","Isolated femur fracture"],answer:1,why:"Receptor up-regulation after about 24\u201372 hours causes dangerous hyperkalaemia."},{q:"In shock, the induction agent dose is typically ___ and the paralytic dose ___:",options:["Increased; reduced","Reduced; kept full or increased","Unchanged; reduced","Reduced; reduced"],answer:1,why:"Lower induction dose limits hypotension; slower circulation needs a full paralytic dose."},{q:"Sugammadex reverses:",options:["Succinylcholine","Rocuronium","Etomidate","Ketamine"],answer:1,why:"It encapsulates aminosteroid blockers (rocuronium, vecuronium)."},{q:"Etomidate's best-known adverse effect is:",options:["Bronchospasm","Adrenal suppression","Hyperkalaemia","Malignant hyperthermia"],answer:1,why:"It inhibits 11-\u03B2-hydroxylase transiently."},{q:"Twenty minutes after RSI with rocuronium and etomidate, HR rises to 130 and BP to 180/100. Most likely cause:",options:["Anaphylaxis","Awareness and pain as etomidate wears off","Hypovolaemia","Tube in the oesophagus"],answer:1,why:"Etomidate lasts minutes; rocuronium persists. Give analgesia and sedation."},{q:"Which agent is favoured for induction in severe bronchospasm?",options:["Propofol","Ketamine","Etomidate","Midazolam"],answer:1,why:"Ketamine causes bronchodilation via catecholamine release."},{q:"Typical rocuronium RSI dose:",options:["0.1 mg/kg","0.6 mg/kg","1\u20131.2 mg/kg","3 mg/kg"],answer:2,why:"High doses give onset approaching succinylcholine."},{q:"Delayed sequence intubation primarily aims to:",options:["Avoid paralysis","Allow pre-oxygenation in an agitated patient","Delay transport","Reduce drug costs"],answer:1,why:"Dissociative ketamine allows NIV or mask pre-oxygenation before paralysis."},{q:"Repeat succinylcholine doses in children may cause:",options:["Tachycardia","Bradycardia","Hypertension","Hypokalaemia"],answer:1,why:"Muscarinic stimulation causes bradycardia."}],sources:[{title:"StatPearls: Rapid sequence intubation",url:"https://www.ncbi.nlm.nih.gov/books/?term=Rapid+sequence+intubation+StatPearls"},{title:"StatPearls: Succinylcholine",url:"https://www.ncbi.nlm.nih.gov/books/?term=Succinylcholine+StatPearls"},{title:"StatPearls: Sugammadex",url:"https://www.ncbi.nlm.nih.gov/books/?term=Sugammadex+StatPearls"}]},M={id:"fpc-passive-oxygenation",domain:"airway",ref:"III.4",title:"Pre-oxygenation and passive (apnoeic) oxygenation",summary:"How to fill the oxygen tank before apnoea, how to keep oxygen flowing during the attempt, and when to stop and ventilate.",objectives:["Pre-oxygenate effectively with a non-rebreather, bag-mask, high-flow nasal oxygen or NIV.","Explain apnoeic oxygenation and its limits.","Set a stop point before the desaturation cliff."],sections:[{id:"why",title:"Denitrogenation: filling the tank",core:!0,body:["Pre-oxygenation replaces nitrogen in the functional residual capacity with oxygen. The goal is an end-tidal oxygen fraction near 90 % when it can be measured, or at least three minutes of tidal breathing \u2014 or eight vital-capacity breaths \u2014 on a high-FiO\u2082 source with a good seal.",`A standard non-rebreather mask at 15 L/min delivers far less than 100 % because room air is entrained around the mask and through the valves when the patient's inspiratory flow exceeds the oxygen flow. Turning the flowmeter to "flush" (often 40\u201360 L/min) reduces entrainment and markedly increases the delivered FiO\u2082.`,"A bag-valve-mask with a tight seal and a PEEP valve can deliver close to 100 %, but only if the patient's effort opens the valve \u2014 or if the operator gently assists. Without a tight seal it performs worse than a non-rebreather. Nasal cannula at high flow under a mask adds oxygen to the reservoir in the nasopharynx."],table:{caption:"Pre-oxygenation options",head:["Device","Approximate FiO\u2082","Best for"],rows:[["NRB at 15 L/min","0.6\u20130.7","Not ideal alone"],["NRB at flush rate","Up to ~0.9","Practical default when no NIV"],["BVM + PEEP valve, sealed","Up to ~1.0","Spontaneously breathing, cooperative"],["NIV (CPAP/BiPAP) FiO\u2082 1.0","~1.0 with recruitment","Shunt physiology, obesity, pneumonia"],["High-flow nasal oxygen","High, flow-dependent","Pre-oxygenation and apnoeic oxygenation"]]}},{id:"shunt",title:"When shunt limits the mask",core:!0,body:["Patients with pneumonia, pulmonary oedema or ARDS have alveoli that are flooded or collapsed. Oxygen delivered to the mouth cannot reach them, so saturation may stay in the 80s even at FiO\u2082 1.0. These patients need positive end-expiratory pressure to recruit lung: CPAP or BiPAP for pre-oxygenation, or a BVM with a PEEP valve set to 5\u201315 cmH\u2082O.","NIV pre-oxygenation is particularly helpful in obesity and in patients who are already hypoxaemic. It requires a cooperative patient and a protected airway reflex; agitation may require delayed sequence intubation with ketamine."]},{id:"apnoeic",title:"Apnoeic oxygenation",core:!0,body:["Once the patient is apnoeic, oxygen continues to be taken up from the alveoli at roughly 250 mL/min in an adult, while CO\u2082 is returned at about 200 mL/min, much of it buffered in blood. The resulting net gas movement into the alveoli draws gas from the pharynx into the lungs. If the pharynx is filled with oxygen \u2014 nasal cannula at 15 L/min or high-flow nasal oxygen \u2014 that bulk flow is oxygen, extending the time before desaturation.","Apnoeic oxygenation works only with a patent airway: a jaw thrust or the laryngoscope blade keeps the pharynx open. It does not remove CO\u2082 effectively; PaCO\u2082 rises by roughly 3 mmHg a minute of apnoea, which matters in patients with acidosis or raised intracranial pressure.","Leave the nasal cannula on throughout the attempt, under the pre-oxygenation mask. It is cheap, quick and does not interfere with laryngoscopy."]},{id:"stop",title:"When to stop and ventilate",core:!0,body:["Agree a stop point before the blade goes in: a saturation (commonly 93 % or a fall of a set amount from baseline) or a time. When reached, the operator withdraws, the team ventilates with a BVM and an oropharyngeal airway (or places a supraglottic airway), re-oxygenates and reconsiders the plan.","Gentle mask ventilation during the apnoeic period \u2014 low pressures, low rates, a PEEP valve \u2014 is reasonable in patients at high risk of desaturation; it reduces severe hypoxaemia without a clear increase in aspiration when done carefully."],example:{case:"An obese 52-year-old with COVID pneumonia: SpO\u2082 88 % on NRB at 15 L/min.",steps:["Recognise shunt and a small FRC: the mask alone will not pre-oxygenate.","Sit up 30\xB0; apply NIV with FiO\u2082 1.0 and PEEP 8\u201310 cmH\u2082O; add nasal cannula at 15 L/min.","Target SpO\u2082 \u2265 94 % or the best achievable after three minutes.","During the attempt, keep the cannula flowing; stop at the agreed saturation and ventilate gently with PEEP."]}}],keyPoints:["Pre-oxygenate for three minutes or eight vital-capacity breaths with a sealed high-FiO\u2082 source.","NRB at flush rate beats NRB at 15 L/min.","Shunt needs PEEP: NIV or BVM with a PEEP valve.","Nasal cannula at 15 L/min during apnoea extends safe time if the airway is open.","Agree a saturation or time stop point before laryngoscopy."],pearls:["Head-up positioning adds safe apnoea time in obese and pregnant patients.","Apnoeic oxygenation does not clear CO\u2082."],pitfalls:["A BVM held loosely over the face without assistance.","Removing nasal oxygen to fit the mask.","Pressing on with laryngoscopy as saturation drops."],live:[{id:"pop-apnoea",label:"Apnoea: how long the oxygen lasts"},{id:"hypox",label:"Why is the PaO\u2082 low?"}],questions:[{q:"Which increases FiO\u2082 delivered by a non-rebreather most?",options:["Reducing flow to 10 L/min","Turning the flowmeter to flush rate","Removing the reservoir","Adding humidification"],answer:1,why:"Higher flow reduces room-air entrainment."},{q:"Minimum pre-oxygenation by tidal breathing is about:",options:["30 seconds","1 minute","3 minutes","15 minutes"],answer:2,why:"Three minutes of tidal breathing or eight vital-capacity breaths."},{q:"A pneumonia patient stays at SpO\u2082 86 % on FiO\u2082 1.0 by mask. Best next step:",options:["Proceed immediately","Add PEEP with NIV or a PEEP valve","Lower FiO\u2082","Give a diuretic"],answer:1,why:"Shunt requires recruitment with positive pressure."},{q:"Apnoeic oxygenation requires:",options:["A patent airway","Spontaneous breathing","An endotracheal tube","Sedation reversal"],answer:0,why:"Bulk flow from the pharynx needs an open airway."},{q:"During apnoea, PaCO\u2082 rises roughly:",options:["0.3 mmHg/min","3 mmHg/min","30 mmHg/min","Not at all"],answer:1,why:"About 3 mmHg per minute after the first minute."},{q:"Nasal cannula flow commonly used for apnoeic oxygenation:",options:["2 L/min","6 L/min","15 L/min","60 L/min with a standard cannula"],answer:2,why:"15 L/min with a standard cannula; higher with high-flow devices."},{q:"Why does a BVM perform poorly for pre-oxygenation without a seal?",options:["Valves leak oxygen","Room air is entrained around the mask","It delivers too much PEEP","It increases CO\u2082"],answer:1,why:"Without a seal, inspiratory flow pulls in room air."},{q:"Gentle mask ventilation during the apnoeic period is reasonable when:",options:["Never","High risk of desaturation, using low pressures","Only after three failed attempts","Only in children"],answer:1,why:"Careful low-pressure ventilation reduces severe hypoxaemia."},{q:"The best positioning for pre-oxygenating an obese patient:",options:["Supine flat","Head up 20\u201330\xB0","Trendelenburg","Prone"],answer:1,why:"Head-up improves FRC."},{q:"An agitated hypoxic patient tears off every mask. Strategy:",options:["Proceed with RSI unoxygenated","Delayed sequence intubation with ketamine","Physical restraint only","Abandon intubation"],answer:1,why:"Ketamine allows pre-oxygenation before paralysis."}],sources:[{title:"Weingart SD, Levitan RM. Preoxygenation and prevention of desaturation during emergency airway management. Ann Emerg Med (2012)",url:"https://pubmed.ncbi.nlm.nih.gov/22050948/"},{title:"Casey JD et al. Bag-mask ventilation during tracheal intubation of critically ill adults (PreVent). NEJM (2019)",url:"https://www.nejm.org/doi/full/10.1056/NEJMoa1812405"}]};var N={id:"fpc-failed-airway",domain:"airway",ref:"III.5",title:"The failed airway",summary:`Recognising failure early, the difference between "can't intubate, can oxygenate" and "can't intubate, can't oxygenate", and moving through plans A to D without fixation.`,objectives:["Define a failed airway and the CICO situation.","Apply a stepwise plan: best attempt at intubation, supraglottic rescue, face-mask oxygenation, front-of-neck access.","Use human factors \u2014 limiting attempts, declaring failure aloud \u2014 to avoid fixation."],sections:[{id:"define",title:"What counts as failure",core:!0,body:["A failed airway exists when an experienced operator cannot intubate after a limited number of best attempts, or when oxygenation cannot be maintained at any point. The distinction that matters is whether the patient can be oxygenated by another means.",`"Can't intubate, can oxygenate" is a failed intubation but not yet an emergency of minutes: the team has time to re-oxygenate, change technique or operator, place a supraglottic airway, wake the patient if appropriate, or consider a planned surgical airway.`,`"Can't intubate, can't oxygenate" (CICO) is the end of the line. Failed intubation plus failure of a supraglottic airway plus failure of optimised face-mask ventilation, with falling saturation, demands immediate front-of-neck access. Hesitation here \u2014 not the incision \u2014 is what kills patients.`],list:{caption:"Commonly used limits",items:["No more than three attempts at intubation in total, with the fourth only by a more experienced operator if available.","Each attempt is a best attempt: optimal position, device, adjunct and paralysis.","Stop any attempt at the agreed saturation or time and re-oxygenate.","No more than three attempts at supraglottic airway insertion."]}},{id:"plans",title:"Plans A to D",core:!0,body:["Plan A is tracheal intubation, maximising first-pass success: a video laryngoscope where available, a bougie or stylet, full neuromuscular blockade, optimal positioning and external laryngeal manipulation. Change something between attempts \u2014 device, blade, position, operator \u2014 otherwise a second attempt is likely to fail in the same way.","Plan B is rescue oxygenation through a second-generation supraglottic airway (one with a gastric drainage channel). If it works, stop and think: wake the patient, intubate through the device with a fibreoptic scope if skilled, transport with the supraglottic airway, or proceed to a planned surgical airway.","Plan C is face-mask ventilation with two hands, an oropharyngeal and nasopharyngeal airway, and full paralysis \u2014 paralysis improves mask ventilation by abolishing laryngospasm and chest wall rigidity. If oxygenation is restored, the options are the same as after a successful Plan B.",`Plan D is front-of-neck access when Plans A, B and C have failed and saturation is falling. Declare it aloud: "This is a can't intubate, can't oxygenate situation. I am doing a cricothyrotomy." Continue attempts at oxygenation from above while the neck is opened.`],example:{case:"A trauma patient, paralysed with rocuronium. Two video laryngoscopy attempts give a grade 4 view through blood. SpO\u2082 is 89 % and falling. A size 4 supraglottic airway is placed; there is no chest rise and no capnography trace. Two-person mask ventilation fails.",steps:["Plans A, B and C have failed and the patient is desaturating: this is CICO.","Declare it, call for the surgical airway kit, and extend the neck.","Perform a scalpel\u2013bougie\u2013tube cricothyrotomy while another rescuer continues to attempt oxygenation from above.","Confirm with waveform capnography, ventilate, then secure the tube."]}},{id:"human",title:"Human factors and fixation",core:!0,body:["Experienced operators fail airways most often not for lack of skill but because of task fixation \u2014 repeated attempts with the same approach while the patient desaturates. Time distortion is real: an operator focused on the screen loses track of seconds and saturation.","Assign roles before induction: an airway operator, an assistant, someone watching the monitor who will call out saturation and time, and someone responsible for the drug plan. Give that observer explicit permission to call a stop. Use shared language, such as the Vortex approach, where any best attempt at one of the three upper-airway lifelines (tube, supraglottic airway, face mask) that fails moves the team toward the next, and failure of all three moves the team to the neck.","Debrief every failed or difficult airway. Record the grade of view, what worked and what did not, and tell the patient and receiving team so the next operator is warned."]},{id:"tricks",title:"Techniques that rescue Plan A",body:["Bougie: with a grade 2b or 3 view, pass the bougie with the angled tip anterior, feel for tracheal rings (clicks) and hold-up at the small bronchi around 30\u201340 cm; then railroad the tube, rotating it 90\xB0 counter-clockwise to avoid catching on the arytenoids.","External laryngeal manipulation: the operator moves the thyroid cartilage with the right hand to bring the cords into view, then an assistant holds it there. This is different from cricoid pressure.","Suction-assisted laryngoscopy and airway decontamination (SALAD): lead with a rigid suction catheter, park it in the upper oesophagus to the left of the blade, and clear the view continuously in massive vomit or blood.","Changing device: a hyperangulated video blade for an anterior larynx, a direct blade for heavy contamination that blinds the camera, a smaller tube for oedema."]}],keyPoints:["Failed airway: can't intubate after limited best attempts, or can't oxygenate at any point.","Change something between attempts; limit to three.","Plan B: second-generation supraglottic airway; Plan C: two-handed mask with adjuncts and full paralysis.","CICO with falling saturation = immediate front-of-neck access, declared aloud.","Assign a monitor-watcher with authority to call a stop."],pearls:["Paralysis improves face-mask ventilation.","After a successful rescue, the next decision is a choice \u2014 wake, convert or transport \u2014 not reflexive re-intubation."],pitfalls:["Fourth and fifth attempts with the same blade.","Delaying cricothyrotomy to try one more supraglottic device."],live:[{id:"pop-apnoea",label:"Apnoea: how long the oxygen lasts"}],questions:[{q:"CICO is defined as failure of:",options:["Intubation only","Intubation, supraglottic airway and face-mask oxygenation","Two intubation attempts","Capnography"],answer:1,why:"All three upper-airway lifelines fail with falling saturation."},{q:"Between intubation attempts you should:",options:["Repeat the same technique faster","Change something and re-oxygenate","Give more induction agent","Remove monitoring"],answer:1,why:"Repeating the same approach usually fails the same way."},{q:"Preferred supraglottic device for rescue:",options:["First-generation without drain","Second-generation with gastric drainage","Nasal airway only","Oral airway only"],answer:1,why:"Better seal and gastric access."},{q:"Neuromuscular blockade during failed mask ventilation:",options:["Worsens ventilation","Often improves ventilation","Is contraindicated","Has no effect"],answer:1,why:"It abolishes laryngospasm and chest wall rigidity."},{q:"After successful supraglottic rescue in a can't-intubate patient, which is NOT an appropriate next step?",options:["Wake the patient","Intubate through the device with a scope","Transport with the device","Repeated blind intubation attempts until success"],answer:3,why:"Further unstructured attempts risk losing the airway."},{q:"The commonest human-factor cause of airway disasters is:",options:["Lack of equipment","Task fixation","Excessive checklists","Too many team members"],answer:1,why:"Repeated attempts while desaturating."},{q:"Hold-up of a bougie at 30\u201340 cm suggests:",options:["Oesophageal placement","Tracheal placement reaching small bronchi","Piriform recess","Kinked bougie"],answer:1,why:"Distal hold-up is a sign of tracheal placement."},{q:"When railroading a tube over a bougie, rotate it:",options:["90\xB0 counter-clockwise","180\xB0","Not at all","90\xB0 clockwise always"],answer:0,why:"Rotation keeps the bevel from catching on the right arytenoid."},{q:"SALAD is used for:",options:["Bronchospasm","Massive airway contamination","Laryngospasm","Tube confirmation"],answer:1,why:"Suction-assisted laryngoscopy and airway decontamination."},{q:"In CICO, while one rescuer performs cricothyrotomy, others should:",options:["Stop all oxygenation","Continue to attempt oxygenation from above","Prepare for extubation","Draw labs"],answer:1,why:"Any oxygen delivered buys time."}],sources:[{title:"Difficult Airway Society: unanticipated difficult intubation guidelines (2015)",url:"https://das.uk.com/guidelines/das_intubation_guidelines"},{title:"The Vortex Approach",url:"https://vortexapproach.org/"}]},D={id:"fpc-surgical-airway",domain:"airway",ref:"III.6",title:"Surgical airway: cricothyrotomy and needle techniques",summary:"The scalpel\u2013bougie\u2013tube technique, open surgical cricothyrotomy, needle cricothyrotomy in children, and the complications and contraindications.",objectives:["Perform a scalpel\u2013bougie\u2013tube cricothyrotomy step by step.","Know when needle cricothyrotomy is preferred and its limits.","Recognise complications and confirm placement."],sections:[{id:"indication",title:"Indications and contraindications",core:!0,body:["The main indication is CICO. Others are massive facial trauma or upper airway obstruction that makes oral intubation impossible, when oxygenation cannot otherwise be secured.","Relative contraindications include laryngeal fracture or transection, a large neck mass or haematoma over the membrane, and young age. In children under roughly 10\u201312 years the cricothyroid membrane is tiny and the larynx is soft and mobile; most guidelines prefer needle cricothyrotomy, or a surgical tracheostomy by a surgeon, in this age group. In CICO there is no absolute contraindication in an adult: an imperfect surgical airway beats a dead patient."]},{id:"sbt",title:"Scalpel\u2013bougie\u2013tube technique",core:!0,body:["This technique is favoured by many guidelines because it needs little equipment \u2014 a wide (number 10) scalpel blade, a bougie and a 6.0 mm cuffed tube \u2014 and works in the same way every time.","If the membrane is palpable: stabilise the larynx with the non-dominant hand, make a transverse stab incision through skin and membrane, rotate the blade 90\xB0 so the sharp edge faces caudally, pull the blade toward you to open the hole, slide the bougie along the blade into the trachea, then pass the tube over the bougie and inflate the cuff.","If the membrane is impalpable (obesity, swelling): make an 8\u201310 cm vertical midline incision, use blunt finger dissection to find the larynx, then proceed with the transverse membrane incision as above. The vertical skin incision avoids lateral vessels and allows extension."],list:{caption:"Steps (palpable membrane)",items:["Extend the neck; identify the membrane with the laryngeal handshake.","Transverse stab incision through skin and membrane, blade edge toward the operator.","Rotate blade 90\xB0 (sharp edge caudal); pull toward you to open.","Slide the bougie along the blade into the trachea.","Railroad a lubricated 6.0 cuffed tube; inflate the cuff.","Confirm with waveform capnography; ventilate; secure."],ordered:!0}},{id:"needle",title:"Needle cricothyrotomy",core:!0,body:["A large-bore cannula (12\u201314 gauge) passed through the membrane at about 45\xB0 caudally, aspirating air as it enters the trachea, can deliver oxygen. It is the preferred emergency technique in young children.","Ventilation through a narrow cannula requires a high-pressure source: jet ventilation or a commercial device, with inspiration of about one second and expiration of about four. Exhalation must occur through the upper airway; if the upper airway is completely obstructed, gas cannot escape, pressure rises and barotrauma follows. CO\u2082 clearance is poor, so needle cricothyrotomy is a short bridge to a definitive airway.","Kinking, dislodgement and subcutaneous emphysema are common. A standard BVM attached to a 3.0 mm tube adapter on a cannula cannot generate enough flow to ventilate an adult."]},{id:"complications",title:"Complications and aftercare",body:["Immediate complications: bleeding (usually venous, controlled by pressure and the tube itself), false passage into the pretracheal tissues (no capnography trace \u2014 remove and re-site), posterior tracheal wall or oesophageal injury, and subcutaneous emphysema. Late complications include subglottic stenosis and voice change.","Secure the tube carefully: in the neck it is short and easily displaced. Note the depth, avoid advancing so far that the tube enters a main bronchus, and reconfirm capnography after every patient movement."]}],keyPoints:["Indication: CICO, or impossible oral intubation with failing oxygenation.","Scalpel\u2013bougie\u2013tube: transverse stab, rotate blade caudally, bougie along blade, 6.0 cuffed tube.","Impalpable membrane: vertical skin incision and blunt dissection first.","Children under about 10\u201312 years: needle cricothyrotomy preferred.","Needle oxygenation is a short bridge, needs high-pressure gas, and exhalation via the upper airway."],pearls:["Mark the membrane before induction in predicted difficult airways.","The tube in the neck is short \u2014 confirm after every move."],pitfalls:["Horizontal skin incision through a swollen neck where the membrane cannot be felt.","Expecting a BVM to ventilate through a 14-gauge cannula."],questions:[{q:"Tube commonly used for scalpel\u2013bougie\u2013tube cricothyrotomy in adults:",options:["3.0 uncuffed","6.0 cuffed","8.5 cuffed","Tracheostomy size 10"],answer:1,why:"A 6.0 cuffed tube passes easily through the membrane."},{q:"When the membrane is impalpable, the first incision is:",options:["Transverse 2 cm","Vertical midline 8\u201310 cm","Needle only","Lateral"],answer:1,why:"Vertical incision and blunt dissection to locate the larynx."},{q:"Needle cricothyrotomy is preferred in:",options:["Obese adults","Children under about 10\u201312 years","Laryngeal fracture in adults","Elderly patients"],answer:1,why:"The paediatric membrane is too small for a surgical approach."},{q:"With needle jet ventilation, exhalation occurs via:",options:["The cannula","The upper airway","A second cannula only","Not required"],answer:1,why:"The cannula is too narrow for passive exhalation; total upper obstruction risks barotrauma."},{q:"After cricothyrotomy, no capnography trace suggests:",options:["Successful placement","False passage","Bronchospasm only","Normal finding"],answer:1,why:"Pretracheal placement \u2014 remove and re-site."},{q:"Rotating the scalpel blade 90\xB0 after the stab incision is done so the sharp edge faces:",options:["Cephalad","Caudad","Laterally","Posteriorly"],answer:1,why:"Caudal edge reduces injury to the cricothyroid vessels and cords above."},{q:"Which is a relative contraindication to surgical cricothyrotomy?",options:["Obesity","Laryngeal fracture","Facial burns","Beard"],answer:1,why:"Laryngeal disruption may make the membrane unusable."},{q:"Needle cricothyrotomy ventilation primarily fails to:",options:["Oxygenate","Clear CO\u2082","Deliver high pressure","Cause emphysema"],answer:1,why:"CO\u2082 accumulates; it is a short bridge."},{q:"In CICO, an adult has a large neck haematoma. You should:",options:["Avoid surgical airway entirely","Proceed \u2014 CICO has no absolute contraindication","Wait for surgery","Use needle only"],answer:1,why:"Failure to act is fatal; an imperfect airway is better."},{q:"The cuffed tube in a surgical airway should be advanced:",options:["Until resistance at the carina","Just past the cuff into the trachea, then secured","As deep as possible","Only 1 cm"],answer:1,why:"Avoid mainstem placement; the tracheal segment is short."}],sources:[{title:"Difficult Airway Society: front-of-neck access (2015 guidelines)",url:"https://das.uk.com/guidelines/das_intubation_guidelines"},{title:"StatPearls: Cricothyrotomy",url:"https://www.ncbi.nlm.nih.gov/books/?term=Cricothyrotomy+StatPearls"}]};var F={id:"fpc-mech-vent",domain:"airway",ref:"III.7",title:"Mechanical ventilation in transport",summary:"Modes, initial settings, lung-protective ventilation, troubleshooting with DOPE and the inspiratory hold, and disease-specific strategies for ARDS, obstruction, acidosis and brain injury.",objectives:["Set initial ventilator settings from predicted body weight and the clinical problem.","Interpret peak, plateau and driving pressure, and troubleshoot alarms.","Adjust ventilation for ARDS, asthma/COPD, metabolic acidosis and raised ICP."],sections:[{id:"modes",title:"Modes: what you set and what varies",core:!0,body:["In volume control (VC), you set the tidal volume, rate, flow (or inspiratory time), PEEP and FiO\u2082. The ventilator guarantees the volume; airway pressure is the result and rises when compliance falls or resistance rises. Watch the peak and plateau pressures.","In pressure control (PC), you set the inspiratory pressure above PEEP, inspiratory time, rate, PEEP and FiO\u2082. Pressure is capped; tidal volume is the result and falls when the lungs stiffen or the airways narrow. Watch the exhaled tidal volume and minute ventilation.","Assist-control (AC) delivers a full mandatory breath, volume- or pressure-targeted, every time the patient triggers, plus backup breaths at the set rate. SIMV delivers set mandatory breaths synchronised with patient effort and allows spontaneous breaths between them, usually with pressure support. Pressure support (PS) alone requires the patient to trigger every breath and is not appropriate for a paralysed or apnoeic patient."]},{id:"initial",title:"Initial settings",core:!0,body:["Base tidal volume on predicted body weight (PBW), not actual weight \u2014 the lungs are the size of the person's height. PBW is 50 + 0.91 \xD7 (height in cm \u2212 152.4) kg for men and 45.5 + 0.91 \xD7 (height \u2212 152.4) for women. A starting tidal volume of 6\u20138 mL/kg PBW is lung-protective for most patients; use 6 mL/kg in ARDS.","A typical adult start: AC/VC, VT 6\u20138 mL/kg PBW, rate 16\u201320, PEEP 5\u20138 cmH\u2082O, FiO\u2082 1.0 then titrated to SpO\u2082 92\u201396 %, inspiratory time about 1 second or an I:E ratio of 1:2. Then adjust: match the patient's pre-intubation minute ventilation if they were compensating for an acidosis; lengthen expiration in obstruction.","Check an arterial or venous gas and end-tidal CO\u2082 trends after settings change. EtCO\u2082 normally runs a few mmHg below PaCO\u2082; the gap widens with dead space (low cardiac output, pulmonary embolism, COPD, overdistension)."],table:{caption:"Predicted body weight and 6 mL/kg tidal volume",head:["Height","PBW (male)","VT 6 mL/kg (male)","PBW (female)","VT 6 mL/kg (female)"],rows:[["160 cm","57 kg","340 mL","52 kg","315 mL"],["170 cm","66 kg","400 mL","62 kg","370 mL"],["180 cm","75 kg","450 mL","71 kg","425 mL"],["190 cm","84 kg","505 mL","80 kg","480 mL"]]}},{id:"pressures",title:"Reading the pressures",core:!0,body:["Peak inspiratory pressure (PIP) is the pressure needed to push the tidal volume through the airways and stretch the lungs and chest wall. Plateau pressure (Pplat), measured with an inspiratory hold of about 0.5 seconds when flow is zero, reflects only the elastic component. Keep the plateau at or below 30 cmH\u2082O.","Driving pressure is plateau minus PEEP. It expresses how hard the tidal volume stretches the available lung; lower driving pressures (below about 15 cmH\u2082O) are associated with better outcomes in ARDS. Static compliance is tidal volume divided by driving pressure.","High peak with a normal plateau (a large peak\u2013plateau gap) is a resistance problem: kinked or bitten tube, secretions, bronchospasm, small tube. High peak with a high plateau is a compliance problem: pneumothorax, mainstem intubation, pulmonary oedema, ARDS, abdominal distension, chest wall rigidity, auto-PEEP."]},{id:"dope",title:"The crashing ventilated patient: DOPE",core:!0,body:["If a ventilated patient suddenly desaturates or becomes hypotensive, disconnect from the ventilator and ventilate by hand with a BVM on 100 % oxygen. This separates machine problems from patient problems and immediately relieves breath stacking. Then work through DOPE."],list:{caption:"DOPE (plus S for stacking)",items:["Displacement: tube out or in a mainstem bronchus \u2014 capnography, depth, breath sounds.","Obstruction: kink, biting, secretions, blood \u2014 pass a suction catheter.","Pneumothorax: unilateral sounds, rising pressures, hypotension \u2014 decompress.","Equipment: oxygen supply, circuit disconnection, ventilator failure.","Stacked breaths (auto-PEEP): disconnect and let the chest empty; lower rate and lengthen expiration."]}},{id:"disease",title:"Disease-specific strategies",body:["ARDS: VT 6 mL/kg PBW (4\u20138), plateau \u2264 30, PEEP set by an oxygenation table or response (often 10\u201316 or higher), accept PaCO\u2082 elevation if pH > 7.20\u20137.25, and consider prone positioning and neuromuscular blockade in severe disease at the receiving centre.","Asthma and COPD: the danger is air trapping. Use a low rate (8\u201312), a normal tidal volume, a short inspiratory time with a high flow, and an I:E ratio of 1:4 or longer so expiratory flow returns to zero before the next breath. Accept hypercapnia. Measure auto-PEEP with an expiratory hold; if the blood pressure falls, disconnect and allow the chest to empty.","Severe metabolic acidosis (DKA, salicylates, sepsis): set a high minute ventilation that matches the patient's own pre-intubation effort \u2014 often a rate of 28\u201335 with an adequate volume \u2014 and check a gas early. Over-ventilating a salicylate patient is protective; under-ventilating can cause arrest.","Raised ICP: aim for normocapnia (PaCO\u2082 35\u201340 mmHg, using EtCO\u2082 trends) and normal oxygenation. Brief hyperventilation to PaCO\u2082 about 30\u201335 is a temporising measure only for signs of herniation; prolonged hyperventilation causes cerebral vasoconstriction and ischaemia."],example:{case:"A 175 cm woman with asthma, intubated; VC with VT 450, RR 20, PEEP 5. Peak 52, plateau 24. BP falls to 76/40.",steps:["Peak\u2013plateau gap of 28: high resistance; plateau acceptable.","Hypotension with obstruction: suspect breath stacking. Disconnect from the ventilator and compress the chest gently while it empties.","Reconnect with RR 10, a shorter inspiratory time, VT about 400 (6 mL/kg PBW for her height is \u2248 400), PEEP low; check expiratory flow reaches zero.","Treat the airway: inhaled bronchodilator in-line, IV magnesium, ketamine for sedation; accept a higher CO\u2082."]}},{id:"altitude",title:"Transport specifics",body:["Altitude reduces the partial pressure of oxygen; in unpressurised aircraft or at high cabin altitudes, expect to raise FiO\u2082 to maintain the same saturation. Gas in the endotracheal tube cuff expands with altitude (Boyle's law) \u2014 monitor cuff pressure and adjust, or fill the cuff with saline on long or high flights if your protocol allows.","Transport ventilators differ: some compensate for altitude in delivered volume, some do not; know your device. Secure the tube and circuit before moving, carry a BVM with PEEP valve, and calculate oxygen requirement for the flight with a reserve."]}],keyPoints:["VC sets volume (watch pressure); PC sets pressure (watch volume).","VT 6\u20138 mL/kg predicted body weight; plateau \u2264 30; driving pressure < 15.","Big peak\u2013plateau gap = resistance; high plateau = compliance.","Crashing patient: disconnect, bag on 100 %, then DOPE plus stacked breaths.","Obstruction: low rate, long expiration; acidosis: high minute ventilation; raised ICP: normocapnia."],pearls:["Height, not weight, decides the tidal volume.","Disconnecting the circuit is diagnostic and therapeutic in auto-PEEP.","Cuff pressure rises at altitude."],pitfalls:["Pressure support in a paralysed patient.","Fast rates in asthma.","Normal settings in severe metabolic acidosis."],live:[{id:"eom",label:"One equation runs the ventilator"},{id:"rc",label:"Resistance or compliance?"},{id:"vent-ards-signature",label:"ARDS: open the lung"},{id:"auto",label:"Auto-PEEP and the time constant"}],questions:[{q:"PBW for a 180 cm man is about:",options:["60 kg","75 kg","90 kg","Equal to actual weight"],answer:1,why:"50 + 0.91 \xD7 (180 \u2212 152.4) \u2248 75 kg."},{q:"Peak 45, plateau 20 cmH\u2082O suggests:",options:["Pneumothorax","Increased airway resistance","ARDS","Mainstem intubation"],answer:1,why:"A large peak\u2013plateau gap is resistive."},{q:"Upper limit for plateau pressure in lung-protective ventilation:",options:["20","30","40","50 cmH\u2082O"],answer:1,why:"Keep plateau \u2264 30 cmH\u2082O."},{q:"In pressure control, a falling exhaled VT suggests:",options:["Improving compliance","Worsening compliance or resistance","Leak only","Normal"],answer:1,why:"Pressure is capped; stiffer lungs receive less volume."},{q:"First action for sudden desaturation on the ventilator:",options:["Increase PEEP","Disconnect and bag with 100 % oxygen","Order a chest X-ray","Increase rate"],answer:1,why:"Separates machine from patient and relieves stacking."},{q:"Best initial strategy for intubated status asthmaticus:",options:["RR 24, I:E 1:1","RR 10, short inspiratory time, long expiration","High PEEP 15","Large VT 10 mL/kg"],answer:1,why:"Minimise air trapping."},{q:"Driving pressure equals:",options:["PIP \u2212 PEEP","Pplat \u2212 PEEP","PIP \u2212 Pplat","VT \xF7 PEEP"],answer:1,why:"Plateau minus PEEP."},{q:"A ventilated DKA patient with pH 7.05 should have:",options:["Low minute ventilation","Minute ventilation matching their pre-intubation effort","Permissive hypercapnia","PS only"],answer:1,why:"Preserve respiratory compensation."},{q:"Target PaCO\u2082 in severe TBI without herniation signs:",options:["25\u201330","35\u201340","45\u201350",">55"],answer:1,why:"Normocapnia; hyperventilation only as a bridge for herniation."},{q:"ETT cuff pressure during ascent in an unpressurised aircraft:",options:["Falls","Rises","Unchanged","Becomes negative"],answer:1,why:"Boyle's law: gas expands as ambient pressure falls."}],sources:[{title:"ARDS Network. Ventilation with lower tidal volumes. NEJM (2000)",url:"https://www.nejm.org/doi/full/10.1056/NEJM200005043421801"},{title:"Amato MBP et al. Driving pressure and survival in ARDS. NEJM (2015)",url:"https://www.nejm.org/doi/full/10.1056/NEJMsa1410639"}]},j={id:"fpc-alt-airway",domain:"airway",ref:"III.8",title:"Alternative airway devices",summary:"Supraglottic airways, video and direct laryngoscopes, bougies and stylets, and the basic adjuncts: what each is for, how to size it, and how it fails.",objectives:["Select and size supraglottic airways and know first- versus second-generation designs.","Compare direct, standard-geometry video and hyperangulated video laryngoscopy.","Use oral and nasal adjuncts correctly and know their contraindications."],sections:[{id:"adjuncts",title:"Basic adjuncts",core:!0,body:["An oropharyngeal airway (OPA) lifts the tongue off the posterior pharynx. Size from the incisors (or corner of the mouth) to the angle of the jaw. It is tolerated only by patients without a gag reflex; in a patient with a gag it causes vomiting and laryngospasm.","A nasopharyngeal airway (NPA) is tolerated by patients with an intact gag. Size from the nostril to the tragus, lubricate, and insert along the floor of the nose with the bevel toward the septum. Basilar skull fracture is a traditional contraindication, though the risk is very small with careful technique when the airway is otherwise lost. Use two NPAs plus an OPA with two-handed mask ventilation in difficult cases."]},{id:"sga",title:"Supraglottic airways",core:!0,body:["Supraglottic airways (SGAs) sit above the glottis and seal around the laryngeal inlet. First-generation devices (classic laryngeal mask airway) have a single lumen. Second-generation devices (such as the i-gel or LMA Supreme) add a gastric drainage channel, a bite block and a higher seal pressure, making them better rescue devices and allowing gastric decompression.","Retroglottic devices such as the King LT sit with the distal tip in the oesophagus and balloons above and below the larynx. They are quick to place blind but can cause tongue swelling with prolonged use and are sometimes difficult to exchange.","Sizing is by weight (or height for some devices) \u2014 check the device. Insert with the head in a neutral or sniffing position, the device lubricated on its back, along the hard palate until resistance. Confirm with capnography, chest rise and absence of a large leak.","SGAs do not protect fully against aspiration, can leak at high airway pressures (poor lungs, obesity, bronchospasm), and fail with obstruction at or below the larynx. They are an excellent bridge and a reasonable transport airway when intubation is not possible."],table:{caption:"i-gel sizes (manufacturer weight guide)",head:["Size","Patient weight"],rows:[["1","2\u20135 kg"],["1.5","5\u201312 kg"],["2","10\u201325 kg"],["2.5","25\u201335 kg"],["3","30\u201360 kg"],["4","50\u201390 kg"],["5","90+ kg"]]}},{id:"laryngoscopes",title:"Laryngoscopes",core:!0,body:["Direct laryngoscopy aligns the oral, pharyngeal and laryngeal axes to see the cords directly. It is quick, robust in heavy contamination and works when the camera fails, but needs neck extension and mandibular space.","Standard-geometry video laryngoscopes (Macintosh-shaped blades with a camera) allow both direct and indirect views and work with a standard stylet or bougie. Hyperangulated blades see around the tongue with minimal neck movement, which helps in spinal precautions and anterior larynges, but the tube must follow a steep curve: a rigid angled stylet shaped to the blade is needed, and seeing the cords does not guarantee delivering the tube.","Video laryngoscopy improves first-pass success in many emergency settings and lets the team see the view. Fogging, blood and secretions on the lens and screen glare in sunlight are its main field limitations."]},{id:"bougie",title:"Bougies, stylets and exchange",body:["A bougie (tracheal tube introducer) has an angled tip that can be steered anterior to the arytenoids in a limited view. Tracheal placement is suggested by clicks against tracheal rings and hold-up at the small airways; oesophageal placement passes without resistance. First-pass success with a bougie on every attempt was higher than with a stylet in some emergency trials.","To convert an SGA to an endotracheal tube, intubating SGAs and fibreoptic or airway-exchange-catheter techniques exist; they are skills best practised before needed. In transport, a functioning SGA is often safer to keep than to exchange in a moving aircraft."]}],keyPoints:["OPA only without a gag; NPA tolerated with a gag (bevel to septum).","Second-generation SGAs: gastric drain, better seal \u2014 preferred for rescue.","SGAs leak at high pressures and fail with obstruction at or below the glottis.","Hyperangulated video blades need a rigid shaped stylet; seeing is not delivering.","Bougie clicks and distal hold-up suggest tracheal placement."],pearls:["Keep a direct blade available when blood blinds the camera.","A working SGA in flight is often better than a risky exchange."],pitfalls:["OPA in a patient with a gag reflex.","Hyperangulated blade with a straight-to-cuff stylet."],questions:[{q:"An OPA is sized from:",options:["Nostril to tragus","Incisors to angle of jaw","Chin to sternum","Ear to eye"],answer:1,why:"Incisors/mouth corner to the angle of the mandible."},{q:"An NPA is inserted with the bevel toward:",options:["The lateral wall","The septum","The floor","Upward"],answer:1,why:"Bevel to the septum reduces turbinate trauma."},{q:"A key feature of second-generation SGAs:",options:["Single lumen","Gastric drainage channel","No cuff","Requires laryngoscope"],answer:1,why:"Drain channel, bite block and higher seal pressure."},{q:"An i-gel size 4 is for about:",options:["10\u201325 kg","30\u201360 kg","50\u201390 kg",">90 kg"],answer:2,why:"Manufacturer guide: size 4 for 50\u201390 kg."},{q:"SGAs are most likely to fail with:",options:["Edentulous patients","Obstruction below the glottis","Normal lungs","Neutral head position"],answer:1,why:"They seal above the glottis."},{q:"Hyperangulated video laryngoscopy requires:",options:["A straight stylet","A rigid stylet shaped to the blade curve","No stylet","Cricoid pressure"],answer:1,why:"The tube must follow the steep curve."},{q:"Main field limitation of video laryngoscopy:",options:["Needs neck extension","Blood and secretions on the camera","Cannot use a bougie","Slower than direct"],answer:1,why:"Contamination blinds the lens."},{q:"Retroglottic devices like the King LT sit with the tip in the:",options:["Trachea","Oesophagus","Nasopharynx","Vallecula"],answer:1,why:"Distal tip and balloon in the oesophagus."},{q:"Absence of resistance as a bougie is advanced deeply suggests:",options:["Tracheal placement","Oesophageal placement","Bronchospasm","Mainstem"],answer:1,why:"Trachea gives clicks and hold-up; the oesophagus does not."},{q:"A patient with a strong gag reflex needs an airway adjunct while awaiting RSI. Best choice:",options:["OPA","NPA","SGA","None"],answer:1,why:"NPAs are tolerated with an intact gag."}],sources:[{title:"StatPearls: Laryngeal mask airway",url:"https://www.ncbi.nlm.nih.gov/books/?term=Laryngeal+mask+airway+StatPearls"},{title:"Driver BE et al. Bougie vs stylet for first-attempt success (BEAM). JAMA (2018)",url:"https://jamanetwork.com/journals/jama/fullarticle/2686035"}]};var W={id:"fpc-peri-arrest",domain:"airway",ref:"III.9",title:"Peri-intubation cardiac arrest",summary:"Why critically ill patients arrest around intubation, how to predict who will, and the resuscitation bundle that prevents it.",objectives:["List the mechanisms of peri-intubation arrest: hypoxaemia, hypotension, acidosis and RV failure.","Apply a pre-intubation resuscitation bundle with measurable targets.","Manage post-intubation hypotension and arrest."],sections:[{id:"scope",title:"How often and why",core:!0,body:["In critically ill adults, cardiac arrest occurs in a few percent of emergency intubations, far more often than in the operating room. Severe hypoxaemia and cardiovascular collapse (a systolic pressure below about 65 mmHg or a new vasopressor requirement) are each common. Most arrests happen within minutes of induction and many are pulseless electrical activity or bradycardia.","Four mechanisms combine. Hypoxaemia from apnoea in a patient with poor reserve. Hypotension from loss of sympathetic tone with induction and reduced venous return from positive pressure. Worsening acidosis when a compensating patient becomes apnoeic and is then under-ventilated. And right-ventricular failure when hypoxia, hypercapnia and positive pressure raise pulmonary vascular resistance in a ventricle already at its limit."],list:{caption:"Red flags for peri-intubation arrest",items:["SpO\u2082 < 93 % despite pre-oxygenation","Systolic BP < 90 mmHg or shock index > 0.9","Severe metabolic acidosis (pH < 7.1\u20137.2, high compensatory minute ventilation)","Known pulmonary hypertension or RV dysfunction, massive PE","Older age, obesity, multiple intubation attempts"]}},{id:"bundle",title:"Resuscitate before you intubate",core:!0,body:["Hypoxaemia: optimise pre-oxygenation with NIV or a PEEP valve, use apnoeic oxygenation, ventilate gently during apnoea if needed, and aim for first-pass success.","Hypotension: treat volume depletion with fluid or blood, start or increase a vasopressor infusion before induction (many teams target a systolic pressure above about 90\u2013100 or MAP above 65 before proceeding), have push-dose vasopressors ready, and reduce the induction dose. Avoid propofol in shock.","Acidosis: minimise apnoea time; immediately after intubation set a minute ventilation matching the pre-intubation effort. Some clinicians consider bicarbonate in extreme acidaemia as a bridge, though evidence is limited.","RV failure: avoid hypotension and hypoxia; consider an inhaled pulmonary vasodilator if available; use modest PEEP and tidal volumes; consider awake or delayed approaches and the smallest possible induction dose."],example:{case:"GI bleed, haemoglobin 6.1, BP 84/50, HR 132, confused and vomiting blood. Airway protection is needed before a 50-minute flight.",steps:["Threats: haemorrhagic shock (hypotension), aspiration, low oxygen-carrying capacity.","Transfuse blood products before induction; aim for a better pressure; norepinephrine or push-dose pressor ready.","Head-up, SALAD-ready suction, pre-oxygenate.","Reduced-dose ketamine plus full-dose rocuronium; first-pass with video laryngoscope and bougie.","Post-intubation: modest PEEP, continue transfusion, recheck BP within one to two minutes."]}},{id:"after",title:"Post-intubation hypotension and arrest",core:!0,body:["Check pressure every one to three minutes after induction. If it falls: give a push-dose vasopressor, increase the infusion, reduce PEEP and tidal volume temporarily if positive pressure is limiting venous return, rule out tension pneumothorax and auto-PEEP by disconnecting briefly, and treat bleeding.","If the patient arrests, start high-quality CPR and follow ACLS, and look for reversible causes particular to this setting: hypoxia (tube position, DOPE), hypovolaemia, tension pneumothorax, acidosis, hyperkalaemia (succinylcholine in a susceptible patient), and auto-PEEP. Disconnecting the ventilator for 30\u201360 seconds treats breath stacking."]}],keyPoints:["Peri-intubation arrest is common in the critically ill and mostly physiological, not technical.","Hypoxaemia, hypotension, acidosis and RV failure \u2014 resuscitate each before induction.","Vasopressor running or drawn, induction dose reduced, first-pass success.","Match minute ventilation after intubation in acidosis.","Post-induction: check BP every few minutes; in arrest think DOPE, auto-PEEP, potassium."],pearls:["Shock index above 0.9 predicts post-intubation hypotension.","Disconnecting the ventilator is a 30-second test for stacking."],pitfalls:['Intubating a hypotensive patient "to get it done" before resuscitation.',"Missing hyperkalaemia from succinylcholine in renal failure."],live:[{id:"lines-shock-states",label:"Shock states at the bedside"},{id:"hyperk-signature",label:"Hyperkalaemia: the membrane, the ECG, the rescue"}],questions:[{q:"Most peri-intubation arrests in the critically ill are caused by:",options:["Failure to place the tube","Physiological derangement (hypoxia, hypotension)","Drug allergy","Equipment failure"],answer:1,why:"Physiology, not technique, drives most arrests."},{q:"A shock index above about ___ predicts post-intubation hypotension:",options:["0.5","0.7","0.9","1.5"],answer:2,why:"SI > 0.9 is a common threshold."},{q:"Which is part of the pre-intubation bundle for hypotension?",options:["Full-dose propofol","Vasopressor running or drawn up","High PEEP","Delaying blood"],answer:1,why:"Prepare and start vasopressors before induction."},{q:"After intubation the BP falls to 70/40 and peak pressures are high. A quick diagnostic step:",options:["Increase PEEP","Disconnect the ventilator briefly","Give propofol","Increase rate"],answer:1,why:"Rules out auto-PEEP; consider tension pneumothorax."},{q:"An arrest one minute after succinylcholine in a dialysis patient suggests:",options:["Hypoglycaemia","Hyperkalaemia","Hypocalcaemia","Anaphylaxis to rocuronium"],answer:1,why:"Succinylcholine raises potassium."},{q:"In a patient with RV failure, avoid:",options:["Hypotension and hypoxia","Small induction doses","Modest PEEP","Inhaled pulmonary vasodilators"],answer:0,why:"Both worsen RV perfusion and afterload."},{q:"Common rhythms in peri-intubation arrest:",options:["VF only","PEA and bradycardia","Atrial flutter","Torsades only"],answer:1,why:"Hypoxic and hypotensive arrests are often PEA/brady."},{q:"Best induction choice in haemorrhagic shock, given the options:",options:["Propofol 2 mg/kg","Reduced-dose ketamine","Midazolam 0.3 mg/kg","Thiopental"],answer:1,why:"Ketamine at reduced dose best preserves BP."},{q:"Gentle bag-mask ventilation during the apnoeic period:",options:["Increases arrest risk","Reduces severe hypoxaemia in high-risk patients","Is contraindicated","Replaces pre-oxygenation"],answer:1,why:"Low-pressure ventilation reduces desaturation."},{q:"After intubating a pH 7.02 septic patient, ventilate:",options:["RR 12","At the patient's pre-intubation minute ventilation","With permissive hypercapnia","Only with PS"],answer:1,why:"Maintain compensation."}],sources:[{title:"Russotto V et al. Intubation practices and adverse peri-intubation events in critically ill patients (INTUBE). JAMA (2021)",url:"https://jamanetwork.com/journals/jama/fullarticle/2777606"},{title:"Mosier JM et al. The physiologically difficult airway. West J Emerg Med (2015)",url:"https://pubmed.ncbi.nlm.nih.gov/26759643/"}]},G={id:"fpc-trach",domain:"airway",ref:"III.10",title:"Tracheostomy, laryngectomy and special airways",summary:"Telling a tracheostomy from a laryngectomy, managing the blocked or displaced tracheostomy, and the airway in angioedema, burns, trauma and obesity.",objectives:["Distinguish a patient who can be oxygenated from above (tracheostomy) from one who cannot (laryngectomy).","Follow an emergency algorithm for a blocked or displaced tracheostomy.","Anticipate special airway problems: angioedema, inhalation injury, penetrating neck trauma, obesity."],sections:[{id:"neck",title:"Neck breather or not?",core:!0,body:["A tracheostomy is an opening into the trachea; the upper airway is still connected to the lungs. These patients can, in principle, be oxygenated from the mouth and nose, or intubated orally, once the stoma is covered.","A laryngectomy removes the larynx and brings the trachea out as an end stoma; there is no connection between the mouth and the lungs. Oxygen must go to the stoma. Oral intubation is impossible. Bedside signs, wristbands and the patient's own information should make clear which type you are dealing with."]},{id:"blocked",title:"The blocked or displaced tracheostomy",core:!0,body:["Call for help, apply oxygen to both the face and the stoma, and assess patency. Remove any speaking valve or cap, remove the inner cannula if present (many blockages are in the inner tube), and pass a suction catheter. If the catheter passes easily, the tube is likely patent: continue assessment and ventilate.","If the catheter will not pass, deflate the cuff and reassess. If the patient is still not breathing adequately, remove the tracheostomy tube. Then oxygenate: for a tracheostomy, by standard upper-airway methods with the stoma covered, or via the stoma with a paediatric face mask or a laryngeal mask applied to the stoma; for a laryngectomy, via the stoma only.","Secondary steps: oral intubation (tracheostomy patients only) or intubation of the stoma with a smaller tracheostomy or endotracheal tube, ideally over a bougie or with a fibreoptic scope. A new or fresh tracheostomy (less than about 7 days) has an immature tract that may close or allow a false passage, so recannulation is riskier."],list:{caption:"Emergency tracheostomy algorithm (adapted)",items:["Call for help; oxygen to face and stoma.","Remove speaking valve or cap and inner cannula.","Can you pass a suction catheter? Yes \u2192 ventilate and reassess.","No \u2192 deflate the cuff; reassess.","Still failing \u2192 remove the tracheostomy tube.","Oxygenate: upper airway (trach) or stoma (laryngectomy).","Secondary airway: oral intubation (trach only) or stoma intubation."],ordered:!0}},{id:"special",title:"Special airways",core:!0,body:["Angioedema: from ACE inhibitors (bradykinin-mediated, does not respond reliably to adrenaline or antihistamines), hereditary angioedema, or anaphylaxis (histamine-mediated, responds to IM adrenaline). Look for voice change, stridor, drooling and tongue or floor-of-mouth swelling. An awake fibreoptic nasal approach by an expert, with a surgical airway prepared, is often preferred when swelling is progressing.","Inhalation injury: soot in the airway, facial burns, singed nasal hair, hoarseness or stridor after fire in an enclosed space. Swelling progresses over hours, worsened by resuscitation fluids. Early intubation with a large tube (7.5\u20138.0 or more for bronchoscopy) before transport is often indicated when signs of airway involvement exist.","Penetrating neck trauma: an expanding haematoma can distort and compress the airway. Avoid blind techniques that may enter a false passage; consider an awake approach or early surgical airway with a surgeon present. Airway injury with air bubbling from the wound may be intubated directly through the wound in extremis.","Obesity: rapid desaturation, difficult mask ventilation and difficult surgical airway. Ramp, head up, pre-oxygenate with PEEP, use apnoeic oxygenation and video laryngoscopy, and mark the membrane by ultrasound if possible."]}],keyPoints:["Tracheostomy: upper airway still connected. Laryngectomy: oxygenate the stoma only.","Blocked trach: oxygen to face and stoma, remove inner cannula, suction, deflate cuff, remove tube if failing.","Fresh tracheostomies (< about 7 days) recannulate poorly.","ACE-inhibitor angioedema does not respond reliably to adrenaline.","Inhalation injury swells over hours: intubate early with a large tube when the airway is involved."],pearls:["Most trach blockages are in the inner cannula.","A paediatric mask over a stoma oxygenates well."],pitfalls:["Trying to bag-mask a laryngectomy patient through the mouth.","Waiting for stridor before intubating an airway burn on a long flight."],questions:[{q:"A laryngectomy patient needs oxygen. Apply it to:",options:["Mouth and nose","The stoma","Both equally","Neither"],answer:1,why:"There is no connection between upper airway and lungs."},{q:"First step for a blocked tracheostomy after calling for help and oxygen:",options:["Remove the tube immediately","Remove the inner cannula and suction","Oral intubation","Cricothyrotomy"],answer:1,why:"Inner cannula blockage is common."},{q:"A suction catheter will not pass a tracheostomy tube. Next step:",options:["Inflate the cuff","Deflate the cuff and reassess","Insert a smaller suction catheter","Give sedation"],answer:1,why:"Deflating the cuff may allow airflow around the tube."},{q:"A tracheostomy placed 3 days ago is displaced. Main concern:",options:["Mature tract","Immature tract \u2014 recannulation risk and false passage","Infection only","No concern"],answer:1,why:"Fresh tracts may close or create false passages."},{q:"ACE-inhibitor angioedema is mediated by:",options:["Histamine","Bradykinin","IgE","Leukotrienes"],answer:1,why:"Bradykinin; adrenaline and antihistamines are often ineffective."},{q:"Which suggests airway involvement in a burn victim?",options:["Burns to the legs","Carbonaceous sputum and hoarseness","Normal voice","Isolated hand burn"],answer:1,why:"Soot and voice change indicate inhalation injury."},{q:"Preferred tube size when intubating an inhalation injury adult:",options:["6.0","7.5\u20138.0 or larger","5.0","SGA only"],answer:1,why:"Large tubes allow bronchoscopy and secretion clearance."},{q:"An expanding neck haematoma after a stab wound:",options:["Use blind nasal intubation","Prepare for awake or surgical airway with expert help","Delay airway","Use NPA only"],answer:1,why:"Distorted anatomy risks false passages."},{q:"Can a tracheostomy patient be orally intubated?",options:["Never","Yes, upper airway remains connected","Only with a laryngectomy","Only with a cuffed trach"],answer:1,why:"Cover the stoma and intubate from above if needed."},{q:"Best oxygenation via a stoma when no trach tube is in place:",options:["Nasal cannula","Paediatric face mask or LMA over the stoma","Venturi to mouth","NRB to mouth"],answer:1,why:"Small masks seal over a stoma."}],sources:[{title:"National Tracheostomy Safety Project: emergency algorithms",url:"https://www.tracheostomy.org.uk/healthcare-staff/emergency-care"},{title:"StatPearls: Angioedema",url:"https://www.ncbi.nlm.nih.gov/books/?term=Angioedema+StatPearls"}]},z={id:"fpc-tube-confirm",domain:"airway",ref:"III.11",title:"Tube confirmation and monitoring",summary:"Waveform capnography as the standard for confirmation, the limits of every other sign, securing and depth, and continuous monitoring through transport.",objectives:["Confirm endotracheal placement with waveform capnography and explain why other signs are unreliable.","Interpret an absent or decaying capnogram after intubation.","Secure the tube, document depth and monitor cuff pressure."],sections:[{id:"standard",title:"The standard: sustained waveform capnography",core:!0,body:['A sustained, rectangular capnography waveform over several breaths confirms that the tube delivers gas to and from perfused lungs. Professional guidelines treat continuous waveform capnography as mandatory for confirmation and monitoring of every intubated patient, including during transport. "No trace = wrong place" until proven otherwise.',"An oesophageal tube may briefly show CO\u2082 if the stomach contains exhaled gas from mask ventilation or carbonated drinks, but the trace decays to zero within a few breaths. A tube above the cords can show a trace but will leak and dislodge.","In cardiac arrest, CO\u2082 delivery to the lungs falls with low flow, but high-quality CPR usually produces a measurable, if low, waveform. A flat trace during CPR should prompt reassessment of tube position (visualise with the laryngoscope) rather than acceptance."]},{id:"other",title:"Other signs and their limits",body:["Visualising the tube pass through the cords is strong evidence at the time but does not protect against later displacement. Breath sounds are unreliable in noisy aircraft and may be transmitted from the stomach. Chest rise, misting of the tube and colorimetric CO\u2082 detectors support placement but are less reliable than waveforms. Ultrasound can show tracheal versus oesophageal placement and bilateral lung sliding. A chest X-ray shows depth, not tracheal versus oesophageal placement.","Oesophageal detector devices (bulb or syringe) are unreliable in obesity, pregnancy and with copious secretions. Pulse oximetry falls late after oesophageal intubation, particularly after good pre-oxygenation \u2014 saturation can remain high for minutes with the tube in the oesophagus."]},{id:"depth",title:"Depth, securing and cuff pressure",core:!0,body:["In adults, a depth of about 21 cm at the incisors in women and 23 cm in men is typical; in children over about two years, three times the tube size or (age \xF7 2) + 12 cm at the lips. Confirm bilateral air entry and, when available, imaging or ultrasound. Document the depth and recheck it after every move.","Neck flexion moves the tube tip toward the carina; extension moves it toward the cords. In small children a few centimetres of movement can extubate or cause mainstem intubation.","Cuff pressure should be about 20\u201330 cmH\u2082O, measured with a manometer. Over-inflation causes tracheal mucosal ischaemia; under-inflation allows aspiration and leak. At altitude in unpressurised cabins, air in the cuff expands; check and adjust."]},{id:"monitor",title:"Continuous monitoring in transport",core:!0,body:['Keep capnography connected from intubation to handover. A sudden loss of the waveform means displacement, disconnection or obstruction until proven otherwise; a sudden fall to a low value suggests cardiac arrest or massive embolism; a gradual rise suggests hypoventilation or rising metabolism; a "shark-fin" upstroke suggests bronchospasm or obstruction.',"Before every move \u2014 onto the stretcher, into the aircraft, at the receiving facility \u2014 recheck depth and waveform. Many unplanned extubations occur during these transfers."]}],keyPoints:["Sustained waveform capnography is the standard for confirmation and continuous monitoring.","No trace = wrong place, including during CPR \u2014 re-look with the laryngoscope.","Breath sounds, colour change and SpO\u2082 are unreliable alone.","Typical adult depth 21 (female) / 23 (male) cm at teeth; children 3 \xD7 tube size.","Cuff pressure 20\u201330 cmH\u2082O; it rises with altitude."],pearls:["Neck flexion pushes the tube in; extension pulls it out.","SpO\u2082 can stay high for minutes after oesophageal intubation."],pitfalls:['Accepting a flat capnogram during CPR as "low flow".',"Moving the patient without rechecking depth and trace."],questions:[{q:"The most reliable confirmation of ETT placement:",options:["Breath sounds","Colorimetric detector","Sustained waveform capnography","Chest X-ray"],answer:2,why:"Sustained waveforms over several breaths confirm ventilation of perfused lungs."},{q:"A capnogram shows CO\u2082 for 3 breaths then falls to zero. Most likely:",options:["Tracheal placement","Oesophageal placement","Bronchospasm","Hyperventilation"],answer:1,why:"Gastric CO\u2082 washes out within a few breaths."},{q:"During CPR the trace is flat. You should:",options:["Accept it as low flow","Reconfirm placement with laryngoscopy","Increase compression rate only","Stop CPR"],answer:1,why:"High-quality CPR usually yields a waveform."},{q:"A chest X-ray can confirm:",options:["Tracheal vs oesophageal placement reliably","Tube depth","Cuff pressure","Ventilation adequacy"],answer:1,why:"It shows depth, not reliably oesophageal placement."},{q:"Neck flexion moves the tube tip:",options:["Toward the cords","Toward the carina","Not at all","Laterally"],answer:1,why:"Flexion pushes the tube deeper."},{q:"Target cuff pressure:",options:["5\u201310 cmH\u2082O","20\u201330 cmH\u2082O","40\u201350 cmH\u2082O","60 cmH\u2082O"],answer:1,why:"Prevents ischaemia and leak."},{q:"Tube depth at the lips for a 6-year-old with a 5.5 tube:",options:["About 12 cm","About 16\u201317 cm","About 22 cm","About 8 cm"],answer:1,why:"3 \xD7 5.5 = 16.5 cm or (6/2)+12 = 15 cm."},{q:"Why is SpO\u2082 a poor early sign of oesophageal intubation?",options:["Oximeters are inaccurate","Pre-oxygenation keeps saturation high for minutes","It reads too low","It measures CO\u2082"],answer:1,why:"Desaturation is delayed."},{q:"A sudden loss of the waveform mid-flight most likely means:",options:["Improved ventilation","Displacement, disconnection or obstruction","Hyperthermia","Normal variation"],answer:1,why:"Treat as displacement until proven otherwise."},{q:"Typical adult male depth at the incisors:",options:["17 cm","19 cm","23 cm","28 cm"],answer:2,why:"About 23 cm in men, 21 cm in women."}],sources:[{title:"Cook TM et al. NAP4: major complications of airway management. Br J Anaesth (2011)",url:"https://www.nationalauditprojects.org.uk/NAP4_home"},{title:"AHA guidelines for CPR and ECC: advanced airway confirmation",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"}]};var U={id:"fpc-suction",domain:"airway",ref:"III.12",title:"Airway suctioning",summary:"Oral, nasal and endotracheal suction: equipment, pressures, catheter sizing, technique and complications, and decontaminating a soiled airway.",objectives:["Choose suction equipment and catheter size for oral and endotracheal suction.","Perform endotracheal suctioning safely, limiting hypoxaemia and trauma.","Manage massive airway contamination."],sections:[{id:"equipment",title:"Equipment and settings",core:!0,body:["Rigid (Yankauer or large-bore) catheters clear the oropharynx of blood, vomit and particulate matter. Large-bore rigid catheters clear thick material far faster than standard Yankauers. Soft (French) catheters pass through endotracheal and tracheostomy tubes or the nose.","Typical suction pressures are 80\u2013120 mmHg for endotracheal suction in adults (lower in children and neonates, often 60\u2013100 mmHg and 60\u201380 mmHg respectively); oropharyngeal clearance of heavy contamination may use higher settings. Follow your device and protocol.","Size an endotracheal suction catheter so it occludes no more than about half the internal diameter of the tube; a quick rule is catheter size in French \u2248 2 \xD7 the tube size in mm (for example, a 14 Fr catheter for a 7.0 tube). Too large a catheter can evacuate the lungs and cause atelectasis."]},{id:"technique",title:"Endotracheal suction technique",core:!0,body:["Pre-oxygenate with FiO\u2082 1.0 for 30\u201360 seconds. Insert the catheter without suction to the carina or until resistance, withdraw 1 cm, then apply suction while withdrawing with a rotating motion. Limit each pass to about 10\u201315 seconds in adults (shorter in children). Allow re-oxygenation between passes.","Closed in-line suction systems allow suctioning without disconnecting the ventilator, preserving PEEP and reducing aerosol exposure \u2014 preferable in ARDS, high PEEP, and infectious disease. Routine saline instillation is not recommended: it can worsen oxygenation and spread contamination.","Watch for hypoxaemia, bradycardia (vagal stimulation), arrhythmias, raised intracranial pressure, mucosal trauma and bleeding, and bronchospasm."]},{id:"contaminated",title:"The contaminated airway",core:!0,body:["Massive regurgitation or haemorrhage defeats laryngoscopy and fills the lungs. Position head-up if possible, use a large-bore rigid suction catheter, and lead with it during laryngoscopy (suction-assisted laryngoscopy and airway decontamination, SALAD). After clearing the oropharynx, park the catheter in the upper oesophagus to the left of the blade to control ongoing regurgitation.","After intubation, suction through the tube before ventilating if aspirated material is present; bronchoscopy at the receiving centre may be needed for particulate aspiration."]}],keyPoints:["Rigid large-bore catheters for the mouth; soft catheters for tubes.","Catheter French size \u2248 2 \xD7 ETT size (\u2264 half the lumen).","Pre-oxygenate; suction on withdrawal only; 10\u201315 s per pass in adults.","Closed in-line suction preserves PEEP; avoid routine saline.","SALAD for massive contamination."],pearls:["A standard Yankauer clogs with thick vomit \u2014 carry a large-bore option."],pitfalls:["Prolonged suction passes in hypoxaemic children.","Routine saline instillation."],questions:[{q:"Appropriate suction catheter for a 7.5 ETT:",options:["8 Fr","14 Fr","20 Fr","24 Fr"],answer:1,why:"\u2248 2 \xD7 7.5 = 15; choose 14 Fr (\u2264 half the lumen)."},{q:"Apply suction during:",options:["Insertion","Withdrawal","Both","Neither"],answer:1,why:"Insert without suction, then suction while withdrawing."},{q:"Maximum duration of a single adult suction pass:",options:["5 s","10\u201315 s","30 s","60 s"],answer:1,why:"Limits hypoxaemia."},{q:"Closed in-line suction is preferred in:",options:["Low PEEP","ARDS with high PEEP","Spontaneous breathing without a tube","Oral suction"],answer:1,why:"Preserves PEEP and reduces aerosol."},{q:"Routine saline instillation before suctioning:",options:["Recommended","Not recommended","Required for thick secretions","Improves oxygenation"],answer:1,why:"It can worsen oxygenation."},{q:"A vagal response to suction causes:",options:["Tachycardia","Bradycardia","Hypertension only","Hyperthermia"],answer:1,why:"Vagal stimulation slows the heart."},{q:"Typical adult ET suction pressure:",options:["20\u201340 mmHg","80\u2013120 mmHg","200\u2013300 mmHg","400 mmHg"],answer:1,why:"Protocol ranges commonly 80\u2013120 mmHg."},{q:"In SALAD, after clearing the pharynx the suction catheter is parked:",options:["In the trachea","In the upper oesophagus left of the blade","Outside the mouth","In the nose"],answer:1,why:"It controls ongoing regurgitation."},{q:"Too large a suction catheter can cause:",options:["Atelectasis","Hyperinflation","Hyperkalaemia","Hypertension only"],answer:0,why:"It evacuates lung volume."},{q:"Before ET suction, pre-oxygenate with:",options:["Room air","FiO\u2082 1.0 for 30\u201360 s","No oxygen","Nitrous oxide"],answer:1,why:"Reduces suction-induced hypoxaemia."}],sources:[{title:"AARC Clinical Practice Guideline: endotracheal suctioning of mechanically ventilated patients (2010)",url:"https://www.aarc.org/wp-content/uploads/2014/08/06.10.0758.pdf"},{title:"Root CW et al. Suction-assisted laryngoscopy and airway decontamination (SALAD). Resuscitation (2020)",url:"https://pubmed.ncbi.nlm.nih.gov/31739032/"}]},K={id:"fpc-capnography",domain:"airway",ref:"III.13",title:"Waveform capnography",summary:"The four phases of the capnogram, what each abnormal shape means, the PaCO\u2082\u2013EtCO\u2082 gap, and capnography in cardiac arrest, sedation and head injury.",objectives:["Name the phases of a normal capnogram.","Recognise bronchospasm, rebreathing, leak, oesophageal placement, hypoventilation and arrest on the waveform.","Use EtCO\u2082 in CPR, ROSC detection, sedation and brain injury."],sections:[{id:"phases",title:"The normal capnogram",core:!0,body:["Phase I is the inspiratory baseline, near zero, as dead-space gas without CO\u2082 leaves first. Phase II is the expiratory upstroke as alveolar gas mixes with dead space. Phase III is the alveolar plateau, ending in the end-tidal value (normally 35\u201345 mmHg). Phase 0 (sometimes called phase IV) is the inspiratory downstroke as fresh gas enters.","EtCO\u2082 is usually 2\u20135 mmHg below PaCO\u2082 in healthy lungs. The gap widens with dead space: low cardiac output, pulmonary embolism, COPD, overdistension, and hypovolaemia. In those patients EtCO\u2082 underestimates PaCO\u2082, so trend EtCO\u2082 against a blood gas."],table:{caption:"Waveform patterns",head:["Pattern","Meaning"],rows:[["Sustained normal rectangles","Tracheal tube, ventilating perfused lungs"],["Decay to zero over a few breaths","Oesophageal intubation"],["Sudden loss of waveform","Disconnection, displacement, complete obstruction"],['"Shark fin" (sloped upstroke, no plateau)',"Bronchospasm, COPD, partial obstruction"],["Baseline does not return to zero","Rebreathing (exhausted absorber, insufficient flow, valve failure)"],["Gradually rising EtCO\u2082","Hypoventilation, rising metabolism (fever, MH), bicarbonate"],["Sudden fall in EtCO\u2082","Cardiac arrest, massive PE, sudden hypotension, leak"],['Cleft in the plateau ("curare cleft")',"Spontaneous effort against the ventilator"]]}},{id:"arrest",title:"Capnography in cardiac arrest",core:!0,body:["During CPR, EtCO\u2082 reflects pulmonary blood flow generated by compressions. A value persistently below about 10 mmHg suggests poor-quality compressions \u2014 change compressors, check depth and rate \u2014 or a very poor prognosis when it persists after prolonged resuscitation despite good CPR (interpreted alongside other factors, never alone).","A sudden rise in EtCO\u2082 (often to 35\u201345 mmHg or more) during compressions is an early sign of return of spontaneous circulation, often before a pulse is palpable. Bicarbonate administration also transiently raises EtCO\u2082, which must be distinguished from ROSC."]},{id:"uses",title:"Other uses",core:!0,body:["Sedation and opioids: nasal-oral capnography detects hypoventilation and apnoea before oxygen saturation falls, particularly when supplemental oxygen keeps SpO\u2082 high.","Brain injury: target normocapnia (PaCO\u2082 35\u201340). Establish the PaCO\u2082\u2013EtCO\u2082 gap with a blood gas, then ventilate to the EtCO\u2082 that corresponds; hyperventilate only briefly for signs of herniation.","Metabolic acidosis: in a spontaneously breathing patient a very low EtCO\u2082 reflects respiratory compensation (for example, in DKA); after intubation, preserving that low CO\u2082 is essential.","Shock: falling EtCO\u2082 at constant ventilation suggests falling cardiac output."],example:{case:"A ventilated TBI patient: EtCO\u2082 30, PaCO\u2082 on the gas 38, BP 84/50.",steps:["The gap is 8 mmHg \u2014 wider than normal, consistent with reduced pulmonary perfusion from hypotension.","PaCO\u2082 is already in the normocapnic target; do not increase ventilation to push EtCO\u2082 up.","Treat the hypotension to protect cerebral perfusion; recheck the gap after resuscitation."]}}],keyPoints:["Phases: I baseline, II upstroke, III plateau (EtCO\u2082), 0 downstroke.","EtCO\u2082 normally 2\u20135 below PaCO\u2082; the gap widens with dead space and low output.","Shark fin = bronchospasm; non-zero baseline = rebreathing; decay to zero = oesophagus.","CPR: EtCO\u2082 < 10 \u2192 improve compressions; sudden rise \u2192 ROSC.","Capnography detects hypoventilation before SpO\u2082 in sedated patients."],pearls:["Calibrate the EtCO\u2082 target to a blood gas in brain injury.","Bicarbonate causes a transient EtCO\u2082 rise that mimics ROSC."],pitfalls:["Using EtCO\u2082 as a direct PaCO\u2082 substitute in shock.","Relying on SpO\u2082 alone for sedation monitoring on oxygen."],live:[{id:"hypox",label:"Why is the PaO\u2082 low? (dead space)"},{id:"vbg",label:"ABG or VBG?"}],questions:[{q:"Phase III of the capnogram is:",options:["Inspiratory baseline","Expiratory upstroke","Alveolar plateau","Inspiratory downstroke"],answer:2,why:"The plateau ends at end-tidal CO\u2082."},{q:"A shark-fin waveform suggests:",options:["Oesophageal tube","Bronchospasm","Rebreathing","ROSC"],answer:1,why:"Obstructed expiration slopes the upstroke."},{q:"Baseline that fails to return to zero indicates:",options:["Hypoventilation","Rebreathing","Bronchospasm","Leak"],answer:1,why:"Inspired gas contains CO\u2082."},{q:"During CPR, EtCO\u2082 of 8 mmHg should prompt:",options:["Stopping CPR immediately","Improving compression quality","Giving bicarbonate","Extubation"],answer:1,why:"Low EtCO\u2082 suggests poor compressions."},{q:"An abrupt EtCO\u2082 rise from 15 to 40 during CPR most likely indicates:",options:["Displacement","ROSC","Hypoventilation","Bronchospasm"],answer:1,why:"Increased pulmonary flow with ROSC."},{q:"The PaCO\u2082\u2013EtCO\u2082 gap widens with:",options:["Healthy lungs","Pulmonary embolism","Hyperventilation","Normal output"],answer:1,why:"Dead space increases the gap."},{q:"Sedated patient on 4 L O\u2082, SpO\u2082 99 %, EtCO\u2082 rising with slow RR. Concern:",options:["None","Hypoventilation","Hyperventilation","Shunt"],answer:1,why:"Capnography detects hypoventilation before desaturation."},{q:"A cleft in the plateau indicates:",options:["Spontaneous effort","Leak","Oesophagus","Arrest"],answer:0,why:"Patient effort against the ventilator."},{q:"Normal EtCO\u2082 range:",options:["10\u201320","35\u201345","50\u201360","70\u201380 mmHg"],answer:1,why:"35\u201345 mmHg."},{q:"In a ventilated TBI patient with a known 6 mmHg gap, to achieve PaCO\u2082 38 target EtCO\u2082 of about:",options:["26","32","38","44"],answer:1,why:"38 \u2212 6 = 32 mmHg."}],sources:[{title:"StatPearls: Capnography",url:"https://www.ncbi.nlm.nih.gov/books/?term=Capnography+StatPearls"},{title:"AHA guidelines for CPR and ECC: physiological monitoring during CPR",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"}]},_={id:"fpc-nippv",domain:"airway",ref:"III.14",title:"Non-invasive positive pressure ventilation",summary:"CPAP and BiPAP: physiology, indications, contraindications, settings, monitoring, failure criteria, and high-flow nasal oxygen.",objectives:["Explain how CPAP and BiPAP improve oxygenation and ventilation.","Select patients and contraindications for NIV in transport.","Set and titrate NIV and recognise failure early."],sections:[{id:"physiology",title:"How it works",core:!0,body:["CPAP applies one continuous pressure throughout the breath. It recruits collapsed alveoli and increases FRC, reducing shunt and improving oxygenation; in cardiogenic pulmonary oedema it reduces preload and LV afterload by raising intrathoracic pressure; it splints open the upper airway in obstructive sleep apnoea; and it offsets auto-PEEP, reducing the work of triggering in COPD.","BiPAP (bilevel) adds a higher inspiratory pressure (IPAP) above the expiratory pressure (EPAP, equivalent to PEEP). The difference, the pressure support, augments tidal volume and so improves ventilation and CO\u2082 clearance \u2014 the key indication being hypercapnic COPD exacerbation."]},{id:"select",title:"Who benefits, who must not",core:!0,body:["Strong evidence supports NIV in acute hypercapnic COPD exacerbation (pH roughly 7.25\u20137.35) and cardiogenic pulmonary oedema. It is also used for pre-oxygenation, in immunocompromised patients with respiratory failure, and in selected asthma and pneumonia patients with close monitoring.","Contraindications: respiratory or cardiac arrest, inability to protect the airway or clear secretions, severely depressed consciousness (except hypercapnic narcosis expected to improve quickly), vomiting or upper GI bleeding, facial trauma or burns preventing a seal, recent upper airway or oesophageal surgery, untreated pneumothorax, and haemodynamic instability (positive pressure lowers venous return)."],list:{caption:"Typical starting settings (adult)",items:["CPAP 5\u201310 cmH\u2082O (oedema often 8\u201310).","BiPAP: IPAP 10\u201312, EPAP 5; increase IPAP by 2\u20133 to target CO\u2082 and VT about 6\u20138 mL/kg.","FiO\u2082 titrated to SpO\u2082 88\u201392 % in COPD, 94\u201398 % otherwise.","Keep IPAP below about 20\u201325 to limit gastric insufflation."]}},{id:"monitor",title:"Monitoring and failure",core:!0,body:["Reassess within 30\u201360 minutes and continuously in transport: respiratory rate, work of breathing, SpO\u2082, EtCO\u2082 trend, mental status, leak, synchrony and blood pressure. Expected improvement: falling respiratory rate and heart rate, better comfort, improving pH and CO\u2082.","Failure signs: worsening mental status, inability to tolerate the mask, rising CO\u2082 or falling pH, persistent tachypnoea, haemodynamic instability, vomiting. Delayed intubation after failed NIV is associated with worse outcomes; in transport, where intubating mid-flight is difficult, the threshold to intubate before departure should be lower if improvement is not clear.","Altitude: mask leak and gastric distension may increase; some transport devices compensate for altitude. Communication is harder under a mask; agree hand signals."],example:{case:"COPD exacerbation: RR 32, SpO\u2082 84 % on 4 L, pH 7.27, PaCO\u2082 72, alert and cooperative. Flight time 35 minutes.",steps:["Hypercapnic respiratory acidosis with intact consciousness: ideal NIV candidate.","Start BiPAP 12/5, FiO\u2082 to SpO\u2082 88\u201392 %, bronchodilators in-line.","Reassess at 15\u201330 minutes before departure: RR, EtCO\u2082 trend, comfort. If worsening, intubate on the ground.","In flight, watch mental status and leak; plan for deterioration with drugs and equipment ready."]}},{id:"hfno",title:"High-flow nasal oxygen",body:["Heated, humidified high-flow nasal oxygen (often 30\u201360 L/min) delivers a reliable FiO\u2082, washes CO\u2082 from the anatomical dead space, produces a small positive pressure, and is comfortable. It is useful in hypoxaemic respiratory failure, for pre-oxygenation and for apnoeic oxygenation. It is oxygen-hungry, which matters for transport oxygen calculations."]}],keyPoints:["CPAP recruits lung and offloads the heart; BiPAP adds pressure support for CO\u2082.","Best evidence: hypercapnic COPD and cardiogenic pulmonary oedema.","Contraindications: arrest, can't protect airway, vomiting, facial trauma, instability, pneumothorax.","Start BiPAP 10\u201312/5; titrate IPAP for CO\u2082, EPAP/FiO\u2082 for oxygen.","Reassess early; intubate on the ground if not clearly improving before flight."],pearls:["Raise IPAP for CO\u2082, EPAP for oxygenation.","Calculate oxygen consumption for high-flow devices before departure."],pitfalls:["NIV in a vomiting, obtunded patient.","Continuing failing NIV into the aircraft."],live:[{id:"peep",label:"PEEP, recruitment and overdistension"},{id:"resp",label:"CO\u2082, pH and the kidneys"}],questions:[{q:"BiPAP improves CO\u2082 clearance mainly through:",options:["EPAP","The IPAP\u2013EPAP difference (pressure support)","FiO\u2082","Humidification"],answer:1,why:"Pressure support augments tidal volume."},{q:"The strongest NIV indication is:",options:["Pneumothorax","Hypercapnic COPD exacerbation","Facial burns","Vomiting GI bleed"],answer:1,why:"Strong evidence supports NIV here."},{q:"Which is a contraindication to NIV?",options:["Cardiogenic oedema","Active vomiting","COPD with pH 7.30","Mild hypoxaemia"],answer:1,why:"Aspiration risk."},{q:"To improve oxygenation on BiPAP, increase:",options:["IPAP only","EPAP and/or FiO\u2082","Backup rate only","Mask size"],answer:1,why:"EPAP recruits lung; FiO\u2082 raises alveolar oxygen."},{q:"CPAP helps cardiogenic pulmonary oedema by:",options:["Increasing preload","Reducing preload and LV afterload","Increasing heart rate","Diuresis"],answer:1,why:"Raised intrathoracic pressure reduces venous return and transmural LV pressure."},{q:"SpO\u2082 target for a COPD patient on NIV:",options:["100 %","94\u201398 %","88\u201392 %","80\u201385 %"],answer:2,why:"Avoid worsening hypercapnia."},{q:"An early sign of NIV failure:",options:["Falling RR","Worsening mental status","Improved comfort","Falling CO\u2082"],answer:1,why:"Deterioration in consciousness indicates failure."},{q:"Keep IPAP below about 20\u201325 cmH\u2082O to limit:",options:["Hypoxia","Gastric insufflation","CO\u2082 clearance","Leak"],answer:1,why:"Higher pressures open the oesophageal sphincter."},{q:"High-flow nasal oxygen reduces CO\u2082 partly by:",options:["Bronchodilation","Washing out anatomical dead space","Increasing tidal volume greatly","Lowering metabolism"],answer:1,why:"Dead-space washout."},{q:"A patient on NIV before a long flight is not clearly improving. Best plan:",options:["Depart and reassess in the air","Intubate on the ground","Remove NIV","Increase sedation"],answer:1,why:"Intubating in flight is harder; delayed intubation worsens outcomes."}],sources:[{title:"ERS/ATS guidelines: noninvasive ventilation for acute respiratory failure (2017)",url:"https://erj.ersjournals.com/content/50/2/1602426"},{title:"StatPearls: Noninvasive positive pressure ventilation",url:"https://www.ncbi.nlm.nih.gov/books/?term=Noninvasive+positive+pressure+ventilation+StatPearls"}]};var o=(a,i,n,r)=>({q:a,options:i,answer:n,why:r}),Q={"fpc-airway-assessment":{sections:[{id:"case",title:"Transport case: the trapped driver",body:["You land at a rural crash. A 58-year-old man is pinned in a vehicle on its side, GCS 9, snoring respirations, SpO\u2082 90 % on a non-rebreather, BP 102/64, HR 112. He has a thick neck, a beard, blood in the mouth, and fire crews estimate 20 minutes to extricate.","The assessment drives the plan. Anatomically, he predicts difficult mask ventilation (beard, obesity, blood) and difficult laryngoscopy (blood, limited access, spinal precautions). Physiologically, he is borderline hypoxaemic and his shock index is above 1. The environment \u2014 a vehicle on its side \u2014 makes intubation in place a poor choice."],example:{case:"What do you do while he is still trapped, and what changes once he is out?",steps:["Trapped: jaw thrust, suction, a nasopharyngeal airway (tolerated with a gag), high-flow oxygen; keep him breathing spontaneously rather than inducing in the wreck.","Prepare in parallel: drugs drawn and labelled, video laryngoscope and bougie, second-generation SGA sized and open, cricothyrotomy kit opened, the membrane palpated and marked when you can reach the neck.","Once out: on the stretcher at waist height, head up with in-line stabilisation, pre-oxygenate with a sealed BVM and PEEP valve plus nasal cannula at 15 L/min.","Resuscitate before induction: blood or fluid per trauma protocol, a push-dose vasopressor ready; reduced-dose ketamine, full-dose rocuronium.",'Verbalise: "Plan A video with bougie, two attempts; Plan B i-gel 5; Plan C two-person mask with adjuncts; Plan D scalpel\u2013bougie\u2013tube. Stop at 93 %."',"After intubation: waveform capnography, depth documented, analgesia and sedation started before loading."]}}],questions:[o("Which most clearly predicts a difficult surgical airway?",["Edentulism","Previous neck radiation","Mallampati II","Age 30"],1,"Radiation (the R of SMART) fibroses tissue and obscures landmarks."),o("Before induction in a predicted difficult airway, an important step is to:",["Skip the checklist to save time","Palpate and mark the cricothyroid membrane","Remove nasal oxygen","Give a larger induction dose"],1,"Marking speeds front-of-neck access if needed."),o("A patient trapped in a vehicle with a patent but snoring airway is best managed initially with:",["RSI in the vehicle","Basic manoeuvres, NPA, oxygen and preparation","Immediate cricothyrotomy","No intervention"],1,"Keep spontaneous breathing until a controlled setting is available."),o("Obstructive sleep apnoea primarily predicts difficulty with:",["Surgical airway","Mask ventilation","IV access","Capnography"],1,"OSA is part of ROMAN (obstruction)."),o('Which "physiologic" factor is most commonly associated with peri-intubation arrest?',["Mild anaemia","Hypotension before induction","Hyperglycaemia","Bradypnoea"],1,"Pre-induction hypotension predicts arrest.")]},"fpc-airway-anatomy":{sections:[{id:"case",title:"Transport case: the 14-month-old with stridor",body:["A 14-month-old with three days of cough now has inspiratory stridor at rest, intercostal recession and SpO\u2082 93 % on blow-by oxygen. Weight about 10 kg. The referring hospital has given nebulised adrenaline with partial improvement.","The anatomy explains the danger: a subglottic airway of a few millimetres, a cricoid ring that cannot expand, and resistance rising with the fourth power of the radius. Agitation converts laminar to turbulent flow and worsens the obstruction. Oxygen consumption per kilogram is roughly double an adult's, so if the airway closes, desaturation is fast."],example:{case:"How does anatomy shape your management?",steps:["Keep the child calm on a parent's lap where possible; avoid unnecessary procedures that provoke crying.","Treat the swelling: dexamethasone (if not given) and nebulised adrenaline, recognising rebound after about 2 hours.","Prepare for intubation by the most skilled operator: a tube 0.5\u20131.0 mm smaller than the age-predicted size, a straight blade available for the floppy epiglottis, a shoulder roll for the large occiput.","Plan oxygenation rescue: a paediatric SGA, two-person mask technique, and needle cricothyrotomy equipment (surgical cricothyrotomy is not appropriate at this age).","In flight: continuous SpO\u2082 and capnography if intubated; bradycardia is a pre-arrest sign of hypoxia."]}}],questions:[o("Why does crying worsen upper airway obstruction in a child?",["It reduces oxygen consumption","Turbulent flow raises resistance further","It opens the cricoid","It reduces dead space"],1,"Turbulent flow resistance rises with about the fifth power of radius."),o("In a 1-year-old with croup needing intubation, choose a tube:",["Age-predicted size","0.5\u20131.0 mm smaller than predicted","2 sizes larger","An SGA only"],1,"Subglottic swelling narrows the lumen."),o("The hyoepiglottic ligament is the reason a curved blade:",["Lifts the epiglottis indirectly from the vallecula","Must be used in infants","Cannot see the cords","Enters the oesophagus"],0,"Pressure in the vallecula tenses the ligament."),o("The carina lies approximately at:",["C6","T4\u2013T5 (angle of Louis)","T10","L1"],1,"At the sternal angle level."),o("Oxygen consumption of an infant is roughly:",["Half an adult's per kg","Equal per kg","Double per kg","Ten times per kg"],2,"About 6\u20138 vs 3\u20134 mL/kg/min.")]},"fpc-airway-pharm":{sections:[{id:"case",title:"Transport case: three patients, three drug plans",body:["The same flight team sees three patients in a week. Choosing drugs for each one shows how physiology, not habit, decides the plan."],example:{case:"Patient A: 70 kg septic shock, BP 80/45 on norepinephrine. Patient B: 70 kg isolated severe TBI, BP 150/90. Patient C: 70 kg crush injury trapped 6 hours, K\u207A unknown, ECG with peaked T waves.",steps:["A: ketamine at a reduced dose (around 0.5\u20131 mg/kg) or etomidate; rocuronium 1.2 mg/kg (full dose in slow circulation); push-dose pressor ready; avoid propofol.","B: avoid both hypotension and the sympathetic surge of laryngoscopy \u2014 an opioid such as fentanyl, a haemodynamically neutral induction agent at full dose, rocuronium; post-intubation propofol infusion if BP allows, MAP maintained for cerebral perfusion.","C: avoid succinylcholine (crush, likely hyperkalaemia); give calcium for the ECG changes, rocuronium for paralysis, and plan hyperkalaemia treatment and fluids.","All three: analgesia and sedation started within minutes of confirmation; reassess before each move and at altitude."]}}],questions:[o("Fentanyl's main role around intubation of a hypertensive head-injured patient is to:",["Paralyse","Blunt the sympathetic response to laryngoscopy","Raise BP","Reverse rocuronium"],1,"Reduces the pressor response that raises ICP."),o("Malignant hyperthermia can be triggered by:",["Rocuronium","Succinylcholine","Ketamine","Fentanyl"],1,"Succinylcholine and volatile anaesthetics trigger MH."),o("Ketamine may cause hypotension in:",["Every patient","Catecholamine-depleted shock","Hypertensive patients","Asthma"],1,"Its direct myocardial depression is unmasked."),o("Duration of succinylcholine block:",["1\u20132 min","6\u201310 min","45\u201370 min","3\u20134 h"],1,"Rapid hydrolysis by plasma cholinesterase."),o("Sugammadex dose for immediate reversal of deep rocuronium block:",["2 mg/kg","4 mg/kg","16 mg/kg","50 mg/kg"],2,"16 mg/kg for rescue reversal.")]},"fpc-passive-oxygenation":{sections:[{id:"case",title:"Transport case: the term pregnant patient",body:["A 38-week pregnant woman with eclampsia has a further seizure and remains obtunded after magnesium; she is vomiting and must be intubated before transport. SpO\u2082 95 % on a non-rebreather.","Pregnancy compresses the tank and speeds the drain: FRC falls by about a fifth as the uterus pushes up the diaphragm, oxygen consumption rises, and safe apnoea time is shorter than in a non-pregnant adult. Airway oedema and breast tissue make laryngoscopy harder, and aspiration risk is high."],example:{case:"Plan the oxygenation.",steps:["Position: head up 20\u201330\xB0 with left uterine displacement to preserve venous return.","Pre-oxygenate for at least three minutes with a sealed BVM and PEEP valve, or NIV if she tolerates it; nasal cannula at 15 L/min underneath.","Choose a smaller tube (6.0\u20137.0) for airway oedema; video laryngoscope; suction running.","Agree a stop point (for example 93 %); if reached, gentle mask ventilation with low pressures or an SGA.","After intubation, ventilate to her normal pregnancy CO\u2082 (about 30 mmHg) and keep SpO\u2082 \u2265 95 % for the fetus."]}}],questions:[o("Safe apnoea time in a term pregnant patient compared with a non-pregnant adult is:",["Longer","Shorter","The same","Unaffected by pre-oxygenation"],1,"Smaller FRC and higher consumption."),o("Which position best aids pre-oxygenation at term?",["Supine flat","Head up with left uterine displacement","Trendelenburg","Prone"],1,"Improves FRC and venous return."),o("The end-tidal oxygen target for ideal pre-oxygenation is about:",["50 %","70 %","90 %","21 %"],2,"EtO\u2082 near 90 % indicates good denitrogenation."),o("High-flow nasal oxygen during laryngoscopy works best when:",["The mouth is closed","The airway is patent (jaw thrust or blade)","The patient is breathing fast","The cuff is inflated"],1,"Patency allows bulk flow."),o("A BVM with a PEEP valve helps pre-oxygenation mainly in:",["Normal lungs","Shunt physiology","Hyperventilation","Metabolic alkalosis"],1,"PEEP recruits collapsed alveoli.")]},"fpc-failed-airway":{sections:[{id:"case",title:"Transport case: the anaphylaxis airway",body:["A 44-year-old with anaphylaxis after a bee sting has stridor, a swollen tongue and SpO\u2082 88 % despite IM adrenaline twice and an adrenaline infusion. The receiving hospital is 45 minutes away.","This is a predicted difficult airway that may fail quickly: oedema distorts anatomy, mask ventilation may be impossible, and SGAs may not seal over a swollen larynx. The plan must assume failure is likely."],example:{case:"Structure the attempt.",steps:["Maximise medical therapy: adrenaline infusion titrated, fluids, nebulised adrenaline.","Most experienced operator; video laryngoscope and a smaller tube (6.0\u20136.5); bougie; suction.","Mark the cricothyroid membrane before induction; open the scalpel\u2013bougie\u2013tube kit; assign a second clinician to the neck.","Consider an awake technique if skills allow; if RSI, double setup.","If the first attempt fails and oxygenation fails, move to the neck without delay \u2014 oedema worsens with every attempt."]}}],questions:[o(`In a "can't intubate, can oxygenate" situation, the urgency is:`,["Immediate cricothyrotomy","Time to re-oxygenate and choose a plan","Stop all oxygenation","Repeat the same attempt"],1,"Oxygenation buys time for a considered decision."),o('A "double setup" means:',["Two laryngoscopes","Preparing for surgical airway while attempting intubation","Two induction drugs","Two monitors"],1,"The neck is ready before induction."),o("Who should be empowered to call a stop during intubation?",["Only the operator","Any team member watching the monitor","Nobody","The pilot"],1,"Shared authority reduces fixation."),o("In the Vortex approach, the three upper-airway lifelines are:",["Tube, SGA, face mask","Tube, NIV, HFNO","SGA, cric, needle","Mask, cannula, NRB"],0,"Failure of all three leads to front-of-neck access."),o("External laryngeal manipulation is performed by:",["Pressing the cricoid backward blindly","The operator moving the thyroid cartilage to improve the view","The patient","Inflating the cuff"],1,"Then an assistant holds it in place.")]},"fpc-surgical-airway":{sections:[{id:"case",title:"Transport case: massive facial trauma",body:["A motorcyclist without a helmet has severe midface and mandibular fractures. Blood pours from the mouth, the face is unstable, and SpO\u2082 is 80 % despite suction and positioning. Mask ventilation is impossible and the oropharynx is unrecognisable.","Oral intubation and SGA placement are likely to fail; front-of-neck access may be the primary airway rather than a rescue. Sitting the patient forward may help drainage while preparing, if the spine assessment allows."],example:{case:"Perform the surgical airway.",steps:["Declare the plan and assign roles: operator, assistant with suction, monitor-watcher.","Extend the neck if possible; laryngeal handshake to find the membrane.","Transverse stab through skin and membrane, rotate the blade caudally, open the hole.","Bougie along the blade, 6.0 cuffed tube over the bougie, inflate cuff.","Confirm with capnography, ventilate, secure; suction the trachea through the tube; continue haemorrhage control and resuscitation."]}}],questions:[o("Primary surgical airway (rather than rescue) is most appropriate in:",["Mild facial bruising","Massive midface trauma preventing oral access","COPD","Status epilepticus"],1,"When upper airway routes are not feasible."),o("The scalpel blade most often recommended for SBT cricothyrotomy:",["Number 11","Number 10 (wide)","Number 15","Any"],1,"A wide blade makes a hole large enough for the bougie and tube."),o("Jet ventilation through a needle cric uses an I:E of roughly:",["1:1","1:4","4:1","1:10"],1,"About 1 s in, 4 s out to allow exhalation."),o("Bleeding after cricothyrotomy is usually:",["Arterial and torrential","Venous and controlled by pressure and the tube","Absent","From the carotid"],1,"Midline is relatively avascular."),o("Signs of subcutaneous emphysema after cricothyrotomy suggest:",["Correct placement","False passage or leak around the tube","Bronchospasm","Normal finding"],1,"Air tracking in tissues \u2014 reassess placement.")]},"fpc-mech-vent":{sections:[{id:"case",title:"Transport case: inter-facility ARDS transfer",body:["A 40-year-old woman, 165 cm, with influenza pneumonia is on VC: VT 550, RR 18, PEEP 8, FiO\u2082 0.8. SpO\u2082 89 %, peak 38, plateau 33. ABG pH 7.31, PaCO\u2082 52, PaO\u2082 58. You are transferring her to an ECMO centre.","Her PBW is 45.5 + 0.91 \xD7 (165 \u2212 152.4) \u2248 57 kg. A VT of 550 is about 9.6 mL/kg PBW, and the plateau of 33 exceeds the target. P/F ratio is 58/0.8 \u2248 73: severe ARDS."],example:{case:"Adjust for transport.",steps:["Reduce VT to about 340 mL (6 mL/kg PBW); increase RR to around 26\u201330 to support minute ventilation; accept a higher CO\u2082 if pH stays above about 7.20.","Increase PEEP (often 12\u201314 or per a PEEP/FiO\u2082 table) and FiO\u2082 to 1.0 for transport; recheck plateau (target \u2264 30) and driving pressure.","Ensure deep sedation and consider paralysis to prevent dyssynchrony during movement.","Use the transport ventilator on the patient for a period before leaving to confirm stability; carry a BVM with PEEP valve; calculate oxygen for the flight with a reserve.","Avoid disconnections (clamp the tube during circuit changes) to prevent derecruitment."]}}],questions:[o("P/F ratio of PaO\u2082 60 on FiO\u2082 0.6:",["36","100","160","360"],1,"60 / 0.6 = 100: severe ARDS (\u2264 100)."),o("Minimum pH commonly accepted with permissive hypercapnia:",["7.35","7.20\u20137.25","7.00","6.90"],1,"Many protocols accept pH above about 7.20\u20137.25."),o("To lower plateau pressure in ARDS, the first change is usually:",["Increase VT","Reduce VT","Increase rate only","Remove PEEP"],1,"Smaller tidal volume reduces plateau."),o("Disconnecting an ARDS patient's circuit causes:",["Recruitment","Derecruitment and desaturation","Better compliance","No change"],1,"Loss of PEEP collapses alveoli."),o("SIMV with PS differs from AC because:",["All breaths are full in SIMV","Spontaneous breaths between mandatory breaths are supported only by PS","SIMV has no set rate","AC has no backup rate"],1,"Extra patient breaths in SIMV are not full mandatory breaths.")]},"fpc-alt-airway":{sections:[{id:"case",title:"Transport case: the cardiac arrest airway",body:["An adult in out-of-hospital cardiac arrest with ongoing CPR. Ground crews have placed a King LT; there is a capnography trace of 18 mmHg and good chest rise. You are asked to intubate before flight.","A working supraglottic airway with capnographic confirmation is acceptable airway management during CPR; interrupting compressions for laryngoscopy has a cost. Exchange becomes reasonable when compressions can continue during the attempt, or after ROSC, and only if there is a clear benefit (leak at higher pressures, need for protection, long transport)."],example:{case:"Decide and act.",steps:["Confirm the existing airway: chest rise, capnography waveform, no large leak.","Continue CPR without interruption; leave the device in place during the arrest if it works.","If ROSC occurs and transport is long, consider exchange with a video laryngoscope after deflating the device's cuffs, with a backup SGA ready.","Document device, size, confirmation method and the EtCO\u2082 trend."]}}],questions:[o("During CPR, a functioning SGA with a capnography waveform should usually be:",["Removed immediately","Left in place while CPR continues","Replaced with a needle cric","Converted without regard to compressions"],1,"Avoid interrupting compressions."),o("Prolonged King LT use can cause:",["Tongue engorgement","Hyperkalaemia","Hypothermia","Pneumothorax"],0,"Venous congestion of the tongue."),o("An NPA traditionally avoided in:",["Asthma","Suspected basilar skull fracture","Seizure","Obesity"],1,"Theoretical risk of intracranial passage."),o("Video laryngoscopy in sunlight may be limited by:",["Glare on the screen","Battery overheating only","Bougie size","Cuff pressure"],0,"Screen visibility is reduced."),o("The i-gel cuff is:",["Inflatable","Non-inflatable gel","Absent","Oesophageal"],1,"A soft thermoplastic non-inflatable cuff.")]},"fpc-peri-arrest":{sections:[{id:"case",title:"Transport case: massive pulmonary embolism",body:["A 55-year-old after hip surgery with sudden dyspnoea: SpO\u2082 84 % on a non-rebreather, BP 86/52, HR 128, distended neck veins, RV dilation on bedside ultrasound. He is tiring and the team considers intubation before transfer to a centre for catheter-directed therapy.","This patient is at extreme risk of arrest at induction: a failing, pressure-loaded right ventricle that depends on sympathetic tone and preload, combined with hypoxaemia. Positive pressure raises RV afterload and reduces venous return."],example:{case:"Should you intubate, and if so how?",steps:["First ask whether intubation can be avoided: high-flow oxygen or HFNO, cautious NIV, and urgent reperfusion therapy per the receiving centre.","If intubation is unavoidable: norepinephrine running to a robust MAP before induction; avoid large fluid boluses that dilate the RV further.","Minimal-dose induction (for example ketamine at reduced dose), full-dose paralytic, the most skilled operator, first-pass success.","Ventilate with modest VT and low PEEP; avoid hypercapnia and hypoxia which raise PVR.","Be ready for arrest: thrombolysis may be indicated per protocol in PE-related arrest."]}}],questions:[o("Positive-pressure ventilation affects a failing RV by:",["Lowering afterload","Raising afterload and reducing preload","Improving contractility","No effect"],1,"Intrathoracic pressure raises PVR and lowers venous return."),o("Which worsens pulmonary vascular resistance?",["Normocapnia","Hypoxia and hypercapnia","Normal pH","Oxygen"],1,"Both cause pulmonary vasoconstriction."),o("In massive PE with shock, large fluid boluses may:",["Always help","Dilate the RV further and worsen septal shift","Lower PVR","Treat the clot"],1,"Over-distension of the RV compromises the LV."),o("Timing of most peri-intubation arrests:",["Hours later","Within minutes of induction","Before pre-oxygenation","At extubation"],1,"Most occur early."),o("Bicarbonate in severe acidaemia before intubation is:",["Evidence-based standard","A bridge some consider; evidence is limited","Contraindicated","Used to induce anaesthesia"],1,"Limited evidence.")]},"fpc-trach":{sections:[{id:"case",title:"Transport case: the home-ventilated child",body:["A 6-year-old with a tracheostomy on home ventilation becomes acutely distressed during transfer: SpO\u2082 82 %, no chest rise with the ventilator, high-pressure alarms. Parents say the tube was changed yesterday and the stoma is mature.","The airway is probably blocked or displaced. Parents are a resource \u2014 they often know the tube size, how to change it, and the child's baseline."],example:{case:"Work the algorithm.",steps:["Disconnect the ventilator and hand-ventilate with oxygen to the stoma and face.","Remove any inner cannula or speaking valve; pass a suction catheter.","Catheter fails: if cuffed, deflate the cuff; if still failing, remove the tracheostomy tube.","Insert a new tube of the same size (or one size smaller) through the mature stoma, ideally over a suction catheter as a guide; confirm with capnography.","If recannulation fails: oxygenate via the stoma with a small mask or via the upper airway (this child's larynx is intact), and prepare oral intubation as a secondary plan."]}}],questions:[o("A spare tracheostomy tube one size smaller is carried because:",["It fits more easily if the stoma has narrowed","It ventilates better","Parents prefer it","It has no cuff"],0,"A narrowed stoma may not accept the same size."),o("A suction catheter can guide reinsertion by:",["Acting like a bougie through the new tube","Measuring cuff pressure","Providing oxygen","None"],0,"It guides the tube into the tract."),o("Hereditary angioedema is treated specifically with:",["Antihistamines only","C1-esterase inhibitor or bradykinin-pathway drugs","Steroids only","Calcium"],1,"Targeted therapies address bradykinin excess."),o("In a burned patient, airway swelling typically peaks:",["Within 1 minute","Over hours, worsened by fluids","Never","After 2 weeks"],1,"Progressive oedema over the first day."),o("Air bubbling from an open neck wound with obvious tracheal injury may allow:",["Intubation through the wound in extremis","Ignoring the airway","NPA only","Bag through the mouth only"],0,"Direct cannulation through the defect.")]},"fpc-tube-confirm":{sections:[{id:"peds",title:"Tube sizing and securing in children",body:["For children over about two years, the uncuffed tube size is roughly (age \xF7 4) + 4 mm and the cuffed size (age \xF7 4) + 3.5 mm; have a half size above and below ready. Length-based tapes give tube size and drug doses in one step and reduce calculation errors under stress. Depth at the lips is about three times the internal diameter.","Small movements matter: in an infant the trachea may be only 4\u20135 cm long, so flexion or extension of the head can move the tip from mid-trachea into a main bronchus or out through the cords. Keep the head in a neutral position, tape securely across the upper lip, and recheck depth and capnography after every move and before take-off.","In neonates, the tip-to-lip depth is approximately weight in kilograms + 6 cm. A chest X-ray on arrival confirms the tip sits between the clavicles and the carina."]},{id:"case",title:"Transport case: the loading dock",body:["An intubated patient is moved from the ICU bed to your stretcher, then into the aircraft. On reconnection the waveform is absent and the SpO\u2082 is still 98 %.","High saturation reassures nobody: a well pre-oxygenated patient can keep a high SpO\u2082 for minutes after displacement. Loss of the waveform after a move is a displaced or disconnected tube until proven otherwise."],example:{case:"Respond.",steps:["Check the circuit and sampling line: connections, kinks, water in the line, the capnograph itself.","Hand-ventilate: no chest rise or resistance, or air leaking from the mouth, suggests displacement.","Check the depth mark against the documented depth; look with a laryngoscope if any doubt.","If displaced: remove, oxygenate by mask or SGA, and re-intubate; confirm with sustained waveform.","Prevent recurrence: secure the tube with a commercial holder, use head blocks if appropriate, and recheck after every move."]}}],questions:[o("Colorimetric CO\u2082 detectors change from purple to:",["Blue","Yellow (with CO\u2082)","Red","Green"],1,'Yellow indicates CO\u2082 ("yellow is yes").'),o("A colorimetric detector may give false negatives during:",["Normal ventilation","Cardiac arrest with low pulmonary flow","Hyperventilation","Fever"],1,"Low CO\u2082 delivery during low-flow states."),o("Ultrasound evidence of tracheal intubation includes:",['A second "double tract" in the neck',"Bilateral lung sliding with ventilation","Absent sliding on both sides","Pericardial effusion"],1,"Bilateral sliding supports tracheal placement; a double tract suggests oesophageal."),o("Unilateral absent breath sounds on the left after intubation suggest:",["Oesophageal intubation","Right mainstem intubation","Normal","Pneumothorax on the right"],1,"The tube is in the right main bronchus."),o("Over-inflated cuff pressure (> 30 cmH\u2082O) risks:",["Aspiration","Tracheal mucosal ischaemia","Hyperventilation","Bronchospasm"],1,"Capillary perfusion pressure is exceeded.")]},"fpc-suction":{sections:[{id:"checks",title:"Equipment checks and complications",body:["Check suction at the start of every shift and before every airway: power or battery, canister seated and empty, tubing connected, a rigid catheter and soft catheters of the right sizes, and the vacuum reading with the tubing occluded. Portable units lose strength as batteries drain; a manual hand-powered suction is a useful backup.","Complications are mostly preventable. Hypoxaemia is limited by pre-oxygenation and short passes. Mucosal trauma and bleeding are limited by appropriate pressures, not jabbing the catheter, and stopping 1 cm short of the carina. Atelectasis is limited by catheter size no more than half the tube lumen and by closed systems that preserve PEEP. Infection risk is reduced by sterile technique for endotracheal suction.","Document what you removed \u2014 volume, colour, blood or particulate matter \u2014 because it informs the receiving team about aspiration, pneumonia or haemorrhage."]},{id:"special",title:"Suction in special patients",core:!1,body:["Neonates and infants: use lower pressures and smaller catheters, limit each pass to about 5\u201310 seconds, suction the mouth before the nose (nasal stimulation can trigger a gasp and aspiration of oral contents), and watch for bradycardia. In the newly born, routine deep suction is not recommended; suction only if the airway is obstructed.","Raised intracranial pressure: suctioning causes coughing and surges in ICP. Ensure adequate sedation and analgesia, pre-oxygenate, keep passes short, and avoid repeated passes.","Tracheostomy patients: measure the catheter against the tube length or use pre-measured suction to avoid trauma to the carina. Inner cannulas can be removed and cleaned when secretions are thick.","Infectious disease: closed in-line systems reduce aerosol exposure; wear appropriate PPE for open suction."],list:{caption:"Catheter sizes (approximate)",items:["Neonate (2.5\u20133.5 ETT): 5\u20136 Fr","Infant (3.5\u20134.0): 8 Fr","Child (5.0\u20136.0): 10 Fr","Adult (7.0\u20138.0): 14 Fr"]}},{id:"case",title:"Transport case: secretions at altitude",body:["An intubated pneumonia patient on a 90-minute flight develops rising peak pressures, a shark-fin capnogram and falling SpO\u2082. Plateau pressure is unchanged.","A rising peak with an unchanged plateau is a resistance problem; the most likely cause in this patient is secretions in the tube. Dry oxygen and long transport thicken secretions; heat and moisture exchangers help."],example:{case:"Manage it.",steps:["Pre-oxygenate with FiO\u2082 1.0.","Use the closed in-line system with a 14 Fr catheter for a 7.5 tube; suction on withdrawal for no more than 10\u201315 seconds.","Reassess peak pressure, capnogram and SpO\u2082; repeat after re-oxygenation if needed.","If a catheter will not pass, treat as tube obstruction: disconnect, bag, consider changing the tube."]}}],questions:[o("In neonates, suction the mouth before the nose because:",["The nose is larger","Nasal suction can trigger a gasp and aspiration","It is faster","It avoids bradycardia entirely"],1,"Clear the mouth first."),o("Rising peak pressure with unchanged plateau and a shark-fin waveform suggests:",["Pneumothorax","Secretions or bronchospasm","Mainstem intubation","ARDS"],1,"A resistance problem."),o("Suction catheter size for an infant with a 4.0 ETT:",["5 Fr","8 Fr","14 Fr","18 Fr"],1,"About 2 \xD7 tube size."),o("Suction in a patient with raised ICP should be:",["Prolonged and vigorous","Brief, with adequate sedation and pre-oxygenation","Avoided entirely","Performed with saline lavage"],1,"Minimise ICP surges."),o("A heat and moisture exchanger helps by:",["Increasing FiO\u2082","Humidifying inspired gas, limiting thick secretions","Lowering CO\u2082","Measuring EtCO\u2082"],1,"Humidification keeps secretions thinner.")]},"fpc-capnography":{sections:[{id:"physiology",title:"Where the CO\u2082 comes from",body:["End-tidal CO\u2082 depends on three things: production by metabolism, delivery to the lungs by the circulation, and elimination by ventilation. A change in the number always means one of those three has changed \u2014 or the equipment has.","Production rises with fever, shivering, seizures, sepsis, malignant hyperthermia, and when bicarbonate is given (it is converted to CO\u2082). Production falls with hypothermia and deep sedation.","Delivery depends on cardiac output and pulmonary blood flow. A sudden fall at constant ventilation means falling output, a pulmonary embolism or cardiac arrest; a sudden rise during CPR suggests ROSC.","Elimination depends on alveolar ventilation: rate \xD7 (tidal volume \u2212 dead space). Hypoventilation raises EtCO\u2082; hyperventilation lowers it. Increased dead space lowers EtCO\u2082 relative to PaCO\u2082 even though the arterial value may be rising."]},{id:"case",title:"Transport case: reading the trace through a flight",body:["You transport an intubated septic patient. Over the flight, the capnogram tells a story \u2014 if you read it."],example:{case:"Interpret each change.",steps:["Take-off: EtCO\u2082 34 with a normal waveform \u2014 baseline after confirmation; gas earlier showed PaCO\u2082 39 (gap 5).","Minute 15: EtCO\u2082 falls to 24 with unchanged ventilation, BP 74/40 \u2014 falling cardiac output; treat the hypotension.","Minute 25: the baseline rises above zero \u2014 rebreathing; check the circuit, valves and flow.","Minute 40: sudden flat line \u2014 disconnection or displacement; check the circuit and depth, hand-ventilate.","Minute 50: clefts appear in the plateau and EtCO\u2082 rises slightly \u2014 the patient is breathing against the ventilator as sedation wears off; give analgesia and sedation."]}}],questions:[o("With constant ventilation, a falling EtCO\u2082 most often reflects:",["Rising metabolism","Falling cardiac output","Rebreathing","Bronchospasm"],1,"Less CO\u2082 is delivered to the lungs."),o("Malignant hyperthermia causes EtCO\u2082 to:",["Fall","Rise sharply","Stay normal","Become zero"],1,"Hypermetabolism raises CO\u2082 production."),o("Nasal-oral capnography in a sedated, spontaneously breathing patient detects:",["Tube placement","Hypoventilation and apnoea early","Cardiac output exactly","PaO\u2082"],1,"Before desaturation."),o("Phase II of the capnogram reflects:",["Dead-space gas only","Mixing of dead-space and alveolar gas","Inspiration","Rebreathing"],1,"The expiratory upstroke."),o("In DKA before intubation, a low EtCO\u2082 reflects:",["Hypoventilation","Respiratory compensation","Equipment error","Rebreathing"],1,"Kussmaul breathing lowers CO\u2082.")]},"fpc-nippv":{sections:[{id:"interface",title:"Interfaces, leaks and synchrony",body:["The interface decides whether NIV works. Oronasal (full-face) masks suit acute respiratory failure because breathless patients breathe through the mouth. Nasal masks suit calmer patients and allow speech. Total-face masks and helmets spread pressure over a larger area and help when pressure sores or claustrophobia limit other masks.","Fit the mask so it seals without excessive strap tension: one or two fingers should slide under the straps. Small leaks are tolerated by ventilators designed for NIV; large leaks cause asynchrony, failure to trigger or cycle, and dry eyes. Re-fit rather than tighten.","Watch the patient breathe with the machine. Triggering delays, double triggering or breaths that end before the patient finishes inhaling increase work of breathing. Adjust the trigger sensitivity and rise time, coach the patient, and consider low-dose anxiolysis \u2014 while never sedating a patient so deeply that airway protection is lost.","Gastric distension, eye irritation, nasal bridge pressure injury and aspiration are the common complications; a gastric tube may be needed on long transports."]},{id:"case",title:"Transport case: flash pulmonary oedema",body:["A 72-year-old with hypertension is sitting bolt upright, frothy sputum, SpO\u2082 82 % on a non-rebreather, BP 210/120, HR 118, crackles to the apices. She is alert and frightened.","Sympathetic crashing acute pulmonary oedema: high afterload drives fluid into the lungs. CPAP or BiPAP lowers preload and afterload and recruits flooded alveoli, while high-dose nitrates lower afterload. Intubation can often be avoided."],example:{case:"Treat it.",steps:["Keep her upright; coach and reassure.","Start CPAP 8\u201310 cmH\u2082O (or BiPAP if hypercapnic) with FiO\u2082 high, titrating to SpO\u2082 94\u201398 %.","Give nitroglycerin per protocol in high doses as tolerated, reducing as BP falls.","Reassess every few minutes: respiratory rate, work of breathing, SpO\u2082, BP and mental status.","If she deteriorates, becomes obtunded or hypotensive, intubate \u2014 ideally before departure."]}}],questions:[o("CPAP improves oxygenation primarily by:",["Increasing CO\u2082","Recruiting alveoli and raising FRC","Raising heart rate","Lowering FiO\u2082"],1,"Reduces shunt."),o("First-line pharmacological adjunct with NIV for hypertensive pulmonary oedema:",["Fluids","High-dose nitroglycerin","Beta-agonist","Calcium"],1,"Reduces afterload and preload."),o("Which patient is the best NIV candidate?",["Obtunded with vomiting","Alert COPD patient with pH 7.28","Facial burns","Cardiac arrest"],1,"Cooperative hypercapnic patient."),o("If CO\u2082 remains high on BiPAP 10/5, a reasonable change is:",["Lower IPAP","Increase IPAP","Remove EPAP","Lower FiO\u2082 to 0.21"],1,"More pressure support increases VT."),o("Positive pressure may worsen:",["Hypertension","Hypovolaemic hypotension","Oxygenation","Pulmonary oedema"],1,"It reduces venous return.")]}};var X={id:"fpc-endocrine",domain:"medical",ref:"IV.1",title:"Endocrine emergencies: DKA, HHS, thyroid storm and myxoedema",summary:"Diabetic ketoacidosis and the hyperosmolar hyperglycaemic state, hypoglycaemia, thyroid storm and myxoedema coma: recognition, the order of treatment, and the transport traps.",objectives:["Differentiate DKA from HHS and treat each in the right order: fluid, potassium, insulin.","Recognise thyroid storm and myxoedema coma and start time-critical therapy.","Anticipate the airway and haemodynamic hazards of endocrine crises in transport."],sections:[{id:"dka",title:"DKA and HHS",core:!0,body:["Diabetic ketoacidosis (DKA) is insulin deficiency with counter-regulatory hormone excess: glucose usually above 250 mg/dL (14 mmol/L), a high anion-gap metabolic acidosis (pH < 7.30, bicarbonate < 18), and ketones. Kussmaul breathing compensates for the acidosis. Osmotic diuresis causes profound dehydration \u2014 often 5\u20138 litres in adults \u2014 and total-body potassium depletion even when the plasma potassium reads high.","The hyperosmolar hyperglycaemic state (HHS) is seen more in older type 2 diabetics: glucose often above 600 mg/dL (33 mmol/L), serum osmolality above 320 mOsm/kg, little or no ketosis or acidosis, and greater dehydration (often 8\u201310 litres). Altered consciousness tracks osmolality. Mortality is higher than DKA, partly from age, comorbidity and thrombosis.","Order of treatment for both: fluids first (isotonic crystalloid to restore circulation), then potassium (check before insulin; replace if low \u2014 many protocols withhold insulin until K\u207A is at least 3.3 mmol/L), then insulin as a fixed-rate infusion. Add dextrose as glucose falls so insulin can continue until ketones clear. Bicarbonate is reserved for extreme acidaemia per protocol. In HHS, lower glucose and sodium more slowly to avoid cerebral oedema."],table:{caption:"DKA versus HHS",head:["Feature","DKA","HHS"],rows:[["Glucose","> 250 mg/dL","Often > 600 mg/dL"],["pH / HCO\u2083\u207B","< 7.30 / < 18","> 7.30 / > 18"],["Ketones","Moderate to large","Small or none"],["Osmolality","Variable","> 320 mOsm/kg"],["Mental status","Variable","Often obtunded"],["Fluid deficit","\u2248 5\u20138 L","\u2248 8\u201310 L"]]}},{id:"transport",title:"Transport traps in DKA",core:!0,body:[`Intubation is dangerous: the patient is compensating for a severe metabolic acidosis with a very high minute ventilation. Apnoea and then "normal" ventilator settings can drop the pH precipitously and cause arrest. Avoid intubation unless the airway is truly threatened; if needed, keep apnoea short and set a minute ventilation that matches the patient's own.`,"Potassium falls as insulin and fluids act; hypokalaemia causes arrhythmias. Monitor the ECG continuously and recheck potassium on long transports. In children, rapid fluid shifts risk cerebral oedema \u2014 watch for headache, falling GCS, bradycardia and hypertension, and treat with hyperosmolar therapy."]},{id:"hypo",title:"Hypoglycaemia",body:["Hypoglycaemia (glucose below about 70 mg/dL, with symptoms; severe when the patient needs assistance) causes sweating, tremor and tachycardia from adrenergic response, then confusion, seizures and coma from neuroglycopenia. Beta-blockers mask the adrenergic warning signs. Sulfonylurea overdose causes prolonged, recurrent hypoglycaemia; octreotide reduces insulin release in that setting.","Treat with IV dextrose (for example D10 in titrated boluses, or D50 in adults per protocol), or IM glucagon if no access (less effective in depleted glycogen stores \u2014 alcoholics, starvation). Recheck glucose frequently and follow with food or a dextrose infusion."]},{id:"thyroid",title:"Thyroid storm and myxoedema coma",core:!0,body:["Thyroid storm is life-threatening thyrotoxicosis: fever, tachycardia (often atrial fibrillation), agitation or delirium, vomiting, diarrhoea and high-output heart failure, often precipitated by infection, surgery, trauma or stopping antithyroid drugs. Treat in sequence: a beta-blocker (propranolol is classic; esmolol when titration is needed) for adrenergic effects, a thionamide (propylthiouracil or methimazole) to block synthesis, iodine at least an hour after the thionamide to block release, corticosteroids, cooling and supportive care. Avoid aspirin for fever (it displaces thyroid hormone from binding proteins).","Myxoedema coma is decompensated hypothyroidism: hypothermia, bradycardia, hypoventilation with hypercapnia, hyponatraemia, hypoglycaemia and depressed consciousness, often in an older woman in winter. Treat with IV levothyroxine (often with liothyronine per specialist advice), stress-dose hydrocortisone until adrenal insufficiency is excluded, passive rewarming, ventilatory support and careful correction of sodium. These patients are very sensitive to sedatives."]},{id:"case",title:"Transport case: the vomiting teenager",body:["A 16-year-old with type 1 diabetes, vomiting for a day: GCS 13, RR 36 deep, HR 130, BP 98/60, glucose 540 mg/dL, pH 7.04, HCO\u2083\u207B 5, K\u207A 5.6, Na\u207A 131. A 90-minute flight to a paediatric ICU."],example:{case:"What are your priorities and what could go wrong in the air?",steps:["Fluids per paediatric DKA protocol (measured boluses, then calculated deficit over 24\u201348 h) \u2014 not the large volumes used in adults, to limit cerebral oedema risk.","Potassium is 5.6 now but will fall; add potassium to fluids once urine output is confirmed and K\u207A is falling into the normal range.","Fixed-rate insulin per protocol after initial fluids (no insulin bolus in children).","Avoid intubation; if unavoidable, match her minute ventilation.","In flight: hourly glucose, frequent neuro checks for cerebral oedema (headache, bradycardia, falling GCS); have hyperosmolar therapy available."]}}],keyPoints:["DKA: glucose > 250, pH < 7.30, ketones; HHS: glucose > 600, osmolality > 320, little acidosis.","Fluid, then potassium (\u2265 3.3 before insulin), then insulin; add dextrose and continue until ketones clear.","Do not intubate a compensating DKA patient lightly; match minute ventilation if you must.","Thyroid storm: beta-blocker, thionamide, iodine an hour later, steroids, cooling.","Myxoedema coma: IV thyroid hormone, hydrocortisone, rewarming, ventilatory support."],pearls:["Plasma potassium is high in DKA but total-body potassium is low.","Glucagon fails when glycogen is depleted.","Watch children with DKA for cerebral oedema in the first hours of treatment."],pitfalls:["Insulin before potassium is known.","Normal ventilator settings after intubating a DKA patient.","Aspirin for fever in thyroid storm."],live:[{id:"abg-dka",label:"DKA: acid, water and potassium"},{id:"metab",label:"Metabolic acidosis and the anion gap"}],questions:[{q:"Which best distinguishes HHS from DKA?",options:["Glucose above 250","Osmolality above 320 with minimal acidosis","Kussmaul breathing","Hyperkalaemia"],answer:1,why:"HHS is hyperosmolar with little ketoacidosis."},{q:"Before starting insulin in DKA, potassium should generally be at least:",options:["2.5","3.3","5.0","6.0 mmol/L"],answer:1,why:"Insulin drives potassium into cells."},{q:"Glucose falls to 220 mg/dL but the anion gap remains high. You should:",options:["Stop insulin","Add dextrose and continue insulin","Give bicarbonate","Switch to glucagon"],answer:1,why:"Ketosis, not glucose, defines resolution."},{q:"Signs of cerebral oedema in paediatric DKA include:",options:["Tachycardia and hypotension","Headache, bradycardia, falling GCS","Polyuria","Hyperkalaemia"],answer:1,why:"Raised ICP signs."},{q:"First drug to control adrenergic symptoms in thyroid storm:",options:["Iodine","Propranolol","Aspirin","Levothyroxine"],answer:1,why:"Beta-blockade treats tachycardia and agitation."},{q:"Iodine in thyroid storm is given:",options:["Before the thionamide","At least an hour after the thionamide","Never","Instead of beta-blockers"],answer:1,why:"Otherwise it can fuel more hormone synthesis."},{q:"Myxoedema coma typically presents with:",options:["Hyperthermia and tachycardia","Hypothermia, bradycardia, hypoventilation","Hypernatraemia","Diarrhoea"],answer:1,why:"Decompensated hypothyroidism slows everything."},{q:"Why give hydrocortisone in myxoedema coma?",options:["To lower glucose","Possible coexisting adrenal insufficiency","To raise sodium","To treat infection"],answer:1,why:"Thyroid replacement can precipitate adrenal crisis."},{q:"Glucagon is least effective in:",options:["A healthy adult","Chronic alcoholism with depleted glycogen","Insulin overdose in a fed patient","Children"],answer:1,why:"It works by mobilising glycogen."},{q:"Prolonged recurrent hypoglycaemia after sulfonylurea overdose may be treated with:",options:["Insulin","Octreotide","Propranolol","Calcium"],answer:1,why:"Octreotide suppresses insulin secretion."},{q:"Typical fluid deficit in adult DKA:",options:["0.5\u20131 L","5\u20138 L","15\u201320 L","None"],answer:1,why:"Osmotic diuresis causes large losses."},{q:"A DKA patient must be intubated. Initial ventilation should:",options:["Use RR 12","Match pre-intubation minute ventilation","Allow permissive hypercapnia","Use PS 5"],answer:1,why:"Preserve respiratory compensation."},{q:"Insulin bolus in paediatric DKA:",options:["Always given","Not recommended","Given IM","Only with HHS"],answer:1,why:"Children receive a fixed-rate infusion without bolus."},{q:"Beta-blockers can make hypoglycaemia harder to detect because they:",options:["Raise glucose","Mask adrenergic warning symptoms","Cause seizures","Cause hyperkalaemia"],answer:1,why:"Tremor and tachycardia are blunted."},{q:"HHS mortality is higher than DKA partly because of:",options:["Younger patients","Age, comorbidity and thrombosis","Lower glucose","Less dehydration"],answer:1,why:"Older patients with more complications."}],sources:[{title:"ADA consensus report: hyperglycaemic crises in adults with diabetes (2024)",url:"https://diabetesjournals.org/care/article/47/8/1257/156808"},{title:"StatPearls: Thyroid storm",url:"https://www.ncbi.nlm.nih.gov/books/?term=Thyroid+storm+StatPearls"},{title:"StatPearls: Myxedema coma",url:"https://www.ncbi.nlm.nih.gov/books/?term=Myxedema+coma+StatPearls"}]},Y={id:"fpc-adrenal",domain:"medical",ref:"IV.2",title:"Adrenal emergencies: crisis, steroids and pheochromocytoma",summary:"Primary and secondary adrenal insufficiency, adrenal crisis and stress dosing, relative adrenal insufficiency in shock, and catecholamine crises from pheochromocytoma.",objectives:["Recognise adrenal crisis and give hydrocortisone without waiting for confirmation.","Know who needs stress-dose steroids and the role of hydrocortisone in refractory septic shock.","Manage a pheochromocytoma crisis: alpha before beta."],sections:[{id:"physiology",title:"What the adrenals do",core:!0,body:["The adrenal cortex makes cortisol (glucocorticoid), aldosterone (mineralocorticoid) and androgens. Cortisol supports blood pressure by sensitising vessels to catecholamines, raises glucose and modulates inflammation; aldosterone retains sodium and excretes potassium. The adrenal medulla secretes epinephrine and norepinephrine.","Primary adrenal insufficiency (Addison's disease: autoimmune, infection, haemorrhage) loses both cortisol and aldosterone, so hyponatraemia, hyperkalaemia and hyperpigmentation are typical. Secondary insufficiency (pituitary disease, or suppression by long-term steroid therapy \u2014 the commonest cause) loses cortisol but aldosterone is largely preserved, so potassium is usually normal."]},{id:"crisis",title:"Adrenal crisis",core:!0,body:["Adrenal crisis is shock that responds poorly to fluids and vasopressors, often with abdominal pain, vomiting, confusion, fever, hypoglycaemia, hyponatraemia and hyperkalaemia. It is precipitated by infection, trauma, surgery, vomiting that prevents oral steroids, or abrupt withdrawal of chronic steroid therapy. Waterhouse\u2013Friderichsen syndrome is bilateral adrenal haemorrhage in meningococcal sepsis.","Treat immediately: hydrocortisone 100 mg IV or IM in adults (about 50\u2013100 mg/m\xB2, often 2 mg/kg up to 100 mg in children per local protocol), isotonic fluids with dextrose if hypoglycaemic, and treatment of the precipitant. Do not delay hydrocortisone for a cortisol level. At doses of 100 mg and above, hydrocortisone provides enough mineralocorticoid effect that fludrocortisone is not needed acutely.","Patients on long-term steroids (for example prednisone 5 mg or more daily for more than a few weeks) may not mount a stress response. Many carry an emergency card and an injection kit; ask about it, and give stress-dose hydrocortisone in serious illness or injury."]},{id:"sepsis",title:"Steroids in septic shock",core:!0,body:["In septic shock needing ongoing or escalating vasopressor therapy, guidelines suggest IV hydrocortisone (commonly 200 mg/day in divided doses or infusion). Trials show faster shock reversal; mortality benefit is inconsistent. Etomidate's transient adrenal suppression after a single induction dose is debated; many clinicians simply ensure hydrocortisone is considered in refractory shock regardless of induction agent."]},{id:"pheo",title:"Pheochromocytoma crisis",body:["A catecholamine-secreting tumour can cause paroxysmal hypertension, headache, sweating and palpitations, and crises with severe hypertension, arrhythmias, cardiomyopathy and pulmonary oedema \u2014 sometimes triggered by anaesthesia, trauma, steroids or certain drugs (metoclopramide, some antidepressants).","Treat with alpha-blockade or vasodilators first (phentolamine, nicardipine, nitroprusside per protocol). Never give a beta-blocker alone: blocking beta-2 mediated vasodilation leaves alpha vasoconstriction unopposed and blood pressure can rise further. Beta-blockers are added only after adequate alpha-blockade, to control tachycardia."]},{id:"case",title:"Transport case: the post-operative patient who will not stay up",body:["A 62-year-old with rheumatoid arthritis on long-term prednisone, two days after bowel surgery, vomiting for 24 hours: BP 76/40 despite 3 L of fluid and norepinephrine 0.3 mcg/kg/min, HR 118, glucose 58 mg/dL, Na\u207A 129, K\u207A 4.6."],example:{case:"What is the likely diagnosis and what do you give?",steps:["Chronic steroid use + vomiting (missed doses) + surgical stress + refractory shock + hypoglycaemia and hyponatraemia \u2192 adrenal crisis (secondary: potassium normal).","Give hydrocortisone 100 mg IV now; don't wait for a cortisol level.","Treat hypoglycaemia with dextrose; continue fluids and vasopressor; expect vasopressor needs to fall within hours.","Consider other causes concurrently: anastomotic leak and sepsis, bleeding."]}}],keyPoints:["Adrenal crisis: refractory shock, vomiting, hypoglycaemia, hyponatraemia (\xB1 hyperkalaemia in primary).","Hydrocortisone 100 mg IV/IM immediately; never wait for a cortisol level.","Long-term steroid users need stress dosing in serious illness or injury.","Hydrocortisone is suggested in septic shock with ongoing vasopressor need.","Pheochromocytoma: alpha-blockade or vasodilator first, never a beta-blocker alone."],pearls:["Ask about steroid emergency cards and kits.","Secondary adrenal insufficiency usually has a normal potassium."],pitfalls:["Escalating vasopressors in a steroid-dependent patient without hydrocortisone.","Beta-blocking a hypertensive pheochromocytoma crisis."],questions:[{q:"Hyperkalaemia is typical of:",options:["Secondary adrenal insufficiency","Primary adrenal insufficiency","Cushing's syndrome","Pheochromocytoma"],answer:1,why:"Primary loss of aldosterone."},{q:"Adult hydrocortisone dose for adrenal crisis:",options:["5 mg","25 mg","100 mg","1 g"],answer:2,why:"100 mg IV or IM."},{q:"The most common cause of secondary adrenal insufficiency:",options:["Autoimmune adrenalitis","Long-term exogenous steroids","Meningococcaemia","TB"],answer:1,why:"HPA axis suppression."},{q:"Waterhouse\u2013Friderichsen syndrome is:",options:["Pituitary apoplexy","Bilateral adrenal haemorrhage in meningococcal sepsis","Thyroid storm","Addison's from TB"],answer:1,why:"Classic fulminant meningococcaemia complication."},{q:"In adrenal crisis, hydrocortisone should be given:",options:["After cortisol results","Immediately","Only if K\u207A is high","Only orally"],answer:1,why:"Delay increases mortality."},{q:"Hydrocortisone is suggested in septic shock when:",options:["Lactate is 1","Vasopressor requirement is ongoing","BP is normal","Fever is present"],answer:1,why:"Speeds shock reversal."},{q:"First-line for pheochromocytoma hypertensive crisis:",options:["Labetalol alone","Propranolol","Phentolamine or a vasodilator","Metoclopramide"],answer:2,why:"Alpha-blockade first."},{q:"Why avoid a beta-blocker alone in pheochromocytoma?",options:["Causes hypoglycaemia","Unopposed alpha vasoconstriction raises BP","Causes hyperkalaemia","Causes bronchodilation"],answer:1,why:"Loss of beta-2 vasodilation."},{q:"At hydrocortisone 100 mg, fludrocortisone acutely is:",options:["Required","Not needed \u2014 enough mineralocorticoid effect","Contraindicated","Given first"],answer:1,why:"High-dose hydrocortisone has mineralocorticoid activity."},{q:"Hyperpigmentation suggests:",options:["Secondary insufficiency","Primary insufficiency (high ACTH)","Pheochromocytoma","Hypothyroidism"],answer:1,why:"ACTH shares a precursor with MSH."},{q:"A drug that can trigger a pheochromocytoma crisis:",options:["Metoclopramide","Phentolamine","Nicardipine","Hydrocortisone at physiological dose only"],answer:0,why:"Dopamine antagonists can provoke catecholamine release."},{q:"Hypoglycaemia in adrenal crisis results from:",options:["Excess insulin","Lack of cortisol","Excess aldosterone","Catecholamine excess"],answer:1,why:"Cortisol supports gluconeogenesis."},{q:"A steroid-dependent trauma patient is hypotensive despite volume. Consider:",options:["More crystalloid only","Stress-dose hydrocortisone","Beta-blocker","Diuretic"],answer:1,why:"Inadequate stress response."},{q:"Etomidate's adrenal effect after one dose is:",options:["Permanent","Transient suppression; clinical impact debated","Stimulatory","Absent"],answer:1,why:"Inhibits 11-\u03B2-hydroxylase transiently."},{q:"Aldosterone's main effect:",options:["Retains potassium","Retains sodium and excretes potassium","Raises glucose","Vasodilation"],answer:1,why:"Mineralocorticoid action at the distal nephron."}],sources:[{title:"Endocrine Society guideline: diagnosis and treatment of primary adrenal insufficiency (2016)",url:"https://academic.oup.com/jcem/article/101/2/364/2810222"},{title:"Surviving Sepsis Campaign: international guidelines (2021)",url:"https://www.sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-guidelines-2021"}]},J={id:"fpc-renal",domain:"medical",ref:"IV.3",title:"Renal emergencies: AKI, hyperkalaemia and the dialysis patient",summary:"Pre-renal, intrinsic and post-renal kidney injury, the life-threatening complications of renal failure, rhabdomyolysis, and managing dialysis patients and their access in transport.",objectives:["Classify acute kidney injury and identify reversible causes.","Treat hyperkalaemia in order: stabilise, shift, remove.","Manage dialysis patients: access, missed dialysis, fluid overload and drug choices."],sections:[{id:"aki",title:"Acute kidney injury",core:!0,body:["AKI is a rapid rise in creatinine or fall in urine output (for example, creatinine rising by 0.3 mg/dL within 48 hours, or urine below 0.5 mL/kg/h for 6 hours). Classify by cause. Pre-renal: reduced perfusion from hypovolaemia, shock, heart failure or renal artery disease; the kidney itself is initially normal and recovers with perfusion. Intrinsic: acute tubular necrosis from prolonged ischaemia or toxins (contrast, aminoglycosides, myoglobin), glomerulonephritis, interstitial nephritis. Post-renal: obstruction of both outflows (or one in a single kidney) \u2014 prostate, stones, tumours, a blocked catheter.","In transport, the reversible causes are what you can act on: restore perfusion pressure, stop nephrotoxins, and relieve obstruction (a urinary catheter, or flushing a blocked one). Track urine output hourly in critically ill patients."]},{id:"hyperk",title:"Hyperkalaemia",core:!0,body:["Potassium above about 6.5 mmol/L, or any hyperkalaemia with ECG changes, is an emergency. The ECG progresses roughly from peaked T waves, to PR prolongation and flattened P waves, to QRS widening, to a sine wave and then ventricular fibrillation or asystole \u2014 but the sequence is unreliable and arrest can occur without warning.","Stabilise the membrane with IV calcium (calcium gluconate 3 g or calcium chloride 1 g in adults, typically, repeated if ECG changes persist); it acts within minutes, lasts 30\u201360 minutes and does not lower potassium. Shift potassium into cells with insulin plus dextrose (for example 10 units regular insulin with 25 g dextrose) and nebulised salbutamol; bicarbonate helps mainly in concurrent acidosis. Remove potassium with dialysis (definitive in renal failure), potassium binders, or loop diuretics if the kidneys work. Recheck glucose after insulin."],list:{caption:"Causes to look for",items:["Renal failure, missed dialysis","Drugs: ACE inhibitors/ARBs, spironolactone, potassium supplements, succinylcholine, digoxin toxicity","Cell breakdown: rhabdomyolysis, crush, tumour lysis, haemolysis, burns","Acidosis (shift out of cells), adrenal insufficiency","Pseudohyperkalaemia from a haemolysed sample \u2014 but treat if the ECG is abnormal"]}},{id:"rhabdo",title:"Rhabdomyolysis",body:["Muscle breakdown from crush, prolonged immobilisation, exertion, seizures, hyperthermia or drugs releases myoglobin, potassium, phosphate and creatine kinase. Myoglobin causes tubular injury, especially in hypovolaemia and acidosis. Dark urine with a dipstick positive for blood but few red cells suggests myoglobinuria.","Treat with early, aggressive isotonic fluids to maintain a high urine output (often targeted around 200\u2013300 mL/h in adults per protocol), correct hyperkalaemia, and in crush injury start fluids before release where possible to blunt reperfusion hyperkalaemia and acidosis. Avoid succinylcholine."]},{id:"dialysis",title:"The dialysis patient in transport",core:!0,body:["Ask when the last dialysis was. Missed dialysis brings hyperkalaemia, fluid overload with pulmonary oedema, metabolic acidosis and uraemic complications (pericarditis, encephalopathy, bleeding from platelet dysfunction).","Protect the access: avoid blood pressure cuffs, IVs and venepuncture on an arm with a fistula or graft. A palpable thrill and audible bruit indicate patency. Bleeding from a fistula can be torrential; apply firm direct pressure. Central dialysis catheters should not be used for routine access except in an emergency by protocol, as they are often locked with concentrated heparin or citrate that must be aspirated first.","Drug choice: avoid succinylcholine if potassium is unknown or high; use rocuronium. Many drugs accumulate (morphine metabolites, some antibiotics); fentanyl is preferred to morphine. Fluid overload is better treated with nitrates and NIV than with fluid restriction alone; diuretics may be ineffective in anuric patients."],example:{case:"A dialysis patient missed two sessions: dyspnoeic, SpO\u2082 86 %, BP 190/100, crackles, HR 52 with wide QRS, K\u207A 7.9.",steps:["Immediate threat: hyperkalaemia with ECG changes \u2014 IV calcium now, repeat if no narrowing.","Shift: insulin with dextrose and nebulised salbutamol; check glucose hourly.","Pulmonary oedema: sit up, CPAP or BiPAP, nitroglycerin for hypertension.","Arrange urgent dialysis at the destination; avoid the fistula arm; rocuronium if intubation is needed."]}}],keyPoints:["AKI: pre-renal (perfusion), intrinsic (ATN, toxins), post-renal (obstruction) \u2014 fix what is reversible.","Hyperkalaemia with ECG changes: calcium first, then insulin/dextrose and salbutamol, then removal.","Calcium stabilises the membrane but does not lower potassium.","Rhabdomyolysis: early aggressive fluids, high urine output, watch potassium, avoid succinylcholine.","Dialysis patients: last session, protect the fistula arm, rocuronium not succinylcholine."],pearls:["Check for a blocked urinary catheter in sudden oliguria.","Fentanyl is preferred over morphine in renal failure."],pitfalls:["BP cuff on a fistula arm.","Forgetting the glucose recheck after insulin."],live:[{id:"hyperk-signature",label:"Hyperkalaemia: the membrane, the ECG, the rescue"},{id:"hyperk",label:"Hyperkalaemia: stabilise, shift, remove"}],questions:[{q:"A blocked urinary catheter causing anuria is which type of AKI?",options:["Pre-renal","Intrinsic","Post-renal","None"],answer:2,why:"Obstruction of outflow."},{q:"First drug for hyperkalaemia with a widened QRS:",options:["Insulin","Calcium","Furosemide","Kayexalate"],answer:1,why:"Membrane stabilisation first."},{q:"Calcium in hyperkalaemia:",options:["Lowers potassium quickly","Stabilises the membrane without lowering potassium","Removes potassium","Is contraindicated"],answer:1,why:"It raises threshold potential."},{q:"Insulin lowers potassium by:",options:["Renal excretion","Shifting it into cells via Na/K-ATPase","Binding in the gut","Dialysis"],answer:1,why:"Stimulates the pump."},{q:"After insulin for hyperkalaemia, monitor for:",options:["Hyperglycaemia only","Hypoglycaemia","Hypercalcaemia","Hyponatraemia"],answer:1,why:"Hypoglycaemia can occur hours later."},{q:"Dark urine, dipstick blood positive, few red cells suggests:",options:["Haematuria","Myoglobinuria","Bilirubinuria","Normal"],answer:1,why:"Myoglobin reacts with the haem test."},{q:"Mainstay of rhabdomyolysis treatment:",options:["Fluid restriction","Aggressive isotonic fluids","Diuretics alone","Succinylcholine"],answer:1,why:"Dilute myoglobin and maintain urine flow."},{q:"An arm with an AV fistula should not have:",options:["Assessment for thrill","BP cuff or IV","Inspection","Palpation"],answer:1,why:"Protect the access."},{q:"Paralytic of choice in a dialysis patient with unknown potassium:",options:["Succinylcholine","Rocuronium","Either","Neither"],answer:1,why:"Succinylcholine raises potassium."},{q:"Opioid preferred in renal failure:",options:["Morphine","Fentanyl","Meperidine","Codeine"],answer:1,why:"Fewer active renally cleared metabolites."},{q:"Uraemic bleeding is due to:",options:["Thrombocytosis","Platelet dysfunction","Excess factor VIII","Vitamin K excess"],answer:1,why:"Uraemic toxins impair platelets."},{q:"Before release of a crushed limb trapped for hours you should:",options:["Delay fluids","Start IV fluids","Give succinylcholine","Apply heat"],answer:1,why:"Blunts reperfusion hyperkalaemia and acidosis."},{q:"Earliest typical ECG sign of hyperkalaemia:",options:["Sine wave","Peaked T waves","U waves","ST depression"],answer:1,why:"Peaked T often first, though progression is unreliable."},{q:"Urine output definition of AKI:",options:["< 2 mL/kg/h for 1 h","< 0.5 mL/kg/h for 6 h","< 1 L/day","< 100 mL/h"],answer:1,why:"KDIGO criterion."},{q:"Bicarbonate in hyperkalaemia is most helpful when:",options:["Always","Concurrent metabolic acidosis","Alkalosis","Never"],answer:1,why:"Its shifting effect is modest otherwise."}],sources:[{title:"KDIGO clinical practice guideline for acute kidney injury",url:"https://kdigo.org/guidelines/acute-kidney-injury/"},{title:"StatPearls: Hyperkalemia",url:"https://www.ncbi.nlm.nih.gov/books/?term=Hyperkalemia+StatPearls"},{title:"StatPearls: Rhabdomyolysis",url:"https://www.ncbi.nlm.nih.gov/books/?term=Rhabdomyolysis+StatPearls"}]};var $={id:"fpc-metabolic",domain:"medical",ref:"IV.4",title:"Metabolic and electrolyte emergencies",summary:"Sodium, calcium and magnesium disorders, acid\u2013base interpretation, and temperature emergencies: what kills, how fast to correct, and what to watch in flight.",objectives:["Correct hyponatraemia and hypernatraemia at safe rates.","Recognise and treat dangerous calcium and magnesium disorders.","Interpret acid\u2013base disorders systematically, including mixed disorders."],sections:[{id:"sodium",title:"Sodium",core:!0,body:["Plasma sodium sets cell volume, and the brain has no room to swell. Severe symptomatic hyponatraemia \u2014 seizures, coma, vomiting with confusion \u2014 is treated with hypertonic saline boluses (commonly 3 % saline, 100\u2013150 mL over 10\u201320 minutes, repeated up to two or three times) aiming to raise sodium by 4\u20136 mmol/L, which is usually enough to stop symptoms.","Chronic hyponatraemia (present more than 48 hours, or of unknown duration) must not be corrected too fast: limit the rise to about 8\u201310 mmol/L in 24 hours (lower in high-risk patients such as alcoholics, the malnourished and those with hypokalaemia) to avoid osmotic demyelination, which appears days later with dysarthria, dysphagia and quadriparesis.","Hypernatraemia reflects water deficit \u2014 elderly or disabled patients without access to water, diabetes insipidus, osmotic diuresis. Correct gradually with hypotonic fluids, lowering sodium by no more than about 10\u201312 mmol/L per day in chronic cases, to avoid cerebral oedema."]},{id:"calcium",title:"Calcium and magnesium",core:!0,body:["Hypocalcaemia causes perioral and digital paraesthesia, tetany, Chvostek and Trousseau signs, seizures, QT prolongation and hypotension. Causes include massive transfusion (citrate binds calcium), pancreatitis, hypoparathyroidism and hypomagnesaemia. Treat symptomatic patients with IV calcium (gluconate peripherally; chloride contains about three times the elemental calcium and is irritating, so is preferred centrally). In major haemorrhage, give calcium early and often.",'Hypercalcaemia ("stones, bones, groans and psychiatric overtones") causes dehydration, confusion, short QT and arrhythmias, usually from malignancy or hyperparathyroidism. Treat with isotonic fluids first; bisphosphonates and calcitonin follow in hospital.',"Magnesium below normal predisposes to torsades de pointes, refractory hypokalaemia and hypocalcaemia. Magnesium sulfate 2 g IV is given for torsades, severe asthma and eclampsia. Hypermagnesaemia (often iatrogenic in pre-eclampsia treatment or renal failure) causes loss of deep tendon reflexes, then respiratory depression and heart block; calcium is the antidote."]},{id:"acidbase",title:"Acid\u2013base in five steps",core:!0,body:["One: is the pH acidaemic (< 7.35) or alkalaemic (> 7.45)? Two: which value explains it \u2014 PaCO\u2082 (respiratory) or HCO\u2083\u207B (metabolic)? Three: is compensation appropriate? For metabolic acidosis, expected PaCO\u2082 = 1.5 \xD7 HCO\u2083\u207B + 8 (\xB1 2), Winter's formula; acute respiratory acidosis raises HCO\u2083\u207B about 1 per 10 mmHg CO\u2082, chronic about 4. Four: for metabolic acidosis calculate the anion gap, Na\u207A \u2212 (Cl\u207B + HCO\u2083\u207B), normal about 8\u201312. Five: in a high-gap acidosis, compare the change in gap with the change in bicarbonate to uncover a hidden second metabolic disorder.","High anion-gap causes include lactate, ketones (diabetic, alcoholic, starvation), renal failure, and toxins (methanol, ethylene glycol, salicylates, iron, isoniazid). Normal-gap (hyperchloraemic) acidosis follows diarrhoea, large volumes of saline and renal tubular acidosis."],example:{case:"pH 7.18, PaCO\u2082 22, HCO\u2083\u207B 8, Na\u207A 138, Cl\u207B 100.",steps:["Acidaemia; low HCO\u2083\u207B explains it: metabolic acidosis.","Expected PaCO\u2082 = 1.5 \xD7 8 + 8 = 20 \xB1 2; measured 22 \u2014 appropriate compensation.","Anion gap = 138 \u2212 (100 + 8) = 30: high-gap acidosis.","Change in gap 30 \u2212 12 = 18; change in bicarbonate 24 \u2212 8 = 16 \u2014 similar, so no hidden second metabolic process. Look for lactate, ketones, toxins, renal failure."]}},{id:"temp",title:"Temperature emergencies",body:["Heat stroke is a core temperature above about 40 \xB0C with central nervous system dysfunction. It kills by multi-organ failure; the treatment is rapid cooling \u2014 cold-water immersion is fastest for exertional heat stroke, or evaporative cooling with mist and fans plus ice packs. Antipyretics do not work. Stop cooling around 38.5\u201339 \xB0C to avoid overshoot.",'Hypothermia is graded by core temperature (mild 32\u201335 \xB0C, moderate 28\u201332 \xB0C, severe below 28 \xB0C) and by clinical signs. Handle severely hypothermic patients gently and horizontally to avoid triggering ventricular fibrillation; the cold heart may resist defibrillation and drugs until rewarmed. Rewarm actively; "not dead until warm and dead" applies, and ECMO centres can rewarm patients in arrest.']}],keyPoints:["Symptomatic hyponatraemia: 3 % saline bolus to raise Na\u207A 4\u20136; chronic correction \u2264 8\u201310 per 24 h.","Massive transfusion and pancreatitis cause hypocalcaemia \u2014 give calcium.","Magnesium 2 g IV for torsades; calcium reverses magnesium toxicity.","Acid\u2013base: pH, primary process, compensation (Winter's), anion gap, delta gap.","Heat stroke: cool fast; hypothermia: gentle handling, rewarm, prolonged resuscitation."],pearls:["Calcium chloride has three times the elemental calcium of gluconate.","Loss of reflexes is the first sign of magnesium toxicity."],pitfalls:["Over-correcting chronic hyponatraemia.","Antipyretics for heat stroke."],live:[{id:"hypona",label:"Hyponatraemia and the brain"},{id:"abg-resp-vs-metabolic",label:"Respiratory vs metabolic acidosis"},{id:"metab",label:"Metabolic acidosis and the anion gap"}],questions:[{q:"A seizing patient with Na\u207A 112. First treatment:",options:["Fluid restriction","3 % saline bolus","Normal saline 1 L","Desmopressin"],answer:1,why:"Raise sodium 4\u20136 mmol/L quickly."},{q:"Maximum correction of chronic hyponatraemia in 24 h:",options:["2","8\u201310","20","30 mmol/L"],answer:1,why:"Avoids osmotic demyelination."},{q:"Osmotic demyelination typically appears:",options:["Immediately","Days later","Never","Only in children"],answer:1,why:"Delayed onset after overcorrection."},{q:"Hypocalcaemia during massive transfusion results from:",options:["Dilution only","Citrate binding calcium","Hyperkalaemia","Hypothermia"],answer:1,why:"Citrate anticoagulant chelates calcium."},{q:"Treatment of torsades de pointes:",options:["Amiodarone first","Magnesium sulfate 2 g IV","Adenosine","Procainamide"],answer:1,why:"Magnesium is first-line."},{q:"First sign of magnesium toxicity:",options:["Respiratory arrest","Loss of deep tendon reflexes","Hypertension","Tachycardia"],answer:1,why:"Reflexes disappear before respiratory depression."},{q:"Antidote for magnesium toxicity:",options:["Naloxone","Calcium","Glucagon","Atropine"],answer:1,why:"Calcium antagonises magnesium."},{q:"Winter's formula: HCO\u2083\u207B 10, expected PaCO\u2082:",options:["15","23 \xB1 2","30","40"],answer:1,why:"1.5 \xD7 10 + 8 = 23."},{q:"Anion gap for Na 140, Cl 104, HCO\u2083 12:",options:["12","24","28","36"],answer:1,why:"140 \u2212 116 = 24."},{q:"Which causes a normal anion-gap acidosis?",options:["DKA","Methanol","Severe diarrhoea","Lactic acidosis"],answer:2,why:"Bicarbonate loss with chloride retention."},{q:"Heat stroke is defined by high temperature plus:",options:["Sweating","CNS dysfunction","Hypotension only","Rash"],answer:1,why:"Neurological dysfunction distinguishes it from heat exhaustion."},{q:"Fastest cooling for exertional heat stroke:",options:["Antipyretics","Cold-water immersion","Ice packs to groin only","Fan alone"],answer:1,why:"Immersion has the highest cooling rate."},{q:"Severely hypothermic patients should be moved:",options:["Quickly and upright","Gently and horizontally","Only after rewarming","Prone"],answer:1,why:"Rough handling can trigger VF."},{q:"Shortened QT suggests:",options:["Hypocalcaemia","Hypercalcaemia","Hypokalaemia","Hypomagnesaemia"],answer:1,why:"High calcium shortens the QT."},{q:"Hypernatraemia most often reflects:",options:["Sodium excess","Free-water deficit","Hyperglycaemia","Renal failure only"],answer:1,why:"Water loss or inadequate intake."}],sources:[{title:"European clinical practice guideline on hyponatraemia (2014)",url:"https://academic.oup.com/ndt/article/29/suppl_2/i1/1907948"},{title:"StatPearls: Hypocalcemia",url:"https://www.ncbi.nlm.nih.gov/books/?term=Hypocalcemia+StatPearls"},{title:"StatPearls: Heat stroke",url:"https://www.ncbi.nlm.nih.gov/books/?term=Heat+stroke+StatPearls"}]},Z={id:"fpc-sepsis",domain:"medical",ref:"IV.5",title:"Sepsis and septic shock",summary:"Definitions, early recognition, the first hour, fluids, vasopressors, steroids, and source control \u2014 and what to keep doing during transport.",objectives:["Apply Sepsis-3 definitions of sepsis and septic shock.","Deliver the first-hour bundle: lactate, cultures, antibiotics, fluids, vasopressors.","Titrate norepinephrine and adjuncts to perfusion targets in transport."],sections:[{id:"define",title:"Definitions",core:!0,body:["Sepsis is life-threatening organ dysfunction caused by a dysregulated host response to infection (Sepsis-3). Organ dysfunction is identified by a rise in the SOFA score of two or more points. qSOFA \u2014 respiratory rate \u2265 22, altered mentation, systolic BP \u2264 100 \u2014 flags patients at higher risk of death but is not recommended as a single screening tool.","Septic shock is sepsis with persistent hypotension needing vasopressors to keep MAP \u2265 65 mmHg and a serum lactate above 2 mmol/L despite adequate volume resuscitation. Mortality is substantially higher than sepsis alone."]},{id:"bundle",title:"The first hour",core:!0,body:["Measure lactate (and remeasure if above 2). Take blood cultures before antibiotics when this causes no meaningful delay. Give broad-spectrum antibiotics as soon as possible \u2014 within one hour for probable septic shock; delays raise mortality. Give 30 mL/kg of crystalloid for hypotension or lactate \u2265 4, guided by reassessment of perfusion and fluid responsiveness rather than as a fixed target. Start a vasopressor if MAP remains below 65 during or after fluids.","Balanced crystalloids (lactated Ringer's or Plasma-Lyte) are suggested over saline for large volumes. Albumin may be considered when large volumes of crystalloid are needed. Starch solutions are avoided."],table:{caption:"Vasopressors in septic shock",head:["Agent","Role","Notes"],rows:[["Norepinephrine","First-line","\u03B1-1 vasoconstriction with some \u03B2-1; can run peripherally in a good vein for a short time per protocol"],["Vasopressin","Second agent","Added (often 0.03 U/min) to reduce norepinephrine dose"],["Epinephrine","Add-on","Useful with cardiac dysfunction; raises lactate"],["Dobutamine","Inotrope","For persistent hypoperfusion with poor cardiac function"],["Phenylephrine","Limited","Pure \u03B1; can drop cardiac output"]]}},{id:"targets",title:"Targets and reassessment",core:!0,body:["Aim for MAP \u2265 65 mmHg initially, adjusted for chronic hypertension. Track perfusion, not just pressure: mental status, capillary refill, skin mottling, urine output (\u2265 0.5 mL/kg/h) and lactate clearance. Capillary refill time is a validated, simple target.","Before giving more fluid, ask whether the patient is fluid-responsive (passive leg raise with a change in stroke volume or pulse pressure, pulse-pressure variation in a ventilated patient) and whether lungs and oxygenation will tolerate it. Over-resuscitation causes pulmonary oedema, abdominal compartment syndrome and worse outcomes.","Hydrocortisone (commonly 200 mg/day) is suggested when vasopressor needs are ongoing. Source control \u2014 draining an abscess, removing an infected line, relieving obstructed infected urine \u2014 must happen as soon as practical; transport to a centre that can do it is part of treatment."],example:{case:"A 70-year-old with urosepsis: BP 82/44 (MAP 57), HR 118, lactate 5.2, confused, mottled knees. Weight 70 kg. Two litres given at the referring hospital; no antibiotics yet.",steps:["Antibiotics now \u2014 do not wait for the flight.","He has received about 28 mL/kg; reassess responsiveness before more (passive leg raise, ultrasound, lungs).","Start norepinephrine to MAP \u2265 65; peripheral infusion in a large proximal vein is acceptable short-term per protocol.","Targets in flight: MAP \u2265 65, improving mentation and capillary refill, urine output if catheterised.","Hand over source: likely obstructed infected kidney \u2014 needs urgent decompression at the receiving centre."]}}],keyPoints:["Sepsis = infection + organ dysfunction (SOFA \u2265 2); septic shock = vasopressor for MAP \u2265 65 and lactate > 2 after fluids.","Antibiotics within an hour in septic shock; cultures first only if no delay.","30 mL/kg crystalloid for hypotension or lactate \u2265 4, then reassess responsiveness.","Norepinephrine first, vasopressin second; hydrocortisone if pressors are ongoing.","Target MAP \u2265 65 and perfusion markers; source control is treatment."],pearls:["Peripheral norepinephrine in a good vein is acceptable short-term.","Capillary refill time is a practical resuscitation target."],pitfalls:["Delaying antibiotics for transport.",'Fluid "to a number" without reassessing responsiveness.'],live:[{id:"lines-shock-states",label:"Shock states at the bedside"},{id:"lines-oxygen-delivery",label:"Oxygen delivery"},{id:"moa-norepinephrine",label:"Norepinephrine: mechanism of action"}],questions:[{q:"Septic shock requires vasopressors for MAP \u2265 65 and lactate above:",options:["1 mmol/L","2 mmol/L","4 mmol/L","8 mmol/L"],answer:1,why:"Sepsis-3 definition of septic shock."},{q:"Initial crystalloid volume for sepsis-induced hypotension:",options:["10 mL/kg","30 mL/kg","60 mL/kg","100 mL/kg"],answer:1,why:"Then guided by reassessment."},{q:"First-line vasopressor in septic shock:",options:["Dopamine","Norepinephrine","Phenylephrine","Dobutamine"],answer:1,why:"Lower arrhythmia risk than dopamine."},{q:"Usual second vasopressor added:",options:["Vasopressin","Milrinone","Isoproterenol","Nitroglycerin"],answer:0,why:"Reduces norepinephrine requirement."},{q:"Antibiotic timing in probable septic shock:",options:["Within 1 hour","Within 6 hours","After cultures result","At the receiving centre"],answer:0,why:"Delays increase mortality."},{q:"Sepsis-3 defines organ dysfunction as:",options:["SIRS \u2265 2","SOFA rise \u2265 2","Lactate > 1","Fever"],answer:1,why:"SOFA-based definition."},{q:"qSOFA criteria include all EXCEPT:",options:["RR \u2265 22","Altered mentation","SBP \u2264 100","Temperature > 38"],answer:3,why:"Temperature is not part of qSOFA."},{q:"Hydrocortisone in septic shock is suggested when:",options:["On any antibiotic","Vasopressor requirement is ongoing","Lactate is normal","BP normal"],answer:1,why:"Speeds shock reversal."},{q:"Preferred crystalloid for large-volume resuscitation:",options:["Starch","Balanced crystalloid","D5W","Hypertonic saline"],answer:1,why:"Less hyperchloraemic acidosis."},{q:"A good perfusion marker in the field:",options:["Temperature","Capillary refill time","Blood glucose","Heart sounds"],answer:1,why:"Validated as a resuscitation target."},{q:"Before more fluid, assess:",options:["Only BP","Fluid responsiveness and tolerance","Temperature","Glucose"],answer:1,why:"Avoid over-resuscitation."},{q:"Epinephrine as an add-on vasopressor characteristically:",options:["Lowers lactate","Raises lactate","Lowers HR","Causes bradycardia"],answer:1,why:"\u03B2-2 stimulated glycolysis."},{q:"Source control example:",options:["Antipyretics","Draining an abscess","Albumin","Steroids"],answer:1,why:"Removes the infection focus."},{q:"Phenylephrine in septic shock may:",options:["Increase cardiac output","Reduce cardiac output","Lower SVR","Cause tachycardia"],answer:1,why:"Pure afterload increase with reflex bradycardia."},{q:"Septic patient on norepinephrine: MAP 58, lactate 7.5. Appropriate resuscitation targets:",options:["60 and 3.5","65 and lactate falling toward normal","55 and 6","80 and 1"],answer:1,why:"MAP \u2265 65 with improving lactate."}],sources:[{title:"Singer M et al. The Third International Consensus Definitions for Sepsis (Sepsis-3). JAMA (2016)",url:"https://jamanetwork.com/journals/jama/fullarticle/2492881"},{title:"Surviving Sepsis Campaign: international guidelines (2021)",url:"https://www.sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-guidelines-2021"}]},ee={id:"fpc-infectious",domain:"medical",ref:"IV.6",title:"Infectious disease and transport precautions",summary:"Transmission-based precautions in an aircraft, high-consequence infections, meningitis, necrotising soft-tissue infection, and protecting the crew after exposure.",objectives:["Choose standard, contact, droplet and airborne precautions and adapt them to a confined cabin.","Recognise time-critical infections: meningitis, necrotising fasciitis, toxic shock.","Manage occupational exposure, including post-exposure prophylaxis."],sections:[{id:"precautions",title:"Precautions in a confined space",core:!0,body:["Standard precautions apply to every patient: hand hygiene, gloves for body fluids, eye protection when splashes are likely, safe sharps handling. Contact precautions (gown and gloves) add protection against organisms spread by touch, such as MRSA and Clostridioides difficile (soap and water for hands \u2014 alcohol does not kill spores). Droplet precautions (surgical mask within close range) cover influenza, pertussis and meningococcus. Airborne precautions (fit-tested N95 or equivalent respirator) cover tuberculosis, measles and varicella, and aerosol-generating procedures in respiratory viral illness.","Aircraft cabins are small and air circulation varies by airframe. Put a mask on the patient when possible, use HEPA filters on ventilator and BVM circuits, minimise aerosol-generating procedures in flight (secure the airway before departure, use closed suction), and clean the aircraft per protocol afterwards. Some programmes decline or modify transport of high-consequence infections without special containment."],table:{caption:"Precautions by organism (examples)",head:["Precaution","Examples","PPE"],rows:[["Contact","MRSA, VRE, C. difficile, scabies","Gown, gloves"],["Droplet","Influenza, meningococcus, pertussis","Surgical mask + eye protection"],["Airborne","TB, measles, varicella, aerosol procedures","N95/respirator, eye protection"],["High-consequence","Ebola, other viral haemorrhagic fevers","Specialised PPE and protocols"]]}},{id:"meningitis",title:"Meningitis",core:!0,body:["Bacterial meningitis presents with fever, headache, neck stiffness and altered mental status, though all four are present in a minority. A petechial or purpuric rash suggests meningococcal disease, which can progress to septic shock and purpura fulminans within hours. Infants may show only irritability, poor feeding, a bulging fontanelle or hypothermia.","Give antibiotics without delay \u2014 do not wait for lumbar puncture or imaging when transport or testing will delay treatment. Dexamethasone given with or just before the first antibiotic dose reduces neurological sequelae in some forms (notably pneumococcal). Use droplet precautions until 24 hours of effective therapy; close contacts of meningococcal disease, including crew exposed to respiratory secretions without protection (such as during intubation), need prophylaxis."]},{id:"soft",title:"Necrotising infection and toxic shock",core:!0,body:["Necrotising soft-tissue infection causes pain out of proportion to the findings, rapidly spreading erythema, tense oedema, crepitus, bullae and systemic toxicity. It is a surgical emergency: antibiotics, resuscitation and urgent debridement. Transport to a surgical centre should not wait for imaging.","Toxic shock syndrome (staphylococcal or streptococcal) produces fever, diffuse erythroderma, hypotension and multi-organ involvement; look for retained tampons, wounds or surgical sites. Treat as septic shock, remove the source, and add an antibiotic that suppresses toxin production per protocol."]},{id:"exposure",title:"After an exposure",body:["For a needlestick or mucosal splash: wash with soap and water (irrigate mucosa), report immediately, and arrange evaluation of the source and the exposed worker. HIV post-exposure prophylaxis is most effective started within hours, ideally within 2 hours and no later than 72 hours. Hepatitis B vaccination status determines further management; there is no prophylaxis for hepatitis C, but follow-up testing is needed.","Programmes should have a clear post-exposure process available 24 hours a day, including for exposures far from base."]},{id:"case",title:"Transport case: fever and rash in a dormitory",body:["A 19-year-old student: fever, headache, confusion, BP 84/46, a non-blanching purpuric rash spreading on the legs."],example:{case:"What do you do first, and what do you do for the crew?",steps:["Suspect meningococcal sepsis: give IV or IO antibiotics (for example ceftriaxone) immediately; dexamethasone per protocol.","Droplet precautions: surgical masks and eye protection; mask the patient if possible.","Resuscitate as septic shock: fluids, then norepinephrine; consider adrenal crisis if refractory.","If intubation is needed, wear a respirator and eye protection; afterwards report the exposure so crew receive prophylaxis if indicated."]}}],keyPoints:["Contact: gown and gloves (soap and water for C. difficile); droplet: surgical mask; airborne: N95 respirator.","Mask the patient, HEPA filters on circuits, avoid aerosol procedures in flight.","Suspected bacterial meningitis: antibiotics immediately, dexamethasone with the first dose.","Pain out of proportion with spreading erythema: necrotising infection \u2014 surgery now.","Exposure: wash, report, and start HIV PEP within hours if indicated."],pearls:["Alcohol gel does not kill C. difficile spores.","Unprotected intubation of meningococcal disease warrants crew prophylaxis."],pitfalls:["Delaying antibiotics for a lumbar puncture.","Open suction and NIV in a closed cabin without filtration."],questions:[{q:"Tuberculosis requires:",options:["Contact precautions","Droplet precautions","Airborne precautions with a respirator","Standard only"],answer:2,why:"Airborne transmission."},{q:"Hand hygiene after C. difficile:",options:["Alcohol gel","Soap and water","Gloves only","None"],answer:1,why:"Spores resist alcohol."},{q:"Meningococcal disease requires:",options:["Airborne","Droplet","Contact only","None"],answer:1,why:"Respiratory droplets."},{q:"Antibiotics in suspected bacterial meningitis should be given:",options:["After LP","Immediately","After CT","At the receiving hospital"],answer:1,why:"Delay worsens outcomes."},{q:"Dexamethasone in meningitis is given:",options:["Days later","With or just before the first antibiotic","Never","Only in viral meningitis"],answer:1,why:"Reduces neurological sequelae."},{q:"A hallmark of necrotising fasciitis:",options:["Painless rash","Pain out of proportion to findings","Bradycardia","Localised mild swelling"],answer:1,why:"Early clue before skin changes."},{q:"Definitive treatment of necrotising fasciitis:",options:["Oral antibiotics","Surgical debridement","Steroids","Observation"],answer:1,why:"Surgical emergency."},{q:"Ideal window to start HIV PEP:",options:["Within 2 hours, no later than 72","Within 1 week","Within 30 days","Not needed"],answer:0,why:"Earlier is more effective."},{q:"Measles requires:",options:["Contact","Droplet","Airborne","Standard"],answer:2,why:"Airborne spread."},{q:"Reduce aerosol spread from a ventilated patient by:",options:["Open suction","HEPA filter on the circuit","Removing filters","NIV in flight"],answer:1,why:"Filtration of exhaled gas."},{q:"Infant meningitis may present only with:",options:["Neck stiffness","Irritability, poor feeding, bulging fontanelle","Kernig sign","Photophobia"],answer:1,why:"Classic signs are often absent."},{q:"Toxic shock syndrome rash is classically:",options:["Vesicular","Diffuse erythroderma","Petechial only","Absent"],answer:1,why:"Sunburn-like rash."},{q:"Hepatitis C post-exposure prophylaxis:",options:["Immunoglobulin","None available \u2014 follow-up testing","Antiviral for 28 days routinely","Vaccine"],answer:1,why:"No PEP; monitor."},{q:"Purpura fulminans is associated with:",options:["Meningococcal sepsis","C. difficile","TB","Influenza B only"],answer:0,why:"DIC with skin necrosis."},{q:"Droplet precautions for meningococcus can stop after:",options:["1 hour","24 hours of effective antibiotics","7 days","Never"],answer:1,why:"Standard recommendation."}],sources:[{title:"CDC: Guideline for isolation precautions (2007, updated)",url:"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{title:"IDSA practice guidelines for bacterial meningitis",url:"https://www.idsociety.org/practice-guideline/bacterial-meningitis/"},{title:"CDC: Occupational HIV post-exposure prophylaxis",url:"https://www.cdc.gov/hiv/hcp/pep/index.html"}]};var ae={id:"fpc-tox",domain:"medical",ref:"IV.7",title:"Toxicology: toxidromes and antidotes",summary:"Recognising toxidromes, the high-risk overdoses that kill in transport \u2014 salicylates, tricyclics, calcium-channel and beta-blockers, acetaminophen, toxic alcohols, cyanide and carbon monoxide \u2014 and their antidotes.",objectives:["Identify the major toxidromes from vital signs, pupils, skin and mental status.","Treat life-threatening poisonings with specific antidotes and supportive measures.","Avoid the classic ventilation and drug errors in poisoned patients."],sections:[{id:"toxidromes",title:"Toxidromes",core:!0,body:["A toxidrome is a pattern of signs that points to a class of poison. Look at heart rate, blood pressure, temperature, respiratory rate, pupils, skin (dry or sweaty), bowel sounds and mental status. Mixed ingestions blur the picture, so treat the patient in front of you.",'Sympathomimetic (cocaine, amphetamines): agitation, tachycardia, hypertension, hyperthermia, dilated pupils, sweating. Treat with benzodiazepines, cooling and avoidance of physical restraint struggles. Anticholinergic (diphenhydramine, tricyclics, jimson weed): "hot as a hare, dry as a bone, red as a beet, blind as a bat, mad as a hatter" \u2014 tachycardia, hyperthermia, dry flushed skin, dilated pupils, urinary retention, delirium; physostigmine has a role in pure anticholinergic delirium under expert guidance.','Cholinergic (organophosphates, nerve agents): SLUDGE/DUMBELS \u2014 salivation, lacrimation, urination, defecation, GI upset, emesis, plus bronchorrhoea and bronchospasm ("the killer Bs") and bradycardia, with miosis. Treat with large, repeated doses of atropine titrated to drying of secretions, and pralidoxime for organophosphates; decontaminate and protect the crew. Opioid: miosis, respiratory depression and coma; naloxone titrated to breathing, not wakefulness. Sedative-hypnotic: depressed consciousness with relatively normal vital signs; support the airway and breathing.'],table:{caption:"Toxidrome quick table",head:["Toxidrome","HR / BP","Temp","Pupils","Skin","Key treatment"],rows:[["Sympathomimetic","\u2191 / \u2191","\u2191","Dilated","Sweaty","Benzodiazepines, cooling"],["Anticholinergic","\u2191 / \u2191 or \u2194","\u2191","Dilated","Dry, flushed","Benzodiazepines, cooling"],["Cholinergic","\u2193 (often) / \u2194","\u2194","Pinpoint","Wet","Atropine, pralidoxime"],["Opioid","\u2193 / \u2193","\u2193 or \u2194","Pinpoint","\u2194","Naloxone, ventilation"],["Sedative-hypnotic","\u2194 or \u2193","\u2194","\u2194","\u2194","Airway and breathing support"]]}},{id:"killers",title:"Overdoses that kill in transport",core:!0,body:["Salicylates: tinnitus, vomiting, hyperthermia, tachypnoea, a mixed respiratory alkalosis and high-gap metabolic acidosis, and altered mental status. The patient survives by hyperventilating; if intubated, the minute ventilation must stay high or the pH falls, salicylate enters the brain and the patient may arrest. Alkalinise with sodium bicarbonate, give dextrose for neuroglycopenia, and arrange haemodialysis for severe toxicity. Methyl salicylate (oil of wintergreen) is highly concentrated and has a distinctive smell.","Tricyclic antidepressants: anticholinergic signs, seizures, hypotension and sodium-channel blockade with a wide QRS (> 100 ms) and a tall terminal R in aVR. Treat QRS widening, hypotension or arrhythmia with sodium bicarbonate boluses (1\u20132 mEq/kg, repeated) to a pH of about 7.45\u20137.55; avoid type IA and IC antiarrhythmics.","Calcium-channel and beta-blockers: bradycardia and hypotension, with hyperglycaemia typical of calcium-channel blockers. Treat with fluids, calcium, glucagon (beta-blockers), vasopressors, and high-dose insulin euglycaemia therapy (insulin around 1 unit/kg bolus then infusion with dextrose and potassium monitoring) per toxicology advice; lipid emulsion for refractory lipophilic drug toxicity.","Acetaminophen: few early symptoms, then liver injury at 24\u201372 hours. N-acetylcysteine is most effective within 8 hours of ingestion; never withhold it while waiting for levels if presentation is late or the dose is unknown.","Toxic alcohols (methanol, ethylene glycol): inebriation, then a high anion-gap acidosis with a raised osmolar gap; methanol causes visual loss, ethylene glycol renal failure. Fomepizole blocks alcohol dehydrogenase; dialysis removes the parent compound and toxic metabolites."]},{id:"gases",title:"Carbon monoxide and cyanide",core:!0,body:["Carbon monoxide binds haemoglobin about 200\u2013250 times more avidly than oxygen and shifts the dissociation curve left, so tissues receive less oxygen. Headache, nausea, confusion and syncope are common; standard pulse oximetry reads falsely normal because it cannot distinguish carboxyhaemoglobin. Give 100 % oxygen (the half-life of COHb falls from about 4\u20136 hours on air to about 60\u201390 minutes on 100 %); hyperbaric oxygen is considered for severe cases, pregnancy, loss of consciousness or neurological deficits.","Cyanide blocks cytochrome oxidase, halting aerobic metabolism: sudden collapse, seizures, severe lactic acidosis and a high venous oxygen saturation. House fires (burning plastics) cause combined CO and cyanide poisoning; consider cyanide in smoke-inhalation victims with altered consciousness, hypotension or lactate above about 8 mmol/L. Hydroxocobalamin binds cyanide to form cyanocobalamin and turns skin and urine red, interfering with some lab tests."]},{id:"principles",title:"General principles",body:["Airway, breathing and circulation first; check glucose in every altered patient. Decontaminate before transport when the poison is on the skin or clothing (organophosphates, chemicals) to protect the crew and aircraft. Activated charcoal is considered only when the airway is protected and within about an hour of a significant ingestion of an adsorbable toxin; it does not bind iron, lithium, alcohols or metals.","Seizures from poisoning are treated with benzodiazepines first; phenytoin is ineffective and harmful in some (tricyclics). Contact a poison centre early; transport time is a good time to call."],example:{case:"A 32-year-old after a mixed overdose: GCS 8, HR 132, BP 84/50, temp 38.6 \xB0C, pupils dilated, skin dry, QRS 140 ms with a tall R in aVR.",steps:["Anticholinergic signs plus a wide QRS: suspect a tricyclic.","Sodium bicarbonate 1\u20132 mEq/kg IV, repeat until the QRS narrows and BP improves.","Secure the airway; after intubation hyperventilate modestly to keep the pH alkaline.","Benzodiazepines for seizures; avoid class IA/IC antiarrhythmics; vasopressor for persistent hypotension."]}}],keyPoints:["Use HR, BP, temperature, pupils, skin and mental status to name the toxidrome.","Cholinergic: atropine until secretions dry, plus pralidoxime; opioid: naloxone to breathing.","Salicylates: keep minute ventilation high if intubated; bicarbonate; dialysis.","TCA: wide QRS and tall R in aVR \u2192 sodium bicarbonate.","CO: pulse oximetry falsely normal \u2014 100 % O\u2082; cyanide in fires \u2014 hydroxocobalamin."],pearls:["Oil of wintergreen smells distinctive and is highly concentrated salicylate.","High venous oxygen saturation plus severe lactic acidosis suggests cyanide."],pitfalls:["Normal ventilator settings after intubating a salicylate overdose.","Trusting SpO\u2082 in carbon monoxide poisoning."],live:[{id:"metab",label:"Metabolic acidosis and the anion gap (salicylates)"}],questions:[{q:"Dry, flushed skin, dilated pupils, tachycardia and delirium suggest:",options:["Cholinergic","Anticholinergic","Opioid","Sedative"],answer:1,why:"Classic anticholinergic toxidrome."},{q:"Treatment end-point for atropine in organophosphate poisoning:",options:["Heart rate 60","Drying of bronchial secretions","Pupil dilation","Fixed dose of 1 mg"],answer:1,why:"Titrate to dry secretions and clear breathing."},{q:"A toddler drank a liniment and now has vomiting, tachypnoea and tinnitus-like distress. The most concerning ingredient is:",options:["Menthol","Methyl salicylate","Camphor-free lanolin","Glycerin"],answer:1,why:"Methyl salicylate (oil of wintergreen) is highly concentrated salicylate \u2014 small volumes are dangerous."},{q:"After intubating a salicylate-poisoned patient, ventilation should be:",options:["Low rate","High minute ventilation","Permissive hypercapnia","PS only"],answer:1,why:"Acidosis drives salicylate into the brain."},{q:"A tricyclic overdose with QRS 150 ms is treated first with:",options:["Amiodarone","Sodium bicarbonate","Procainamide","Phenytoin"],answer:1,why:"Sodium loading and alkalinisation."},{q:"Hyperglycaemia with bradycardia and hypotension suggests poisoning with:",options:["Beta-blocker","Calcium-channel blocker","Opioid","Organophosphate"],answer:1,why:"CCBs impair insulin release."},{q:"High-dose insulin therapy is used for:",options:["TCA toxicity","Calcium-channel/beta-blocker toxicity","Opioids","CO"],answer:1,why:"Improves myocardial energy use."},{q:"N-acetylcysteine is most effective within:",options:["1 hour","8 hours","48 hours","7 days"],answer:1,why:"Early therapy prevents hepatotoxicity."},{q:"Fomepizole treats:",options:["Methanol and ethylene glycol","Cyanide","CO","Iron"],answer:0,why:"Blocks alcohol dehydrogenase."},{q:"Standard pulse oximetry in CO poisoning reads:",options:["Falsely low","Falsely normal","Accurate","Zero"],answer:1,why:"COHb is read as oxyhaemoglobin."},{q:"Half-life of COHb on 100 % oxygen:",options:["4\u20136 h","60\u201390 min","5 min","24 h"],answer:1,why:"Much shorter than on room air."},{q:"Smoke inhalation with lactate 12 and coma suggests adding:",options:["Naloxone","Hydroxocobalamin","Flumazenil","Atropine"],answer:1,why:"Cyanide toxicity."},{q:"Activated charcoal does NOT bind:",options:["Acetaminophen","Iron and lithium","Aspirin","Tricyclics"],answer:1,why:"Metals and alcohols are not adsorbed."},{q:"First-line for toxin-induced seizures:",options:["Phenytoin","Benzodiazepine","Propranolol","Physostigmine"],answer:1,why:"Phenytoin is ineffective/harmful in some poisonings."},{q:"Naloxone should be titrated to:",options:["Full wakefulness","Adequate breathing","Pupil size","Heart rate"],answer:1,why:"Avoid precipitating violent withdrawal."}],sources:[{title:"StatPearls: Toxidromes",url:"https://www.ncbi.nlm.nih.gov/books/?term=Toxidromes+StatPearls"},{title:"StatPearls: Salicylate toxicity",url:"https://www.ncbi.nlm.nih.gov/books/?term=Salicylate+toxicity+StatPearls"},{title:"StatPearls: Carbon monoxide toxicity",url:"https://www.ncbi.nlm.nih.gov/books/?term=Carbon+monoxide+toxicity+StatPearls"}]},ie={id:"fpc-blood",domain:"medical",ref:"IV.8",title:"Blood products and transfusion",summary:"Red cells, plasma, platelets, cryoprecipitate and whole blood; compatibility; massive transfusion; reactions; and the complications of large-volume transfusion.",objectives:["Select the right product and compatibility for the situation.","Run a massive transfusion with balanced ratios, calcium and warming.","Recognise and manage transfusion reactions in flight."],sections:[{id:"products",title:"The products",core:!0,body:["Packed red blood cells (PRBCs) restore oxygen-carrying capacity; one unit raises haemoglobin by about 1 g/dL in an adult. Plasma (fresh frozen or liquid/thawed) replaces clotting factors. Platelets (one apheresis unit raises the count by roughly 30,000\u201350,000/\xB5L) treat thrombocytopenia or dysfunction. Cryoprecipitate is concentrated fibrinogen, factor VIII, von Willebrand factor and factor XIII. Low-titre O whole blood provides all components in one bag and is increasingly carried by prehospital services.","Universal donors: O-negative red cells (O-positive acceptable for most males and for women beyond childbearing age when stocks require); AB plasma is the universal plasma donor (low-titre A plasma is used by some programmes). Women of childbearing potential receive O-negative red cells when the type is unknown to avoid Rh sensitisation."],table:{caption:"Products at a glance",head:["Product","Contains","Main use","Storage"],rows:[["PRBC","Red cells","Anaemia, haemorrhage","Refrigerated 1\u20136 \xB0C"],["Plasma","All clotting factors","Coagulopathy, MTP","Frozen or thawed refrigerated"],["Platelets","Platelets","Thrombocytopenia, MTP","Room temperature, agitated"],["Cryoprecipitate","Fibrinogen, VIII, vWF, XIII","Low fibrinogen","Frozen"],["Whole blood","All","Haemorrhagic shock","Refrigerated"]]}},{id:"mtp",title:"Massive transfusion",core:!0,body:["Massive transfusion is commonly defined as 10 or more units of red cells in 24 hours, or a rapid rate such as 3\u20134 units in an hour. Damage-control resuscitation gives products in a balanced ratio approximating whole blood \u2014 about 1:1:1 plasma, platelets and red cells \u2014 limits crystalloid, permits low blood pressure until haemorrhage control (except in head injury), and treats coagulopathy early with tranexamic acid (within 3 hours of injury) and fibrinogen replacement guided by testing.","Hazards rise with volume: hypocalcaemia (citrate binds calcium \u2014 give calcium early), hypothermia (warm every product; cold blood worsens coagulopathy), hyperkalaemia (stored cells leak potassium), acidosis, dilutional coagulopathy, and transfusion-associated circulatory overload."]},{id:"reactions",title:"Transfusion reactions",core:!0,body:["Watch closely during the first 15 minutes of each unit and throughout. If a reaction is suspected: stop the transfusion, keep the line open with saline, check the patient's identity against the unit, treat the symptoms, and report and return the bag per protocol.","Acute haemolytic reaction (ABO incompatibility, usually clerical error): fever, chills, back or flank pain, hypotension, haemoglobinuria and DIC \u2014 can be fatal; stop, fluids, support. Febrile non-haemolytic: fever and chills without other signs; antipyretics after excluding haemolysis. Allergic: urticaria and itching; antihistamines; anaphylaxis (wheeze, hypotension) needs adrenaline. TRALI: acute hypoxaemia and bilateral infiltrates within 6 hours, often with hypotension and fever; supportive ventilation. TACO: hypertension, pulmonary oedema and volume overload; slow or stop, diuretics, NIV. Sepsis from contaminated product: high fever and shock, especially with platelets."],list:{caption:"TRALI versus TACO",items:["TRALI: hypotension common, no response to diuretics, fever, non-cardiogenic oedema.","TACO: hypertension, raised JVP, responds to diuretics, cardiogenic oedema."]}},{id:"case",title:"Transport case: the motorcyclist",body:["A 28-year-old motorcyclist with a pelvic fracture and femur fracture: HR 140, BP 74/40, cool and pale. You carry 2 units of low-titre O whole blood and 2 units of plasma."],example:{case:"Resuscitate.",steps:["Control external bleeding; pelvic binder; femoral traction splint.","Give whole blood through a warmer; tranexamic acid 1 g IV (within 3 hours of injury) per protocol.","Give calcium with the blood products; check temperature and keep him warm.","Target a systolic around 80\u201390 (permissive hypotension) without head injury until haemorrhage control; pre-alert for massive transfusion at the trauma centre.","Monitor for reactions; document unit numbers."]}}],keyPoints:["O-negative red cells for unknown type in women of childbearing potential; AB plasma is the universal plasma.","Massive transfusion: balanced 1:1:1, limited crystalloid, TXA within 3 h, fibrinogen.","Give calcium and warm every product.","Reaction: stop, saline, check identity, treat, report.","TRALI is hypotensive non-cardiogenic oedema; TACO is hypertensive volume overload."],pearls:["One unit of PRBCs raises Hb about 1 g/dL.","Platelets are stored at room temperature and carry the highest bacterial contamination risk."],pitfalls:["Running cold blood through a fast line without a warmer.","Forgetting calcium during massive transfusion."],live:[{id:"lines-haemorrhage-transfusion",label:"Haemorrhagic shock and transfusion"},{id:"labs-coag",label:"Reversing anticoagulation"}],questions:[{q:"Universal donor plasma type:",options:["O","A","B","AB"],answer:3,why:"AB plasma lacks anti-A and anti-B antibodies."},{q:"Unknown-type woman of childbearing age needs uncrossmatched red cells:",options:["O-positive","O-negative","AB-negative","A-positive"],answer:1,why:"Avoid Rh sensitisation."},{q:"Cryoprecipitate is mainly used to replace:",options:["Platelets","Fibrinogen","Albumin","Red cells"],answer:1,why:"Rich in fibrinogen."},{q:"Massive transfusion target ratio:",options:["1 plasma : 4 RBC","1:1:1 plasma, platelets, RBC","Crystalloid only","RBC only"],answer:1,why:"Approximates whole blood."},{q:"TXA in trauma is given within:",options:["1 hour only","3 hours of injury","24 hours","Any time"],answer:1,why:"Benefit lost (possible harm) after 3 h."},{q:"Citrate in stored blood causes:",options:["Hypercalcaemia","Hypocalcaemia","Hyponatraemia","Hypoglycaemia"],answer:1,why:"Citrate chelates calcium."},{q:"First action for a suspected transfusion reaction:",options:["Slow the rate","Stop the transfusion","Give furosemide","Continue and observe"],answer:1,why:"Stop, keep line open with saline."},{q:"Fever, flank pain, hypotension and dark urine early in a transfusion suggest:",options:["Allergic reaction","Acute haemolytic reaction","TACO","Febrile non-haemolytic"],answer:1,why:"ABO incompatibility."},{q:"Hypoxaemia, bilateral infiltrates, hypotension within 6 h of transfusion:",options:["TACO","TRALI","Anaphylaxis","Haemolysis"],answer:1,why:"TRALI is non-cardiogenic and often hypotensive."},{q:"Hypertension, raised JVP and pulmonary oedema after transfusion:",options:["TRALI","TACO","Sepsis","Haemolysis"],answer:1,why:"Volume overload."},{q:"Highest bacterial contamination risk product:",options:["PRBC","Plasma","Platelets","Cryoprecipitate"],answer:2,why:"Room-temperature storage."},{q:"One adult PRBC unit raises Hb by about:",options:["0.1 g/dL","1 g/dL","3 g/dL","5 g/dL"],answer:1,why:"Standard estimate."},{q:"Stored blood potassium tends to be:",options:["Low","High","Normal","Zero"],answer:1,why:"Cells leak potassium during storage."},{q:"Why warm blood products?",options:["Prevent hypothermia-induced coagulopathy","Increase haemoglobin","Prevent TRALI","Not needed"],answer:0,why:"Hypothermia impairs clotting."},{q:"Permissive hypotension is NOT appropriate with:",options:["Penetrating torso trauma","Traumatic brain injury","Pelvic fracture","Splenic injury"],answer:1,why:"The brain needs perfusion pressure."}],sources:[{title:"CRASH-2 trial: tranexamic acid in bleeding trauma patients. Lancet (2010)",url:"https://pubmed.ncbi.nlm.nih.gov/20554319/"},{title:"Holcomb JB et al. PROPPR: 1:1:1 vs 1:1:2 transfusion. JAMA (2015)",url:"https://jamanetwork.com/journals/jama/fullarticle/2107789"},{title:"StatPearls: Transfusion reactions",url:"https://www.ncbi.nlm.nih.gov/books/?term=Transfusion+reactions+StatPearls"}]},te={id:"fpc-gi",domain:"medical",ref:"IV.9",title:"Gastrointestinal emergencies",summary:"Upper and lower GI bleeding, variceal haemorrhage, liver failure, pancreatitis, bowel obstruction and perforation, and mesenteric ischaemia \u2014 what to do before and during transport.",objectives:["Resuscitate GI haemorrhage, including variceal bleeding and anticoagulated patients.","Recognise and manage pancreatitis, obstruction, perforation and mesenteric ischaemia.","Plan airway and aspiration management for the vomiting or bleeding patient."],sections:[{id:"bleeding",title:"GI haemorrhage",core:!0,body:["Upper GI bleeding (above the ligament of Treitz) presents with haematemesis, coffee-ground vomit or melaena; common causes are peptic ulcer, varices, Mallory\u2013Weiss tears and oesophagitis. Brisk upper bleeding can also cause haematochezia. Lower GI bleeding usually presents with fresh blood per rectum (diverticulosis, angiodysplasia, colitis).","Resuscitate with blood products guided by haemodynamics and a restrictive transfusion threshold (around Hb 7 g/dL) in stable patients without cardiac disease; massive bleeding needs balanced products. Reverse anticoagulants as indicated. A proton-pump inhibitor is commonly started for suspected upper bleeding. Large-bore access, suction and a plan for the airway are essential: blood in the airway turns intubation into a contaminated, high-risk procedure."]},{id:"varices",title:"Variceal bleeding and liver failure",core:!0,body:["Patients with cirrhosis and portal hypertension bleed from oesophageal or gastric varices. Treatment adds octreotide (splanchnic vasoconstrictor) and prophylactic antibiotics (they reduce infection and rebleeding and improve survival) to resuscitation, with endoscopic banding as definitive therapy. Avoid over-transfusion, which raises portal pressure. In uncontrolled bleeding, a balloon tamponade device (Sengstaken\u2013Blakemore or Minnesota tube) is a bridge, placed only after intubation.","Cirrhotic patients have a complex coagulopathy (both bleeding and clotting tendencies), thrombocytopenia, encephalopathy (lactulose; look for precipitants such as bleeding and infection), ascites with possible spontaneous bacterial peritonitis, hepatorenal syndrome and relative hypotension. Acute liver failure (for example from acetaminophen) adds cerebral oedema and hypoglycaemia."]},{id:"abdomen",title:"Pancreatitis, obstruction, perforation and ischaemia",core:!0,body:["Acute pancreatitis (gallstones and alcohol are commonest) causes epigastric pain radiating to the back, vomiting and raised lipase. Severe disease brings systemic inflammation, third-spacing, hypocalcaemia, ARDS and shock. Give goal-directed fluids \u2014 avoid both under- and over-resuscitation \u2014 analgesia, and organ support.","Bowel obstruction causes colicky pain, distension, vomiting and absolute constipation; decompress with a gastric tube, replace fluids and electrolytes, and watch for strangulation (constant pain, fever, peritonism, lactate). Perforation causes sudden severe pain, peritonitis and free air; treat with resuscitation, antibiotics and surgery.","Acute mesenteric ischaemia \u2014 often an embolus in a patient with atrial fibrillation \u2014 causes pain out of proportion to a soft abdomen. Lactate may be normal early. It needs urgent CT angiography and revascularisation; delay costs bowel."]},{id:"transport",title:"Transport considerations",body:["Gas expands at altitude (Boyle's law): an obstructed or distended bowel enlarges, increasing pain, vomiting and splinting of the diaphragm. Decompress with a gastric tube before flight in obstruction or ileus, and vent it during flight. Consider lower cabin altitude when possible.","For a patient vomiting blood with a decreased level of consciousness, the airway decision is about aspiration risk and the transport environment: intubation on the ground with SALAD technique and resuscitation first is usually safer than an airway crisis in flight."],example:{case:"A 55-year-old with cirrhosis vomiting large volumes of blood: HR 128, BP 86/50, confused.",steps:["Blood products through a warmer; avoid over-transfusion; reverse coagulopathy per protocol.","Octreotide and IV antibiotics; PPI per protocol.","Protect the airway before flight: head up, large-bore suction, SALAD-ready, resuscitate first, reduced-dose induction.","Gastric decompression after intubation; balloon tamponade only if bleeding is uncontrolled and expertise exists."]}}],keyPoints:["Upper GI bleed: haematemesis, coffee grounds, melaena; resuscitate, reverse anticoagulants, PPI.","Varices: octreotide plus antibiotics; avoid over-transfusion; tamponade only after intubation.","Pancreatitis: goal-directed fluids, analgesia, watch for hypocalcaemia and ARDS.","Mesenteric ischaemia: pain out of proportion; normal lactate does not exclude it.","Decompress distended bowel before flight; gas expands with altitude."],pearls:["Prophylactic antibiotics improve survival in variceal haemorrhage.","Brisk upper GI bleeding can present as bright red rectal blood."],pitfalls:["Liberal transfusion in variceal bleeding.","Flying an obstructed patient without gastric decompression."],live:[{id:"abd-mesenteric",label:"Acute mesenteric ischaemia"},{id:"abd-obstruction",label:"Bowel obstruction and perforation"}],questions:[{q:"Melaena usually indicates bleeding:",options:["From haemorrhoids","Above the ligament of Treitz","From the sigmoid","From the bladder"],answer:1,why:"Upper GI blood digested in transit."},{q:"Octreotide in variceal bleeding works by:",options:["Increasing portal pressure","Splanchnic vasoconstriction","Neutralising acid","Clotting factor replacement"],answer:1,why:"Lowers portal inflow."},{q:"Which improves survival in cirrhotic GI bleeding?",options:["Prophylactic antibiotics","Liberal transfusion","Albumin only","Aspirin"],answer:0,why:"Reduces infection and rebleeding."},{q:"A balloon tamponade tube should be placed:",options:["Before intubation","After intubation","Never","In the field always"],answer:1,why:"Airway protection first."},{q:"Over-transfusion in variceal bleeding:",options:["Lowers portal pressure","Raises portal pressure and rebleeding","Is required","Prevents encephalopathy"],answer:1,why:"Restrictive strategy preferred."},{q:"Classic pancreatitis pain:",options:["Right lower quadrant","Epigastric radiating to the back","Suprapubic","Left shoulder only"],answer:1,why:"Retroperitoneal organ."},{q:"Electrolyte disturbance in severe pancreatitis:",options:["Hypercalcaemia","Hypocalcaemia","Hypernatraemia","Hyperkalaemia always"],answer:1,why:"Saponification of fat binds calcium."},{q:"Pain out of proportion with a soft abdomen in AF suggests:",options:["Appendicitis","Mesenteric ischaemia","Gastritis","Constipation"],answer:1,why:"Early ischaemia lacks peritonism."},{q:"At altitude, gas in an obstructed bowel:",options:["Contracts","Expands","Unchanged","Dissolves"],answer:1,why:"Boyle's law."},{q:"Before flying a patient with bowel obstruction:",options:["Give oral fluids","Place and vent a gastric tube","Give laxatives","Nothing"],answer:1,why:"Decompress to limit expansion."},{q:"Restrictive Hb threshold for stable GI bleeding without cardiac disease:",options:["5","7","10","12 g/dL"],answer:1,why:"Restrictive strategy improves outcomes."},{q:"Hepatic encephalopathy is treated with:",options:["Lactulose","Morphine","Benzodiazepines","Protein loading"],answer:0,why:"Reduces ammonia absorption."},{q:"Free air under the diaphragm on an upright film suggests:",options:["Obstruction","Perforated viscus","Pancreatitis","Normal"],answer:1,why:"Pneumoperitoneum."},{q:"Strangulated obstruction is suggested by:",options:["Colicky pain only","Constant pain, fever, peritonism","Normal lactate always","Diarrhoea"],answer:1,why:"Ischaemic bowel."},{q:"Acute liver failure particularly risks:",options:["Hyperglycaemia","Cerebral oedema and hypoglycaemia","Hypercoagulability only","Bradycardia"],answer:1,why:"Loss of hepatic function."}],sources:[{title:"StatPearls: Upper gastrointestinal bleeding",url:"https://www.ncbi.nlm.nih.gov/books/?term=Upper+gastrointestinal+bleeding+StatPearls"},{title:"Villanueva C et al. Transfusion strategies for acute upper GI bleeding. NEJM (2013)",url:"https://www.nejm.org/doi/full/10.1056/NEJMoa1211801"},{title:"StatPearls: Acute pancreatitis",url:"https://www.ncbi.nlm.nih.gov/books/?term=Acute+pancreatitis+StatPearls"}]};var oe={id:"fpc-labs",domain:"medical",ref:"IV.10",title:"Lab values: CBC, coagulation, BMP, ABG and cardiac markers",summary:"The normal ranges worth knowing cold, what each abnormality means for the patient in front of you, and how to read a set of labs as a story rather than a list.",objectives:["Recall normal ranges for common critical care labs.","Interpret CBC, coagulation, chemistry, blood gas and cardiac marker results in context.","Spot the lab patterns that change transport management."],sections:[{id:"ranges",title:"Values to know",core:!0,body:["Reference ranges vary slightly between laboratories, but exam questions and bedside decisions rest on a core set. Learn the units your system uses; US labs report glucose in mg/dL and many others in mmol/L (divide mg/dL by 18)."],table:{caption:"Common adult reference values (approximate)",head:["Test","Normal","Critical clues"],rows:[["Haemoglobin","12\u201316 (F), 13.5\u201317.5 (M) g/dL","Lags behind acute bleeding"],["WBC","4\u201311 \xD7 10\u2079/L","> 12 or < 4 in SIRS; left shift in infection"],["Platelets","150\u2013400 \xD7 10\u2079/L","< 50 bleeding risk with procedures; < 20 spontaneous"],["Sodium","135\u2013145 mmol/L","< 120 or > 160 dangerous"],["Potassium","3.5\u20135.0 mmol/L","> 6.5 or ECG changes: emergency"],["Chloride / HCO\u2083\u207B","98\u2013106 / 22\u201328 mmol/L","Anion gap = Na \u2212 (Cl + HCO\u2083), \u2248 8\u201312"],["BUN / creatinine","7\u201320 / 0.6\u20131.2 mg/dL","BUN:Cr > 20 suggests pre-renal or upper GI bleed"],["Glucose","70\u2013100 mg/dL fasting","< 70 hypoglycaemia"],["PT / INR","11\u201313.5 s / 0.8\u20131.2","Warfarin target 2\u20133"],["aPTT","25\u201335 s","Prolonged with heparin, factor deficits"],["Fibrinogen","200\u2013400 mg/dL","< 150\u2013200 replace in haemorrhage"],["Lactate","< 2 mmol/L","> 4 high risk"],["Troponin","Below the 99th percentile (assay specific)","Rise and/or fall indicates myocardial injury"],["ABG","pH 7.35\u20137.45, PaCO\u2082 35\u201345, PaO\u2082 80\u2013100, HCO\u2083\u207B 22\u201326","Interpret with compensation"]]}},{id:"cbc",title:"CBC and coagulation in context",core:!0,body:["Haemoglobin is a concentration. In acute haemorrhage it stays near normal until fluid shifts in or crystalloid is given, so a normal first haemoglobin does not exclude major bleeding. Conversely, dilution after crystalloid can lower it without further bleeding.","White cell counts rise with infection, stress, steroids and epinephrine. A low count in sepsis is ominous. Thrombocytopenia has many causes: consumption (DIC, massive bleeding), sequestration (splenomegaly), destruction (immune, heparin-induced thrombocytopenia) and dilution.","PT/INR tests the extrinsic and common pathways (factor VII and vitamin K\u2013dependent factors: warfarin, liver disease); aPTT tests the intrinsic and common pathways (heparin, haemophilia). DIC prolongs both, lowers platelets and fibrinogen and raises D-dimer. Viscoelastic tests (TEG, ROTEM) guide targeted product replacement in haemorrhage where available."]},{id:"chem",title:"Chemistry and cardiac markers",core:!0,body:["Creatinine reflects filtration but rises late; a normal value does not mean normal function in an elderly, small or malnourished patient. A BUN-to-creatinine ratio above about 20 suggests pre-renal states or blood digested from an upper GI bleed.","Troponin rises within hours of myocardial injury; high-sensitivity assays detect smaller injuries earlier, and serial values distinguish acute injury (a rise and/or fall) from chronic elevation (renal failure, heart failure). Troponin elevation is not the same as myocardial infarction: sepsis, pulmonary embolism, myocarditis and tachyarrhythmia also cause it. BNP rises with ventricular stretch and supports a diagnosis of heart failure; it is higher with renal failure and lower in obesity.",'Liver tests: AST and ALT rise with hepatocellular injury (ischaemic "shock liver" and acetaminophen produce very high values); bilirubin and alkaline phosphatase rise with obstruction. Ammonia rises in liver failure but does not correlate tightly with encephalopathy severity.']},{id:"story",title:"Reading labs as a story",body:["Ask what process could produce all the abnormalities at once. A low bicarbonate, high anion gap, high glucose and high potassium tell the story of DKA. Low platelets, low fibrinogen and prolonged clotting times after major trauma tell the story of consumptive coagulopathy. Low sodium with seizures in a marathon runner tells the story of exercise-associated hyponatraemia."],example:{case:"A 68-year-old with fever and confusion: WBC 2.8, platelets 62, INR 1.9, fibrinogen 120, lactate 6.4, creatinine 2.4.",steps:["Leukopenia and high lactate: severe sepsis with hypoperfusion.","Low platelets, prolonged INR and low fibrinogen: disseminated intravascular coagulation.","Raised creatinine: acute kidney injury from hypoperfusion.","Management: septic shock bundle, source control, product replacement only if bleeding or procedures are planned."]}}],keyPoints:["Potassium > 6.5 or ECG changes: emergency; sodium < 120 or > 160: dangerous.","Haemoglobin lags behind acute bleeding.","PT/INR = extrinsic (warfarin, liver); aPTT = intrinsic (heparin); DIC prolongs both, lowers platelets and fibrinogen.","Troponin rise/fall = acute myocardial injury, not necessarily MI.","BUN:Cr > 20 suggests pre-renal states or upper GI bleeding."],pearls:["Divide glucose in mg/dL by 18 for mmol/L.","A low WBC in sepsis is a bad sign."],pitfalls:["Reassurance from a normal haemoglobin early in haemorrhage.","Calling every troponin rise a heart attack."],live:[{id:"labs-coag",label:"Reversing anticoagulation"},{id:"lactate",label:"Lactate: made and cleared"}],questions:[{q:"Normal anion gap is about:",options:["2\u20134","8\u201312","20\u201324","30\u201334"],answer:1,why:"Na \u2212 (Cl + HCO\u2083)."},{q:"Warfarin prolongs mainly:",options:["aPTT","PT/INR","Bleeding time only","Platelet count"],answer:1,why:"Vitamin K\u2013dependent factors, especially VII."},{q:"Unfractionated heparin prolongs mainly:",options:["PT","aPTT","Fibrinogen","Hb"],answer:1,why:"Intrinsic pathway via antithrombin."},{q:"DIC typically shows:",options:["High platelets, high fibrinogen","Low platelets, low fibrinogen, prolonged PT/aPTT","Normal coagulation","Isolated high INR"],answer:1,why:"Consumption of factors and platelets."},{q:"Hb 14 ten minutes after a stab wound with BP 80/50:",options:["Excludes bleeding","Does not exclude major haemorrhage","Means polycythaemia","Means dehydration only"],answer:1,why:"Concentration lags."},{q:"BUN:Cr ratio above 20 suggests:",options:["Intrinsic renal disease","Pre-renal state or upper GI bleed","Liver failure","Normal"],answer:1,why:"BUN rises disproportionately."},{q:"Glucose 180 mg/dL in mmol/L:",options:["5","10","18","32"],answer:1,why:"180 \xF7 18 = 10."},{q:"Troponin elevation without MI can occur in:",options:["Pulmonary embolism","Ankle sprain","Hypoglycaemia only","Asthma always"],answer:0,why:"RV strain causes myocardial injury."},{q:"BNP is falsely lower in:",options:["Renal failure","Obesity","Heart failure","Old age"],answer:1,why:"Adipose tissue clears natriuretic peptides."},{q:"Platelet count below which spontaneous bleeding risk rises sharply:",options:["150","100","20","400"],answer:2,why:"Below about 10\u201320 \xD7 10\u2079/L."},{q:"Very high AST/ALT after prolonged hypotension suggests:",options:["Biliary obstruction","Ischaemic hepatitis (shock liver)","Pancreatitis","Normal"],answer:1,why:"Hepatocellular injury."},{q:"Fibrinogen threshold commonly prompting replacement in haemorrhage:",options:["< 400","< 150\u2013200 mg/dL","< 50","Never"],answer:1,why:"Low fibrinogen predicts bleeding."},{q:"Normal PaCO\u2082 range:",options:["25\u201335","35\u201345","45\u201355","60\u201380"],answer:1,why:"Standard reference."},{q:"Lactate above which risk of death rises markedly in sepsis:",options:["1","2","4","0.5 mmol/L"],answer:2,why:"Lactate \u2265 4 triggers aggressive resuscitation."},{q:"Leukopenia in sepsis indicates:",options:["Good prognosis","Severe illness and worse prognosis","Viral infection only","Lab error"],answer:1,why:"Bone marrow overwhelmed."}],sources:[{title:"StatPearls: Laboratory evaluation (reference ranges)",url:"https://www.ncbi.nlm.nih.gov/books/?term=Laboratory+evaluation+%28reference+ranges%29+StatPearls"},{title:"Fourth Universal Definition of Myocardial Infarction (2018)",url:"https://www.ahajournals.org/doi/10.1161/CIR.0000000000000617"}]},ne={id:"fpc-adv-assess",domain:"medical",ref:"IV.11",title:"Advanced medical assessment",summary:"Structured assessment of the critically ill transport patient: the primary survey, focused history, haemodynamic and perfusion assessment, point-of-care ultrasound, and handover.",objectives:["Perform a structured primary and secondary assessment adapted to transport.","Assess perfusion beyond blood pressure.","Use bedside ultrasound and structured handover to guide transport decisions."],sections:[{id:"primary",title:"Primary survey and the referral handover",core:!0,body:["Begin with what threatens life in the next few minutes: airway patency and protection, breathing and oxygenation, circulation and haemorrhage, disability (GCS, pupils, glucose), and exposure (temperature, rashes, wounds, lines). In medical patients, catastrophic haemorrhage is less common but GI and obstetric bleeding are not.","At an inter-facility transfer, take a structured handover from the sending team (for example SBAR or a programme-specific format), then assess the patient yourself before leaving. Reconcile infusions, ventilator settings, lines and drains against what you were told. Many transport adverse events trace to unreconciled information."],list:{caption:"Before leaving the referring facility",items:["Airway secure and confirmed with waveform capnography","Adequate IV access (two reliable lines), drips labelled and on transport pumps","Oxygen, battery and drug quantities calculated for the trip plus reserve","Imaging and records sent; consent and family informed","Patient packaged: temperature, padding, restraints, tubes secured"]}},{id:"perfusion",title:"Perfusion beyond the blood pressure",core:!0,body:['Blood pressure is a late and imperfect marker. Assess end-organ perfusion: mental status, capillary refill (more than about 3 seconds is abnormal in adults), skin temperature and mottling, urine output, and lactate trends. A shock index (heart rate \xF7 systolic BP) above about 0.9\u20131.0 suggests significant shock even with a "normal" pressure.',"Classify shock to choose treatment: hypovolaemic (low filling, low output), cardiogenic (high filling, low output), obstructive (tamponade, tension pneumothorax, PE: high filling, low output, obstructed), distributive (low SVR: sepsis, anaphylaxis, neurogenic). Mixed states are common."]},{id:"pocus",title:"Point-of-care ultrasound",core:!0,body:["Focused ultrasound answers specific questions quickly. RUSH-style protocols look at the pump (pericardial effusion, gross LV function, RV dilation), the tank (IVC size and collapsibility, FAST for free fluid, pleural effusions) and the pipes (aortic aneurysm, DVT). Lung ultrasound identifies pneumothorax (absent sliding, lung point), interstitial syndrome (B-lines) and consolidation.","Ultrasound findings support decisions; they do not replace clinical judgement. IVC size is unreliable in ventilated patients and those with raised intra-abdominal pressure. In flight, vibration and limited space make scanning harder; scan before departure when possible."],example:{case:"Hypotension of unclear cause: BP 78/44, HR 122, JVP raised, clear lungs.",steps:["Raised JVP with hypotension narrows the field to cardiogenic or obstructive shock.","Cardiac view: pericardial effusion with RV diastolic collapse \u2192 tamponade; dilated RV with septal flattening \u2192 massive PE; poor LV \u2192 cardiogenic.","Lung: absent sliding unilaterally \u2192 tension pneumothorax.","Treat the finding: pericardiocentesis, decompression, thrombolysis per protocol, or inotropes."]}},{id:"secondary",title:"Secondary survey and history",body:["A focused history (SAMPLE or OPQRST for pain) and a head-to-toe examination follow stabilisation. In medical transports, the medication list is a diagnostic tool: anticoagulants, beta-blockers masking tachycardia, steroids (adrenal suppression), insulin and sulfonylureas, recent antibiotics.","Reassess after every intervention and at regular intervals in flight. Trends \u2014 a rising heart rate, falling EtCO\u2082, widening pulse pressure \u2014 often warn before absolute values cross thresholds."]}],keyPoints:["Primary survey first; take a structured handover and reassess everything yourself before leaving.","Perfusion: mentation, capillary refill, mottling, urine, lactate; shock index > 0.9 is a warning.","Classify shock: hypovolaemic, cardiogenic, obstructive, distributive.","POCUS: pump, tank, pipes; lung sliding and B-lines.","Reassess after every intervention; trends warn early."],pearls:["The medication list is a diagnostic test.","Scan before departure \u2014 flight makes ultrasound harder."],pitfalls:["Departing with unreconciled infusions.","Treating a normal BP as reassuring with a shock index of 1.2."],live:[{id:"lines-shock-states",label:"Shock states at the bedside"},{id:"abd-fast",label:"FAST: where free blood goes"}],questions:[{q:"Shock index of HR 120, SBP 100:",options:["0.8","1.2","2.0","0.5"],answer:1,why:"Shock index = 120 \xF7 100 = 1.2."},{q:"Raised JVP with hypotension suggests:",options:["Hypovolaemia","Cardiogenic or obstructive shock","Distributive only","Normal"],answer:1,why:"High filling pressure with low output."},{q:"Normal adult capillary refill is under about:",options:["1 s","3 s","6 s","10 s"],answer:1,why:"Beyond about 3 s is delayed."},{q:"Pericardial effusion with RV diastolic collapse indicates:",options:["Massive PE","Tamponade","Cardiogenic shock","Pneumothorax"],answer:1,why:"Ultrasound sign of tamponade."},{q:"A dilated RV with septal flattening in shock suggests:",options:["Tamponade","Massive PE","Hypovolaemia","Sepsis"],answer:1,why:"Acute RV pressure overload."},{q:"Absent lung sliding with a lung point indicates:",options:["Pneumonia","Pneumothorax","Effusion","Oedema"],answer:1,why:"Lung point is specific."},{q:"IVC size is unreliable in:",options:["Spontaneously breathing healthy patients","Ventilated patients","Children always","Never"],answer:1,why:"Positive pressure alters IVC dynamics."},{q:"Distributive shock includes:",options:["Tamponade","Sepsis, anaphylaxis, neurogenic","Haemorrhage","MI"],answer:1,why:"Low SVR states."},{q:"Before leaving the referring hospital you should confirm:",options:["Only the BP","Airway, access, drips, oxygen and battery reserves","Nothing \u2014 trust the handover","Lab results only"],answer:1,why:"Reconcile and prepare."},{q:"Which medication may mask tachycardia in shock?",options:["Beta-blocker","Insulin","Furosemide","Statin"],answer:0,why:"Blunts heart rate response."},{q:"B-lines on lung ultrasound indicate:",options:["Pneumothorax","Interstitial fluid","Normal lung","Consolidation only"],answer:1,why:"Interstitial syndrome."},{q:"Mottling of the knees suggests:",options:["Good perfusion","Poor peripheral perfusion","Hyperthermia only","Allergy"],answer:1,why:"Associated with mortality in shock."},{q:"An early trend warning of deterioration in flight:",options:["Stable HR","Rising HR and falling EtCO\u2082","Improving capillary refill","Falling lactate"],answer:1,why:"Suggests falling output."},{q:"SBAR stands for:",options:["Situation, Background, Assessment, Recommendation","Signs, Blood, Airway, Respiration","Status, Base, Action, Review","None"],answer:0,why:"Structured handover."},{q:'The RUSH "tank" assessment includes:',options:["LV function","IVC, FAST, pleural fluid","Aorta only","DVT only"],answer:1,why:"Volume status and fluid collections."}],sources:[{title:"StatPearls: RUSH exam",url:"https://www.ncbi.nlm.nih.gov/books/?term=RUSH+exam+StatPearls"},{title:"Hern\xE1ndez G et al. ANDROMEDA-SHOCK: capillary refill-targeted resuscitation. JAMA (2019)",url:"https://jamanetwork.com/journals/jama/fullarticle/2724361"}]},re={id:"fpc-treatment",domain:"medical",ref:"IV.12",title:"Treatment modalities: infusions, drips and transport pharmacology",summary:"Vasopressors and inotropes, infusion calculations, sedation and analgesia drips, anticoagulants and reversal, and managing pumps and drug supplies during transport.",objectives:["Choose and titrate vasoactive infusions by haemodynamic goal.","Calculate infusion rates accurately.","Manage anticoagulated patients and reversal agents."],sections:[{id:"vaso",title:"Vasoactive drugs",core:!0,body:["Match the drug to the problem. Low SVR (distributive shock): norepinephrine first (\u03B1-1 with some \u03B2-1), vasopressin as a second agent. Poor contractility (cardiogenic shock): an inotrope \u2014 dobutamine (\u03B2-1 with some \u03B2-2 vasodilation) or milrinone (a phosphodiesterase-3 inhibitor; vasodilating, renally cleared) \u2014 usually with norepinephrine to support pressure. Bradycardia with hypotension: epinephrine or dopamine infusions, or pacing.","Epinephrine combines inotropy and vasoconstriction; it raises lactate and heart rate. Phenylephrine is pure \u03B1-1 and useful as a push-dose agent for transient post-induction hypotension, but it can lower cardiac output in a weak heart. Dopamine causes more arrhythmias than norepinephrine and is no longer first-line in septic shock."],table:{caption:"Common infusions (typical adult ranges; follow protocol)",head:["Drug","Receptors","Typical range","Use"],rows:[["Norepinephrine","\u03B1-1 > \u03B2-1","0.02\u20130.5+ mcg/kg/min","Septic and vasodilatory shock"],["Epinephrine","\u03B2-1, \u03B2-2, \u03B1-1","0.02\u20130.5 mcg/kg/min","Anaphylaxis, cardiogenic, add-on"],["Vasopressin","V1","0.03\u20130.04 U/min (fixed)","Second agent in septic shock"],["Dobutamine","\u03B2-1 > \u03B2-2","2\u201320 mcg/kg/min","Low output, cardiogenic"],["Phenylephrine","\u03B1-1","Push 50\u2013200 mcg; infusion per protocol","Transient hypotension"],["Milrinone","PDE-3 inhibitor","0.125\u20130.75 mcg/kg/min","Low output, pulmonary hypertension"]]}},{id:"calc",title:"Infusion calculations",core:!0,body:["For weight-based drips: mL/h = dose (mcg/kg/min) \xD7 weight (kg) \xD7 60 \xF7 concentration (mcg/mL). For example, norepinephrine 4 mg in 250 mL is 16 mcg/mL; 0.1 mcg/kg/min for 80 kg = 0.1 \xD7 80 \xD7 60 \xF7 16 = 30 mL/h.","Non-weight-based: mL/h = dose per hour \xF7 concentration. Use smart pumps with drug libraries where available, double-check high-alert infusions with a second clinician, and label every line at the patient end. Before transport, change bags that will run out during the trip and calculate the volume needed plus a reserve."],example:{case:"Dobutamine 250 mg in 250 mL (1000 mcg/mL); order 5 mcg/kg/min; patient 70 kg.",steps:["5 \xD7 70 = 350 mcg/min.","\xD7 60 = 21,000 mcg/h.","\xF7 1000 mcg/mL = 21 mL/h."]}},{id:"anticoag",title:"Anticoagulants and reversal",core:!0,body:["Warfarin: four-factor prothrombin complex concentrate (PCC) plus IV vitamin K for life-threatening bleeding; plasma if PCC is unavailable. Heparin: protamine (about 1 mg per 100 units given in the last few hours; partial effect for low-molecular-weight heparin). Dabigatran: idarucizumab. Factor Xa inhibitors (apixaban, rivaroxaban): andexanet alfa where available, or PCC per protocol.","Thrombolytics (alteplase, tenecteplase) cause bleeding that may need cryoprecipitate and antifibrinolytics. Antiplatelet drugs are not reversed by PCC; platelet transfusion has a limited and selective role. In intracranial haemorrhage, reversal is time-critical."]},{id:"transport",title:"Infusions in transport",body:["Consolidate infusions onto transport pumps before leaving, and verify each against the order. Avoid stopping vasopressors during transfers \u2014 a brief interruption can drop pressure. Run critical drips through dedicated lines; do not bolus through a line carrying a vasopressor. Peripheral vasopressors in a good, proximal vein are acceptable short-term with site checks; extravasation of norepinephrine is treated with phentolamine infiltration per protocol.","Altitude can affect drip chambers and pressure bags; pumps eliminate most gravity-based errors. Battery life and oxygen supply should exceed the planned transport time with a margin."]}],keyPoints:["Low SVR \u2192 norepinephrine (then vasopressin); low output \u2192 dobutamine or milrinone, often with norepinephrine.","mL/h = mcg/kg/min \xD7 kg \xD7 60 \xF7 mcg/mL.","Warfarin \u2192 PCC + vitamin K; heparin \u2192 protamine; dabigatran \u2192 idarucizumab; Xa inhibitors \u2192 andexanet or PCC.","Never bolus through a vasopressor line; don't interrupt pressors during moves.","Calculate drug, battery and oxygen needs with a reserve before departure."],pearls:["Phenylephrine push doses bridge transient hypotension.","Milrinone accumulates in renal failure."],pitfalls:["A bag running out mid-flight.","Flushing a line that carries norepinephrine."],live:[{id:"moa-norepinephrine",label:"Norepinephrine: mechanism"},{id:"moa-dobutamine",label:"Dobutamine: mechanism"},{id:"labs-coag",label:"Reversing anticoagulation"}],questions:[{q:"Norepinephrine 4 mg/250 mL at 0.05 mcg/kg/min for 80 kg:",options:["5 mL/h","15 mL/h","30 mL/h","60 mL/h"],answer:1,why:"0.05 \xD7 80 \xD7 60 \xF7 16 = 15 mL/h."},{q:"Inotrope that is a PDE-3 inhibitor:",options:["Dobutamine","Milrinone","Dopamine","Vasopressin"],answer:1,why:"Raises cAMP independent of \u03B2-receptors."},{q:"Dabigatran is reversed with:",options:["Protamine","Idarucizumab","Vitamin K","Andexanet"],answer:1,why:"Specific antibody fragment."},{q:"Warfarin reversal in life-threatening bleeding:",options:["Vitamin K alone","PCC plus IV vitamin K","Protamine","Platelets"],answer:1,why:"Fast factor replacement plus sustained effect."},{q:"Heparin is reversed by:",options:["Protamine","Naloxone","Flumazenil","Calcium"],answer:0,why:"Protamine binds heparin."},{q:"Vasopressin in septic shock is usually dosed:",options:["By weight, titrated widely","Fixed around 0.03 U/min","1 U/kg","As a bolus only"],answer:1,why:"Fixed-dose second agent."},{q:"A drug that raises lactate:",options:["Norepinephrine","Epinephrine","Vasopressin","Milrinone"],answer:1,why:"\u03B2-2 glycolysis."},{q:"Phenylephrine acts on:",options:["\u03B2-1","\u03B1-1","V1","D1"],answer:1,why:"Pure \u03B1-1 agonist."},{q:"Norepinephrine extravasation is treated with:",options:["Heat and massage","Phentolamine infiltration","Calcium","Protamine"],answer:1,why:"\u03B1-blockade reverses local vasoconstriction."},{q:"Dobutamine 1000 mcg/mL at 10 mcg/kg/min for 60 kg:",options:["6 mL/h","36 mL/h","60 mL/h","600 mL/h"],answer:1,why:"10 \xD7 60 \xD7 60 \xF7 1000 = 36."},{q:"Which should never be done through a vasopressor line?",options:["Monitoring","Bolus injections","Labeling","Using a pump"],answer:1,why:"Flushes a pressor bolus into the patient."},{q:"Dopamine compared with norepinephrine in septic shock:",options:["Fewer arrhythmias","More arrhythmias","Equal","Preferred"],answer:1,why:"Higher arrhythmia rate."},{q:"Factor Xa inhibitor reversal options include:",options:["Idarucizumab","Andexanet alfa or PCC","Vitamin K","Protamine fully"],answer:1,why:"Specific or non-specific reversal."},{q:"Before a 2-hour transport, a drip bag with 45 minutes left should be:",options:["Left alone","Replaced before departure","Doubled in rate","Stopped"],answer:1,why:"Avoid running out in flight."},{q:"Milrinone dose adjustment is needed in:",options:["Liver failure","Renal failure","Hypertension","Hyperthermia"],answer:1,why:"Renally cleared."}],sources:[{title:"Surviving Sepsis Campaign (2021): vasoactive agents",url:"https://www.sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-guidelines-2021"},{title:"ACC expert consensus: management of bleeding on oral anticoagulants (2020)",url:"https://www.jacc.org/doi/10.1016/j.jacc.2020.04.053"}]};var se={id:"fpc-lines",domain:"medical",ref:"IV.13",title:"Invasive lines: arterial, central, IO and PA catheters",summary:"Indications, placement sites and complications of arterial lines, central venous catheters, intraosseous access and pulmonary artery catheters, and how to read and troubleshoot transduced pressures.",objectives:["Choose and troubleshoot vascular access for critically ill transport patients.","Level, zero and damping-check transduced pressures.","Interpret CVP and PA catheter values and recognise complications."],sections:[{id:"access",title:"Choosing access",core:!0,body:["Two large-bore peripheral IVs serve most resuscitations; flow depends on catheter radius and length (Poiseuille), so a short 14\u201316 gauge peripheral line outflows a long, narrow central lumen. Intraosseous (IO) access is fast and reliable when veins fail \u2014 proximal humerus, proximal or distal tibia, and the sternum in some devices. Humeral IO gives higher flow and faster central delivery than tibial. Flush, give lidocaine for pain in awake patients per protocol, and use a pressure bag for flow.","Central venous catheters (internal jugular, subclavian, femoral) allow vasopressors, multiple infusions, CVP monitoring and central venous saturation. Ultrasound guidance reduces complications. Subclavian lines carry the highest pneumothorax risk; femoral lines the highest infection risk; the internal jugular sits in between and is accessible with ultrasound."]},{id:"art",title:"Arterial lines and transduced pressures",core:!0,body:["An arterial line gives beat-to-beat pressure and arterial sampling \u2014 valuable on vasopressors, in labile patients and where non-invasive cuffs fail in vibration. The radial artery is preferred; femoral and brachial are alternatives. Complications include thrombosis, distal ischaemia, infection, haematoma and accidental drug injection.","Level the transducer to the phlebostatic axis (4th intercostal space, mid-axillary line) and zero it to atmosphere. A transducer below the heart reads falsely high; above reads falsely low \u2014 roughly 7.4 mmHg per 10 cm. Re-level after every position change, and remember aircraft cabin pressure changes do not affect a properly zeroed system once rezeroed at altitude per protocol.","Perform a square-wave (fast-flush) test: one to two oscillations then return to the waveform indicates optimal damping. Many oscillations mean underdamping (systolic overestimated); a slow return with no oscillation means overdamping (bubble, clot, kink, soft pressure bag; systolic underestimated). The mean arterial pressure is least affected by damping."]},{id:"pa",title:"Central and PA catheter values",core:!0,body:["CVP approximates right atrial pressure (normal about 2\u20138 mmHg). Read it at end-expiration. A high CVP occurs with RV failure, tamponade, tension pneumothorax, pulmonary hypertension, volume overload and high PEEP; a low CVP suggests hypovolaemia. CVP alone predicts fluid responsiveness poorly; trends and context matter.",'Pulmonary artery catheters measure right-sided pressures, PA pressure (normal about 15\u201330 systolic / 4\u201312 diastolic), pulmonary artery occlusion ("wedge") pressure approximating left atrial pressure (about 6\u201312), cardiac output and mixed venous saturation (SvO\u2082 about 65\u201375 %). A wedge above about 18 with low cardiac index points to cardiogenic shock; low wedge with low output points to hypovolaemia; low SVR with high output points to distributive shock.',"In transport, a PA catheter must never be left in the wedge position (balloon inflated) \u2014 it risks pulmonary infarction and rupture. Watch the waveform: a damped, wedged trace when the balloon is deflated means the catheter has migrated distally; pull it back per protocol. Secure catheters carefully; migration is common with movement."],table:{caption:"Haemodynamic patterns",head:["Shock","CVP","Wedge","CO/CI","SVR"],rows:[["Hypovolaemic","\u2193","\u2193","\u2193","\u2191"],["Cardiogenic (LV)","\u2191 or \u2194","\u2191","\u2193","\u2191"],["Obstructive (tamponade)","\u2191 (equalised)","\u2191 (equalised)","\u2193","\u2191"],["Distributive (septic)","\u2193 or \u2194","\u2193 or \u2194","\u2191 or \u2194","\u2193"]]}},{id:"complications",title:"Line complications in transport",body:["Air embolism: air entering a central line (especially with the patient upright or during disconnection) causes sudden hypoxia, hypotension and arrest. Clamp the line, place the patient left lateral and head down (Durant's manoeuvre), give 100 % oxygen, and aspirate from the catheter if possible.","Dislodgement and bleeding: secure lines and tubing before moves; a dislodged arterial line can bleed briskly. Infection: maintain aseptic handling. Pneumothorax after a recent subclavian or IJ insertion may declare itself at altitude as trapped air expands."],example:{case:"On ascent, the arterial line reads 168/92 while the cuff reads 124/70.",steps:["Check level: transducer slipped below the phlebostatic axis? Re-level.","Fast-flush test: many oscillations suggest underdamping and systolic overestimation.","Compare MAPs: if similar, the systolic difference is a damping artefact.","Fix bubbles, shorten tubing, rezero; trust the MAP for decisions."]}}],keyPoints:["Short, wide peripheral lines flow fastest; humeral IO is fast and reliable.","Level to the phlebostatic axis; ~7.4 mmHg error per 10 cm; zero to air.","Square-wave test: 1\u20132 oscillations optimal; MAP is least affected by damping.","CVP 2\u20138, wedge 6\u201312, SvO\u2082 65\u201375 %; never transport with the PA balloon wedged.","Air embolism: clamp, left lateral head down, 100 % oxygen."],pearls:["Trust the MAP when systolics disagree.","Re-level after every position change."],pitfalls:["A PA catheter left wedged.","Disconnecting a central line with the patient upright."],live:[{id:"ln-setup",label:"From artery to monitor"},{id:"ln-level",label:"Levelling and zeroing"},{id:"ln-damp",label:"Damping and the square-wave test"},{id:"lines-cvc",label:"Ultrasound-guided IJ"}],questions:[{q:"Fastest flow for volume resuscitation:",options:["Triple-lumen central distal port","14 G short peripheral IV","22 G peripheral","PICC"],answer:1,why:"Short and wide wins (Poiseuille)."},{q:"The phlebostatic axis is at:",options:["2nd ICS MCL","4th ICS mid-axillary","5th ICS anterior axillary","Xiphoid"],answer:1,why:"Right atrial level."},{q:"Transducer 10 cm below the axis causes:",options:["False low ~7 mmHg","False high ~7 mmHg","No error","Zero reading"],answer:1,why:"Hydrostatic column adds pressure."},{q:"Optimal square-wave test shows:",options:["No oscillation","1\u20132 oscillations","6 oscillations","Flat line"],answer:1,why:"Optimally damped."},{q:"Overdamping causes systolic to read:",options:["High","Low","Accurate","Zero"],answer:1,why:"Peaks are blunted."},{q:"Normal PA occlusion (wedge) pressure:",options:["0\u20132","6\u201312","20\u201325","30\u201340 mmHg"],answer:1,why:"Approximates LA pressure."},{q:"High wedge, low cardiac output, high SVR suggests:",options:["Septic shock","Cardiogenic shock","Hypovolaemia","Anaphylaxis"],answer:1,why:"Failing LV."},{q:"Equalised CVP and wedge pressures suggest:",options:["Tamponade","Sepsis","Hypovolaemia","Normal"],answer:0,why:"Diastolic equalisation."},{q:"A wedged trace with the balloon deflated means:",options:["Normal","Catheter migrated distally","Balloon ruptured","Air embolism"],answer:1,why:"Pull back per protocol."},{q:"Treatment position for venous air embolism:",options:["Right lateral head up","Left lateral head down","Prone","Sitting"],answer:1,why:"Durant's manoeuvre traps air in the RA."},{q:"Highest pneumothorax risk central line site:",options:["Femoral","Subclavian","Internal jugular","PICC"],answer:1,why:"Proximity to the pleura."},{q:"Highest infection risk central line site traditionally:",options:["Subclavian","Femoral","IJ","Radial"],answer:1,why:"Groin contamination."},{q:"Normal mixed venous saturation:",options:["30\u201340 %","65\u201375 %","90\u2013100 %","50 %"],answer:1,why:"Reflects oxygen extraction."},{q:"Which pressure value is least affected by damping?",options:["Systolic","Diastolic","Mean","Pulse pressure"],answer:2,why:"MAP is robust."},{q:"Humeral IO compared with tibial IO:",options:["Slower flow","Higher flow and faster central delivery","Contraindicated","Same"],answer:1,why:"Closer to the central circulation."}],sources:[{title:"StatPearls: Arterial line placement",url:"https://www.ncbi.nlm.nih.gov/books/?term=Arterial+line+placement+StatPearls"},{title:"StatPearls: Pulmonary artery catheter",url:"https://www.ncbi.nlm.nih.gov/books/?term=Pulmonary+artery+catheter+StatPearls"}]},le={id:"fpc-radiology",domain:"medical",ref:"IV.14",title:"Radiographic interpretation for transport",summary:"A systematic approach to the chest X-ray, tube and line positions, the findings that change transport, and the basics of CT you will be handed at the referring hospital.",objectives:["Read a chest X-ray systematically, including tubes and lines.","Recognise pneumothorax, haemothorax, effusion, oedema, consolidation and free air.","Use imaging findings to anticipate problems at altitude."],sections:[{id:"system",title:"A systematic chest film",core:!0,body:["Confirm the patient, date and projection (AP films magnify the heart and are standard in ICU and transport; PA films are standard in clinics). Check rotation (spinous processes centred between clavicle heads) and inspiration (about 9\u201310 posterior ribs visible).","Then a fixed sequence, so nothing is skipped: tubes and lines; airway (trachea midline?); breathing (lung fields, pleural spaces, costophrenic angles, apices for pneumothorax); cardiac silhouette and mediastinum; diaphragm (free air beneath?); everything else (bones, soft tissues, surgical emphysema)."],list:{caption:"Tubes and lines",items:["ETT tip 3\u20135 cm above the carina (about at the clavicles) with the head neutral.","Central line tip at the cavo-atrial junction / lower SVC.","Gastric tube below the diaphragm, tip in the stomach, not coiled in the oesophagus or in a bronchus.","Chest tube with side holes inside the pleural space.","PA catheter tip in a proximal pulmonary artery, not far peripheral."],ordered:!1}},{id:"findings",title:"Findings that change transport",core:!0,body:["Pneumothorax: a visceral pleural line with no lung markings beyond it; on a supine film, look for a deep sulcus sign (a deep, lucent costophrenic angle). Tension pneumothorax is a clinical diagnosis, but a film may show mediastinal shift away and a flattened hemidiaphragm. Any pneumothorax will expand at altitude (Boyle's law); drain before flight per programme policy.",'Haemothorax and effusion: blunting of the costophrenic angle on an upright film; on a supine film, a diffuse haziness of one hemithorax. Pulmonary oedema: bilateral perihilar ("bat-wing") opacities, cardiomegaly, Kerley B lines and upper-lobe diversion in cardiogenic oedema; ARDS tends to be more peripheral with a normal heart size. Consolidation: a lobar opacity with air bronchograms.',"Widened mediastinum (above about 8 cm on a PA film, though AP films magnify) with blunt deceleration raises concern for aortic injury. Free air under the diaphragm on an upright film indicates a perforated viscus. Gastric distension on a film before flight warrants a gastric tube."]},{id:"ct",title:"CT basics you will be handed",body:["On CT, density is measured in Hounsfield units: air is about \u22121000, fat about \u2212100, water 0, acute blood about 40\u201380 (bright on non-contrast CT), bone +1000. Fresh intracranial blood is bright; acute ischaemic stroke may look normal early. An epidural haematoma is biconvex (lens-shaped) and does not cross sutures; a subdural is crescentic and crosses sutures but not the midline falx.","Ask the referring team for the formal report and send images with the patient. Your job is to recognise findings that change care en route \u2014 expanding blood, pneumothorax, free air, tube position \u2014 not to provide a formal read."]},{id:"case",title:"Transport case: the pre-flight film",body:["An intubated pneumonia patient's pre-transfer film shows: ETT tip 1 cm above the carina, a 15 % right apical pneumothorax after a recent IJ line, and a gastric tube coiled in the oesophagus."],example:{case:"Fix before flight.",steps:["Withdraw the ETT 2\u20133 cm to place the tip 3\u20135 cm above the carina; recheck depth and capnography.","The pneumothorax will expand at altitude in a ventilated patient: a chest drain before departure (per programme policy).","Reposition the gastric tube into the stomach; confirm.","Repeat imaging if available, then depart with a plan for deterioration."]}}],keyPoints:["Read every film in the same order: tubes and lines, airway, breathing, cardiac/mediastinum, diaphragm, everything else.","ETT tip 3\u20135 cm above the carina; central line at the cavo-atrial junction.","Supine pneumothorax: deep sulcus sign; any pneumothorax expands at altitude.","Cardiogenic oedema: big heart, bat-wing, Kerley B; ARDS: peripheral with a normal heart.","CT: acute blood is bright; epidural biconvex, subdural crescentic."],pearls:["AP films magnify the heart and mediastinum.","Count ribs to judge inspiration before calling a film abnormal."],pitfalls:["Missing a supine pneumothorax.","Accepting an ETT just above the carina before a move."],live:[{id:"vent-tension-ptx",label:"Tension pneumothorax on the ventilator"},{id:"vent-ards-signature",label:"ARDS (films and ultrasound)"}],questions:[{q:"Ideal ETT tip position on chest film:",options:["At the carina","3\u20135 cm above the carina","In the right main bronchus","At the vocal cords"],answer:1,why:"Allows for head movement."},{q:"A deep, lucent costophrenic angle on a supine film suggests:",options:["Effusion","Pneumothorax (deep sulcus sign)","Consolidation","Normal"],answer:1,why:"Air collects anteriorly and basally."},{q:"Central line tip should sit at:",options:["Right ventricle","Cavo-atrial junction / lower SVC","Internal jugular","Left atrium"],answer:1,why:"Reduces arrhythmia and perforation risk."},{q:"Bat-wing opacities with cardiomegaly suggest:",options:["ARDS","Cardiogenic pulmonary oedema","Pneumothorax","Lobar pneumonia"],answer:1,why:"Classic pattern."},{q:"Air bronchograms within a lobar opacity suggest:",options:["Pneumothorax","Consolidation","Effusion","Atelectasis only"],answer:1,why:"Air-filled bronchi in fluid-filled alveoli."},{q:"Adequate inspiration shows about:",options:["4 posterior ribs","9\u201310 posterior ribs","15 ribs","2 ribs"],answer:1,why:"Standard criterion."},{q:"AP compared with PA films:",options:["Minimise heart size","Magnify heart and mediastinum","Are not used in ICU","Show free air better"],answer:1,why:"Heart is farther from the detector."},{q:"Free air under the diaphragm indicates:",options:["Pneumothorax","Perforated viscus","Normal gas bubble","Effusion"],answer:1,why:"Pneumoperitoneum."},{q:"A small pneumothorax before flight in a ventilated patient:",options:["Will shrink at altitude","Will expand at altitude \u2014 consider drainage","Is irrelevant","Requires only oxygen"],answer:1,why:"Boyle's law plus positive pressure."},{q:"Acute blood on non-contrast CT appears:",options:["Dark","Bright (hyperdense)","Invisible","Fat-density"],answer:1,why:"About 40\u201380 HU."},{q:"An epidural haematoma is typically:",options:["Crescentic, crosses sutures","Biconvex, does not cross sutures","Within the ventricles","In the brainstem"],answer:1,why:"Arterial bleed bound by suture lines."},{q:"Air density in Hounsfield units:",options:["0","+1000","\u22121000","+40"],answer:2,why:"Air is \u22121000."},{q:"A gastric tube coiled in the oesophagus should be:",options:["Left in place","Repositioned into the stomach","Used for feeding","Removed permanently"],answer:1,why:"Ineffective and aspiration risk."},{q:"Upright film costophrenic angle blunting suggests:",options:["Pneumothorax","Pleural fluid","Emphysema","Normal"],answer:1,why:"Fluid collects dependently."},{q:"Widened mediastinum after high-speed deceleration raises concern for:",options:["Pneumonia","Aortic injury","Rib fracture only","Normal finding"],answer:1,why:"Blunt aortic injury."}],sources:[{title:"StatPearls: Chest radiograph interpretation",url:"https://www.ncbi.nlm.nih.gov/books/?term=Chest+radiograph+interpretation+StatPearls"},{title:"Radiopaedia: Endotracheal tube position",url:"https://radiopaedia.org/articles/endotracheal-tube"}]},ce={id:"fpc-resp-sys",domain:"medical",ref:"IV.15",title:"Respiratory physiology: oxygen, CO\u2082 and intrathoracic pressure",summary:"From the Krebs cycle to the oxyhaemoglobin dissociation curve, V/Q matching, and how changes in intrathoracic pressure move blood \u2014 the physiology behind ventilator, shock and flight decisions.",objectives:["Explain cellular respiration and why oxygen debt produces lactate.","Use the oxyhaemoglobin dissociation curve and its shifts clinically.","Relate intrathoracic pressure to venous return and cardiac output."],sections:[{id:"cell",title:"Cellular respiration",core:!0,body:["Glycolysis in the cytoplasm turns glucose into pyruvate and a small amount of ATP (two per glucose) without oxygen. With oxygen, pyruvate enters the mitochondria, feeds the Krebs (citric acid) cycle, and the electron transport chain uses oxygen as the final electron acceptor to produce most of the cell's ATP (roughly 30\u201336 per glucose) and CO\u2082 and water.","Without enough oxygen \u2014 or when mitochondria are poisoned (cyanide) \u2014 pyruvate is converted to lactate to keep glycolysis running. Lactate rises; ATP falls. This is why hypoperfusion causes lactic acidosis, and why restoring oxygen delivery, not just blood pressure, is the goal of resuscitation."]},{id:"curve",title:"The oxyhaemoglobin dissociation curve",core:!0,body:["Haemoglobin binding is cooperative, giving a sigmoid curve. On the flat upper part, a large fall in PaO\u2082 barely changes saturation (90 % saturation at about 60 mmHg). On the steep part, small falls in PaO\u2082 release large amounts of oxygen \u2014 good for tissues, but meaning saturation can fall quickly once PaO\u2082 drops below about 60.","A right shift (lower affinity, more oxygen released to tissues) occurs with acidosis, raised CO\u2082, fever and increased 2,3-DPG \u2014 the Bohr effect helps active tissues. A left shift (higher affinity, less release) occurs with alkalosis, low CO\u2082, hypothermia, low 2,3-DPG (stored blood), carbon monoxide and fetal haemoglobin.","Oxygen content is mostly bound to haemoglobin: CaO\u2082 \u2248 (1.34 \xD7 Hb \xD7 SaO\u2082) + (0.003 \xD7 PaO\u2082). Delivery is content \xD7 cardiac output. Raising PaO\u2082 above full saturation adds little oxygen, except in hyperbaric therapy."],list:{caption:'Right shift ("CADET, face right")',items:["CO\u2082 \u2191","Acid (H\u207A \u2191)","2,3-DPG \u2191","Exercise","Temperature \u2191"]}},{id:"vq",title:"V/Q, shunt and dead space",core:!0,body:["Ideal gas exchange matches ventilation (V) to perfusion (Q). Low V/Q units (pneumonia, atelectasis) and shunt (V/Q = 0: flooded or collapsed alveoli, intracardiac shunt) cause hypoxaemia. V/Q mismatch improves with oxygen; true shunt barely does and needs recruitment.","Dead space (V/Q = \u221E: pulmonary embolism, low cardiac output, overdistension) wastes ventilation and raises the PaCO\u2082\u2013EtCO\u2082 gap. Hypoxic pulmonary vasoconstriction diverts blood away from poorly ventilated regions; vasodilators can worsen V/Q matching by abolishing it.","The alveolar gas equation (PAO\u2082 = FiO\u2082 \xD7 (Pb \u2212 47) \u2212 PaCO\u2082/0.8) explains why altitude (lower barometric pressure, Pb) and hypoventilation (higher PaCO\u2082) lower alveolar oxygen even with normal lungs."]},{id:"itp",title:"Intrathoracic pressure and the circulation",core:!0,body:["Spontaneous inspiration lowers intrathoracic pressure, drawing venous blood into the chest and augmenting right-heart filling. Positive-pressure ventilation does the opposite: it raises intrathoracic pressure, reducing venous return and right-ventricular preload while lowering left-ventricular afterload. Hypovolaemic patients therefore become hypotensive after intubation, while patients with LV failure may improve on positive pressure.","High PEEP, auto-PEEP and tension pneumothorax all raise intrathoracic pressure and can cause obstructive shock. In tamponade, spontaneous inspiration fills the RV, shifts the septum and reduces LV output \u2014 pulsus paradoxus. Pulse-pressure variation on controlled ventilation reflects preload responsiveness."],example:{case:"A haemorrhaging trauma patient is intubated; BP falls from 98/60 to 70/40 after the first few breaths.",steps:["Positive pressure has reduced venous return in an under-filled circulation.","Give blood, reduce tidal volume and PEEP temporarily, avoid excessive rates.","Exclude tension pneumothorax and auto-PEEP (brief disconnection).","Recheck BP within a minute or two; continue haemorrhage control."]}}],keyPoints:["Without oxygen, pyruvate becomes lactate and ATP output falls sharply.","SaO\u2082 90 % \u2248 PaO\u2082 60; below that, saturation falls fast.","Right shift (CO\u2082, acid, 2,3-DPG, exercise, temperature) releases oxygen; CO, alkalosis, cold and fetal Hb shift left.","V/Q mismatch responds to oxygen; shunt needs recruitment; dead space widens the CO\u2082 gap.","Positive pressure lowers venous return (hypotension in hypovolaemia) and LV afterload."],pearls:["Stored blood is low in 2,3-DPG and releases oxygen poorly at first.","Altitude lowers PAO\u2082 via barometric pressure."],pitfalls:["Chasing PaO\u2082 far above full saturation.",'Forgetting that intubation removes the "thoracic pump" in hypovolaemia.'],live:[{id:"o2path",label:"Oxygen: from air to mitochondria"},{id:"hypox",label:"Why is the PaO\u2082 low?"},{id:"ln-heartlung",label:"Heart\u2013lung interactions"}],questions:[{q:"ATP from glycolysis alone per glucose:",options:["2","12","36","100"],answer:0,why:"Net 2 ATP anaerobically."},{q:"The final electron acceptor in the electron transport chain:",options:["CO\u2082","Oxygen","Lactate","Glucose"],answer:1,why:"Oxygen is reduced to water."},{q:"SaO\u2082 of 90 % corresponds to PaO\u2082 of about:",options:["40","60","80","100 mmHg"],answer:1,why:"The curve's shoulder."},{q:"Which shifts the curve to the right?",options:["Alkalosis","Hypothermia","Fever","Carbon monoxide"],answer:2,why:"Temperature increase lowers affinity."},{q:"Fetal haemoglobin shifts the curve:",options:["Right","Left","No change","Down only"],answer:1,why:"Higher affinity for oxygen."},{q:"Stored blood's low 2,3-DPG causes:",options:["Right shift","Left shift","No change","Haemolysis"],answer:1,why:"Less oxygen offloading initially."},{q:"Most oxygen in blood is carried:",options:["Dissolved","Bound to haemoglobin","As bicarbonate","In plasma proteins"],answer:1,why:"1.34 \xD7 Hb \xD7 SaO\u2082 dominates."},{q:"Shunt hypoxaemia responds to supplemental oxygen:",options:["Well","Poorly","Completely","Not relevant"],answer:1,why:"Shunted blood never meets the oxygen."},{q:"Pulmonary embolism mainly causes:",options:["Shunt","Dead space","Hypoventilation","Diffusion block"],answer:1,why:"Ventilated but unperfused lung."},{q:"At altitude, PAO\u2082 falls mainly because:",options:["FiO\u2082 falls","Barometric pressure falls","CO\u2082 rises","Hb falls"],answer:1,why:"FiO\u2082 stays 0.21; total pressure falls."},{q:"Positive-pressure ventilation affects venous return by:",options:["Increasing it","Decreasing it","No effect","Only in children"],answer:1,why:"Raised intrathoracic pressure."},{q:"A patient with LV failure on positive pressure may improve because:",options:["Preload rises","LV afterload falls","Heart rate rises","SVR rises"],answer:1,why:"Transmural LV pressure falls."},{q:"Cyanide causes lactic acidosis because:",options:["It lowers PaO\u2082","It blocks mitochondrial oxygen use","It lowers Hb","It causes hypoventilation"],answer:1,why:"Cytochrome oxidase blocked."},{q:"Hypoxic pulmonary vasoconstriction:",options:["Worsens V/Q matching","Diverts blood from poorly ventilated areas","Occurs only at altitude","Lowers PVR"],answer:1,why:"Improves matching."},{q:"Mnemonic for right shift factors:",options:["LEMON","CADET (face right)","DOPE","SLUDGE"],answer:1,why:"CO\u2082, Acid, 2,3-DPG, Exercise, Temperature."}],sources:[{title:"StatPearls: Physiology, oxygen transport",url:"https://www.ncbi.nlm.nih.gov/books/?term=Physiology%2C+oxygen+transport+StatPearls"},{title:"StatPearls: Physiology, Krebs cycle",url:"https://www.ncbi.nlm.nih.gov/books/?term=Physiology%2C+Krebs+cycle+StatPearls"},{title:"StatPearls: Ventilation-perfusion mismatch",url:"https://www.ncbi.nlm.nih.gov/books/?term=Ventilation-perfusion+mismatch+StatPearls"}]};var de={"fpc-adrenal":{questions:[],sections:[{id:"stress",title:"Stress dosing and who is at risk",body:["Anyone taking the equivalent of prednisone 5 mg a day or more for longer than about three to four weeks in the past year may have a suppressed hypothalamic\u2013pituitary\u2013adrenal axis. So may patients using high-dose inhaled or topical steroids, those with known Addison's disease or pituitary disease, and those recently given etomidate repeatedly. In serious illness, trauma, or before surgery they need stress-dose steroids.","Practical doses in transport: hydrocortisone 100 mg IV or IM for crisis or serious illness, followed in hospital by 200 mg per day (by infusion or divided doses). Children receive weight- or body-surface-based doses per protocol. Many patients carry an emergency card and a hydrocortisone injection kit; use the patient's own supply if needed and record the time given.","Clues that a shocked patient may have adrenal insufficiency: poor response to fluids and vasopressors, hypoglycaemia, hyponatraemia, hyperkalaemia (primary), eosinophilia, vomiting and abdominal pain, a history of steroid use, or hyperpigmentation. When in doubt in refractory shock, hydrocortisone is low-risk and potentially life-saving."]}]},"fpc-renal":{questions:[],sections:[{id:"case",title:"Transport case: the crush injury",body:["A construction worker trapped under a collapsed wall for five hours. Legs swollen and tense, HR 118, BP 104/66. Extrication is imminent."],example:{case:"What do you do before and after release?",steps:["Before release: IV or IO access and isotonic fluid (commonly 1\u20131.5 L/h in adults per protocol) to dilute released potassium and myoglobin.","Cardiac monitoring; calcium and insulin\u2013dextrose ready for hyperkalaemia; consider tourniquets only per protocol for uncontrolled haemorrhage.","After release: watch for sudden hypotension, arrhythmia (peaked T, wide QRS) and acidosis; treat hyperkalaemia immediately with calcium.","Avoid succinylcholine; target high urine output once catheterised; watch for compartment syndrome in the limbs.","Transport to a centre with dialysis capability."]}}]},"fpc-sepsis":{questions:[],sections:[{id:"transport",title:"Keeping the bundle going in flight",body:["Transport is not a pause in sepsis care. Make sure the first antibiotic dose has been given and note the time; if the flight is long and a second dose falls due, carry it. Keep fluids and vasopressors on pumps, and bring enough of each for the flight plus a reserve.","Reassess perfusion at regular intervals: MAP, heart rate, mental status, capillary refill and, where measured, urine output and lactate. Escalate norepinephrine and add vasopressin per protocol if MAP falls; consider hydrocortisone for escalating requirements.","Hand over the timeline clearly: when sepsis was recognised, cultures taken, antibiotics given, the fluid volume received, the vasopressor course, and the suspected source with any source-control plan."]},{id:"special",title:"Sepsis in special populations",body:["Older adults may present with confusion, falls or hypothermia rather than fever. Immunocompromised patients \u2014 chemotherapy, transplant, high-dose steroids \u2014 may have few signs; neutropenic fever is treated as an emergency with immediate broad-spectrum antibiotics. Pregnant women have physiologically higher heart rates and lower blood pressures, which can mask early sepsis; obstetric sources (endometritis, chorioamnionitis) are common.","Children compensate with tachycardia and vasoconstriction; hypotension appears late. Paediatric fluid boluses are 10\u201320 mL/kg with reassessment after each, and epinephrine or norepinephrine is chosen by clinical phenotype (cold versus warm shock). Neonates may show apnoea, poor feeding or temperature instability.","Asplenic patients are at risk of overwhelming post-splenectomy infection with encapsulated organisms; they deteriorate rapidly and need immediate antibiotics."]}]},"fpc-infectious":{questions:[],sections:[{id:"decon",title:"Cleaning the aircraft and equipment",body:["After a transport, clean all surfaces the patient or crew touched with a hospital-grade disinfectant, respecting the product's contact time. For C. difficile and other spore-forming organisms, use a sporicidal (bleach-based) product. Single-use items go to clinical waste; reusable equipment (laryngoscope handles, monitor cables, stretcher mattresses) follows the manufacturer's decontamination process.","For airborne pathogens, the aircraft's air exchange rate determines how long to leave doors open or ventilation running before the next patient; follow programme policy. Crew should remove PPE in a defined order to avoid self-contamination \u2014 usually gloves first, then gown, then eye protection, then respirator, with hand hygiene between steps.","Document exposures and decontamination steps. A clear process protects the next patient and the crew."]}]},"fpc-blood":{questions:[],sections:[{id:"equipment",title:"Running blood in transport",body:["Blood is stored in validated coolers that hold 1\u20136 \xB0C for a defined time; record the temperature and time out of storage, and return unused units per protocol. Inspect each unit for leaks, clots or discolouration, and check the label and expiry. Two-person verification of patient identity is the main defence against ABO-incompatible transfusion, even in emergencies.","Use a filtered blood administration set, a fluid warmer for rapid transfusion, and a pressure infuser for haemorrhage. Do not run blood with dextrose or lactated Ringer's in the same line unless the protocol permits \u2014 calcium in LR can clot citrated blood, and dextrose can haemolyse cells. Normal saline is compatible.","Document unit numbers, start and stop times, volumes and any reaction. Blood products are traceable to donors; good records protect patients."]}]},"fpc-gi":{questions:[],sections:[{id:"scores",title:"Risk scores and destination",body:["The Glasgow\u2013Blatchford score uses BUN, haemoglobin, systolic pressure, pulse, melaena, syncope, liver disease and heart failure to estimate the need for intervention in upper GI bleeding; a score of zero or one identifies very low-risk patients, while high scores indicate need for urgent endoscopy and possibly transfusion. You will not usually calculate it in flight, but its components are the same red flags you assess.","Destination matters: active haemorrhage needs a centre with immediate endoscopy, interventional radiology and surgery. Variceal bleeding may need TIPS (transjugular intrahepatic portosystemic shunt) capability. Pre-alert early so the receiving team can prepare blood and procedures."]},{id:"case",title:"Transport case: the anticoagulated older man",body:["An 81-year-old on apixaban for atrial fibrillation, three episodes of melaena, light-headed: HR 108 (on a beta-blocker), BP 96/58, Hb 7.9, BUN 58, creatinine 1.1."],example:{case:"Interpret and act.",steps:["A high BUN:creatinine ratio (\u2248 53) supports an upper GI source; the beta-blocker blunts his tachycardia, so the haemodynamic picture may be worse than it looks.","Resuscitate with blood products to restore perfusion; restrictive target if stable.","Discuss reversal of apixaban per protocol (andexanet alfa or PCC) for life-threatening bleeding.","PPI per protocol; NPO; large-bore access; head up with suction ready.","Destination: a centre with endoscopy available now."]}}]},"fpc-labs":{questions:[],sections:[{id:"gas",title:"Reading a blood gas at the bedside",body:["Arterial samples judge oxygenation and acid\u2013base; venous samples are adequate for pH, bicarbonate, lactate and electrolytes in most stable patients (venous pH about 0.03 lower, PCO\u2082 about 5 mmHg higher). Venous PO\u2082 does not measure lung oxygenation.","Calculate the P/F ratio (PaO\u2082 \xF7 FiO\u2082) to grade hypoxaemia: below 300 indicates impaired oxygenation, and in ARDS, 200\u2013300 is mild, 100\u2013200 moderate and below 100 severe. Calculate the A\u2013a gradient (PAO\u2082 \u2212 PaO\u2082; normal roughly age/4 + 4 on room air) to separate hypoventilation (normal gradient) from lung disease (widened gradient).","Base excess (normal \u22122 to +2) summarises the metabolic component; a large negative base deficit in trauma reflects shock and predicts transfusion needs. Point-of-care analysers give results in minutes and are increasingly carried by transport teams."]}]},"fpc-adv-assess":{questions:[],sections:[{id:"case",title:"Transport case: undifferentiated shock",body:["A 59-year-old found confused at home: BP 80/50, HR 124, RR 28, SpO\u2082 92 %, warm extremities, temperature 38.9 \xB0C, lactate 4.8. A 25-minute flight."],example:{case:"Work it through.",steps:["Primary survey: airway patent; breathing tachypnoeic; circulation shocked; GCS 13; glucose normal.","Warm extremities and fever suggest distributive (septic) shock; check skin for rashes and a source (urine, lungs, skin).","POCUS: hyperdynamic LV, small collapsible IVC, no effusion \u2014 consistent with distributive shock and hypovolaemia.","Treat: antibiotics, cultures if quick, fluids with reassessment, norepinephrine for MAP < 65.","Reassess in flight: mentation, capillary refill, MAP, EtCO\u2082 trend; hand over with a structured report."]}},{id:"neuro",title:"Focused neurological and abdominal assessment",body:["In altered patients, document the GCS by component (eye, verbal, motor), pupil size and reactivity, and lateralising signs. A falling motor score is the most important trend. Check glucose early in every altered patient.","The abdomen in critical illness: distension, peritonism, a pulsatile mass, flank bruising (retroperitoneal haemorrhage) and bladder size. A distended abdomen with rising airway pressures and falling urine output suggests abdominal compartment syndrome; bladder pressure above about 20 mmHg with new organ dysfunction confirms it."]}]},"fpc-treatment":{questions:[],sections:[{id:"push",title:"Push-dose vasopressors",body:["Push-dose vasopressors bridge brief hypotension \u2014 post-induction, during sedation, or while an infusion is prepared. Phenylephrine is commonly prepared at 100 mcg/mL and given in 50\u2013200 mcg boluses; dilute epinephrine is prepared at 10 mcg/mL (for example 1 mL of 0.1 mg/mL epinephrine added to 9 mL of saline) and given in 5\u201320 mcg boluses. Preparation errors are a recognised hazard: use standard recipes, label syringes clearly, and double-check.","Push-dose pressors are a bridge, not a treatment plan. If repeated boluses are needed, start an infusion and treat the cause \u2014 volume, haemorrhage, sepsis, or the induction agent."]},{id:"sedation",title:"Sedation and analgesia infusions",body:["Ventilated patients need analgesia first, then sedation titrated to a target such as a Richmond Agitation\u2013Sedation Scale (RASS) of \u22121 to \u22122 for most, deeper (\u22124 to \u22125) when paralysed or for raised ICP. Common infusions: fentanyl 25\u2013200 mcg/h, propofol 5\u201350 mcg/kg/min (watch blood pressure and triglycerides on prolonged use), midazolam 1\u201310 mg/h (accumulates in renal and hepatic failure), ketamine 0.5\u20132 mg/kg/h (haemodynamically supportive), and dexmedetomidine 0.2\u20131.5 mcg/kg/h (bradycardia and hypotension; little respiratory depression).","Paralysed patients must be deeply sedated; check that sedation infusions are running before any redose of a paralytic. In flight, stimuli are greater and patients may need more; reassess at regular intervals and before landing and transfer."]}]},"fpc-radiology":{questions:[],sections:[{id:"case2",title:"Transport case: two films, two decisions",body:["Two patients are ready for transfer. Patient A, after a fall: supine film with a deep, lucent left costophrenic angle and subcutaneous emphysema. Patient B, with sepsis: bilateral peripheral opacities, normal heart size, ETT tip at the level of the clavicles, central line tip in the right atrium deep."],example:{case:"What do you change before flight?",steps:["A: deep sulcus sign suggests an anterior pneumothorax; with subcutaneous emphysema and a planned flight (and likely positive pressure), drain before departure per programme policy.","B: the ETT is well placed; the opacities fit ARDS. A central line deep in the right atrium can cause arrhythmia; withdraw it to the cavo-atrial junction per protocol before moving.","Both: document findings and send images with the patient."]}},{id:"ultrasound",title:"Ultrasound images you will be shown",body:["Bedside ultrasound images increasingly travel with the patient. Recognise the key findings: a pericardial effusion as a black stripe around the heart (with right ventricular diastolic collapse in tamponade); free fluid in Morison's pouch on a FAST; absent lung sliding and a barcode M-mode in pneumothorax; B-lines in interstitial oedema; and an abdominal aorta wider than 3 cm.","Ultrasound is operator-dependent; record who performed it and when, and repeat if the patient changes. A negative FAST does not rule out haemorrhage, particularly retroperitoneal."]}]},"fpc-resp-sys":{questions:[],sections:[{id:"co2",title:"Carbon dioxide transport",body:["CO\u2082 travels in three forms: about 70 % as bicarbonate (formed in red cells by carbonic anhydrase), about 20\u201323 % bound to haemoglobin as carbamino compounds, and 7\u201310 % dissolved. Deoxygenated haemoglobin carries more CO\u2082 (the Haldane effect), which helps load CO\u2082 in the tissues and unload it in the lungs.","Giving high-flow oxygen to some patients with chronic CO\u2082 retention can raise PaCO\u2082 through the Haldane effect, worsened V/Q matching (loss of hypoxic pulmonary vasoconstriction) and, to a lesser degree, reduced drive. Target SpO\u2082 88\u201392 % in known retainers while treating the cause.","Ventilation controls PaCO\u2082 within minutes: halving alveolar ventilation roughly doubles PaCO\u2082. That is why EtCO\u2082 responds quickly to rate changes on the ventilator, while bicarbonate adjustment by the kidneys takes days."]}]}};var he={id:"fpc-12-lead",domain:"cardiac",ref:"VI.1",title:"Multi-lead ECG interpretation",summary:"A systematic 12-lead read, localising STEMI and its equivalents, recognising mimics, and the findings \u2014 blocks, axis, QT, Brugada, WPW \u2014 that change transport decisions.",objectives:["Read a 12-lead ECG in a fixed order: rate, rhythm, axis, intervals, morphology, ST\u2013T.","Localise STEMI to a coronary territory and recognise STEMI equivalents.","Identify high-risk non-ischaemic patterns: Brugada, WPW, long QT, hyperkalaemia."],sections:[{id:"system",title:"A fixed order",core:!0,body:["Read every ECG the same way so nothing is missed. Rate: 300 divided by the number of large boxes between R waves, or count complexes in 10 seconds and multiply by six. Rhythm: regular or irregular, P before every QRS, QRS after every P. Axis: normal if leads I and aVF are both positive; left axis deviation if I is positive and aVF negative (with lead II negative); right axis deviation if I is negative and aVF positive.","Intervals: PR 120\u2013200 ms; QRS under 120 ms; QTc under about 450 ms in men and 460\u2013470 in women (above 500 is high risk for torsades). Then morphology: P waves, Q waves, QRS width and pattern (bundle branch blocks), R-wave progression, and finally the ST segments and T waves."],table:{caption:"Normal intervals",head:["Interval","Normal","Abnormal means"],rows:[["PR","120\u2013200 ms","< 120: pre-excitation; > 200: first-degree block"],["QRS","< 120 ms","\u2265 120: bundle branch block, ventricular rhythm, hyperkalaemia, Na-channel blockade"],["QTc","< 450 (M) / < 460 (F) ms","> 500 ms: torsades risk"]]}},{id:"stemi",title:"Localising STEMI",core:!0,body:["STEMI criteria (in the absence of LVH or LBBB): new ST elevation at the J point in two contiguous leads of at least 1 mm, except in V2\u2013V3 where the thresholds are 2 mm in men 40 or older, 2.5 mm in men under 40, and 1.5 mm in women. Reciprocal ST depression in the opposite territory increases specificity.","Inferior STEMI (II, III, aVF) is usually the right coronary artery (or circumflex in left-dominant systems); obtain right-sided leads (V4R) to look for right-ventricular infarction, which makes the patient preload-dependent \u2014 avoid nitrates and give fluid for hypotension. ST elevation in III greater than II and reciprocal depression in I and aVL favour the RCA. Anterior STEMI (V1\u2013V4) is the LAD; lateral (I, aVL, V5\u2013V6) the circumflex or diagonal. Posterior infarction shows ST depression with tall R waves in V1\u2013V3; confirm with posterior leads V7\u2013V9 (ST elevation \u2265 0.5 mm)."],table:{caption:"Territories",head:["Leads","Territory","Usual artery"],rows:[["II, III, aVF","Inferior","RCA (or LCx)"],["V1\u2013V2","Septal","LAD"],["V3\u2013V4","Anterior","LAD"],["I, aVL, V5\u2013V6","Lateral","LCx / diagonal"],["V7\u2013V9 (ST depression V1\u2013V3)","Posterior","RCA / LCx"],["V4R","Right ventricle","Proximal RCA"]]}},{id:"equivalents",title:"STEMI equivalents and mimics",core:!0,body:["Some occlusions do not meet classic criteria. Widespread ST depression with ST elevation in aVR suggests left main or multivessel ischaemia. De Winter T waves \u2014 upsloping ST depression with tall, symmetric T waves in the precordial leads \u2014 indicate proximal LAD occlusion. Wellens pattern (deep symmetric or biphasic T waves in V2\u2013V3 in a pain-free patient) warns of critical proximal LAD stenosis. In LBBB or a paced rhythm, the Sgarbossa criteria (concordant ST elevation \u2265 1 mm, concordant ST depression in V1\u2013V3, or excessively discordant elevation) identify acute occlusion.","Mimics include early repolarisation (young patients, notched J points, stable), pericarditis (diffuse concave ST elevation with PR depression, PR elevation in aVR), left ventricular hypertrophy, left bundle branch block, left ventricular aneurysm (persistent ST elevation with Q waves after an old MI), Brugada pattern and hyperkalaemia. Takotsubo cardiomyopathy can mimic anterior STEMI and is diagnosed after angiography."]},{id:"highrisk",title:"Other high-risk patterns",body:["Wolff\u2013Parkinson\u2013White: short PR, delta wave and wide QRS. Atrial fibrillation with WPW produces an irregular, very fast, wide-complex tachycardia with changing QRS shapes; AV nodal blockers (adenosine, beta-blockers, calcium-channel blockers, digoxin) can accelerate conduction down the accessory pathway into ventricular fibrillation. Treat unstable patients with synchronised cardioversion, stable ones with procainamide per protocol.","Brugada pattern (coved ST elevation of at least 2 mm in V1\u2013V2 with T-wave inversion) predisposes to sudden death, especially with fever; treat fever and avoid sodium-channel blockers. Long QT (congenital or drug-induced) predisposes to torsades. Hyperkalaemia progresses from peaked T waves to wide QRS and sine waves. Bifascicular block with syncope may herald complete heart block."]},{id:"case",title:"Transport case: inferior STEMI with hypotension",body:["A 61-year-old with chest pain: ST elevation 3 mm in III, 2 mm in II and aVF, ST depression in I and aVL. BP 84/52, HR 54, lungs clear. Referring team gave nitroglycerin and BP fell."],example:{case:"Interpret and manage.",steps:["Inferior STEMI with III > II and reciprocal changes in I/aVL: RCA occlusion likely.","Hypotension after nitrates with clear lungs: suspect RV infarction \u2014 obtain V4R (ST elevation \u2265 1 mm supports it).","Stop nitrates; give fluid boluses cautiously to support RV preload; atropine or pacing for symptomatic bradycardia (AV block is common with RCA occlusion).","Antiplatelet and anticoagulation per protocol; direct to a PCI centre with pre-activation of the cath lab."]}}],keyPoints:["Read every ECG in order: rate, rhythm, axis, intervals, morphology, ST\u2013T.","STEMI: \u2265 1 mm in two contiguous leads (higher thresholds in V2\u2013V3); look for reciprocal change.","Inferior STEMI: get V4R; RV infarction is preload-dependent \u2014 no nitrates, give fluid.","Equivalents: aVR elevation with diffuse depression, de Winter, posterior (V7\u2013V9), Sgarbossa in LBBB.","AF with WPW: avoid AV nodal blockers; cardiovert or procainamide."],pearls:["ST depression in V1\u2013V3 with tall R waves may be a posterior STEMI.","Fever unmasks Brugada."],pitfalls:["Nitrates in right-ventricular infarction.","Adenosine for irregular wide-complex tachycardia."],questions:[{q:"ST elevation in II, III and aVF localises to the:",options:["Anterior wall","Inferior wall","Lateral wall","Septum"],answer:1,why:"Inferior leads."},{q:"An inferior STEMI patient becomes hypotensive after nitroglycerin with clear lungs. Next step:",options:["More nitroglycerin","Right-sided leads and fluid","Furosemide","Morphine"],answer:1,why:"RV infarction is preload-dependent."},{q:"ST depression V1\u2013V3 with tall R waves suggests:",options:["Anterior ischaemia only","Posterior STEMI","RBBB","Normal variant"],answer:1,why:"Confirm with V7\u2013V9."},{q:"Diffuse ST depression with ST elevation in aVR suggests:",options:["Pericarditis","Left main or multivessel ischaemia","Early repolarisation","Hypokalaemia"],answer:1,why:"Global subendocardial ischaemia."},{q:"De Winter T waves indicate:",options:["RCA occlusion","Proximal LAD occlusion","Pericarditis","Hyperkalaemia"],answer:1,why:"STEMI equivalent."},{q:"Diffuse concave ST elevation with PR depression suggests:",options:["STEMI","Pericarditis","Brugada","LVH"],answer:1,why:"Classic pericarditis pattern."},{q:"A 19-year-old collapses while sprinting; the ECG shows marked LVH with deep, narrow Q waves in the lateral leads. Most likely:",options:["Pericarditis","Hypertrophic cardiomyopathy","Mitral stenosis","Brugada syndrome"],answer:1,why:"HCM causes septal hypertrophy and sudden death with exertion in the young."},{q:"Normal axis is:",options:["I negative, aVF positive","I and aVF positive","I positive, aVF negative","Both negative"],answer:1,why:"Both positive."},{q:"QTc associated with high torsades risk:",options:["> 380 ms","> 500 ms","< 400 ms","> 300 ms"],answer:1,why:"Above 500 ms."},{q:"Short PR and delta wave indicate:",options:["LGL","WPW","First-degree block","Brugada"],answer:1,why:"Pre-excitation."},{q:"Irregular, very fast wide-complex tachycardia with varying QRS in a stable patient. Avoid:",options:["Procainamide","Adenosine and AV nodal blockers","Cardioversion","Expert consult"],answer:1,why:"Possible AF with WPW."},{q:"Sgarbossa criteria are used in:",options:["RBBB","LBBB or paced rhythm","Normal ECG","Pericarditis"],answer:1,why:"Identify occlusion despite LBBB."},{q:"ST elevation threshold in V2\u2013V3 for women:",options:["0.5 mm","1.5 mm","2.5 mm","4 mm"],answer:1,why:"Sex-specific thresholds."},{q:"Coved ST elevation in V1\u2013V2 with fever suggests:",options:["Brugada pattern","Pericarditis","Anterior STEMI","Hyperkalaemia"],answer:0,why:"Fever unmasks Brugada."},{q:"Lateral STEMI involves leads:",options:["II, III, aVF","I, aVL, V5\u2013V6","V1\u2013V2","aVR only"],answer:1,why:"Lateral territory."}],sources:[{title:"Fourth Universal Definition of Myocardial Infarction (2018)",url:"https://www.ahajournals.org/doi/10.1161/CIR.0000000000000617"},{title:"LITFL ECG Library",url:"https://litfl.com/ecg-library/"}]},pe={id:"fpc-cardiac-anatomy",domain:"cardiac",ref:"VI.2",title:"Cardiac anatomy and the coronary circulation",summary:"Chambers, valves, coronary arteries and dominance, the conduction system, and the physiology of the cardiac cycle, preload, afterload and contractility.",objectives:["Map coronary arteries to myocardial territories and the conduction system.","Explain the cardiac cycle and the determinants of stroke volume.","Relate anatomy to clinical consequences of infarction and valve disease."],sections:[{id:"coronaries",title:"Coronary arteries and dominance",core:!0,body:["The left main coronary artery divides into the left anterior descending (LAD), which supplies the anterior wall, the anterior two-thirds of the septum and the apex, and the circumflex (LCx), which supplies the lateral and, in some, posterior walls. The right coronary artery (RCA) supplies the right ventricle, the inferior wall in most people, and the SA node in about 60 % and the AV node in about 80\u201390 %.","Dominance is defined by which artery gives the posterior descending artery: the RCA in about 70\u201385 % (right-dominant), the circumflex in about 5\u201310 % (left-dominant), and both in the rest (co-dominant). Coronary flow to the left ventricle occurs mainly in diastole, when the muscle relaxes; tachycardia shortens diastole and reduces perfusion \u2014 one reason heart rate control matters in ischaemia."],table:{caption:"Infarct location and complications",head:["Artery","Territory","Watch for"],rows:[["LAD","Anterior wall, septum, apex","Pump failure, Mobitz II/CHB (infranodal), LV thrombus"],["RCA","Inferior wall, RV, SA/AV nodes","Bradycardia, AV block (nodal), RV infarction"],["LCx","Lateral (\xB1 posterior)","Often electrically subtle; papillary muscle rupture"],["Left main","Most of the LV","Cardiogenic shock, arrest"]]}},{id:"chambers",title:"Chambers, valves and the cycle",core:!0,body:["Deoxygenated blood returns to the right atrium, passes the tricuspid valve into the right ventricle and the pulmonary valve into the pulmonary artery. Oxygenated blood returns to the left atrium, passes the mitral valve into the left ventricle and the aortic valve into the aorta. The left ventricle generates systemic pressures (about 120/10 mmHg); the right, pulmonary pressures (about 25/5).",'In systole the ventricles contract, the AV valves close (S1), pressure rises until the semilunar valves open, and blood is ejected. In diastole the semilunar valves close (S2), the ventricles relax, the AV valves open and the ventricles fill \u2014 passively at first, then with atrial contraction (the "atrial kick", up to 20\u201330 % of filling, lost in atrial fibrillation).',"Stroke volume depends on preload (filling, the stretch on the fibres \u2014 Frank\u2013Starling), afterload (the resistance the ventricle ejects against) and contractility. Cardiac output equals stroke volume times heart rate; mean arterial pressure equals cardiac output times systemic vascular resistance (plus CVP)."]},{id:"valves",title:"Valve lesions in transport",body:["Aortic stenosis: fixed outflow obstruction, so the patient depends on preload and on afterload to perfuse the coronaries; vasodilators and tachycardia are poorly tolerated. Avoid hypotension. Mitral stenosis: filling depends on time, so tachycardia and atrial fibrillation cause pulmonary congestion. Acute mitral regurgitation (papillary muscle rupture after MI) causes sudden pulmonary oedema and shock; afterload reduction and urgent surgery help. Acute aortic regurgitation (dissection, endocarditis) causes shock with a wide pulse pressure; tachycardia shortens regurgitation time."]},{id:"conduction",title:"The conduction system",core:!0,body:["The sinoatrial node, high in the right atrium, sets the rate (60\u2013100). The impulse crosses the atria to the atrioventricular node, which delays conduction (the PR interval) to allow ventricular filling. It then passes the bundle of His, divides into the right and left bundle branches (the left into anterior and posterior fascicles), and spreads through the Purkinje fibres.","Intrinsic escape rates fall the lower the pacemaker: AV junction 40\u201360, ventricles 20\u201340. Block above or at the AV node (often RCA, inferior MI) tends to produce narrow escape rhythms that respond to atropine; block below the node (often LAD, anterior MI) produces wide escape rhythms that are unreliable and need pacing."],example:{case:"Anterior STEMI with new RBBB and left anterior fascicular block, HR 76, BP 110/70.",steps:["Bifascicular block from proximal LAD involvement.","High risk of progression to complete heart block with a wide, unstable escape.","Apply transcutaneous pacing pads before transport; atropine will not help infranodal block.","Expedite reperfusion."]}},{id:"case",title:"Transport case: the papillary muscle",body:["Five days after an inferior-posterior MI, a 70-year-old develops sudden severe dyspnoea, SpO\u2082 82 %, BP 78/50, and a new loud holosystolic murmur at the apex."],example:{case:"What happened and how do you transport?",steps:["Acute severe mitral regurgitation from papillary muscle rupture (the posteromedial papillary muscle has a single blood supply, often from the RCA/PDA).","Support oxygenation with NIV or intubation; afterload reduction if BP allows, otherwise inotropes and vasopressors; an intra-aortic balloon pump reduces regurgitation.","This needs emergency cardiac surgery \u2014 transport to a surgical centre with pre-alert."]}}],keyPoints:["LAD: anterior/septum/apex; RCA: inferior/RV/nodes; LCx: lateral.","Right-dominant (~70\u201385 %) means the RCA gives the PDA.","LV coronary flow is mainly diastolic \u2014 tachycardia worsens ischaemia.","SV = preload, afterload, contractility; CO = SV \xD7 HR; MAP \u2248 CO \xD7 SVR.","Nodal block (inferior MI) responds to atropine; infranodal block (anterior MI) needs pacing."],pearls:["Atrial fibrillation loses the atrial kick \u2014 up to 30 % of filling.","Aortic stenosis patients need preload and afterload."],pitfalls:["Vasodilating a patient with severe aortic stenosis.","Relying on atropine for infranodal block."],live:[{id:"heart-vsd",label:"Ventricular septal defect on the live heart"}],questions:[{q:"The LAD supplies:",options:["Inferior wall","Anterior wall, septum and apex","RV only","SA node usually"],answer:1,why:"Anterior territory."},{q:"In right-dominant circulation the PDA arises from:",options:["LAD","LCx","RCA","Left main"],answer:2,why:"Definition of dominance."},{q:"The AV node is supplied by the RCA in about:",options:["10 %","50 %","80\u201390 %","100 %"],answer:2,why:"Explains AV block in inferior MI."},{q:"LV coronary perfusion occurs mainly in:",options:["Systole","Diastole","Isovolumic contraction","Equally"],answer:1,why:"Compression limits systolic flow."},{q:"Atrial kick contributes up to:",options:["5 %","20\u201330 %","60 %","90 %"],answer:1,why:"Lost in AF."},{q:"Ventricular escape rate:",options:["60\u2013100","40\u201360","20\u201340","100\u2013150"],answer:2,why:"Lowest intrinsic pacemaker."},{q:"Complete heart block in anterior MI typically:",options:["Responds to atropine","Is infranodal and needs pacing","Is benign","Has narrow QRS"],answer:1,why:"Below the AV node."},{q:"Severe aortic stenosis patients poorly tolerate:",options:["Bradycardia only","Vasodilators and hypotension","Fluids","Oxygen"],answer:1,why:"Fixed outflow; coronary perfusion depends on pressure."},{q:"Mitral stenosis worsens with:",options:["Bradycardia","Tachycardia","Fluids restriction","Rest"],answer:1,why:"Less diastolic filling time."},{q:"New holosystolic apical murmur with shock after MI suggests:",options:["Aortic stenosis","Papillary muscle rupture (acute MR)","Pericarditis","Tamponade"],answer:1,why:"Mechanical complication."},{q:"MAP is approximately:",options:["HR \xD7 SV","CO \xD7 SVR (+ CVP)","SBP \u2212 DBP","CVP \xD7 PVR"],answer:1,why:"Ohm's law for flow."},{q:"Frank\u2013Starling law relates stroke volume to:",options:["Afterload","Preload (fibre stretch)","Heart rate","Oxygen"],answer:1,why:"More stretch, more force (to a point)."},{q:"The SA node rate:",options:["20\u201340","40\u201360","60\u2013100","150\u2013200"],answer:2,why:"Dominant pacemaker."},{q:"Posteromedial papillary muscle rupture is more common because:",options:["Dual blood supply","Single blood supply","Thicker muscle","No relation"],answer:1,why:"Usually PDA only."},{q:"Bifascicular block in anterior MI before transport warrants:",options:["Nothing","Pacing pads applied","Adenosine","Digoxin"],answer:1,why:"Risk of complete block."}],sources:[{title:"StatPearls: Anatomy, thorax, heart coronary arteries",url:"https://www.ncbi.nlm.nih.gov/books/?term=Anatomy%2C+thorax%2C+heart+coronary+arteries+StatPearls"},{title:"StatPearls: Physiology, cardiac cycle",url:"https://www.ncbi.nlm.nih.gov/books/?term=Physiology%2C+cardiac+cycle+StatPearls"}]},ue={id:"fpc-electrophys",domain:"cardiac",ref:"VI.13",title:"Electrophysiology: action potentials, pacing and devices",summary:"The cardiac action potential and the drugs and electrolytes that change it, transcutaneous and transvenous pacing, pacemakers and ICDs, and defibrillation and cardioversion energy.",objectives:["Describe the phases of the ventricular and pacemaker action potentials and drug effects.","Set up and troubleshoot transcutaneous pacing.","Manage patients with pacemakers and ICDs in transport."],sections:[{id:"ap",title:"Action potentials",core:!0,body:["The ventricular myocyte rests near \u221290 mV, set by potassium. Phase 0 is rapid depolarisation through fast sodium channels (the QRS); phase 1 early repolarisation; phase 2 the plateau, held by calcium influx (the ST segment); phase 3 repolarisation by potassium efflux (the T wave); phase 4 rest.",'Pacemaker cells in the SA and AV nodes have no true resting potential: phase 4 drifts upward (the "funny" current), and phase 0 depends on calcium channels, which is why calcium-channel blockers and beta-blockers slow the nodes. Sympathetic stimulation steepens phase 4 (faster rate); vagal stimulation flattens it.'],table:{caption:"Vaughan Williams classes",head:["Class","Mechanism","Examples","ECG effect"],rows:[["I","Na\u207A channel block","Procainamide (IA), lidocaine (IB), flecainide (IC)","QRS widening (IA, IC)"],["II","\u03B2-blockade","Metoprolol, esmolol","PR prolongation, slower rate"],["III","K\u207A channel block","Amiodarone, sotalol","QT prolongation"],["IV","Ca\xB2\u207A channel block","Diltiazem, verapamil","PR prolongation"],["Other","Adenosine, digoxin, magnesium","\u2014","AV nodal effects"]]}},{id:"pacing",title:"Transcutaneous pacing",core:!0,body:["Indicated for symptomatic bradycardia unresponsive to atropine (or when atropine is unlikely to work, as in infranodal block or heart transplant patients), and as a bridge to transvenous pacing. Place pads anterior\u2013posterior or anterior\u2013lateral; set a rate (often 60\u201380) and increase the current from the minimum until electrical capture (a wide QRS with a broad T after each pacing spike) occurs, then add a small margin.","Confirm mechanical capture with a palpable pulse (femoral is less confused by muscle twitching), a pulse oximetry waveform matching the paced rate, or an arterial line. Electrical artefact can mimic capture. Transcutaneous pacing is painful: give analgesia and sedation. Large body habitus, effusions and hyperinflated lungs raise thresholds.","Transvenous pacing (via internal jugular or femoral) is more reliable and comfortable; in transport, check the wire's position, connections, threshold and pacing box battery, and secure everything carefully."]},{id:"devices",title:"Pacemakers and ICDs",core:!0,body:["Pacemaker codes describe chamber paced, chamber sensed, and response (for example DDD: dual chamber paced and sensed, triggered and inhibited). Failure to pace (no spike when expected), failure to capture (spike without a following complex) and failure to sense (spikes at inappropriate times) are the main malfunctions; causes include lead displacement, battery depletion, electrolyte disturbance and ischaemia.","A magnet placed over a pacemaker usually switches it to asynchronous pacing at a fixed rate; over an ICD it usually suspends shock delivery without changing pacing \u2014 useful for inappropriate shocks, but the patient then needs external monitoring and defibrillation capability. Defibrillation pads should sit at least a few centimetres away from the device generator."]},{id:"energy",title:"Defibrillation and cardioversion",body:["Ventricular fibrillation and pulseless VT need unsynchronised defibrillation at the maximum or manufacturer-recommended biphasic energy (often 120\u2013200 J, escalating). Unstable tachyarrhythmias with a pulse need synchronised cardioversion: synchronisation avoids delivering the shock on the T wave. Typical starting energies: narrow regular (SVT, flutter) 50\u2013100 J, irregular narrow (AF) 120\u2013200 J, monomorphic VT with a pulse 100 J, all biphasic and escalating per protocol. Polymorphic VT is treated as VF (unsynchronised).","In aircraft, defibrillation is safe when the crew is clear of the patient and the stretcher; follow programme procedures and inform the pilot before shocking if required."]},{id:"case",title:"Transport case: pacing in the air",body:["A 77-year-old with complete heart block, HR 32, BP 72/40, confused. Atropine 1 mg had no effect. Transfer for a permanent pacemaker."],example:{case:"Set up and verify pacing for a 60-minute flight.",steps:["Pads anterior\u2013posterior; rate 70; increase current until electrical capture (e.g. 80 mA), then add ~10 %.","Confirm mechanical capture: femoral pulse and SpO\u2082 pleth at 70.","Analgesia and sedation (e.g. fentanyl and low-dose midazolam or ketamine).","An epinephrine or dopamine infusion as a pharmacological backup if capture is lost.","Recheck capture after every move; carry spare pads and battery."]}}],keyPoints:["Phase 0 Na\u207A (QRS), phase 2 Ca\xB2\u207A plateau, phase 3 K\u207A repolarisation (T); nodes depend on Ca\xB2\u207A.","Class I Na\u207A block widens QRS; class III prolongs QT; classes II and IV slow the AV node.","Pacing: increase mA to electrical capture, confirm mechanical capture with a pulse, then sedate.","Magnet: pacemaker \u2192 asynchronous pacing; ICD \u2192 shocks suspended.","Synchronise for unstable tachycardias with a pulse; unsynchronised for VF, pulseless VT and polymorphic VT."],pearls:["Check the femoral pulse to confirm capture \u2014 muscle twitch fools carotid palpation.","Pads a few centimetres from implanted devices."],pitfalls:['Calling electrical artefact "capture" without a pulse.',"Synchronised cardioversion attempts for polymorphic VT."],questions:[{q:"Phase 0 of the ventricular action potential is due to:",options:["K\u207A efflux","Na\u207A influx","Ca\xB2\u207A influx","Cl\u207B influx"],answer:1,why:"Fast sodium channels."},{q:"The plateau phase is maintained by:",options:["Na\u207A","Ca\xB2\u207A influx","K\u207A influx","Mg\xB2\u207A"],answer:1,why:"L-type calcium channels."},{q:"Nodal depolarisation (phase 0) depends mainly on:",options:["Sodium","Calcium","Chloride","Potassium"],answer:1,why:"Hence CCBs slow the AV node."},{q:"Amiodarone is primarily class:",options:["I","II","III","IV"],answer:2,why:"K\u207A channel blockade (with others)."},{q:"A drug class that widens the QRS:",options:["Class IC","Class II","Class IV","Adenosine"],answer:0,why:"Strong Na\u207A blockade."},{q:"Electrical capture on transcutaneous pacing appears as:",options:["Spike only","Spike followed by wide QRS and T wave","Narrow QRS","No change"],answer:1,why:"Ventricular depolarisation after each spike."},{q:"Best confirmation of mechanical capture:",options:["Carotid pulse during muscle twitch","Femoral pulse or SpO\u2082 waveform at paced rate","Monitor spike","Patient movement"],answer:1,why:"Avoids twitch artefact."},{q:"A magnet over an ICD usually:",options:["Starts pacing at 100","Suspends shock delivery","Turns off pacing","Shocks the patient"],answer:1,why:"Tachy therapies suspended."},{q:"A magnet over a pacemaker usually causes:",options:["Inhibition","Asynchronous fixed-rate pacing","Shocks","No effect"],answer:1,why:"Prevents oversensing inhibition."},{q:"Spikes without following complexes indicate:",options:["Failure to sense","Failure to capture","Normal pacing","Failure to pace"],answer:1,why:"Stimulus delivered, no depolarisation."},{q:"Polymorphic VT with a pulse but unstable is treated with:",options:["Synchronised cardioversion 50 J","Unsynchronised defibrillation","Adenosine","Vagal manoeuvres"],answer:1,why:"Synchronisation is unreliable."},{q:"Typical starting energy for unstable SVT (biphasic):",options:["10 J","50\u2013100 J","360 J","Unsynchronised 200 J"],answer:1,why:"Lower energies usually suffice."},{q:"Atropine is unlikely to help bradycardia in:",options:["Sinus bradycardia","Heart transplant patients","Vagal reaction","Inferior MI with nodal block"],answer:1,why:"Denervated hearts."},{q:"DDD pacing means:",options:["Single chamber","Dual chamber paced and sensed, dual response","Defibrillator only","Demand ventricular"],answer:1,why:"Standard code."},{q:"Sympathetic stimulation affects pacemaker cells by:",options:["Flattening phase 4","Steepening phase 4","Blocking Na\u207A","Prolonging plateau"],answer:1,why:"Faster rate."}],sources:[{title:"AHA guidelines for CPR and ECC: adult advanced life support",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{title:"StatPearls: Transcutaneous pacing",url:"https://www.ncbi.nlm.nih.gov/books/?term=Transcutaneous+pacing+StatPearls"}]};var me={id:"fpc-acs",domain:"cardiac",ref:"VI.4",title:"Acute coronary syndromes",summary:"STEMI, NSTEMI and unstable angina: pathophysiology, reperfusion strategy and time targets, antithrombotic therapy, and the complications to anticipate during transfer.",objectives:["Distinguish STEMI, NSTEMI and unstable angina and their urgency.","Choose a reperfusion strategy (PCI versus fibrinolysis) by time and transport distance.","Give and avoid the right drugs, and anticipate arrhythmic and mechanical complications."],sections:[{id:"patho",title:"From plaque to infarct",core:!0,body:["Most ACS begins when an atherosclerotic plaque ruptures or erodes, exposing thrombogenic material. Platelets adhere and aggregate, the coagulation cascade forms fibrin, and the resulting thrombus partially or completely occludes the artery. Complete, persistent occlusion produces transmural ischaemia and ST elevation (STEMI); partial or intermittent occlusion produces subendocardial ischaemia (NSTEMI if troponin rises, unstable angina if it does not).",'Myocardium dies from the endocardium outward over hours \u2014 "time is muscle". Reperfusion within the first few hours salvages the most myocardium and reduces mortality and heart failure.']},{id:"reperfusion",title:"Reperfusion strategy and time",core:!0,body:['Primary PCI is preferred for STEMI when it can be delivered promptly: first medical contact to device within 90 minutes, or within 120 minutes when transfer from a non-PCI hospital is required. If PCI cannot be achieved within 120 minutes of first medical contact, fibrinolysis is given (goal: within 30 minutes of arrival, "door-to-needle") unless contraindicated, followed by transfer to a PCI centre \u2014 immediately for rescue PCI if reperfusion fails, or within 2\u201324 hours for a routine invasive strategy.',"Signs of successful fibrinolysis: ST-segment resolution of 50 % or more at 60\u201390 minutes, relief of pain and reperfusion arrhythmias such as accelerated idioventricular rhythm. Failed reperfusion or cardiogenic shock needs urgent transfer for PCI regardless of time.","High-risk NSTEMI (refractory pain, haemodynamic instability, arrhythmia, heart failure) needs angiography within hours; others within 24\u201372 hours."],list:{caption:"Absolute contraindications to fibrinolysis (examples)",items:["Any prior intracranial haemorrhage","Ischaemic stroke within 3 months","Known intracranial neoplasm or vascular malformation","Suspected aortic dissection","Active bleeding (excluding menses)","Significant head or facial trauma within 3 months"]}},{id:"drugs",title:"Medications",core:!0,body:["Aspirin (162\u2013325 mg chewed) for all ACS unless allergic. A P2Y12 inhibitor (ticagrelor, prasugrel or clopidogrel) per the PCI centre's protocol. Anticoagulation (unfractionated heparin, enoxaparin or bivalirudin) per strategy.","Nitroglycerin relieves ischaemic pain but is avoided with hypotension, suspected right-ventricular infarction, and recent phosphodiesterase-5 inhibitor use (sildenafil within 24 hours, tadalafil within 48). Oxygen is given only for SpO\u2082 below 90 % \u2014 routine oxygen in normoxic patients has no benefit. Opioids relieve pain but may delay oral P2Y12 absorption; use the lowest effective dose. Beta-blockers are avoided in the acute phase if there are signs of heart failure, low output or risk of shock."]},{id:"complications",title:"Complications en route",body:["Arrhythmias: ventricular fibrillation is most common early; have pads on. Bradycardia and AV block with inferior MI (usually nodal, atropine-responsive); Mobitz II and complete block with anterior MI (infranodal, needs pacing). Pump failure and cardiogenic shock with large infarcts. Mechanical complications \u2014 papillary muscle rupture (acute MR), ventricular septal rupture (new harsh murmur, shock), and free wall rupture (tamponade, PEA) \u2014 typically occur days 2\u20137 but may occur earlier, and need emergency surgery."],example:{case:"Anterior STEMI at a rural hospital, symptom onset 90 minutes ago. Nearest PCI centre: 140 minutes by ground, 55 minutes by helicopter including handover. No contraindications to fibrinolysis.",steps:["By air, first-contact-to-device can be under 120 minutes \u2014 primary PCI is feasible: aspirin, P2Y12 and anticoagulant per centre protocol, pre-activate the cath lab.","If air transport is unavailable (weather), PCI within 120 minutes is not achievable: give fibrinolysis within 30 minutes, then transfer.","In flight: pads on, analgesia, avoid hypotension, monitor for VF and AV block."]}},{id:"special",title:"Special presentations",body:["Women, the elderly and diabetics more often present atypically \u2014 dyspnoea, fatigue, nausea, epigastric pain \u2014 which delays diagnosis. Cocaine-associated chest pain is treated with benzodiazepines, aspirin and nitrates; beta-blockers are traditionally avoided acutely. Spontaneous coronary artery dissection affects younger women, often peripartum. MI with non-obstructive coronary arteries (MINOCA) and Takotsubo cardiomyopathy can mimic STEMI."]}],keyPoints:["STEMI = complete occlusion; NSTEMI = troponin rise without STE; UA = no troponin rise.","Primary PCI if first contact to device \u2264 90 min (\u2264 120 with transfer); otherwise fibrinolysis within 30 min then transfer.","Aspirin for all; P2Y12 and anticoagulant per protocol; oxygen only if SpO\u2082 < 90 %.","No nitrates with hypotension, RV infarction or recent PDE-5 inhibitors.","Pads on: VF early; AV block (inferior nodal, anterior infranodal); mechanical complications need surgery."],pearls:["Accelerated idioventricular rhythm after lysis often signals reperfusion.","Air transport can make primary PCI possible where ground transport cannot."],pitfalls:["Routine oxygen for normoxic ACS.","Nitrates after sildenafil."],questions:[{q:"Target first medical contact to device time when transfer is required:",options:["\u2264 60 min","\u2264 120 min","\u2264 180 min","\u2264 6 h"],answer:1,why:"Otherwise fibrinolysis is preferred."},{q:"Door-to-needle goal for fibrinolysis:",options:["10 min","30 min","60 min","90 min"],answer:1,why:"Within 30 minutes."},{q:"Sign of successful fibrinolysis:",options:["New Q waves only","\u2265 50 % ST resolution at 60\u201390 min","Rising BP","Bradycardia"],answer:1,why:"ST resolution with pain relief."},{q:"An absolute contraindication to fibrinolysis:",options:["Age 75","Prior intracranial haemorrhage","Hypertension 150/90","Diabetes"],answer:1,why:"Bleeding risk."},{q:"Oxygen in ACS is indicated when SpO\u2082 is:",options:["< 99 %","< 90 %","Always","Never"],answer:1,why:"No benefit in normoxia."},{q:"Nitroglycerin should be avoided after sildenafil within:",options:["2 h","24 h","1 week","It is fine"],answer:1,why:"Profound hypotension."},{q:"NSTEMI differs from unstable angina by:",options:["ST elevation","Troponin rise","Pain duration","Age"],answer:1,why:"Biomarker evidence of necrosis."},{q:"Most common lethal arrhythmia early in MI:",options:["AF","VF","Sinus tachycardia","PACs"],answer:1,why:"Have pads on."},{q:"Mobitz II in anterior MI implies:",options:["Nodal block","Infranodal block \u2014 prepare to pace","Benign finding","Digoxin effect"],answer:1,why:"High risk of CHB."},{q:"New harsh holosystolic murmur and shock on day 4 after MI suggests:",options:["Pericarditis","Ventricular septal rupture","Aortic stenosis","Dressler syndrome"],answer:1,why:"Mechanical complication."},{q:"Cocaine chest pain first-line adjunct:",options:["Beta-blocker","Benzodiazepine","Fibrinolysis always","Haloperidol"],answer:1,why:"Reduces sympathetic drive."},{q:"Aspirin dose for ACS:",options:["81 mg swallowed","162\u2013325 mg chewed","1 g IV","Not given"],answer:1,why:"Chewed for rapid absorption."},{q:"Opioids in ACS may:",options:["Speed P2Y12 absorption","Delay oral P2Y12 absorption","Prevent VF","Replace aspirin"],answer:1,why:"Slowed gut motility."},{q:"Plaque rupture leads to occlusion mainly via:",options:["Vasospasm only","Platelet aggregation and fibrin thrombus","Embolism from the LA","Hypotension"],answer:1,why:"Thrombosis."},{q:"High-risk NSTEMI with refractory pain needs angiography:",options:["Within hours","Within 1 week","Electively","Not at all"],answer:0,why:"Immediate invasive strategy."}],sources:[{title:"2025 ACC/AHA guideline for the management of acute coronary syndromes",url:"https://www.ahajournals.org/doi/10.1161/CIR.0000000000001309"},{title:"StatPearls: ST-elevation myocardial infarction",url:"https://www.ncbi.nlm.nih.gov/books/?term=ST-elevation+myocardial+infarction+StatPearls"}]},ye={id:"fpc-cardiogenic",domain:"cardiac",ref:"VI.5",title:"Cardiogenic shock",summary:"Recognising pump failure, haemodynamic profiles, SCAI staging, inotropes and vasopressors, mechanical support, and the airway and ventilation hazards of the failing heart.",objectives:["Recognise cardiogenic shock and stage its severity.","Choose vasopressor and inotrope support by haemodynamic profile.","Anticipate mechanical circulatory support and safe ventilation strategies."],sections:[{id:"define",title:"Definition and profiles",core:!0,body:["Cardiogenic shock is hypoperfusion from primary cardiac failure: systolic BP below about 90 mmHg (or vasopressors needed to hold it), with signs of hypoperfusion \u2014 cold extremities, oliguria, altered mentation, rising lactate \u2014 and evidence of high filling pressures (pulmonary oedema, raised JVP). Acute MI is the leading cause; others include decompensated chronic heart failure, myocarditis, valve catastrophes and arrhythmias.",'Bedside profiles combine congestion (wet or dry) and perfusion (warm or cold). "Cold and wet" is the classic cardiogenic shock: low cardiac index, high wedge pressure, high SVR. RV-predominant shock has a high CVP with clear lungs. The SCAI stages run from A (at risk) through B (beginning: hypotension or tachycardia without hypoperfusion), C (classic: hypoperfusion needing intervention), D (deteriorating despite treatment) to E (extremis: arrest or refractory collapse).']},{id:"treat",title:"Drugs",core:!0,body:["Norepinephrine is the usual first agent to restore perfusion pressure (MAP around 65) with less arrhythmia than dopamine. Add an inotrope \u2014 dobutamine, or milrinone if beta-blocked or with pulmonary hypertension \u2014 for persistent low output once pressure is adequate. Epinephrine is an alternative but raises lactate and myocardial oxygen demand.","Avoid large fluid boluses unless there is clear hypovolaemia or RV infarction (where cautious volume helps). Treat the cause: reperfusion for MI (emergency PCI improves survival in MI-related shock), rhythm control for arrhythmia, surgery for mechanical lesions. Correct acidosis, hypoxaemia and electrolytes."]},{id:"mcs",title:"Mechanical circulatory support",core:!0,body:["When drugs fail, devices bridge to recovery, transplant or decision: intra-aortic balloon pumps (afterload reduction and coronary perfusion; modest output support), Impella devices (axial-flow pumps across the aortic valve that unload the LV), and VA-ECMO (full cardiopulmonary support but raises LV afterload \u2014 the LV may need venting). Transporting patients on these devices is covered in the mechanical support lesson; early recognition and transfer to a centre that can place them is the transport team's main contribution."]},{id:"airway",title:"Airway and ventilation",core:!0,body:["Intubating a patient in cardiogenic shock risks arrest: induction agents drop sympathetic tone, and positive pressure reduces venous return. Yet positive pressure helps the failing LV by reducing afterload and pulmonary oedema. Use NIV first when possible; if intubation is necessary, start or increase vasopressors before induction, use a reduced dose of a haemodynamically stable agent, and apply PEEP thoughtfully. For RV failure, avoid high intrathoracic pressures, hypoxia and hypercapnia, which raise pulmonary vascular resistance."],example:{case:"A 66-year-old after anterior STEMI: BP 78/48, HR 112, cold mottled legs, crackles to mid-zones, SpO\u2082 88 % on NRB, lactate 5.1, urine 10 mL/h.",steps:["Cold and wet, SCAI stage C: classic cardiogenic shock.","Norepinephrine to MAP \u2265 65; add dobutamine for low output once pressure is supported.","Oxygenation: CPAP/BiPAP if tolerated; if intubating, pressors running and reduced-dose induction.","No routine fluids; aspirin and anticoagulation per protocol; emergency PCI \u2014 direct to a centre with mechanical support capability."]}}],keyPoints:["Cardiogenic shock: hypotension + hypoperfusion + high filling pressures; MI is the leading cause.",'Profile "cold and wet": low CI, high wedge, high SVR.',"Norepinephrine for pressure, then dobutamine or milrinone for output.","Treat the cause: emergency PCI for MI-related shock.","NIV first; if intubating, pressors before induction and reduced-dose agent."],pearls:["RV shock: high CVP, clear lungs \u2014 cautious fluid helps.","Choose destinations with mechanical support capability."],pitfalls:["Fluid-loading a congested failing LV.","Inducing without vasopressor support."],live:[{id:"lines-shock-states",label:"Shock states at the bedside"},{id:"ln-disease",label:"Waveforms of disease (failing LV)"}],questions:[{q:"The classic cardiogenic shock profile is:",options:["Warm and dry","Cold and wet","Warm and wet","Cold and dry"],answer:1,why:"Low perfusion, congestion."},{q:"First vasopressor commonly used in cardiogenic shock:",options:["Phenylephrine","Norepinephrine","Vasopressin alone","Isoproterenol"],answer:1,why:"Fewer arrhythmias than dopamine."},{q:"An inotrope preferred in a beta-blocked patient:",options:["Dobutamine","Milrinone","Phenylephrine","Esmolol"],answer:1,why:"Acts independently of \u03B2-receptors."},{q:"Leading cause of cardiogenic shock:",options:["Myocarditis","Acute MI","Valve disease","Sepsis"],answer:1,why:"Large infarcts."},{q:"SCAI stage C means:",options:["At risk","Beginning shock without hypoperfusion","Classic shock with hypoperfusion","Extremis"],answer:2,why:"Hypoperfusion requiring intervention."},{q:"Haemodynamics of cardiogenic shock:",options:["High CI, low SVR","Low CI, high wedge, high SVR","Low wedge, low CVP","High CI, high wedge"],answer:1,why:"Pump failure."},{q:"Which improves survival in MI-related cardiogenic shock?",options:["Fibrinolysis alone","Emergency revascularisation","Large fluid boluses","Beta-blockade"],answer:1,why:"Early revascularisation (PCI) improves survival in MI-related shock."},{q:"VA-ECMO can increase:",options:["LV preload only","LV afterload","Coronary perfusion only","RV failure"],answer:1,why:"Retrograde aortic flow."},{q:"Positive pressure ventilation helps the failing LV by:",options:["Increasing afterload","Reducing afterload and pulmonary oedema","Raising heart rate","Increasing preload"],answer:1,why:"Lower transmural pressure."},{q:"RV-predominant shock typically shows:",options:["Low CVP","High CVP with clear lungs","Pulmonary oedema","High CI"],answer:1,why:"RV backs up."},{q:"Epinephrine in cardiogenic shock may:",options:["Lower lactate","Raise lactate and myocardial oxygen demand","Cause bradycardia","Lower BP"],answer:1,why:"\u03B2-2 and \u03B2-1 effects."},{q:"Fluids in cardiogenic shock are appropriate mainly in:",options:["All cases","RV infarction or clear hypovolaemia","Pulmonary oedema","Never"],answer:1,why:"Otherwise worsens congestion."},{q:"Before intubating cardiogenic shock, start:",options:["Diuretic","Vasopressor support","Nitroglycerin","Beta-blocker"],answer:1,why:"Prevent post-induction collapse."},{q:"An Impella device:",options:["Inflates in diastole","Pumps blood from LV into aorta","Oxygenates blood","Paces the heart"],answer:1,why:"Axial-flow LV unloading."},{q:"Mottled legs and oliguria indicate:",options:["Congestion","Hypoperfusion","Overhydration","Normal"],answer:1,why:"End-organ hypoperfusion."}],sources:[{title:"SCAI SHOCK stage classification (2019, updated 2022)",url:"https://www.jacc.org/doi/10.1016/j.jacc.2021.12.003"},{title:"Hochman JS et al. SHOCK trial. NEJM (1999)",url:"https://www.nejm.org/doi/full/10.1056/NEJM199908263410901"}]},ge={id:"fpc-heart-failure",domain:"cardiac",ref:"VI.6",title:"Acute heart failure",summary:"Systolic and diastolic failure, acute decompensation phenotypes, sympathetic crashing pulmonary oedema, NIV, nitrates and diuretics, and right heart failure.",objectives:["Classify acute heart failure by congestion and perfusion.","Treat hypertensive acute pulmonary oedema with NIV and high-dose nitrates.","Recognise right heart failure and its specific hazards."],sections:[{id:"types",title:"Types and triggers",core:!0,body:["Heart failure with reduced ejection fraction (HFrEF, EF \u2264 40 %) is a failure of contraction; with preserved ejection fraction (HFpEF) the ventricle is stiff and fills poorly at normal pressures. Acute decompensation is triggered by ischaemia, arrhythmia (especially new AF), uncontrolled hypertension, infection, non-adherence to medicines or salt and fluid restriction, renal failure, and drugs (NSAIDs, some calcium-channel blockers).",'Most decompensated patients are "warm and wet": congested but perfused. Treat congestion (diuretics, vasodilators). "Cold and wet" patients are in cardiogenic shock. "Cold and dry" patients are underfilled and low output.']},{id:"scape",title:"Hypertensive (sympathetic crashing) pulmonary oedema",core:!0,body:["A sudden surge of afterload with fluid redistribution into the lungs produces extreme dyspnoea, frothy sputum, hypertension, tachycardia and hypoxaemia. Total body water may not be increased; the problem is afterload and redistribution.","Treatment is immediate CPAP or BiPAP plus high-dose nitroglycerin \u2014 for example sublingual 0.4\u20130.8 mg repeated every few minutes, or IV boluses and an infusion starting high (often 100 mcg/min or more) and titrating down as the blood pressure falls. Diuretics are secondary and slower. Many of these patients avoid intubation if treated aggressively and early."]},{id:"diuretics",title:"Diuretics, morphine and inotropes",core:!0,body:["In volume-overloaded patients, IV loop diuretics (furosemide, often at least the patient's daily oral dose given IV, or 40 mg in diuretic-naive adults) relieve congestion over hours. Monitor potassium and renal function. Morphine is no longer routine \u2014 it may increase intubation and adverse outcomes. Inotropes are reserved for low-output states with hypoperfusion."]},{id:"rv",title:"Right heart failure",body:["The right ventricle is thin-walled and tolerates volume better than pressure. Acute RV failure (massive PE, RV infarction, decompensated pulmonary hypertension) produces raised JVP, hepatomegaly, peripheral oedema and hypotension with clear lungs. Over-filling dilates the RV, shifts the septum and compresses the LV.","Principles: maintain systemic pressure (norepinephrine, vasopressin, which does not raise PVR), optimise RV preload carefully, reduce RV afterload (oxygen, avoid hypercapnia and acidosis, inhaled pulmonary vasodilators where available), and support contractility (dobutamine or milrinone). Intubation and positive pressure are high-risk."],example:{case:"A 74-year-old woman with sudden dyspnoea: BP 212/118, HR 124, SpO\u2082 80 %, sitting upright, frothy sputum, crackles throughout.",steps:["Sympathetic crashing acute pulmonary oedema.","CPAP 8\u201310 cmH\u2082O immediately, FiO\u2082 high.","High-dose nitroglycerin sublingual then IV; titrate to BP.","Reassess frequently; furosemide once stabilising if volume overloaded; intubate only if NIV fails."]}},{id:"case",title:"Transport case: new AF in heart failure",body:["A 70-year-old with known HFrEF (EF 25 %), new AF at 148, BP 96/60, crackles, SpO\u2082 90 % on 4 L."],example:{case:"Rate, rhythm or flow?",steps:["Rapid AF reduces filling and output in a weak heart; it may be the trigger for decompensation.","Unstable (hypotension, pulmonary oedema): synchronised cardioversion is reasonable.","If borderline stable: avoid negative inotropes (diltiazem) in severe HFrEF; amiodarone or cautious digoxin per protocol.","Treat congestion with NIV and diuretics as BP allows; anticoagulation considerations at the destination."]}}],keyPoints:["HFrEF = weak pump (EF \u2264 40 %); HFpEF = stiff ventricle.","Most acute HF is warm and wet: diuretics and vasodilators.","Hypertensive pulmonary oedema: CPAP/BiPAP plus high-dose nitroglycerin.","Morphine is not routine.","RV failure: support pressure, cautious preload, reduce PVR, avoid high intrathoracic pressure."],pearls:["High-dose nitrates often avert intubation in SCAPE.","Vasopressin raises SVR without raising PVR."],pitfalls:["Diltiazem in severe HFrEF with rapid AF.","Large fluid boluses in RV failure."],questions:[{q:"HFrEF is defined by EF:",options:["\u2264 40 %","\u2265 50 %","60\u201370 %","> 80 %"],answer:0,why:"Reduced ejection fraction."},{q:"First-line therapy for hypertensive acute pulmonary oedema:",options:["Morphine","NIV and high-dose nitroglycerin","Fluids","Beta-blocker"],answer:1,why:"Afterload and preload reduction."},{q:"Most decompensated HF patients are:",options:["Cold and dry","Warm and wet","Cold and wet","Warm and dry"],answer:1,why:"Congested but perfused."},{q:"Morphine in acute HF:",options:["Routine","Not routine; may worsen outcomes","Mandatory","Replaces NIV"],answer:1,why:"Associated with adverse outcomes."},{q:"A common trigger of HF decompensation:",options:["Hypothyroidism only","New atrial fibrillation","Bradycardia 60","Mild exercise"],answer:1,why:"Loss of atrial kick and rapid rate."},{q:"Right heart failure classically shows:",options:["Pulmonary oedema","Raised JVP, clear lungs","Low CVP","Bradycardia"],answer:1,why:"Systemic venous congestion."},{q:"Vasopressor favoured in RV failure because it does not raise PVR:",options:["Phenylephrine","Vasopressin","Dopamine","Epinephrine"],answer:1,why:"V1 effects spare pulmonary vessels."},{q:"Avoid in severe HFrEF with rapid AF:",options:["Amiodarone","Diltiazem","Cardioversion","Anticoagulation"],answer:1,why:"Negative inotrope."},{q:"Furosemide dose for a diuretic-naive adult in acute HF:",options:["5 mg","40 mg IV","400 mg","1 g"],answer:1,why:"Typical starting dose."},{q:"HFpEF patients have:",options:["Weak contraction","Stiff ventricle with impaired filling","Normal hearts","Dilated RV only"],answer:1,why:"Diastolic dysfunction."},{q:"Over-filling a failing RV:",options:["Improves LV output","Shifts the septum and compresses the LV","Lowers CVP","Has no effect"],answer:1,why:"Ventricular interdependence."},{q:"IV nitroglycerin starting dose in SCAPE is often:",options:["5 mcg/min","100 mcg/min or more","1000 mcg/min","0.1 mcg/min"],answer:1,why:"High-dose then titrate."},{q:"NSAIDs worsen heart failure by:",options:["Diuresis","Sodium and fluid retention","Lowering BP","Bradycardia"],answer:1,why:"Renal prostaglandin inhibition."},{q:"Unstable rapid AF with pulmonary oedema and hypotension:",options:["Diltiazem","Synchronised cardioversion","Observation","Adenosine"],answer:1,why:"Electrical rhythm control."},{q:"Inotropes in acute HF are reserved for:",options:["All patients","Low output with hypoperfusion","Hypertensive oedema","Mild symptoms"],answer:1,why:"Not for congestion alone."}],sources:[{title:"2022 AHA/ACC/HFSA guideline for the management of heart failure",url:"https://www.ahajournals.org/doi/10.1161/CIR.0000000000001063"},{title:"StatPearls: Acute pulmonary edema",url:"https://www.ncbi.nlm.nih.gov/books/?term=Acute+pulmonary+edema+StatPearls"}]};var fe={id:"fpc-mcs",domain:"cardiac",ref:"VI.3",title:"Mechanical circulatory support: IABP, Impella, ECMO and VADs",summary:"How each device supports the circulation, what to monitor, the alarms and complications that matter in transport, and how to resuscitate a patient on a device.",objectives:["Explain the haemodynamic effect of IABP, Impella, VA-ECMO and durable VADs.","Monitor and troubleshoot each device during transport.","Adapt assessment and resuscitation for device-dependent patients."],sections:[{id:"iabp",title:"Intra-aortic balloon pump",core:!0,body:["A balloon in the descending thoracic aorta, its tip just below the left subclavian artery and above the renal arteries, inflates in diastole (at the dicrotic notch) to augment diastolic pressure and coronary perfusion, and deflates just before systole to reduce afterload. Cardiac output rises modestly (often around 0.5 L/min). It is triggered from the ECG or arterial waveform; pacing spikes or arrhythmias can disrupt timing.","Timing errors: early inflation (before the notch) shortens ejection; late inflation loses augmentation; early deflation loses afterload reduction; late deflation (balloon still inflated as the ventricle ejects) increases afterload and is the most dangerous. Complications include limb ischaemia (check distal pulses), balloon rupture (blood in the helium line \u2014 stop the pump and clamp per protocol), malposition (left arm or renal ischaemia), thrombocytopenia and bleeding.","In transport, secure the catheter, confirm position on imaging before departure, carry the console's battery and helium supply, and know how to switch triggers. Do not leave a balloon stationary for more than a short period (thrombus risk); hand-inflate per manufacturer guidance if the console fails."]},{id:"impella",title:"Impella",core:!0,body:["An Impella is a microaxial pump placed across the aortic valve, drawing blood from the left ventricle and ejecting it into the ascending aorta, directly unloading the LV. Support ranges from about 2.5 to 5.5 L/min depending on device. A right-sided version supports the RV.","Monitor position (via console placement signals and, when available, echo), purge pressure and flow, haemolysis (dark urine, rising LDH), limb perfusion and bleeding at the access site. Suction alarms mean the pump inlet is pulling against the ventricle wall \u2014 usually hypovolaemia, RV failure or malposition; reduce the support level and treat the cause."]},{id:"ecmo",title:"ECMO",core:!0,body:[`Veno-venous (VV) ECMO drains venous blood, oxygenates it and returns it to the venous side: it supports gas exchange only and relies on the patient's own heart. Veno-arterial (VA) ECMO returns oxygenated blood to the arterial system, supporting both heart and lungs. Peripheral femoral VA-ECMO pumps blood retrogradely up the aorta, which raises LV afterload; a non-ejecting LV may distend and need venting, and differential hypoxaemia ("north\u2013south syndrome") can occur when the native heart ejects poorly oxygenated blood to the upper body \u2014 check right-hand SpO\u2082 or right radial gases.`,'Transporting ECMO patients requires a specialist team: secure cannulas (dislodgement is catastrophic), clamps at the bedside, gas supply and battery for the console, anticoagulation monitoring, and a plan for circuit emergencies. Low flow with "chattering" lines suggests hypovolaemia or kinked cannulas.']},{id:"vad",title:"Durable left ventricular assist devices",core:!0,body:["Modern LVADs are continuous-flow pumps from the LV apex to the aorta, powered through a driveline by external batteries and a controller. Many patients have no palpable pulse and a narrow or absent pulse pressure; measure MAP with a Doppler (the first Korotkoff sound approximates MAP) or an arterial line, targeting roughly 70\u201390 mmHg. Pulse oximetry may not read.","Assessment: check perfusion (mentation, skin, capillary refill), listen for the pump hum over the chest, read the controller (flow, power, speed, alarms), check batteries and connections. Common problems: driveline infection, GI bleeding (acquired von Willebrand deficiency plus anticoagulation), pump thrombosis (rising power, haemolysis), arrhythmias (often tolerated), RV failure and stroke.","Cardiac arrest: if the patient is unresponsive with poor perfusion and the pump is not running or not working, many protocols allow chest compressions; check with the VAD centre where possible but do not delay resuscitation in a truly unperfused patient. Always bring the patient's spare controller and batteries, and contact the implanting centre."],example:{case:"An LVAD patient is confused with a Doppler MAP of 58 and a low-flow alarm.",steps:["Check batteries, driveline and controller connections first.","Low flow with low MAP suggests hypovolaemia (bleeding?), RV failure or arrhythmia \u2014 check rhythm and give a cautious fluid bolus.","Look for GI bleeding; check haemoglobin when possible.","Call the VAD coordinator; transport to the implanting centre with spare equipment."]}}],keyPoints:["IABP: inflate at the dicrotic notch, deflate before systole; late deflation is the dangerous error.","Impella unloads the LV across the aortic valve; suction alarm \u2192 reduce support, treat hypovolaemia or malposition.","VV-ECMO = lungs only; VA-ECMO = heart and lungs, raises LV afterload; watch right-hand SpO\u2082.","LVAD: often pulseless \u2014 Doppler MAP 70\u201390; check controller, batteries, driveline.","Bring spare batteries and controllers; call the device centre."],pearls:["Blood in an IABP helium line means balloon rupture.","Right radial gases detect differential hypoxaemia on femoral VA-ECMO."],pitfalls:["Trusting a non-palpable pulse as arrest in an LVAD patient without assessing perfusion.","Leaving an IABP balloon stationary."],live:[{id:"lines-iabp",label:"Intra-aortic balloon pump timing"}],questions:[{q:"IABP inflation should occur at:",options:["The R wave","The dicrotic notch","Peak systole","The P wave"],answer:1,why:"Onset of diastole."},{q:"The most dangerous IABP timing error:",options:["Early deflation","Late inflation","Late deflation","Early inflation"],answer:2,why:"Raises afterload during ejection."},{q:"Ideal IABP tip position:",options:["Ascending aorta","Just below the left subclavian artery","Below the renal arteries","In the LV"],answer:1,why:"Descending thoracic aorta."},{q:"Blood in the IABP gas line indicates:",options:["Normal","Balloon rupture","Good augmentation","Malposition only"],answer:1,why:"Stop the pump."},{q:"An Impella pumps blood from:",options:["RA to aorta","LV to ascending aorta","Vena cava to oxygenator","Aorta to LV"],answer:1,why:"Direct LV unloading."},{q:"Impella suction alarm commonly reflects:",options:["Hypervolaemia","Hypovolaemia or malposition","Hypertension","Hyperthermia"],answer:1,why:"Inlet pulls on the wall."},{q:"VV-ECMO supports:",options:["Heart only","Gas exchange only","Heart and lungs","Kidneys"],answer:1,why:"Venous return to venous side."},{q:"Peripheral VA-ECMO may cause:",options:["LV unloading","Increased LV afterload and distension","Hypercarbia always","RV failure only"],answer:1,why:"Retrograde aortic flow."},{q:"To detect differential hypoxaemia on femoral VA-ECMO, monitor:",options:["Left foot SpO\u2082","Right hand SpO\u2082 or right radial gas","Femoral venous gas","EtCO\u2082 only"],answer:1,why:"Upper body perfused by native heart."},{q:"MAP in an LVAD patient is best measured by:",options:["Palpation","Doppler (first sound \u2248 MAP) or arterial line","Automated cuff always","SpO\u2082"],answer:1,why:"Low pulsatility."},{q:"Target MAP for a continuous-flow LVAD:",options:["40\u201350","70\u201390","110\u2013130","> 140"],answer:1,why:"Avoid hypo- and hypertension."},{q:"GI bleeding is common in LVAD patients due to:",options:["Thrombocytosis","Acquired von Willebrand deficiency and anticoagulation","Hypertension","Vitamin K excess"],answer:1,why:"Shear stress degrades vWF."},{q:"Rising LVAD power with dark urine suggests:",options:["Hypovolaemia","Pump thrombosis with haemolysis","Battery failure","Normal"],answer:1,why:"Thrombus increases load."},{q:"First step for an LVAD alarm:",options:["CPR","Check batteries, connections and controller","Defibrillate","Ignore"],answer:1,why:"Power problems are common and fixable."},{q:"IABP may cause which complication in the leg?",options:["DVT only","Limb ischaemia","Hyperaemia","None"],answer:1,why:"Femoral catheter obstruction."}],sources:[{title:"StatPearls: Intra-aortic balloon pump",url:"https://www.ncbi.nlm.nih.gov/books/?term=Intra-aortic+balloon+pump+StatPearls"},{title:"ELSO guidelines",url:"https://www.elso.org/ecmo-resources/elso-ecmo-guidelines.aspx"},{title:"StatPearls: Left ventricular assist device",url:"https://www.ncbi.nlm.nih.gov/books/?term=Left+ventricular+assist+device+StatPearls"}]},be={id:"fpc-cardiac-infect",domain:"cardiac",ref:"VI.7",title:"Pericarditis, tamponade, myocarditis, endocarditis and valve disease",summary:"Inflammatory and infectious heart disease: recognising pericarditis and tamponade, myocarditis presenting as shock, endocarditis and its embolic complications, and acute valve failure.",objectives:["Differentiate pericarditis from STEMI and recognise tamponade early.","Recognise myocarditis and endocarditis and their complications.","Manage acute valvular emergencies until surgery."],sections:[{id:"pericarditis",title:"Pericarditis",core:!0,body:["Acute pericarditis causes sharp, pleuritic chest pain that improves sitting forward, a pericardial friction rub, and diffuse concave ST elevation with PR depression (PR elevation in aVR). Causes include viral infection, post-MI (early, and Dressler syndrome weeks later), uraemia, autoimmune disease, malignancy and post-cardiac surgery. Treatment is NSAIDs and colchicine for most; steroids are second-line.","Distinguish from STEMI: pericarditis has diffuse elevation not confined to a territory, no reciprocal depression (except in aVR and V1), PR depression, and no Q waves. When in doubt, bedside echo and serial ECGs help; myopericarditis raises troponin."]},{id:"tamponade",title:"Cardiac tamponade",core:!0,body:["Fluid in the pericardium raises pressure until the chambers cannot fill. Speed matters more than volume: 100\u2013200 mL accumulating rapidly (trauma, rupture after MI, aortic dissection, post-procedural) can cause tamponade, while slow effusions may reach litres. Beck's triad \u2014 hypotension, distended neck veins and muffled heart sounds \u2014 is classic but often incomplete. Look for tachycardia, a narrow pulse pressure, pulsus paradoxus (systolic fall > 10 mmHg on inspiration) and electrical alternans.","Ultrasound shows the effusion with right atrial systolic collapse and right ventricular diastolic collapse, and a plethoric IVC. Temporising measures: fluid bolus to raise filling pressure, avoid positive-pressure ventilation if possible (it worsens filling), and vasopressors. Definitive treatment is drainage \u2014 pericardiocentesis (ideally ultrasound-guided) or surgical drainage, which is preferred in trauma and aortic dissection."]},{id:"myo",title:"Myocarditis and endocarditis",core:!0,body:["Myocarditis (viral, toxic, autoimmune, vaccine-associated, giant cell) ranges from chest pain with raised troponin to fulminant cardiogenic shock and arrhythmias in young, previously healthy patients. Fulminant cases may need inotropes and mechanical support; transport early to a centre with ECMO capability.","Infective endocarditis presents with fever, a new or changed murmur, and embolic or immunological phenomena (splinter haemorrhages, Janeway lesions, Osler nodes, Roth spots, stroke, renal and splenic infarcts). Risk factors include injection drug use (often right-sided, tricuspid, with septic pulmonary emboli), prosthetic valves and structural heart disease. Complications include acute valve regurgitation with heart failure, abscess with heart block (new PR prolongation), and septic emboli to the brain. Blood cultures before antibiotics when feasible; urgent surgery for heart failure or uncontrolled infection."]},{id:"valves",title:"Acute valve emergencies",body:["Acute aortic regurgitation (endocarditis, dissection, trauma) causes sudden pulmonary oedema and shock; the LV cannot dilate quickly. Avoid bradycardia (longer diastole means more regurgitation); vasodilators and inotropes bridge to surgery; an IABP is contraindicated because diastolic inflation worsens regurgitation. Acute mitral regurgitation (papillary muscle rupture, chordal rupture, endocarditis) causes flash pulmonary oedema; afterload reduction and an IABP help.","Prosthetic valve thrombosis or failure presents with sudden heart failure, embolism and muffled prosthetic clicks; anticoagulation history matters."],example:{case:"Post-operative cardiac surgery patient 6 hours out: chest drains stopped draining, BP 74/50, CVP rising from 10 to 19, HR 128.",steps:["Sudden cessation of drain output with falling BP and rising CVP: tamponade (clotted drains).","Fluid bolus and vasopressor as a bridge; avoid increasing PEEP.","Urgent re-exploration by the surgical team is definitive; bedside ultrasound confirms if time allows."]}},{id:"case",title:"Transport case: the penetrating chest wound",body:["A 24-year-old stabbed in the left parasternal region: HR 132, BP 70/52, distended neck veins, SpO\u2082 95 %, equal breath sounds. One litre of fluid given with transient improvement."],example:{case:"What is your diagnosis and intervention?",steps:["Narrow pulse pressure, JVD and a precordial wound with equal breath sounds: tamponade rather than tension pneumothorax.","Confirm with ultrasound if immediately available.","Pericardiocentesis is a temporising, life-saving intervention in the deteriorating patient; definitive treatment is surgical (thoracotomy or sternotomy).","Avoid vasopressors as a substitute for drainage; transport to a trauma centre with surgical capability without delay."]}}],keyPoints:["Pericarditis: diffuse concave STE, PR depression, positional pleuritic pain \u2014 NSAIDs and colchicine.","Tamponade: hypotension, JVD, muffled sounds, pulsus paradoxus; RV diastolic collapse on echo.","Tamponade: fluid as a bridge, avoid positive pressure, drain (surgically in trauma/dissection).","Endocarditis: fever + murmur + emboli; new heart block suggests abscess.","Acute AR: avoid bradycardia; IABP contraindicated. Acute MR: afterload reduction and IABP."],pearls:["Fast accumulation of small volumes causes tamponade.","Injection drug use endocarditis is often tricuspid with septic lung emboli."],pitfalls:["Intubating a tamponade patient without drainage ready.","IABP in aortic regurgitation."],live:[{id:"lines-shock-states",label:"Shock states (tamponade)"},{id:"ln-heartlung",label:"Heart\u2013lung interactions (pulsus paradoxus)"}],questions:[{q:"PR depression with diffuse ST elevation suggests:",options:["STEMI","Pericarditis","Hyperkalaemia","Brugada"],answer:1,why:"Classic pericarditis findings."},{q:"Beck's triad consists of:",options:["Fever, murmur, emboli","Hypotension, JVD, muffled heart sounds","Bradycardia, hypertension, irregular breathing","Tachycardia, wheeze, rash"],answer:1,why:"Tamponade triad."},{q:"Pulsus paradoxus is a systolic fall on inspiration of more than:",options:["2 mmHg","10 mmHg","30 mmHg","50 mmHg"],answer:1,why:"Definition."},{q:"Ultrasound sign of tamponade:",options:["LV hypertrophy","RV diastolic collapse","Small IVC","B-lines"],answer:1,why:"High pericardial pressure."},{q:"Definitive management of traumatic tamponade is:",options:["Repeated fluid boluses","Surgical drainage and repair","High-dose vasopressors","Intubation with high PEEP"],answer:1,why:"Pericardiocentesis temporises; surgery repairs the injury."},{q:"Electrical alternans suggests:",options:["Large pericardial effusion","Hyperkalaemia","WPW","RBBB"],answer:0,why:"Swinging heart."},{q:"First-line treatment for viral pericarditis:",options:["Antibiotics","NSAIDs plus colchicine","Thrombolysis","Pericardiectomy"],answer:1,why:"Reduces recurrence."},{q:"New PR prolongation in endocarditis suggests:",options:["Benign","Perivalvular abscess","Hyperkalaemia","Drug effect only"],answer:1,why:"Abscess near the conduction system."},{q:"Injection drug use endocarditis commonly affects:",options:["Mitral valve","Tricuspid valve","Pulmonary only","Aortic only"],answer:1,why:"Right-sided with septic pulmonary emboli."},{q:"IABP is contraindicated in:",options:["Acute MR","Significant aortic regurgitation","Cardiogenic shock","Unstable angina"],answer:1,why:"Diastolic inflation worsens regurgitation."},{q:"In acute aortic regurgitation, avoid:",options:["Tachycardia","Bradycardia","Vasodilators","Inotropes"],answer:1,why:"Longer diastole increases regurgitant volume."},{q:"Fulminant myocarditis in a young patient may require:",options:["Outpatient follow-up","Mechanical circulatory support","Thrombolysis","Pericardiocentesis always"],answer:1,why:"Severe pump failure."},{q:"Janeway lesions and Osler nodes suggest:",options:["Pericarditis","Endocarditis","Myocarditis","MI"],answer:1,why:"Embolic/immunological phenomena."},{q:"Positive-pressure ventilation in tamponade:",options:["Improves filling","Worsens filling and BP","Has no effect","Is treatment"],answer:1,why:"Raises intrathoracic pressure."},{q:"Dressler syndrome occurs:",options:["Hours after MI","Weeks after MI","Before MI","Only in children"],answer:1,why:"Autoimmune pericarditis."}],sources:[{title:"2025 ESC guidelines for myocarditis and pericarditis",url:"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines"},{title:"StatPearls: Cardiac tamponade",url:"https://www.ncbi.nlm.nih.gov/books/?term=Cardiac+tamponade+StatPearls"},{title:"StatPearls: Infective endocarditis",url:"https://www.ncbi.nlm.nih.gov/books/?term=Infective+endocarditis+StatPearls"}]},we={id:"fpc-arrhythmias",domain:"cardiac",ref:"VI.8",title:"Arrhythmias",summary:"Bradycardias and AV blocks, narrow- and wide-complex tachycardias, AF and flutter, and the stable-versus-unstable decision that drives electrical versus pharmacological treatment.",objectives:["Classify and treat bradycardia and AV block, including when to pace.","Differentiate SVT, AF, flutter and VT and choose treatment by stability.","Recognise rhythms where common drugs are dangerous."],sections:[{id:"stable",title:"The first question: stable or unstable?",core:!0,body:["Signs of instability attributable to the rhythm \u2014 hypotension, acutely altered mental status, signs of shock, ischaemic chest pain or acute heart failure \u2014 call for electrical therapy: synchronised cardioversion for tachycardias with a pulse, pacing for bradycardias. Stable patients allow time to identify the rhythm and use drugs. Treat the patient, not the monitor: a heart rate of 150 with a fever is usually sinus tachycardia and needs the cause treated."]},{id:"brady",title:"Bradycardias and AV block",core:!0,body:["First-degree block: PR > 200 ms, every P conducted \u2014 usually benign. Second-degree Mobitz I (Wenckebach): progressively lengthening PR then a dropped beat, usually at the AV node, often vagal or inferior MI, usually benign. Mobitz II: constant PR with sudden dropped beats, usually infranodal with a wide QRS, high risk of complete block \u2014 prepare to pace. Third-degree (complete) block: P waves and QRS complexes unrelated; escape rhythm narrow (junctional, 40\u201360) or wide (ventricular, 20\u201340).","For symptomatic bradycardia: atropine 1 mg IV every 3\u20135 minutes (maximum 3 mg); if ineffective, transcutaneous pacing or an infusion of epinephrine (2\u201310 mcg/min) or dopamine (5\u201320 mcg/kg/min). Atropine is unlikely to work in infranodal block or after heart transplant. Look for causes: hyperkalaemia, beta-blocker or calcium-channel blocker toxicity, digoxin, hypothermia, hypoxia, raised intracranial pressure, and inferior MI."]},{id:"narrow",title:"Narrow-complex tachycardias",core:!0,body:["Regular narrow-complex tachycardia (often AVNRT or AVRT) in a stable patient: vagal manoeuvres (a modified Valsalva \u2014 strain then lie flat with legs raised \u2014 is most effective), then adenosine 6 mg rapid IV push with a flush, then 12 mg. Adenosine briefly blocks the AV node; it terminates re-entry through the node and unmasks flutter waves or atrial tachycardia. Warn the patient of a brief, unpleasant sensation. If unsuccessful, a calcium-channel blocker or beta-blocker; unstable patients get synchronised cardioversion.","Atrial fibrillation (irregularly irregular, no P waves) and flutter (sawtooth waves, often 2:1 at about 150): control rate with diltiazem or a beta-blocker in stable patients with preserved function; use amiodarone or digoxin cautiously in heart failure; cardiovert if unstable. Anticoagulation decisions follow at the destination (AF lasting more than 48 hours carries embolic risk with cardioversion). AF with WPW must not receive AV nodal blockers."]},{id:"wide",title:"Wide-complex tachycardias",core:!0,body:["Assume a regular wide-complex tachycardia is ventricular tachycardia, especially with structural heart disease or prior MI \u2014 misdiagnosis of VT as SVT with aberrancy and treatment with calcium-channel blockers can be fatal. Clues for VT: AV dissociation, capture or fusion beats, very wide QRS, concordance across the precordial leads, and extreme axis.","Stable monomorphic VT: amiodarone 150 mg over 10 minutes or procainamide (avoid in long QT and heart failure), or elective synchronised cardioversion with sedation. Unstable VT with a pulse: synchronised cardioversion. Pulseless VT or VF: defibrillation and ACLS. Polymorphic VT with a long QT (torsades de pointes): magnesium 2 g IV, correct potassium, consider overdrive pacing or isoproterenol, and defibrillate if pulseless."],example:{case:"A 70-year-old with prior MI: regular wide-complex tachycardia at 180, BP 112/74, alert, mild chest discomfort.",steps:["Assume VT (structural heart disease).","Stable: amiodarone 150 mg IV over 10 min; pads on.","If BP falls or mental status changes: synchronised cardioversion (100 J biphasic, escalate).","Avoid diltiazem or verapamil."]}},{id:"case",title:"Transport case: adenosine reveals the answer",body:["A 45-year-old with a regular narrow-complex tachycardia at 150 that does not respond to vagal manoeuvres. After adenosine 6 mg, the rate briefly slows and sawtooth waves appear at 300 per minute before the rate returns to 150."],example:{case:"What is the rhythm and what next?",steps:["Atrial flutter with 2:1 conduction (flutter rate 300, ventricular 150).","Adenosine will not terminate flutter; it only revealed it.","Rate control (diltiazem or beta-blocker) if stable, or synchronised cardioversion (often 50\u2013100 J) if unstable.","Consider anticoagulation implications at the destination."]}}],keyPoints:["Unstable (hypotension, AMS, shock, ischaemia, HF) \u2192 electricity: cardiovert tachycardias, pace bradycardias.","Atropine 1 mg (max 3 mg); infranodal block or transplant hearts need pacing or epinephrine/dopamine.","Mobitz II and wide-escape CHB: pads on, prepare to pace.","Regular narrow: vagal manoeuvres, adenosine 6 then 12 mg; flutter at 150 is often 2:1.","Regular wide = VT until proven otherwise; torsades = magnesium; AF + WPW = no AV nodal blockers."],pearls:["The modified Valsalva (strain then legs up) doubles vagal success.","A rate of exactly 150 should make you look for flutter."],pitfalls:["Calcium-channel blockers for presumed SVT with aberrancy that is actually VT.","Atropine-only strategy in Mobitz II."],questions:[{q:"Atropine dose for symptomatic bradycardia:",options:["0.1 mg","1 mg IV every 3\u20135 min, max 3 mg","5 mg once","0.5 mg max 1 mg only"],answer:1,why:"Current ACLS dosing."},{q:"Progressive PR lengthening then a dropped beat:",options:["Mobitz II","Mobitz I (Wenckebach)","Third-degree","First-degree"],answer:1,why:"Classic Wenckebach."},{q:"Mobitz II carries high risk of:",options:["AF","Complete heart block","Pericarditis","Torsades"],answer:1,why:"Infranodal disease."},{q:"First drug for stable regular narrow-complex tachycardia after vagal manoeuvres:",options:["Amiodarone","Adenosine 6 mg rapid push","Digoxin","Lidocaine"],answer:1,why:"Terminates AV nodal re-entry."},{q:"A regular wide-complex tachycardia in a patient with prior MI should be treated as:",options:["SVT with aberrancy","VT","Sinus tachycardia","AF"],answer:1,why:"VT until proven otherwise."},{q:"Torsades de pointes first-line treatment:",options:["Amiodarone","Magnesium sulfate 2 g","Procainamide","Adenosine"],answer:1,why:"Stabilises repolarisation."},{q:"Ventricular rate of 150 with sawtooth waves suggests:",options:["AF","Atrial flutter with 2:1 block","VT","Sinus"],answer:1,why:"Flutter at 300 with 2:1."},{q:"Unstable tachycardia with a pulse requires:",options:["Adenosine","Synchronised cardioversion","Unsynchronised shock","Observation"],answer:1,why:"Electrical therapy."},{q:"An irregular wide-complex tachycardia at 240 with varying QRS morphology:",options:["Give diltiazem","Suspect AF with WPW \u2014 avoid AV nodal blockers","Give adenosine","Give digoxin"],answer:1,why:"Risk of VF."},{q:"Junctional escape rate:",options:["20\u201340","40\u201360","60\u2013100","100\u2013150"],answer:1,why:"AV junction intrinsic rate."},{q:"Atropine is ineffective in:",options:["Vagal bradycardia","Heart transplant recipients","Sinus bradycardia","Inferior MI nodal block"],answer:1,why:"Denervated heart."},{q:"Clue favouring VT over SVT with aberrancy:",options:["Response to vagal manoeuvres","AV dissociation or fusion beats","Young age","Narrow QRS"],answer:1,why:"Specific for VT."},{q:"Epinephrine infusion dose for bradycardia:",options:["2\u201310 mcg/min","1 mg bolus","50 mcg/kg/min","0.01 mcg/min"],answer:0,why:"Chronotropic support."},{q:"Rate control for AF in severe HFrEF should avoid:",options:["Amiodarone","Diltiazem","Digoxin","Cardioversion if unstable"],answer:1,why:"Negative inotropy."},{q:"Adenosine in atrial flutter typically:",options:["Terminates it","Transiently slows AV conduction, revealing flutter waves","Causes VF always","Has no effect"],answer:1,why:"Diagnostic, not curative."}],sources:[{title:"AHA guidelines for CPR and ECC: adult bradycardia and tachycardia algorithms",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{title:"Appelboam A et al. REVERT trial: modified Valsalva for SVT. Lancet (2015)",url:"https://pubmed.ncbi.nlm.nih.gov/26314489/"}]};var ve={id:"fpc-htn-crisis",domain:"cardiac",ref:"VI.9",title:"Hypertensive emergencies",summary:"Separating hypertensive emergency from urgency, organ-specific blood pressure targets, the drugs that lower pressure smoothly, and the conditions where the rules change.",objectives:["Distinguish hypertensive emergency (end-organ damage) from severe hypertension without it.","Apply organ-specific targets and rates of reduction.","Choose titratable IV agents and avoid harmful ones."],sections:[{id:"define",title:"Emergency or urgency?",core:!0,body:["Severe hypertension (often above 180/120) becomes a hypertensive emergency when it causes acute end-organ injury: hypertensive encephalopathy, stroke (ischaemic or haemorrhagic), acute coronary syndrome, acute pulmonary oedema, aortic dissection, acute kidney injury, pre-eclampsia or eclampsia, or retinal haemorrhage and papilloedema. Without organ injury, the pressure is lowered gradually over hours to days with oral agents.","Chronic hypertension shifts cerebral autoregulation to higher pressures; dropping the pressure too fast causes cerebral, coronary or renal ischaemia. The general rule for most emergencies is to lower MAP by no more than about 20\u201325 % in the first hour, then toward 160/100 over the next 2\u20136 hours, then to normal over 24\u201348 hours."]},{id:"targets",title:"Exceptions with their own targets",core:!0,body:["Aortic dissection: rapid control \u2014 heart rate around 60 and systolic below about 120 within 20 minutes or so \u2014 with a beta-blocker first (esmolol or labetalol), then a vasodilator if needed. Pre-eclampsia/eclampsia with severe range pressures (\u2265 160 systolic or \u2265 110 diastolic): treat within 30\u201360 minutes with IV labetalol or hydralazine or oral nifedipine, plus magnesium for seizure prophylaxis. Acute ischaemic stroke: lower only if above 185/110 before thrombolysis (and keep below 180/105 afterwards), or above 220/120 if no reperfusion therapy. Intracerebral haemorrhage: smooth lowering of systolic to about 140 is commonly targeted. Sympathetic crashing pulmonary oedema: high-dose nitrates and NIV."],table:{caption:"Targets by condition (common guidance)",head:["Condition","Target","Preferred agents"],rows:[["Most emergencies","MAP \u2193 \u2264 25 % in 1 h","Nicardipine, clevidipine, labetalol"],["Aortic dissection","HR ~60, SBP < 120 quickly","Esmolol/labetalol, then nicardipine"],["Pre-eclampsia","Treat \u2265 160/110 within 30\u201360 min","Labetalol, hydralazine, nifedipine + Mg"],["Ischaemic stroke + lysis","< 185/110 before, < 180/105 after","Labetalol, nicardipine"],["ICH","SBP \u2248 140, smoothly","Nicardipine, labetalol"],["Acute pulmonary oedema","Relieve congestion","Nitroglycerin, NIV"]]}},{id:"drugs",title:"Drug choices",core:!0,body:["Use short-acting, titratable IV drugs on a pump with an arterial line when possible. Nicardipine and clevidipine (calcium-channel blockers) are arterial vasodilators with little effect on heart rate or contractility; clevidipine is ultra-short-acting and lipid-based. Labetalol combines alpha- and beta-blockade; avoid in bradycardia, heart block, decompensated heart failure and asthma. Esmolol is a short-acting beta-1 blocker. Nitroglycerin is mainly a venodilator \u2014 ideal for pulmonary oedema and ACS. Nitroprusside is potent but risks cyanide toxicity and rebound and is used less often.","Avoid immediate-release sublingual nifedipine (unpredictable, precipitous drops, except oral nifedipine in pregnancy protocols) and avoid pure vasodilators without beta-blockade in dissection. In cocaine or amphetamine toxicity, benzodiazepines come first."]},{id:"case",title:"Transport case: the confused hypertensive patient",body:["A 52-year-old with untreated hypertension: BP 238/142, headache, vomiting, confusion, papilloedema; CT shows no haemorrhage."],example:{case:"How fast and with what?",steps:["Hypertensive encephalopathy: an emergency.","MAP \u2248 174; reduce by no more than about 25 % in the first hour (to MAP \u2248 130).","Nicardipine infusion (e.g. 5 mg/h, titrating by 2.5 mg/h every 5\u201315 min) or labetalol per protocol, with frequent or arterial BP monitoring.","Avoid overshoot; reassess neurology; destination with ICU and neuro capability."]}}],keyPoints:["Emergency = severe hypertension + acute end-organ damage.","Most emergencies: MAP \u2193 \u2264 25 % in the first hour.","Dissection: beta-blocker first, HR ~60 and SBP < 120 quickly.","Pre-eclampsia \u2265 160/110: labetalol, hydralazine or nifedipine within 30\u201360 min, plus magnesium.","Stroke: < 185/110 before lysis; ICH: SBP \u2248 140 smoothly."],pearls:["Clevidipine has a minute-long half-life.","Nitroglycerin is the agent for pulmonary oedema and ACS."],pitfalls:["Normalising BP in an hour in chronic hypertension.","Vasodilator without beta-blockade in dissection."],questions:[{q:"Hypertensive emergency requires:",options:["BP > 160/100","Acute end-organ damage","Headache only","Age > 60"],answer:1,why:"Organ injury defines emergency."},{q:"Initial MAP reduction in most hypertensive emergencies:",options:["50 % in 10 min","\u2264 25 % in the first hour","To normal immediately","None for 24 h"],answer:1,why:"Avoid hypoperfusion."},{q:"Aortic dissection first agent:",options:["Nitroprusside alone","Esmolol or labetalol","Hydralazine","Nifedipine"],answer:1,why:"Reduce shear (dP/dt)."},{q:"BP before thrombolysis for ischaemic stroke should be below:",options:["220/120","185/110","140/90","120/80"],answer:1,why:"Bleeding risk."},{q:"Severe-range BP in pre-eclampsia:",options:["\u2265 140/90","\u2265 160/110","\u2265 200/120","\u2265 120/80"],answer:1,why:"Treat within 30\u201360 min."},{q:"Labetalol should be avoided in:",options:["Pre-eclampsia","Asthma and heart block","Stroke","Dissection"],answer:1,why:"\u03B2-blockade risks."},{q:"Nicardipine is primarily:",options:["Venodilator","Arterial vasodilator (CCB)","\u03B2-blocker","\u03B1-agonist"],answer:1,why:"Dihydropyridine CCB."},{q:"Nitroglycerin primarily dilates:",options:["Arterioles","Veins (preload reduction)","Coronary only","Renal arteries"],answer:1,why:"Venodilation at lower doses."},{q:"A risk of prolonged nitroprusside use:",options:["Hyperkalaemia","Cyanide toxicity","Bronchospasm","Hypoglycaemia"],answer:1,why:"Metabolism releases cyanide."},{q:"ICH systolic target commonly:",options:["~180","~140","~100","~90"],answer:1,why:"Limits haematoma growth."},{q:"Cocaine-induced hypertension first-line:",options:["Beta-blocker","Benzodiazepine","Hydralazine","Diuretic"],answer:1,why:"Treat sympathetic excess."},{q:"Why avoid rapid normalisation in chronic hypertension?",options:["Causes bleeding","Autoregulation shifted \u2014 ischaemia","Causes tachycardia","No reason"],answer:1,why:"Organs adapted to higher pressure."},{q:"Clevidipine is notable for:",options:["Long half-life","Ultra-short half-life","Oral use","\u03B2-blockade"],answer:1,why:"Its half-life is about one minute, allowing fine titration."},{q:"Hypertensive encephalopathy signs include:",options:["Papilloedema, confusion, headache","Wheeze","Bradycardia only","Rash"],answer:0,why:"Cerebral oedema from loss of autoregulation."},{q:"Pre-eclampsia seizure prophylaxis:",options:["Phenytoin","Magnesium sulfate","Diazepam infusion","Levetiracetam"],answer:1,why:"Standard of care."}],sources:[{title:"2017 ACC/AHA high blood pressure guideline: hypertensive crises",url:"https://www.ahajournals.org/doi/10.1161/HYP.0000000000000065"},{title:"ACOG: emergent therapy for acute-onset severe hypertension in pregnancy",url:"https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2020/02/clinical-guidance-for-the-integration-of-the-findings-of-the-chronic-hypertension-and-pregnancy-chap-study"}]},ke={id:"fpc-hemo-instab",domain:"cardiac",ref:"VI.10",title:"Haemodynamic instability: a framework for shock",summary:"Using the haemodynamic equation to find the broken variable, fluid responsiveness, choosing between fluids, blood, vasopressors and inotropes, and avoiding over-resuscitation.",objectives:["Use MAP = CO \xD7 SVR and CO = HR \xD7 SV to locate the failing component.","Assess fluid responsiveness and tolerance before giving volume.","Match the intervention to the problem and monitor its effect."],sections:[{id:"framework",title:"Find the broken variable",core:!0,body:["Blood pressure is the product of cardiac output and systemic vascular resistance; cardiac output is heart rate times stroke volume; stroke volume depends on preload, contractility and afterload. Every hypotensive patient has a problem in one or more of these: rate (too slow, too fast), preload (the tank), contractility (the pump), afterload or vascular tone (the pipes), or obstruction to flow.","Bedside clues: cold, clammy and narrow pulse pressure suggest low output (hypovolaemic, cardiogenic, obstructive); warm, bounding and wide pulse pressure with low diastolic pressure suggest low SVR (distributive). Neck veins and ultrasound separate empty from full. Rhythm strips identify rate problems quickly."]},{id:"fluid",title:"Fluid responsiveness and tolerance",core:!0,body:['Only about half of haemodynamically unstable patients increase stroke volume with fluid. A patient is fluid-responsive if stroke volume (or a surrogate such as pulse pressure or velocity\u2013time integral on echo) rises by about 10\u201315 % after a fluid challenge or a passive leg raise. The passive leg raise is a reversible "self-bolus" of about 300 mL; measure the response within about a minute.',"Pulse-pressure variation above about 12\u201313 % predicts responsiveness only in sedated patients on controlled ventilation with tidal volumes of at least 8 mL/kg, regular rhythm and a closed chest. Static measures such as CVP alone predict poorly. Fluid tolerance matters as much: worsening oxygenation, B-lines and a plethoric IVC say stop."]},{id:"interventions",title:"Matching the intervention",core:!0,body:["Hypovolaemia from bleeding: stop the bleeding and give blood products. Dehydration: crystalloid in boluses with reassessment. Distributive shock: fluid until no longer responsive, then norepinephrine (and vasopressin, steroids in sepsis; adrenaline in anaphylaxis). Cardiogenic shock: inotropes with vasopressor support and treatment of the cause. Obstructive shock: relieve the obstruction \u2014 decompress, drain, thrombolyse. Rate problems: pace or treat the arrhythmia.","Reassess after every intervention using perfusion markers, not just pressure. Over-resuscitation \u2014 fluid overload, excessive vasopressor doses \u2014 has its own harms: pulmonary oedema, bowel and limb ischaemia, arrhythmias."],example:{case:"A ventilated trauma patient: BP 86/50, HR 122, PPV 18 %, Hb 8.2, FAST positive.",steps:["Low output picture with high PPV on controlled ventilation: preload-responsive.","Positive FAST: haemorrhage \u2014 the right fluid is blood.","Transfuse, give TXA if within 3 h, keep warm, give calcium.","Surgical haemorrhage control is definitive; avoid vasopressors as a substitute."]}},{id:"case",title:"Transport case: falling pressure at altitude",body:["Fifteen minutes into a flight, a septic patient on norepinephrine 0.12 mcg/kg/min drops from MAP 70 to MAP 54. HR 118, SpO\u2082 95 %, EtCO\u2082 falls from 34 to 26."],example:{case:"Work through the variables.",steps:["Check equipment first: is the norepinephrine running (line kinked, bag empty, pump alarm, line disconnected)?","Falling EtCO\u2082 at constant ventilation suggests falling cardiac output.","Assess preload: passive leg raise or small bolus; consider increasing norepinephrine and adding vasopressin.","Exclude new arrhythmia, tension pneumothorax and auto-PEEP if ventilated."]}}],keyPoints:["MAP = CO \xD7 SVR; CO = HR \xD7 SV; SV = preload, contractility, afterload.","Cold and narrow pulse pressure = low output; warm and wide = low SVR.","Only about half of unstable patients are fluid-responsive: test with a passive leg raise.","PPV works only on controlled ventilation, VT \u2265 8 mL/kg, regular rhythm.","Match the treatment to the failed variable; reassess perfusion after every intervention."],pearls:["Always check the pump and line before escalating a vasopressor.","A passive leg raise is a reversible fluid test."],pitfalls:["Giving fluid by reflex to a non-responder.","Using vasopressors to hide haemorrhage."],live:[{id:"lines-shock-states",label:"Shock states at the bedside"},{id:"ln-heartlung",label:"Heart\u2013lung interactions"}],questions:[{q:"MAP is determined by:",options:["HR \xD7 SVR","CO \xD7 SVR","SV \xD7 PVR","CVP \xD7 HR"],answer:1,why:"Haemodynamic equation."},{q:"A wide pulse pressure with low diastolic suggests:",options:["Cardiogenic shock","Low SVR (distributive)","Tamponade","Hypovolaemia"],answer:1,why:"Vasodilation."},{q:"Fluid responsiveness means stroke volume rises by about:",options:["1 %","10\u201315 %","50 %","100 %"],answer:1,why:"Common threshold."},{q:"A passive leg raise delivers roughly:",options:["50 mL","300 mL","1 L","2 L"],answer:1,why:"Autotransfusion."},{q:"PPV is valid only with:",options:["Spontaneous breathing","Controlled ventilation, VT \u2265 8 mL/kg, regular rhythm","AF","Open chest"],answer:1,why:"Validation conditions."},{q:"A poor predictor of fluid responsiveness used alone:",options:["Passive leg raise","Static CVP","Echo VTI change","PPV in valid conditions"],answer:1,why:"Static values predict poorly."},{q:"Signs of fluid intolerance:",options:["Improving SpO\u2082","Worsening oxygenation and new B-lines","Falling HR","Rising urine output"],answer:1,why:"Lungs are filling."},{q:"Best fluid for haemorrhagic shock:",options:["Saline","Blood products","Dextrose","Albumin only"],answer:1,why:"Replace what is lost."},{q:"Treatment of obstructive shock:",options:["Inotropes","Relieve the obstruction","Vasopressors alone","Diuretics"],answer:1,why:"Decompress, drain, thrombolyse."},{q:"Before escalating a vasopressor during a sudden drop, first check:",options:["Labs","The infusion line and pump","Temperature","Glucose"],answer:1,why:"Equipment failures are common."},{q:"Falling EtCO\u2082 at constant ventilation suggests:",options:["Rising metabolism","Falling cardiac output","Hypoventilation","Rebreathing"],answer:1,why:"Less CO\u2082 delivered to lungs."},{q:"Cold, clammy skin with narrow pulse pressure suggests:",options:["Distributive shock","Low output state","Hyperthermia","Normal"],answer:1,why:"Vasoconstriction compensating."},{q:"Proportion of unstable patients who are fluid-responsive:",options:["~10 %","~50 %","~90 %","100 %"],answer:1,why:"About half."},{q:"Stroke volume determinants:",options:["Rate, rhythm, temperature","Preload, contractility, afterload","Hb, SaO\u2082, PaO\u2082","CVP, PVR, HR"],answer:1,why:"Classic triad."},{q:"Over-resuscitation with fluid can cause:",options:["Improved oxygenation","Pulmonary oedema and abdominal compartment syndrome","Lower CVP","Bradycardia"],answer:1,why:"Harms of excess fluid."}],sources:[{title:"Monnet X, Teboul JL. Passive leg raising: five rules. Crit Care (2015)",url:"https://ccforum.biomedcentral.com/articles/10.1186/s13054-014-0708-5"},{title:"StatPearls: Shock",url:"https://www.ncbi.nlm.nih.gov/books/?term=Shock+StatPearls"}]},Ae={id:"fpc-chronic-cardiac",domain:"cardiac",ref:"VI.11",title:"Chronic cardiac conditions in the acute patient",summary:"Transporting patients with cardiomyopathies, congenital heart disease in adults, pulmonary hypertension, heart transplants and chronic valve disease \u2014 the physiology that changes acute management.",objectives:["Adapt resuscitation to hypertrophic, dilated and restrictive cardiomyopathy.","Recognise the special risks of pulmonary hypertension and adult congenital heart disease.","Manage heart transplant recipients' unique physiology."],sections:[{id:"cm",title:"Cardiomyopathies",core:!0,body:["Hypertrophic cardiomyopathy (HCM) is a genetic disorder with a thick, stiff ventricle and, in many, dynamic left ventricular outflow obstruction from systolic anterior motion of the mitral valve. It causes exertional syncope and sudden death in the young. Obstruction worsens with low preload, low afterload and high contractility or heart rate: avoid dehydration, vasodilators (nitrates) and inotropes; give fluids, use phenylephrine for hypotension, and beta-blockers to slow the heart. Atrial fibrillation is poorly tolerated.","Dilated cardiomyopathy causes systolic heart failure, arrhythmias and thromboembolism; manage as HFrEF. Restrictive cardiomyopathy (amyloidosis and others) has stiff ventricles, small stroke volumes and dependence on preload and heart rate \u2014 hypotension follows aggressive diuresis or vasodilation."]},{id:"ph",title:"Pulmonary hypertension",core:!0,body:["In pulmonary arterial hypertension the right ventricle works against high resistance and may be at the edge of failure. Decompensation follows infection, arrhythmia, missed medications, pregnancy and anaesthesia. Avoid hypoxia, hypercapnia, acidosis and hypothermia (all raise pulmonary vascular resistance), maintain systemic pressure (norepinephrine, vasopressin), avoid excessive fluid, and support the RV with dobutamine or milrinone.","Never interrupt continuous pulmonary vasodilator infusions (epoprostenol, treprostinil) \u2014 rebound pulmonary hypertension can be fatal within minutes. These run through dedicated lines and pumps; bring backup supplies and do not flush or use the line for anything else. Intubation is extremely high-risk."]},{id:"chd",title:"Adult congenital heart disease",body:["Adults with repaired or palliated congenital heart disease are increasingly common. Fontan patients (single-ventricle circulation, passive venous flow to the lungs) depend on low intrathoracic pressure and adequate preload; positive pressure and dehydration drop output. Eisenmenger patients have reversed shunts and fixed pulmonary hypertension; avoid systemic vasodilation (it increases right-to-left shunting) and air in IV lines (paradoxical embolism). Use air filters on IV lines in any patient with a right-to-left shunt. Contact the specialist centre early."]},{id:"transplant",title:"Heart transplant recipients",core:!0,body:["The transplanted heart is denervated: resting heart rate is higher (often 90\u2013110), it responds to exercise and stress slowly via circulating catecholamines, and drugs acting through the vagus (atropine) have no effect. Use direct-acting agents for bradycardia (epinephrine, isoproterenol) or pacing. Adenosine has an exaggerated effect; use a reduced dose or avoid. Ischaemia may be painless. Patients are immunosuppressed: infection risk is high, and rejection can present as heart failure or arrhythmia."],example:{case:"A transplant recipient with symptomatic bradycardia at 38, BP 78/40.",steps:["Atropine will not work (no vagal innervation).","Epinephrine infusion or transcutaneous pacing.","Consider rejection or drug effects; contact the transplant centre."]}},{id:"case",title:"Transport case: the hypotensive HCM patient",body:["A 24-year-old with known HCM collapses at a tournament; now alert but BP 82/50, HR 128, systolic murmur louder on standing. The referring team is about to give nitroglycerin for chest pain."],example:{case:"What do you change?",steps:["Stop the nitroglycerin: vasodilation worsens outflow obstruction.","Give fluid to improve preload; lie flat with legs raised.","Phenylephrine for hypotension (raises afterload without inotropy); a beta-blocker to slow the rate if tolerated.","Avoid inotropes; pads on for arrhythmia; destination with cardiology."]}}],keyPoints:["HCM: give volume, phenylephrine, beta-blockers; avoid nitrates, inotropes, dehydration.","Pulmonary hypertension: avoid hypoxia, hypercapnia, acidosis; support SVR and the RV.","Never interrupt epoprostenol or treprostinil infusions.","Right-to-left shunts: air filters on IV lines; avoid systemic vasodilation.","Transplanted hearts: no response to atropine; use epinephrine or pacing."],pearls:["HCM murmur increases with standing or Valsalva.","Fontan circulation depends on low intrathoracic pressure."],pitfalls:["Nitrates for chest pain in HCM.","Flushing a prostacyclin line."],questions:[{q:"In HCM with outflow obstruction, avoid:",options:["Fluids","Nitrates and inotropes","Phenylephrine","Beta-blockers"],answer:1,why:"Worsen obstruction."},{q:"Vasopressor of choice for hypotension in HCM:",options:["Dobutamine","Phenylephrine","Epinephrine","Milrinone"],answer:1,why:"Pure afterload increase."},{q:"HCM murmur increases with:",options:["Squatting","Standing or Valsalva","Leg raise","Handgrip"],answer:1,why:"Lower preload worsens obstruction."},{q:"Interrupting an epoprostenol infusion risks:",options:["Hypertension","Fatal rebound pulmonary hypertension","Bradycardia","Hypoglycaemia"],answer:1,why:"Very short half-life."},{q:"Which raises pulmonary vascular resistance?",options:["Oxygen","Hypercapnia and acidosis","Alkalosis","Normothermia"],answer:1,why:"Pulmonary vasoconstriction."},{q:"Heart transplant bradycardia does NOT respond to:",options:["Epinephrine","Isoproterenol","Atropine","Pacing"],answer:2,why:"Denervated heart."},{q:"Adenosine in transplant recipients has:",options:["No effect","An exaggerated effect","Reduced effect","Same effect"],answer:1,why:"Denervation hypersensitivity."},{q:"Resting heart rate after heart transplant is typically:",options:["40\u201350","90\u2013110","150","60"],answer:1,why:"Loss of vagal tone."},{q:"IV air filters are important with:",options:["Left-to-right shunts only","Right-to-left shunts","Normal hearts","HCM"],answer:1,why:"Paradoxical air embolism."},{q:"A Fontan circulation depends on:",options:["High intrathoracic pressure","Low intrathoracic pressure and adequate preload","A strong RV","High PVR"],answer:1,why:"Passive pulmonary blood flow."},{q:"Restrictive cardiomyopathy patients are sensitive to:",options:["Volume loading only","Aggressive diuresis and vasodilation","Oxygen","Bradycardia benefit"],answer:1,why:"Preload-dependent."},{q:"Systemic vasodilation in Eisenmenger syndrome:",options:["Reduces cyanosis","Increases right-to-left shunting","Has no effect","Treats PH"],answer:1,why:"Lower SVR favours R\u2192L flow."},{q:"Ischaemia in transplant recipients may be:",options:["Always painful","Painless","Impossible","Only arrhythmic"],answer:1,why:"Denervation."},{q:"Pulmonary hypertension decompensation support:",options:["Large fluid boluses","Maintain SVR and support RV contractility","Hypoventilation","Nitrates"],answer:1,why:"Protect RV perfusion."},{q:"AF in HCM is:",options:["Well tolerated","Poorly tolerated","Protective","Irrelevant"],answer:1,why:"Loss of atrial kick in a stiff ventricle."}],sources:[{title:"2024 AHA/ACC guideline for hypertrophic cardiomyopathy",url:"https://www.ahajournals.org/doi/10.1161/CIR.0000000000001250"},{title:"StatPearls: Pulmonary hypertension",url:"https://www.ncbi.nlm.nih.gov/books/?term=Pulmonary+hypertension+StatPearls"}]};var Pe={id:"fpc-vascular",domain:"cardiac",ref:"VI.12",title:"Vascular emergencies: aortic dissection, AAA and limb ischaemia",summary:"Recognising thoracic aortic dissection and ruptured abdominal aortic aneurysm, impulse control, permissive hypotension, destination decisions, and acute limb ischaemia.",objectives:["Recognise and classify aortic dissection and start impulse control.","Manage ruptured AAA with permissive hypotension and rapid transfer.","Identify acute limb ischaemia and its time-critical treatment."],sections:[{id:"dissection",title:"Aortic dissection",core:!0,body:["A tear in the intima lets blood split the aortic wall, creating a true and a false lumen. Classic features are sudden, severe, tearing or ripping chest or back pain at maximal intensity from onset, a pulse or blood pressure difference between the arms (more than 20 mmHg), a new diastolic murmur of aortic regurgitation, and neurological deficits. Risk factors: hypertension, connective tissue disease (Marfan, Ehlers\u2013Danlos), bicuspid aortic valve, cocaine, pregnancy and recent aortic procedures.","Stanford type A involves the ascending aorta and is a surgical emergency (complications: tamponade, acute aortic regurgitation, coronary occlusion, stroke). Type B involves only the descending aorta and is usually managed medically unless complicated by malperfusion, rupture or refractory pain.","Impulse control comes first: lower heart rate to about 60 with a short-acting beta-blocker (esmolol or labetalol), then lower systolic pressure below about 120 with a vasodilator (nicardipine, clevidipine) as tolerated by perfusion. A vasodilator alone causes reflex tachycardia and more shear. Analgesia reduces sympathetic drive. Avoid anticoagulants and fibrinolytics \u2014 a dissection can mimic STEMI (especially inferior STEMI from RCA involvement)."]},{id:"aaa",title:"Ruptured abdominal aortic aneurysm",core:!0,body:["An AAA is a permanent dilation of the abdominal aorta to 3 cm or more; rupture risk rises with diameter (above 5.5 cm usually warrants repair). Rupture presents with abdominal, back or flank pain, a pulsatile mass (often hard to feel), hypotension and syncope \u2014 commonly misdiagnosed as renal colic in older patients. Most ruptures are retroperitoneal and temporarily contained; free intraperitoneal rupture is usually fatal.","Bedside ultrasound showing an aorta over 3 cm in a hypotensive older patient with pain is strongly suggestive. Use permissive hypotension \u2014 target a systolic around 70\u201390 mmHg or the lowest pressure that maintains mentation \u2014 to avoid disrupting the contained haematoma, give blood products rather than crystalloid, and transport immediately to a vascular centre capable of open or endovascular repair."]},{id:"limb",title:"Acute limb ischaemia",core:!0,body:['Sudden loss of limb perfusion from embolism (often atrial fibrillation) or thrombosis presents with the "six Ps": pain, pallor, pulselessness, paraesthesia, paralysis and poikilothermia (cold). Sensory loss and paralysis indicate threatened limb viability; revascularisation within about 6 hours preserves the most tissue.',"Start anticoagulation with unfractionated heparin per protocol (unless contraindicated), keep the limb dependent and protected, give analgesia, and transfer to a vascular centre. After reperfusion, watch for compartment syndrome and reperfusion hyperkalaemia and myoglobinuria."],table:{caption:"Dissection versus ruptured AAA",head:["Feature","Thoracic dissection","Ruptured AAA"],rows:[["Pain","Tearing chest/back, abrupt","Abdominal/back/flank"],["BP","Often hypertensive (type B); may be hypotensive","Hypotensive, syncope"],["Key exam","Arm BP difference, AR murmur, deficits","Pulsatile mass, aorta > 3 cm on US"],["Treatment","\u03B2-blocker then vasodilator; surgery for type A","Permissive hypotension, blood, repair"]]}},{id:"case",title:'Transport case: the "renal colic"',body:["A 72-year-old male smoker with sudden left flank pain and a syncopal episode: BP 88/52, HR 104 (on a beta-blocker), pale. Bedside ultrasound shows a 6.4 cm infrarenal aorta."],example:{case:"Manage and route.",steps:["Ruptured AAA until proven otherwise.","Two large-bore lines; blood products; permissive hypotension (SBP ~70\u201390 if mentating).","Avoid large crystalloid volumes and aggressive vasopressors.","Direct transport to a vascular centre with pre-alert; minimise scene and handover time."]}}],keyPoints:["Dissection: abrupt tearing pain, arm BP difference, AR murmur, deficits.","Type A (ascending) = surgery; type B = medical unless complicated.","Impulse control: \u03B2-blocker to HR ~60 first, then vasodilator to SBP < 120.","Ruptured AAA: permissive hypotension, blood, rapid transfer to vascular surgery.","Acute limb ischaemia: six Ps; heparin and revascularisation within ~6 hours."],pearls:["A dissection can mimic inferior STEMI \u2014 never lyse without considering it.",'Older patients with "renal colic" and hypotension need an aortic scan.'],pitfalls:["Vasodilator without beta-blockade in dissection.","Aggressive crystalloid in ruptured AAA."],live:[{id:"abd-dissection",label:"Aortic dissection: type, extent, malperfusion"},{id:"abd-aaa",label:"Abdominal aortic aneurysm"}],questions:[{q:"Classic dissection pain is:",options:["Gradual, pressure-like","Sudden, tearing, maximal at onset","Pleuritic only","Positional"],answer:1,why:"Abrupt onset is typical."},{q:"Stanford type A dissection involves:",options:["Descending aorta only","Ascending aorta","Abdominal aorta only","Iliac arteries"],answer:1,why:"Surgical emergency."},{q:"First drug in dissection:",options:["Nicardipine","Esmolol","Hydralazine","Nitroprusside alone"],answer:1,why:"Rate control before vasodilation."},{q:"Target heart rate in dissection:",options:["~60","~90","~120","No target"],answer:0,why:"Reduce shear stress."},{q:"An arm BP difference of more than ___ mmHg suggests dissection:",options:["5","20","60","100"],answer:1,why:"Significant inter-arm difference."},{q:"Type A dissection complication causing hypotension:",options:["Hyperkalaemia","Tamponade","Pneumothorax","Hyperglycaemia"],answer:1,why:"Rupture into the pericardium."},{q:"AAA is defined as an aortic diameter of at least:",options:["1.5 cm","3 cm","6 cm","10 cm"],answer:1,why:"Aneurysmal dilation."},{q:"Ruptured AAA resuscitation target:",options:["SBP > 140","Permissive hypotension (SBP ~70\u201390 if mentating)","MAP 100","No fluids at all"],answer:1,why:"Avoid disrupting the contained haematoma."},{q:"A common misdiagnosis of ruptured AAA:",options:["Pneumonia","Renal colic","Migraine","Gout"],answer:1,why:"Flank pain in older patients."},{q:"Six Ps of acute limb ischaemia include all EXCEPT:",options:["Pallor","Pulselessness","Paralysis","Pyrexia"],answer:3,why:"Poikilothermia, not pyrexia."},{q:"Initial drug for acute limb ischaemia without contraindications:",options:["Aspirin only","Unfractionated heparin","Vasopressor","Steroids"],answer:1,why:"Prevent propagation."},{q:"Why avoid fibrinolytics until dissection is excluded?",options:["They cause bradycardia","Catastrophic bleeding risk","They raise BP","No reason"],answer:1,why:"Dissection can mimic STEMI."},{q:"Type B dissection is managed surgically/endovascularly when:",options:["Always","Complicated (malperfusion, rupture, refractory pain)","Never","BP is normal"],answer:1,why:"Uncomplicated type B is medical."},{q:"After limb revascularisation, watch for:",options:["Hypokalaemia","Compartment syndrome and hyperkalaemia","Hypertension only","Hypoglycaemia"],answer:1,why:"Reperfusion injury."},{q:"Connective tissue disease linked to dissection:",options:["Lupus only","Marfan syndrome","Psoriasis","Gout"],answer:1,why:"Weak aortic wall."}],sources:[{title:"2022 ACC/AHA guideline for diagnosis and management of aortic disease",url:"https://www.ahajournals.org/doi/10.1161/CIR.0000000000001106"},{title:"StatPearls: Aortic dissection",url:"https://www.ncbi.nlm.nih.gov/books/?term=Aortic+dissection+StatPearls"}]},xe={id:"fpc-cardiac-dx",domain:"cardiac",ref:"VI.14",title:"Cardiac diagnostics: point-of-care echo and ultrasound",summary:"Focused cardiac ultrasound views, what each answers \u2014 effusion, LV function, RV strain, volume status \u2014 and integrating ultrasound with the ECG and labs.",objectives:["Obtain and interpret the four basic cardiac views.","Identify effusion and tamponade, LV dysfunction, RV strain and volume status.","Use ultrasound during cardiac arrest without interrupting compressions."],sections:[{id:"views",title:"Four views",core:!0,body:['Subxiphoid (subcostal): probe under the xiphoid aiming toward the left shoulder; the best view for pericardial effusion and the one used during CPR. Parasternal long axis: left of the sternum at the third or fourth intercostal space, marker toward the right shoulder; shows the LV, mitral and aortic valves, and helps distinguish pericardial from pleural fluid (pericardial fluid tracks anterior to the descending aorta). Parasternal short axis: rotate 90\xB0 for a cross-section of the LV ("doughnut") and RV \u2014 good for septal shape. Apical four-chamber: at the point of maximal impulse; compares RV and LV size.',"Add the IVC (subcostal long axis) for filling assessment, and lung views for B-lines, effusions and pneumothorax."]},{id:"findings",title:"What to look for",core:!0,body:["Pericardial effusion appears as an anechoic (black) stripe around the heart. Tamponade adds right atrial systolic collapse and right ventricular diastolic collapse with a plethoric IVC. LV function is graded visually \u2014 hyperdynamic, normal, reduced or severely reduced \u2014 by wall thickening and endocardial movement; mitral valve leaflet movement close to the septum (E-point septal separation under about 7 mm) suggests normal function.",'Acute RV strain (massive PE): an RV as large as or larger than the LV in the apical view, septal flattening ("D sign") in the short axis, and sometimes McConnell sign (RV free-wall hypokinesis with apical sparing). A small, collapsing IVC suggests low filling pressure in a spontaneously breathing patient; a plethoric IVC suggests high right-sided pressure \u2014 but neither is decisive alone.'],table:{caption:"Ultrasound patterns in shock",head:["Pattern","Heart","IVC","Think"],rows:[["Hypovolaemic","Small, hyperdynamic","Small, collapsing","Bleeding, dehydration"],["Distributive","Hyperdynamic","Small or normal","Sepsis, anaphylaxis"],["Cardiogenic","Poor LV function","Plethoric","MI, cardiomyopathy"],["Obstructive (tamponade)","Effusion, RV collapse","Plethoric","Drain"],["Obstructive (PE)","Dilated RV, D sign","Plethoric","Thrombolysis/embolectomy"]]}},{id:"arrest",title:"Ultrasound in cardiac arrest",core:!0,body:['Use the subxiphoid view during the rhythm check and limit it to 10 seconds or less \u2014 prolonged scanning increases pauses in compressions. Record a clip and review it while compressions resume. Look for cardiac motion (organised activity suggests "pseudo-PEA" with very low output, which may respond to vasopressors), tamponade, a dilated RV, and gross hypovolaemia. Absent cardiac activity after prolonged resuscitation supports decisions to stop, alongside other factors.'],example:{case:"A PEA arrest in a post-operative patient: during the pulse check, the subxiphoid view shows a large effusion with a collapsed RV.",steps:["Tamponade: a reversible cause.","Continue CPR and perform pericardiocentesis (ultrasound-guided if possible).","Reassess rhythm and pulse after drainage; prepare for surgical drainage."]}},{id:"limits",title:"Limits and integration",body:["Focused ultrasound answers yes/no questions; it does not replace comprehensive echocardiography. Body habitus, ventilation, lung disease, wounds and movement in flight limit images. Integrate with the ECG (for example, regional wall motion abnormality supporting ischaemia), labs (troponin, BNP, lactate) and the clinical picture. Document who scanned, when, and the views obtained."]}],keyPoints:["Views: subxiphoid (effusion, CPR), parasternal long and short, apical four-chamber, plus IVC.","Tamponade: effusion + RA systolic and RV diastolic collapse + plethoric IVC.","Massive PE: RV \u2265 LV, septal D sign, McConnell sign.","Small hyperdynamic heart + collapsing IVC = hypovolaemia; poor LV + plethoric IVC = cardiogenic.","In arrest: subxiphoid during pulse checks, \u2264 10 seconds, record and review."],pearls:["Pericardial fluid lies anterior to the descending aorta; pleural fluid lies posterior.",'Organised cardiac motion in "PEA" suggests very low output that may respond to pressors.'],pitfalls:["Long scans that interrupt CPR.","Over-interpreting IVC size in ventilated patients."],live:[{id:"lines-shock-states",label:"Shock states at the bedside"}],questions:[{q:"Best view for pericardial effusion during CPR:",options:["Apical four-chamber","Subxiphoid","Parasternal short","Suprasternal"],answer:1,why:"Accessible without interrupting compressions much."},{q:"Septal flattening (D sign) indicates:",options:["LV failure","RV pressure overload","Hypovolaemia","Normal heart"],answer:1,why:"RV pressure pushes the septum."},{q:"RV diastolic collapse with effusion suggests:",options:["Normal","Tamponade","PE","Cardiomyopathy"],answer:1,why:"Pericardial pressure exceeds RV pressure."},{q:"Small hyperdynamic LV with collapsing IVC suggests:",options:["Cardiogenic shock","Hypovolaemia","Tamponade","PE"],answer:1,why:"Empty tank."},{q:"Maximum duration of ultrasound during a pulse check:",options:["10 seconds","30 seconds","1 minute","No limit"],answer:0,why:"Minimise compression pauses."},{q:"Pericardial effusion is distinguished from pleural by relation to:",options:["IVC","Descending aorta","Liver","Spleen"],answer:1,why:"Pericardial fluid lies anterior to it."},{q:"McConnell sign is associated with:",options:["Tamponade","Acute PE","HCM","Aortic stenosis"],answer:1,why:"RV free wall hypokinesis, apical sparing."},{q:"Organised cardiac activity on ultrasound in PEA suggests:",options:["True asystole","Pseudo-PEA with very low output","Normal output","VF"],answer:1,why:"May respond to vasopressors."},{q:"E-point septal separation under ~7 mm suggests:",options:["Reduced EF","Normal LV function","Tamponade","RV strain"],answer:1,why:"Good LV filling and function."},{q:"IVC assessment is least reliable in:",options:["Spontaneously breathing patients","Ventilated patients","Children","Hypovolaemia"],answer:1,why:"Positive pressure distends it."},{q:"Poor LV function with plethoric IVC suggests:",options:["Distributive shock","Cardiogenic shock","Hypovolaemia","Normal"],answer:1,why:"Pump failure."},{q:"Parasternal short axis is best for assessing:",options:["Pericardial fluid only","Septal shape and LV cross-section","Aorta","IVC"],answer:1,why:"Doughnut view."},{q:"Focused cardiac ultrasound is designed to:",options:["Replace formal echo","Answer specific yes/no questions","Measure valves precisely","Diagnose congenital disease"],answer:1,why:"Goal-directed."},{q:"RV larger than LV in the apical view during shock suggests:",options:["Normal","Acute RV strain (PE)","Hypovolaemia","LV hypertrophy"],answer:1,why:"Normal RV:LV < 0.6\u20131."},{q:"Hyperdynamic heart with small IVC and fever suggests:",options:["Cardiogenic shock","Distributive shock with hypovolaemia","Tamponade","PE"],answer:1,why:"Sepsis pattern."}],sources:[{title:"StatPearls: Focused cardiac ultrasound",url:"https://www.ncbi.nlm.nih.gov/books/?term=Focused+cardiac+ultrasound+StatPearls"},{title:"Huis in 't Veld MA et al. Ultrasound use during CPR and pause duration. Resuscitation (2017)",url:"https://pubmed.ncbi.nlm.nih.gov/28859811/"}]},Ce={id:"fpc-cardiac-labs",domain:"cardiac",ref:"VI.15",title:"Cardiac lab values: troponin, BNP, electrolytes and drug levels",summary:"High-sensitivity troponin pathways, natriuretic peptides, D-dimer, lactate, and the electrolytes and drug levels that drive arrhythmias.",objectives:["Interpret troponin trends and recognise non-ischaemic causes of elevation.","Use BNP and D-dimer appropriately.","Link potassium, magnesium, calcium and digoxin levels to ECG findings and arrhythmias."],sections:[{id:"troponin",title:"Troponin",core:!0,body:["Cardiac troponin I or T is released when myocytes are injured. High-sensitivity assays detect very small amounts within 1\u20133 hours of injury. Myocardial injury is a troponin value above the 99th percentile upper reference limit; acute injury shows a rise and/or fall on serial testing. Myocardial infarction requires acute injury plus clinical evidence of ischaemia (symptoms, ECG changes, imaging).","Type 1 MI is plaque rupture with thrombosis. Type 2 MI is supply\u2013demand mismatch: tachyarrhythmia, hypotension, anaemia, hypoxaemia, severe hypertension. Non-ischaemic injury raises troponin too: myocarditis, PE, sepsis, heart failure, renal failure (often chronically elevated), stroke, cardiac contusion and defibrillation. STEMI is diagnosed on the ECG; never wait for troponin to activate reperfusion."]},{id:"bnp",title:"BNP, D-dimer and lactate",core:!0,body:["BNP and NT-proBNP rise with ventricular wall stress. Low values make acute heart failure unlikely in a dyspnoeic patient; high values support it but also occur with renal failure, PE, sepsis, AF and older age. Obesity lowers levels.","D-dimer is a fibrin degradation product: sensitive but non-specific. A normal D-dimer in a patient with low or intermediate pre-test probability helps exclude PE and DVT; it is raised in dissection, sepsis, malignancy, pregnancy, surgery and trauma, so a high value proves little. Lactate rises with hypoperfusion and in cardiogenic shock tracks severity and response to treatment."]},{id:"electrolytes",title:"Electrolytes and arrhythmias",core:!0,body:["Potassium: hyperkalaemia causes peaked T waves, PR prolongation, QRS widening, sine waves and arrest; hypokalaemia causes U waves, ST depression, QT/QU prolongation and ventricular ectopy, and increases digoxin toxicity. Magnesium: low levels predispose to torsades and refractory hypokalaemia; replete magnesium before or with potassium. Calcium: hypocalcaemia prolongs the QT; hypercalcaemia shortens it.","Targets in high-risk cardiac patients (post-MI, arrhythmias): potassium above about 4.0 and magnesium above about 2.0 mg/dL are commonly used."],table:{caption:"Electrolytes on the ECG",head:["Disturbance","ECG"],rows:[["Hyperkalaemia","Peaked T \u2192 long PR, flat P \u2192 wide QRS \u2192 sine wave"],["Hypokalaemia","U waves, ST depression, long QU, ectopy"],["Hypomagnesaemia","Long QT, torsades"],["Hypocalcaemia","Long QT (long ST segment)"],["Hypercalcaemia","Short QT"]]}},{id:"digoxin",title:"Digoxin and other drug levels",body:['Digoxin toxicity causes nausea, vomiting, visual changes (yellow-green tinge), confusion and almost any arrhythmia \u2014 classically bidirectional VT, atrial tachycardia with block, and bradycardia \u2014 with hyperkalaemia in acute overdose. The "digoxin effect" (scooped ST depression) is not toxicity. Risk rises with renal failure, hypokalaemia and drug interactions (amiodarone). Treat significant toxicity with digoxin-specific antibody fragments; calcium for hyperkalaemia in digoxin toxicity is now considered acceptable by many, but the antidote is the priority.'],example:{case:"An 84-year-old on digoxin and furosemide: vomiting, confusion, HR 42 with junctional rhythm, K\u207A 3.0, creatinine 2.6.",steps:["Chronic digoxin toxicity precipitated by renal failure and hypokalaemia.","Digoxin-specific antibody fragments per toxicology advice.","Replace potassium and magnesium cautiously; atropine or pacing for symptomatic bradycardia.","Monitor in flight; avoid further digoxin."]}},{id:"case",title:"Transport case: troponin without a blocked artery",body:["A 35-year-old with fever, cough and new atrial fibrillation at 160: troponin elevated and rising; ECG shows no ST elevation; BP 98/60."],example:{case:"Is this an MI?",steps:["Acute myocardial injury (rising troponin) \u2014 causes include type 2 MI from tachycardia and fever, myocarditis or sepsis.","Treat the drivers: rate control or cardioversion if unstable, fever control, infection treatment, oxygen if hypoxaemic.","Antithrombotic therapy decisions depend on the mechanism; do not reflexively treat as type 1 MI.","Echo at the destination to assess for myocarditis or regional wall motion abnormalities."]}}],keyPoints:["Acute myocardial injury = troponin above the 99th percentile with a rise/fall; MI needs ischaemia too.","Type 2 MI = supply\u2013demand mismatch; many non-ischaemic causes raise troponin.","Never delay STEMI reperfusion for troponin.","Low BNP argues against acute HF; normal D-dimer helps exclude PE in low-risk patients.","Low K\u207A and Mg\xB2\u207A predispose to arrhythmias and digoxin toxicity; treat digoxin toxicity with antibody fragments."],pearls:["Bidirectional VT suggests digoxin toxicity.","Chronic renal failure often raises baseline troponin \u2014 trends matter."],pitfalls:["Waiting for troponin before activating the cath lab for STEMI.","Using a high D-dimer as proof of PE."],questions:[{q:"Myocardial injury is troponin above:",options:["The 50th percentile","The 99th percentile upper reference limit","Twice normal","Any detectable level"],answer:1,why:"Universal definition."},{q:"Type 2 MI results from:",options:["Plaque rupture","Supply\u2013demand mismatch","Coronary dissection always","Embolism only"],answer:1,why:"E.g. tachycardia, anaemia, hypotension."},{q:"STEMI reperfusion should be activated based on:",options:["Troponin","ECG and clinical picture","BNP","D-dimer"],answer:1,why:"Do not wait for biomarkers."},{q:"A low BNP in a dyspnoeic patient:",options:["Confirms HF","Makes acute HF unlikely","Indicates PE","Is meaningless"],answer:1,why:"High negative predictive value."},{q:"D-dimer is most useful to:",options:["Confirm PE","Help exclude PE in low/intermediate risk","Diagnose MI","Monitor heparin"],answer:1,why:"Sensitive, non-specific."},{q:"U waves suggest:",options:["Hyperkalaemia","Hypokalaemia","Hypercalcaemia","Normal"],answer:1,why:"Classic hypokalaemia sign."},{q:"Hypomagnesaemia predisposes to:",options:["Short QT","Torsades de pointes","Peaked T waves","Bradycardia only"],answer:1,why:"QT prolongation."},{q:"Bidirectional VT suggests:",options:["Hyperkalaemia","Digoxin toxicity","WPW","Brugada"],answer:1,why:"Classic association."},{q:"Digoxin toxicity risk is increased by:",options:["Hyperkalaemia","Hypokalaemia and renal failure","Hypercalcaemia only","Bradycardia"],answer:1,why:"Reduced clearance and enhanced binding."},{q:"Antidote for severe digoxin toxicity:",options:["Naloxone","Digoxin-specific antibody fragments","Atropine only","Calcium alone"],answer:1,why:"Binds digoxin."},{q:"Hypocalcaemia on ECG:",options:["Short QT","Long QT","Peaked T","Delta wave"],answer:1,why:"Prolonged ST segment."},{q:"High-sensitivity troponin detects injury within about:",options:["10 minutes","1\u20133 hours","24 hours","3 days"],answer:1,why:"Rapid rule-in/out pathways."},{q:"Common potassium target in post-MI arrhythmia patients:",options:["> 2.5","> 4.0","> 6.0","< 3.0"],answer:1,why:"Reduces ventricular arrhythmias."},{q:"Scooped ST depression in a patient on digoxin without symptoms:",options:["Toxicity","Digoxin effect","STEMI","Hyperkalaemia"],answer:1,why:"Expected therapeutic finding."},{q:"Obesity tends to:",options:["Raise BNP","Lower BNP","Not affect BNP","Raise troponin"],answer:1,why:"Adipose clearance of natriuretic peptides."}],sources:[{title:"Fourth Universal Definition of Myocardial Infarction (2018)",url:"https://www.ahajournals.org/doi/10.1161/CIR.0000000000000617"},{title:"StatPearls: Digoxin toxicity",url:"https://www.ncbi.nlm.nih.gov/books/?term=Digoxin+toxicity+StatPearls"}]};var Ie={id:"fpc-cardiac-pharm",domain:"cardiac",ref:"VI.16",title:"Cardiac pharmacology",summary:"Antiarrhythmics, rate control, antiplatelets and anticoagulants, fibrinolytics, vasodilators and ACLS drugs: mechanisms, doses that matter, and the interactions that hurt.",objectives:["Select antiarrhythmic and rate-control drugs by rhythm and ventricular function.","Use antithrombotic and fibrinolytic agents safely.","Recall ACLS drug doses and their indications."],sections:[{id:"antiarrhythmics",title:"Antiarrhythmics and rate control",core:!0,body:["Adenosine: 6 mg rapid IV push with a saline flush, then 12 mg; terminates AV-nodal re-entry and unmasks atrial flutter or tachycardia. Reduce the dose (often to 3 mg) with central line administration, heart transplant recipients, or dipyridamole and carbamazepine; theophylline and caffeine blunt its effect. Avoid in irregular wide-complex tachycardia.","Amiodarone: 300 mg IV push in VF/pulseless VT (then 150 mg); 150 mg over 10 minutes for stable VT, followed by an infusion. It causes hypotension and bradycardia, prolongs the QT, and has many interactions. Lidocaine (1\u20131.5 mg/kg) is an alternative in arrest. Procainamide (20\u201350 mg/min to a maximum of 17 mg/kg, or until the QRS widens by 50 % or hypotension) is useful for stable VT and AF with WPW, but avoid in long QT and heart failure.","Rate control: diltiazem (0.25 mg/kg IV over 2 minutes) or metoprolol (2.5\u20135 mg IV) for AF or flutter with preserved function; avoid both in decompensated heart failure and WPW. Digoxin is slower and used in heart failure. Magnesium treats torsades."],table:{caption:"ACLS drug doses (adult)",head:["Drug","Dose","Use"],rows:[["Epinephrine","1 mg IV/IO every 3\u20135 min","Cardiac arrest"],["Amiodarone","300 mg, then 150 mg","VF/pVT refractory to shocks"],["Lidocaine","1\u20131.5 mg/kg, then 0.5\u20130.75 mg/kg","Alternative to amiodarone"],["Adenosine","6 mg, then 12 mg rapid push","Stable regular narrow SVT"],["Atropine","1 mg every 3\u20135 min (max 3 mg)","Symptomatic bradycardia"],["Magnesium","1\u20132 g IV","Torsades"],["Calcium chloride","1 g IV","Hyperkalaemia, CCB toxicity"]]}},{id:"antithrombotics",title:"Antiplatelets, anticoagulants and fibrinolytics",core:!0,body:["Aspirin irreversibly inhibits cyclooxygenase in platelets. P2Y12 inhibitors (clopidogrel, ticagrelor, prasugrel) block ADP-mediated activation; prasugrel is avoided in prior stroke or TIA. Glycoprotein IIb/IIIa inhibitors are used selectively in the cath lab.","Unfractionated heparin (weight-based bolus and infusion, monitored by aPTT or anti-Xa; reversible with protamine) suits patients who may need procedures or have renal failure. Enoxaparin is given subcutaneously or IV, renally cleared and partially reversed by protamine. Bivalirudin is a direct thrombin inhibitor used during PCI.","Fibrinolytics (alteplase, reteplase, tenecteplase) convert plasminogen to plasmin to dissolve fibrin. Tenecteplase is given as a single weight-based bolus \u2014 convenient in transport. Monitor for bleeding, especially intracranial (sudden headache, neurological change, vomiting): stop anticoagulants, and give cryoprecipitate and an antifibrinolytic per protocol."]},{id:"vasodilators",title:"Vasodilators, inotropes and others",core:!0,body:["Nitroglycerin reduces preload (and afterload at high doses) and relieves ischaemic pain; avoid with hypotension, RV infarction, recent PDE-5 inhibitors and severe aortic stenosis. Morphine is reserved for pain refractory to nitrates. Beta-blockers reduce myocardial oxygen demand but are avoided early when heart failure, low output or high shock risk exist. ACE inhibitors and statins are started in hospital.","Inotropes and vasopressors are covered in the treatment modalities and cardiogenic shock lessons; remember the principle \u2014 vasopressors for low SVR, inotropes for low contractility, both when both fail."],example:{case:"A patient with AF at 158 and EF 20 % with mild congestion, BP 104/68.",steps:["Avoid diltiazem (negative inotrope in severe HFrEF).","Amiodarone (150 mg over 10 min then infusion) or digoxin for rate control; cardiovert if unstable.","Treat congestion; consider anticoagulation implications."]}},{id:"case",title:"Transport case: lysis on the way",body:["A remote clinic with no PCI access within 120 minutes. Anterior STEMI, onset 70 minutes ago, 78 kg, no contraindications. Tenecteplase has been given. Twenty minutes into the flight, the patient develops accelerated idioventricular rhythm at 85 with BP 118/70 and decreasing chest pain."],example:{case:"What does it mean and what do you do?",steps:["Accelerated idioventricular rhythm after lysis commonly signals reperfusion; it is usually benign and self-limiting.","Do not treat it with antiarrhythmics unless haemodynamically unstable.","Recheck a 12-lead ECG at 60\u201390 minutes for ST resolution.","Continue anticoagulation per protocol; watch for bleeding; hand over timing of lysis and reperfusion signs."]}}],keyPoints:["Adenosine 6 then 12 mg rapid push; reduce in transplant and central lines; avoid irregular wide-complex rhythms.","Amiodarone 300/150 in arrest; 150 mg over 10 min for stable VT.","Procainamide for AF with WPW; avoid AV nodal blockers.","Fibrinolytics: watch for intracranial haemorrhage; tenecteplase is a single bolus.","No nitrates with hypotension, RV infarction, PDE-5 use or severe AS."],pearls:["Caffeine and theophylline blunt adenosine.","AIVR after lysis is a reperfusion sign \u2014 leave it alone."],pitfalls:["Diltiazem in severe HFrEF.","Prasugrel in a patient with prior stroke."],live:[{id:"labs-coag",label:"Reversing anticoagulation"},{id:"moa-nitroglycerin",label:"Nitroglycerin: mechanism"},{id:"moa-esmolol",label:"Esmolol: mechanism"}],questions:[{q:"Adenosine initial dose:",options:["3 mg slow","6 mg rapid push with flush","12 mg over 2 min","0.25 mg/kg"],answer:1,why:"Very short half-life."},{q:"Adenosine dose should be reduced in:",options:["Asthma","Heart transplant recipients","Children","Hypertension"],answer:1,why:"Denervation hypersensitivity."},{q:"A substance that blunts adenosine:",options:["Dipyridamole","Caffeine","Carbamazepine","Amiodarone"],answer:1,why:"Adenosine receptor antagonist."},{q:"Amiodarone dose in VF after the third shock:",options:["150 mg","300 mg","1 g","50 mg"],answer:1,why:"Then 150 mg."},{q:"Drug for stable AF with WPW:",options:["Diltiazem","Procainamide","Digoxin","Adenosine"],answer:1,why:"Slows accessory pathway."},{q:"Procainamide end-points include:",options:["HR < 60","QRS widening by 50 % or hypotension","Pain relief","Normal QT"],answer:1,why:"Stop for toxicity signs."},{q:"Tenecteplase is given as:",options:["Infusion over 3 h","Single weight-based bolus","Oral tablet","Subcutaneously"],answer:1,why:"Convenient for transport."},{q:"Sudden headache and vomiting after fibrinolysis suggests:",options:["Reperfusion","Intracranial haemorrhage","Migraine only","Hypoglycaemia"],answer:1,why:"Stop anticoagulants; image urgently."},{q:"Prasugrel is contraindicated with:",options:["Diabetes","Prior stroke or TIA","Age 50","Hypertension"],answer:1,why:"Higher bleeding risk."},{q:"Aspirin works by:",options:["P2Y12 block","Irreversible COX inhibition","Thrombin inhibition","Plasminogen activation"],answer:1,why:"Thromboxane reduction."},{q:"Heparin reversal agent:",options:["Vitamin K","Protamine","Idarucizumab","Naloxone"],answer:1,why:"Binds heparin."},{q:"Accelerated idioventricular rhythm after lysis should usually be:",options:["Treated with amiodarone","Observed \u2014 a reperfusion sign","Cardioverted","Treated with lidocaine"],answer:1,why:"Usually benign."},{q:"Calcium chloride is indicated in:",options:["Hypercalcaemia","Hyperkalaemia and CCB toxicity","Digoxin effect","Asystole routinely"],answer:1,why:"Membrane stabilisation; CCB reversal."},{q:"Diltiazem IV dose for AF rate control:",options:["0.25 mg/kg over 2 min","5 mg/kg","1 g","0.01 mg/kg"],answer:0,why:"Standard initial dose."},{q:"Nitroglycerin is contraindicated in:",options:["Pulmonary oedema with HTN","Severe aortic stenosis","Angina","Hypertensive emergency"],answer:1,why:"Preload-dependent outflow obstruction."}],sources:[{title:"AHA guidelines for CPR and ECC: adult ALS drug therapy",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{title:"StatPearls: Adenosine",url:"https://www.ncbi.nlm.nih.gov/books/?term=Adenosine+StatPearls"}]},Se={id:"fpc-cardiac-monitor",domain:"cardiac",ref:"VI.17",title:"Cardiac monitoring equipment",summary:"ECG monitoring and lead placement, non-invasive and invasive blood pressure, pulse oximetry, capnography and cardiac output monitoring \u2014 what each measures, how it fails in flight, and how to troubleshoot.",objectives:["Place ECG leads and acquire a diagnostic 12-lead in the field.","Recognise artefact and measurement limits of NIBP, SpO\u2082 and invasive monitoring.","Choose monitoring appropriate to the patient and transport environment."],sections:[{id:"ecg",title:"ECG monitoring",core:!0,body:["Three- or five-lead monitoring detects rhythm; a 12-lead is needed for ischaemia. Limb electrodes go on the limbs or torso near the shoulders and hips (torso placement changes some voltages); precordial leads: V1 4th intercostal space right sternal border, V2 4th left, V4 5th intercostal space mid-clavicular, V3 between V2 and V4, V5 anterior axillary line level with V4, V6 mid-axillary line level with V4. Right-sided V4R mirrors V4 on the right; posterior V7\u2013V9 continue from V6 around to the back at the same level.","Artefact from vibration, shivering, movement and electrical interference mimics arrhythmias. Check the patient (pulse, perfusion) before treating a monitor rhythm. Good skin preparation, fresh electrodes and securing leads reduce artefact; monitor filters reduce noise but distort ST segments \u2014 use diagnostic mode for 12-leads."]},{id:"bp",title:"Blood pressure",core:!0,body:["Oscillometric non-invasive BP measures MAP most accurately and derives systolic and diastolic values. It fails with vibration, arrhythmias, severe hypotension, shivering and wrong cuff size: a cuff too small reads falsely high, too large falsely low (the bladder should encircle about 80 % of the arm, width about 40 % of the circumference). Frequent cycling causes discomfort and skin injury.","Arterial lines give beat-to-beat pressure and are preferred for unstable patients, vasoactive infusions and long transports where cuffs struggle. They must be levelled to the phlebostatic axis, zeroed, and checked with a fast-flush test. Compare with a cuff periodically; trust the MAP when systolic values differ."]},{id:"spo2",title:"Pulse oximetry and capnography",core:!0,body:["Pulse oximetry compares red and infrared absorption to estimate oxygen saturation. It fails with poor perfusion, cold extremities, motion, nail polish, ambient light and dyshaemoglobins: carbon monoxide reads falsely normal, and methaemoglobinaemia drives readings toward about 85 %. Accuracy falls below about 80 %, and studies show overestimation in patients with darker skin pigmentation \u2014 corroborate with blood gases in critical decisions. The plethysmographic waveform tells you whether the signal is real.","Capnography is covered in detail in the airway domain; in cardiac care, EtCO\u2082 reflects pulmonary blood flow, so it tracks CPR quality, signals ROSC, and falls with low cardiac output."]},{id:"advanced",title:"Advanced monitoring",body:["Cardiac output monitors (pulse-contour analysis from an arterial line, thermodilution with a PA catheter, Doppler-based devices) estimate stroke volume and output and support fluid-responsiveness testing. Central venous oxygen saturation (normal about 65\u201375 %) reflects the balance between delivery and consumption. Near-infrared spectroscopy estimates regional tissue oxygenation, mostly in paediatric and cardiac surgical patients.","Every monitor needs power: check batteries, carry spares, and know the aircraft's power supply. Alarm limits should be set appropriately for each patient to avoid alarm fatigue while catching real deterioration."],example:{case:"In flight the monitor shows VF but the patient is talking.",steps:["Check the patient first: talking means perfusing \u2014 artefact.","Check leads and electrodes; vibration and loose electrodes mimic VF.","Confirm with pulse, SpO\u2082 waveform and arterial line.","Never defibrillate a patient with a pulse."]}},{id:"case",title:"Transport case: discordant numbers",body:["A septic patient on norepinephrine: cuff BP 74/40 at the wrist, arterial line 102/58 (MAP 72), SpO\u2082 reading 84 % with a flat, irregular waveform while the patient is pink and alert."],example:{case:"Which numbers do you trust?",steps:["Cuff at the wrist on a vasoconstricted patient in a vibrating aircraft is least reliable; check the arterial line's level, zero and damping, then trust its MAP.","A poor pleth waveform means an unreliable SpO\u2082 \u2014 warm the hand, try an ear or forehead probe, check a blood gas if needed.","Don't escalate vasopressors based on an artefactual cuff reading."]}}],keyPoints:["V1\u2013V2 4th ICS either side of the sternum; V4 5th ICS MCL; V5\u2013V6 level with V4; V4R and V7\u2013V9 for RV/posterior.","Treat the patient, not the monitor: artefact mimics VF and VT.","Cuff too small reads high; oscillometric MAP is most accurate; arterial lines for unstable patients.","SpO\u2082 fails with poor perfusion, motion, CO (falsely normal), MetHb (~85 %), and can overestimate in darker skin.","Check power, batteries and alarm limits before every flight."],pearls:["The pleth waveform validates the SpO\u2082 number.","Use diagnostic filter mode for 12-leads."],pitfalls:["Defibrillating artefact.","Wrong cuff size on an obese arm."],live:[{id:"ln-art",label:"Reading the arterial waveform"},{id:"ln-damp",label:"Damping and the square-wave test"}],questions:[{q:"V1 is placed at:",options:["5th ICS left MCL","4th ICS right sternal border","2nd ICS left","Mid-axillary 5th ICS"],answer:1,why:"Standard placement."},{q:"V4 is placed at:",options:["4th ICS left sternal border","5th ICS mid-clavicular line","Anterior axillary line","Right side"],answer:1,why:"Standard placement."},{q:"Leads used to detect posterior MI:",options:["V4R","V7\u2013V9","aVR","Lead III"],answer:1,why:"Posterior chest leads."},{q:"A BP cuff that is too small reads:",options:["Falsely low","Falsely high","Accurately","Zero"],answer:1,why:"Requires more pressure to occlude."},{q:"Oscillometric BP measures most accurately:",options:["Systolic","Diastolic","MAP","Pulse pressure"],answer:2,why:"Maximum oscillation equals MAP."},{q:"SpO\u2082 in carbon monoxide poisoning reads:",options:["Falsely low","Falsely normal or high","Accurately","Zero"],answer:1,why:"COHb mistaken for O\u2082Hb."},{q:"Methaemoglobinaemia drives SpO\u2082 toward:",options:["100 %","85 %","50 %","70 %"],answer:1,why:"Characteristic reading."},{q:"Pulse oximetry may overestimate saturation in:",options:["Patients with darker skin pigmentation","Children only","Hyperthermia","Anaemia only"],answer:0,why:"Documented bias \u2014 confirm with gases."},{q:"The monitor shows VF but the patient is talking. You should:",options:["Defibrillate","Assess the patient and check leads \u2014 artefact","Give amiodarone","Start CPR"],answer:1,why:"Treat the patient."},{q:"Monitor filters can distort:",options:["Heart rate","ST segments","P waves only","Nothing"],answer:1,why:"Use diagnostic mode for 12-leads."},{q:"Normal ScvO\u2082:",options:["30\u201340 %","65\u201375 %","95\u2013100 %","50 %"],answer:1,why:"Balance of delivery and consumption."},{q:"Cuff bladder should encircle about:",options:["40 % of the arm","80 % of the arm","100 % twice","20 %"],answer:1,why:"Proper sizing."},{q:"A flat, irregular pleth waveform means:",options:["Accurate SpO\u2082","Unreliable SpO\u2082","Hyperoxia","Normal"],answer:1,why:"Poor signal quality."},{q:"V6 is placed at:",options:["Anterior axillary line","Mid-axillary line level with V4","Posterior axillary","4th ICS sternal"],answer:1,why:"Standard placement."},{q:"In discordant arterial and cuff readings, trust:",options:["The lowest systolic","The arterial MAP after checking level, zero and damping","The cuff always","Neither"],answer:1,why:"Verified invasive MAP is most reliable."}],sources:[{title:"AHA scientific statement: blood pressure measurement (2019)",url:"https://www.ahajournals.org/doi/10.1161/HYP.0000000000000087"},{title:"Sjoding MW et al. Racial bias in pulse oximetry. NEJM (2020)",url:"https://www.nejm.org/doi/full/10.1056/NEJMc2029240"}]};var l=(a,i,n,r)=>({id:a,title:i,body:n,example:r}),Te={"fpc-acs":{questions:[],sections:[l("case","Transport case: NSTEMI that will not settle",["A 66-year-old with ongoing chest pain despite nitrates and heparin. The ECG shows 2 mm ST depression in V4\u2013V6 that comes and goes, troponin is rising, and runs of non-sustained VT appear on the monitor. BP 108/66.","This is very-high-risk NSTEMI: refractory ischaemic pain with electrical instability. Guidelines recommend immediate invasive strategy (angiography within about two hours), the same urgency as STEMI."],{case:"What do you do during transfer?",steps:["Pads on; treat sustained VT per ACLS; correct potassium and magnesium if low.","Continue antiplatelet and anticoagulant therapy per the receiving centre; repeat 12-leads for evolving STEMI (look for posterior changes and aVR elevation).","Treat pain with nitrates as BP allows; small opioid doses if refractory.","Pre-alert the interventional team for immediate angiography."]})]},"fpc-cardiogenic":{questions:[],sections:[l("causes","Non-ischaemic causes to look for",["Not all cardiogenic shock is MI. Consider fulminant myocarditis (young, viral prodrome), stress (Takotsubo) cardiomyopathy, peripartum cardiomyopathy (late pregnancy to months after delivery), drug toxicity (beta-blockers, calcium-channel blockers, sodium-channel blockers), acute valve failure (papillary muscle rupture, endocarditis, prosthetic valve thrombosis), tachy- or bradyarrhythmias, and end-stage chronic heart failure. Each has specific treatments \u2014 antidotes, rhythm control, surgery \u2014 that matter as much as vasopressors.","Ask about recent viral illness, pregnancy, medications and overdoses, and look for murmurs and rhythm problems in every patient."]),l("monitor","Monitoring the response",['In cardiogenic shock, the blood pressure alone is a poor guide. Watch perfusion: mentation, skin temperature and mottling, capillary refill, urine output and lactate clearance. Rising lactate despite a "normal" MAP means the output is still inadequate.',"Invasive monitoring helps: an arterial line for beat-to-beat pressure on vasoactive drugs, central venous saturation (ScvO\u2082 under about 60 % suggests inadequate delivery), and, at the receiving centre, a PA catheter to measure cardiac index, wedge pressure and cardiac power output. Point-of-care echo shows LV and RV function, valve lesions and effusion.","Escalation triggers \u2014 rising vasopressor and inotrope doses, worsening lactate, new arrhythmias, falling urine output \u2014 should prompt early discussion with a centre offering mechanical circulatory support, ideally before the patient reaches SCAI stage D or E."])]},"fpc-heart-failure":{questions:[],sections:[l("oxygen","Oxygen targets and positioning",["Sit patients with pulmonary oedema upright with legs dependent to reduce venous return. Titrate oxygen to SpO\u2082 94\u201398 % (88\u201392 % in known CO\u2082 retainers); NIV is the most effective oxygenation tool in cardiogenic oedema and reduces intubation. Avoid laying these patients flat for transfer until they are stabilised \u2014 orthopnoea can precipitate arrest on a stretcher."]),l("case2","Transport case: the dialysis patient who cannot breathe",["A 64-year-old on haemodialysis missed a session; now orthopnoeic, SpO\u2082 84 %, BP 196/104, crackles throughout, K\u207A 6.1 with peaked T waves.","Two emergencies coexist: volume overload with pulmonary oedema that diuretics cannot treat (anuria), and hyperkalaemia."],{case:"Prioritise.",steps:["Calcium for the ECG changes; insulin\u2013dextrose and salbutamol to shift potassium.","CPAP or BiPAP and high-dose nitrates for the oedema and hypertension.","Diuretics are unlikely to work; urgent dialysis (or ultrafiltration) is definitive.","Avoid succinylcholine if intubation is needed; protect the fistula arm."]}),l("chronic","Chronic heart failure medications in the acute setting",["Patients may take ACE inhibitors, angiotensin receptor\u2013neprilysin inhibitors, beta-blockers, mineralocorticoid antagonists (spironolactone) and SGLT2 inhibitors. In acute decompensation with hypotension or shock, hold vasodilating and negative inotropic drugs temporarily; in hypertensive decompensation, they are usually continued. Spironolactone and ACE inhibitors raise potassium; SGLT2 inhibitors can cause euglycaemic ketoacidosis in acute illness."])]},"fpc-cardiac-infect":{questions:[],sections:[l("pericardiocentesis","Pericardiocentesis technique",["Ultrasound guidance is preferred: choose the approach where the effusion is largest and closest to the skin (subxiphoid, parasternal or apical), avoiding the internal mammary artery near the sternum. The classic blind subxiphoid approach aims a long needle from just left of the xiphoid toward the left shoulder at about 30\u201345\xB0 to the skin, aspirating as it advances.","Removing even 50\u2013100 mL can dramatically improve haemodynamics in acute tamponade. Complications include ventricular puncture, coronary laceration, arrhythmia, pneumothorax and liver injury. In trauma, blood may clot and not aspirate; surgical drainage remains definitive. Leave a catheter in place if the effusion may reaccumulate."])]},"fpc-arrhythmias":{questions:[],sections:[l("afib","Atrial fibrillation in transport",["Many transport patients have AF. Ask: is it the cause of their problem or a consequence of something else (sepsis, hypovolaemia, PE, thyrotoxicosis, alcohol)? Treating the cause often slows the rate more safely than drugs. Rapid AF in septic shock may respond to fluid and vasopressors rather than rate-control agents, which can drop pressure.","Cardioversion of AF present for more than 48 hours (or unknown duration) without anticoagulation carries a risk of stroke from left atrial thrombus; for stable patients, rate control and anticoagulation are preferred, with cardioversion reserved for instability. Anticoagulated patients have bleeding considerations in trauma."])]},"fpc-htn-crisis":{questions:[],sections:[l("monitoring","Monitoring during transport",["Titratable infusions need frequent pressure measurement: every 5 minutes with a cuff during titration, or continuous arterial monitoring. Overshoot causes stroke, MI and renal injury in patients with shifted autoregulation. Reassess neurological status regularly; document the time course of blood pressure and doses so the receiving team can continue the planned reduction."]),l("specific","Special situations",["Sympathomimetic toxicity (cocaine, amphetamines): benzodiazepines first; phentolamine or nicardipine if needed; avoid isolated beta-blockade. Autonomic dysreflexia in spinal cord injury at or above T6: sit the patient up, loosen tight clothing, and look for the trigger \u2014 most often a distended bladder (catheterise or flush a blocked catheter) or faecal impaction \u2014 before giving antihypertensives. Pheochromocytoma: alpha-blockade first.","Post-thrombolysis or post-thrombectomy stroke patients have specific targets set by the neurology team; keep within them. Patients with left ventricular assist devices need Doppler MAP monitoring; hypertension increases stroke and pump complications."])]},"fpc-hemo-instab":{questions:[],sections:[l("vasopressor-choice","Choosing the vasopressor",["Low SVR with adequate output: norepinephrine (and vasopressin). Low output with adequate SVR: an inotrope (dobutamine, milrinone, or epinephrine). Both low: norepinephrine plus an inotrope, or epinephrine alone. Bradycardia driving low output: chronotropy (epinephrine, dopamine, isoproterenol) or pacing. Avoid pure alpha-agonists (phenylephrine) when cardiac output is already low except as a brief bridge."]),l("oxygen","Oxygen delivery and consumption",["Shock is ultimately a failure of oxygen delivery relative to demand. Delivery (DO\u2082) is cardiac output times arterial oxygen content; content depends mostly on haemoglobin and saturation. A patient can be hypoperfused with a normal blood pressure if output or haemoglobin is low, and normotensive patients with rising lactate deserve the same attention as hypotensive ones.","Reduce demand where possible: treat fever, pain, agitation and shivering; sedate and ventilate the patient whose work of breathing consumes a large share of their output. Raise delivery by restoring volume, haemoglobin (transfuse when bleeding or severely anaemic), oxygenation and output."]),l("case2","Transport case: normal pressure, rising lactate",["A post-operative patient: BP 112/64, HR 108, lactate rising from 2.4 to 4.6 over two hours, cool hands, urine 10 mL/h, haemoglobin falling from 11 to 8.2."],{case:"Is this shock?",steps:["Yes: hypoperfusion despite a normal pressure \u2014 likely occult haemorrhage.","Transfuse, check coagulation, reassess the surgical site and drains.","Alert the surgical team; consider imaging or return to theatre."]})]},"fpc-chronic-cardiac":{questions:[],sections:[l("pregnancy","Pregnancy and chronic heart disease",["Pregnancy raises blood volume and cardiac output by 30\u201350 %, which unmasks valve disease, cardiomyopathy and pulmonary hypertension \u2014 the last carries a very high maternal mortality. Mitral stenosis decompensates with the rising heart rate and volume of pregnancy; peripartum cardiomyopathy appears in late pregnancy or the months after delivery. Transport pregnant cardiac patients to centres with both cardiac and obstetric expertise, with left uterine displacement after 20 weeks."]),l("pacemaker","Devices in chronic heart disease",["Many patients with chronic heart disease have pacemakers, ICDs, cardiac resynchronisation devices or LVADs. Identify the device (card, chest X-ray, interrogation at the destination), place defibrillation pads away from the generator, and know that magnets change pacemaker and ICD behaviour differently. Bring the patient's device card and contact the managing centre for complex devices."]),l("valve","Prosthetic valves and anticoagulation",["Mechanical valves need lifelong anticoagulation with warfarin (direct oral anticoagulants are contraindicated); bioprosthetic valves usually do not. In bleeding, reversal decisions balance the bleed against valve thrombosis risk \u2014 involve cardiology, but do not withhold reversal in life-threatening haemorrhage. A muffled mechanical click, new murmur, heart failure or embolism suggests valve thrombosis or dysfunction.","Patients with prosthetic valves are at higher risk of endocarditis; fever in these patients warrants blood cultures before antibiotics where feasible."])]},"fpc-vascular":{questions:[],sections:[l("imaging","Imaging and destination",["CT angiography diagnoses dissection and AAA rupture; bedside ultrasound identifies AAA, pericardial effusion and sometimes an intimal flap in the aortic root. Chest X-ray may show a widened mediastinum but is normal in many dissections. Choose destinations with cardiothoracic or vascular surgery and endovascular capability; avoid stopping at hospitals that cannot provide definitive care when the patient is stable enough for direct transfer."]),l("pe","Pulmonary embolism as a vascular emergency",["Massive (high-risk) PE presents with shock or hypotension; submassive (intermediate-risk) PE has RV strain on echo or raised troponin without hypotension. Management of massive PE includes systemic thrombolysis unless contraindicated, or catheter-directed therapy or surgical embolectomy; transport to a centre with these options.","Supportive care focuses on the right ventricle: oxygen, cautious fluids (avoid overloading the RV), norepinephrine for hypotension, and avoidance of intubation where possible. If intubation is unavoidable, prepare for collapse."])]},"fpc-electrophys":{questions:[],sections:[l("lifevest","Wearable defibrillators and implantable loop recorders",["Some patients wear a wearable cardioverter-defibrillator vest that detects VT or VF and shocks automatically after audible alarms; the patient can press response buttons to abort a shock if conscious. If the patient arrests, the vest may shock; stand clear when it alarms. For CPR or external defibrillation, remove the vest's electrode belt per manufacturer instructions.","Implantable loop recorders record rhythms but do not pace or shock; they are irrelevant to resuscitation but useful for diagnosis later."])]},"fpc-cardiac-dx":{questions:[],sections:[l("ecg-integration","Pairing ultrasound with the ECG",["A regional wall motion abnormality matching ECG changes supports acute ischaemia; a globally poor LV suggests cardiomyopathy or myocarditis; a dilated RV with ST changes in V1\u2013V3 and inferior leads suggests PE or RV infarction. Low-voltage QRS with electrical alternans suggests a large effusion. Combining modalities increases confidence before invasive or irreversible decisions."]),l("lung","Lung ultrasound for cardiac patients",["Three or more B-lines in two or more zones bilaterally suggest interstitial oedema (cardiogenic pulmonary oedema, or ARDS if patchy with pleural line abnormalities). An A-line pattern with lung sliding suggests dry lungs \u2014 useful when deciding whether fluid can be given. Pleural effusions appear as anechoic spaces above the diaphragm.","Combining lung and cardiac views (for example, poor LV function plus diffuse B-lines) strongly supports acute heart failure in a dyspnoeic patient, and the absence of B-lines makes cardiogenic oedema unlikely."]),l("case","Transport case: the breathless patient with two possible causes",["A 78-year-old with COPD and heart failure presents short of breath: wheeze, crackles, BP 168/92."],{case:"Use ultrasound to decide.",steps:["Diffuse bilateral B-lines and poor LV function: acute heart failure \u2014 CPAP and nitrates.","A-lines with sliding and a normal LV: COPD exacerbation \u2014 bronchodilators, steroids, BiPAP if hypercapnic.","Both can coexist; treat what dominates."]})]},"fpc-cardiac-labs":{questions:[],sections:[l("timing","Timing and serial testing",["High-sensitivity troponin pathways use a baseline and a repeat at 1\u20133 hours; a single normal value very early after symptom onset does not exclude MI. Lactate is repeated after resuscitation to confirm clearance. Potassium and magnesium are rechecked after replacement and after insulin or diuretics. In transport, record the time of each result so the receiving team can interpret trends."]),l("other","Other useful results",["Thyroid function: thyrotoxicosis causes AF and high-output failure; hypothyroidism causes bradycardia and effusions. Haemoglobin: anaemia worsens ischaemia and can cause type 2 MI. Coagulation: baseline INR and aPTT before anticoagulation and fibrinolysis. Renal function: guides contrast exposure, drug dosing (enoxaparin, digoxin) and potassium risk.","Point-of-care tests (troponin, INR, lactate, electrolytes) increasingly travel with transport teams; know their limits and confirm critical values at the receiving facility."])]},"fpc-cardiac-pharm":{questions:[],sections:[l("interactions","Dangerous interactions",["QT-prolonging combinations (amiodarone, sotalol, macrolides, fluoroquinolones, antipsychotics, ondansetron, methadone) raise torsades risk \u2014 especially with hypokalaemia or hypomagnesaemia. Beta-blockers plus non-dihydropyridine calcium-channel blockers can cause profound bradycardia and heart block. Nitrates with PDE-5 inhibitors cause severe hypotension. Amiodarone raises digoxin and warfarin levels.","In transport, review the medication list for these before giving additional drugs."])]},"fpc-cardiac-monitor":{questions:[],sections:[l("alarms","Alarm management in the aircraft",["Noise in aircraft makes audible alarms hard to hear; use visual alerts and position monitors in line of sight. Set patient-specific limits: too wide and you miss deterioration, too narrow and alarm fatigue sets in. Silence alarms only after assessing the patient, and re-enable them.","Monitors, pumps and ventilators may interfere with each other or with aircraft systems; use approved equipment, secure cables and know the power supply arrangements. Document monitor trends at regular intervals as part of the transport record."])]}};var Re={id:"fpc-trauma-dx",domain:"trauma",ref:"VII.1",title:"Trauma diagnostics: primary survey, eFAST, X-ray and CT",summary:"The structured trauma assessment, extended FAST, the trauma films and CT findings you will be handed, and how diagnostics should \u2014 and should not \u2014 delay transport.",objectives:["Perform a structured primary survey that treats life threats as they are found.","Perform and interpret eFAST and recognise its limits.","Interpret key trauma X-ray and CT findings and decide whether imaging should delay transfer."],sections:[{id:"survey",title:"The primary survey",core:!0,body:["Trauma assessment follows an order that treats the fastest killers first. Many systems use <C>ABCDE: catastrophic external haemorrhage first (direct pressure, tourniquets, wound packing, junctional devices), then airway with cervical spine protection, breathing (tension pneumothorax, open chest wounds, flail chest, massive haemothorax), circulation (shock assessment, haemorrhage control, access, blood), disability (GCS, pupils, glucose, lateralising signs) and exposure (full examination, then prevent hypothermia).","Treat each threat as you find it, then move on. Reassess after every intervention and whenever the patient changes. The secondary survey \u2014 a head-to-toe examination and AMPLE history \u2014 follows once immediate threats are controlled, and in transport is often completed en route or at the receiving centre.","Mechanism matters but physiology matters more. Field triage guidelines prioritise physiological criteria (GCS \u2264 13, SBP < 90, abnormal respiratory rate) and anatomical injuries (penetrating injury to head, neck, torso; flail chest; pelvic fractures; two or more long-bone fractures; amputation proximal to wrist or ankle; paralysis) for trauma-centre destination, with mechanism and special considerations (older age, anticoagulation, pregnancy) as additional triggers."]},{id:"efast",title:"Extended FAST",core:!0,body:["eFAST looks for free fluid and air in five areas: right upper quadrant (Morison's pouch between liver and kidney \u2014 usually the first positive window), left upper quadrant (around the spleen, including above it under the diaphragm), pelvis (behind the bladder), pericardium (subxiphoid), and both anterior chest walls for lung sliding (pneumothorax). Free fluid appears as an anechoic (black) stripe.","In an unstable trauma patient, a positive abdominal FAST supports haemorrhage in the abdomen and points toward laparotomy or interventional radiology. A negative FAST does not exclude injury: early in bleeding, too little fluid may be visible; retroperitoneal bleeding (pelvic fractures, kidneys, aorta) does not appear in FAST windows; solid organ injuries without free fluid are missed; obesity and subcutaneous emphysema degrade images. Repeat the scan when the patient changes.",'Absent lung sliding with a "barcode" M-mode suggests pneumothorax; finding a lung point confirms it. Ultrasound detects pneumothorax more sensitively than a supine chest film. A pericardial effusion with haemodynamic compromise after penetrating chest trauma suggests tamponade.']},{id:"imaging",title:"X-ray and CT",core:!0,body:["The classic trauma series is a chest X-ray and pelvic X-ray in resuscitation, with CT for definitive diagnosis in stable patients. The chest film looks for haemothorax (a white-out on a supine film rather than a meniscus), pneumothorax (deep sulcus sign when supine), widened mediastinum, rib fractures, tube positions and subcutaneous emphysema. The pelvic film identifies unstable pelvic fractures (open-book, vertical shear), which bleed into the retroperitoneum and need a binder.",'Whole-body CT finds injuries quickly in stable patients. Unstable patients ("transient" or "non-responders") should not go to CT; they need haemorrhage control in theatre or interventional radiology. In transport, the key question is whether imaging at a non-trauma hospital will change management enough to justify the delay: often it will not, and transfer of a seriously injured patient should not wait for CT that the trauma centre will repeat.','On CT, recognise the critical findings you may be handed: epidural haematoma (biconvex), subdural (crescent), midline shift and herniation, aortic injury, free air, solid organ lacerations with active contrast extravasation ("blush" \u2014 ongoing bleeding), and pelvic haematoma.'],table:{caption:"Haemorrhagic shock classes (ATLS-style, adult)",head:["Class","Blood loss","HR","BP","Mental status"],rows:[["I","< 15 %","Normal","Normal","Normal or anxious"],["II","15\u201330 %","\u2191","Normal (narrow pulse pressure)","Anxious"],["III","30\u201340 %","\u2191\u2191","\u2193","Confused"],["IV","> 40 %","\u2191\u2191\u2191 or \u2193","\u2193\u2193","Lethargic"]]}},{id:"case",title:"Transport case: the ejected driver",body:["A 38-year-old ejected from a rolled vehicle: GCS 13, RR 30, SpO\u2082 89 %, absent breath sounds on the left, BP 84/50, HR 132, pelvis unstable. The referring rural hospital asks whether to obtain a CT before transfer."],example:{case:"Prioritise.",steps:["Breathing: likely left tension pneumothorax or massive haemothorax \u2014 decompress/drain now; eFAST confirms absent sliding or fluid.","Circulation: class III shock; pelvic binder at the greater trochanters; blood products; TXA within 3 hours.","eFAST abdomen for intraperitoneal blood.","No CT: an unstable patient goes directly to the trauma centre for haemorrhage control; send any images already done.","Reassess after each intervention and en route; keep warm."]}}],keyPoints:["<C>ABCDE: catastrophic haemorrhage first, then airway, breathing, circulation, disability, exposure \u2014 treat as found.","eFAST: RUQ, LUQ, pelvis, pericardium, lung sliding; negative does not exclude bleeding.","Retroperitoneal (pelvic, renal, aortic) bleeding is invisible to FAST.","Unstable patients go to haemorrhage control, not CT.","Don't delay transfer of a seriously injured patient for imaging the trauma centre will repeat."],pearls:["Morison's pouch is usually positive first when supine.","A supine haemothorax looks like a diffuse white-out, not a meniscus."],pitfalls:["Reassurance from a negative FAST in an unstable patient.","CT at the referring hospital delaying definitive care."],live:[{id:"abd-fast",label:"FAST: where free blood goes \u2014 and what it misses"},{id:"abd-solid-organ",label:"Spleen and liver injury"}],questions:[{q:"In <C>ABCDE, the <C> stands for:",options:["Cervical collar","Catastrophic haemorrhage","Consciousness","Capnography"],answer:1,why:"Control massive external bleeding first."},{q:"The FAST window usually positive first in a supine patient:",options:["Pelvis","Right upper quadrant (Morison's pouch)","Pericardium","LUQ"],answer:1,why:"Most dependent upper abdominal space."},{q:"A negative FAST in an unstable trauma patient:",options:["Excludes haemorrhage","Does not exclude retroperitoneal or early bleeding","Means no surgery","Requires no reassessment"],answer:1,why:"Known limitations."},{q:"Absent lung sliding with a barcode M-mode suggests:",options:["Haemothorax","Pneumothorax","Normal lung","Contusion"],answer:1,why:"No pleural movement."},{q:"Which is NOT seen on FAST?",options:["Haemoperitoneum","Pericardial blood","Retroperitoneal haematoma from pelvic fracture","Pleural fluid with eFAST"],answer:2,why:"Retroperitoneum is outside FAST windows."},{q:"An unstable trauma patient with a positive FAST should go to:",options:["CT","Haemorrhage control (theatre/IR)","MRI","Ward observation"],answer:1,why:"CT delays definitive care."},{q:"Class III haemorrhage represents blood loss of about:",options:["< 15 %","15\u201330 %","30\u201340 %","> 50 %"],answer:2,why:"Hypotension appears."},{q:"A supine haemothorax on chest film appears as:",options:["A meniscus","Diffuse haziness of the hemithorax","Hyperlucency","Normal"],answer:1,why:"Fluid layers posteriorly."},{q:'Active contrast extravasation ("blush") on CT indicates:',options:["Old haematoma","Ongoing bleeding","Infection","Normal enhancement"],answer:1,why:"Needs intervention."},{q:"A physiological trauma-centre triage criterion:",options:["SBP < 90","Age 40","Ankle fracture","Laceration"],answer:0,why:"Field triage guidelines."},{q:"An open-book pelvic fracture is managed initially with:",options:["Traction","Pelvic binder at the greater trochanters","Log-roll repeatedly","Ice"],answer:1,why:"Reduces pelvic volume and bleeding."},{q:"Ultrasound is more sensitive than ___ for pneumothorax:",options:["CT","Supine chest X-ray","Auscultation in silence","MRI"],answer:1,why:"Supine films miss anterior air."},{q:"Class II haemorrhage typically shows:",options:["Hypotension","Tachycardia with narrowed pulse pressure","Bradycardia","Coma"],answer:1,why:"Compensated shock."},{q:"In the secondary survey, AMPLE includes:",options:["Allergies, Medications, Past history, Last meal, Events","Airway, Mental status, Pulse, Lungs, Extremities","Age, Mechanism, Pain, Location, Exposure","None"],answer:0,why:"Standard history mnemonic."},{q:"Should a hypotensive multi-trauma patient wait for CT at a rural hospital before transfer?",options:["Yes, always","Generally no \u2014 transfer for definitive care","Only for head injuries","Only at night"],answer:1,why:"Avoid delays for imaging that will be repeated."}],sources:[{title:"ACS Committee on Trauma: National guideline for the field triage of injured patients (2021)",url:"https://www.facs.org/quality-programs/trauma/systems/field-triage-guidelines/"},{title:"StatPearls: FAST exam",url:"https://www.ncbi.nlm.nih.gov/books/?term=FAST+exam+StatPearls"}]},qe={id:"fpc-trauma-labs",domain:"trauma",ref:"VII.2",title:"Trauma lab values: coagulopathy, lactate and base deficit",summary:"Trauma-induced coagulopathy, viscoelastic testing, lactate and base deficit as shock markers, and the lab changes of massive transfusion, crush and burns.",objectives:["Recognise trauma-induced coagulopathy and its lab signature.","Use lactate and base deficit to grade shock and track resuscitation.","Anticipate electrolyte changes in massive transfusion, crush and burns."],sections:[{id:"tic",title:"Trauma-induced coagulopathy",core:!0,body:["Up to a quarter of severely injured patients arrive coagulopathic before any fluid is given. Tissue injury and shock activate protein C, consume fibrinogen and promote hyperfibrinolysis; dilution, hypothermia, acidosis and hypocalcaemia then worsen it. Coagulopathy on arrival is associated with markedly higher mortality.","Labs show a prolonged PT/INR (INR above about 1.2\u20131.5 is a common threshold), prolonged aPTT, low fibrinogen (below about 1.5\u20132 g/L, or 150\u2013200 mg/dL, is critical in haemorrhage) and falling platelets. Standard tests take time and reflect plasma, not whole-blood clotting.","Viscoelastic tests (TEG, ROTEM) assess clot formation, strength and breakdown in whole blood within minutes and guide targeted therapy: plasma for slow clot initiation, fibrinogen or cryoprecipitate for weak clot from low fibrinogen, platelets for low maximum strength from platelet deficit, and tranexamic acid for hyperfibrinolysis."]},{id:"shock",title:"Lactate and base deficit",core:!0,body:["Lactate rises with tissue hypoperfusion; an initial lactate above about 4 mmol/L, or failure to clear it, predicts transfusion needs and mortality. Base deficit (negative base excess) reflects metabolic acidosis; a base deficit worse than \u22126 suggests significant shock and transfusion need, and worsening deficit despite resuscitation suggests ongoing bleeding.","Both can be misleading: alcohol raises lactate; normal saline creates a hyperchloraemic acidosis that worsens base deficit without hypoperfusion; epinephrine raises lactate. Use trends with the clinical picture. Haemoglobin is a lagging indicator early after injury \u2014 a normal value does not exclude major bleeding."]},{id:"electrolytes",title:"Electrolytes in trauma",core:!0,body:["Massive transfusion: ionised calcium falls as citrate binds it \u2014 hypocalcaemia worsens coagulation and myocardial contractility, so give calcium early and repeatedly; stored red cells leak potassium (hyperkalaemia) and contain little 2,3-DPG; large volumes cause dilutional thrombocytopenia and coagulopathy.","Crush injury and rhabdomyolysis: hyperkalaemia, hyperphosphataemia, hypocalcaemia, metabolic acidosis, raised creatine kinase and myoglobinuria with risk of acute kidney injury. Burns: early hyperkalaemia from cell lysis, later hypokalaemia; hypoalbuminaemia; and with carbon monoxide or cyanide exposure, raised carboxyhaemoglobin and lactate.","Head injury: sodium disorders (SIADH, cerebral salt wasting, diabetes insipidus) and coagulopathy from released tissue factor. Hyperglycaemia is common and worsens outcomes in brain injury."],table:{caption:"Lab targets in major haemorrhage (common guidance)",head:["Test","Target"],rows:[["Haemoglobin","> 7\u20139 g/dL during active bleeding (clinical judgement)"],["Platelets","> 50 \xD7 10\u2079/L (> 100 in head injury)"],["INR","< 1.5"],["Fibrinogen","> 1.5\u20132 g/L"],["Ionised calcium","> 1.1 mmol/L"],["Temperature","> 36 \xB0C"],["pH","> 7.2"]]}},{id:"case",title:"Transport case: the labs that change the plan",body:["A pedestrian struck by a car: BP 92/58, HR 124 after 2 units of blood. Point-of-care results: Hb 9.4, INR 1.8, fibrinogen 1.1 g/L, lactate 6.8, base deficit \u221210, ionised calcium 0.92, temperature 35.1 \xB0C."],example:{case:"Interpret and act.",steps:["Trauma-induced coagulopathy with low fibrinogen, persistent shock (lactate, base deficit), hypocalcaemia and hypothermia \u2014 the lethal triad in progress.","Balanced transfusion: plasma with red cells; fibrinogen concentrate or cryoprecipitate; platelets as available.","Calcium chloride or gluconate now; active warming and warmed products.","TXA if within 3 hours of injury; expedite surgical haemorrhage control."]}}],keyPoints:["Trauma-induced coagulopathy is present early in up to a quarter of major trauma.","Low fibrinogen is critical \u2014 replace with fibrinogen concentrate or cryoprecipitate.","Viscoelastic tests guide targeted product therapy and detect hyperfibrinolysis.","Lactate > 4 or base deficit worse than \u22126 suggests significant shock; trends matter.","Massive transfusion lowers calcium and raises potassium; crush raises potassium and CK."],pearls:["Saline worsens base deficit without hypoperfusion.","Haemoglobin lags behind acute blood loss."],pitfalls:["Waiting for formal coagulation results before giving plasma in massive haemorrhage.","Forgetting calcium."],live:[{id:"labs-coag",label:"Clotting labs and reversal"},{id:"lactate",label:"Lactate: made and cleared"}],questions:[{q:"Proportion of major trauma patients coagulopathic on arrival:",options:["< 1 %","Up to about 25 %","75 %","100 %"],answer:1,why:"Acute traumatic coagulopathy."},{q:"Critical fibrinogen level in haemorrhage:",options:["< 4 g/L","< 1.5\u20132 g/L","< 0.1 g/L only","Not relevant"],answer:1,why:"Replace below this threshold."},{q:"Viscoelastic testing detects:",options:["Only platelet count","Clot formation, strength and lysis in whole blood","Potassium","Lactate"],answer:1,why:"TEG and ROTEM assess whole-blood clotting."},{q:"Base deficit worse than \u22126 suggests:",options:["Normal physiology","Significant shock and transfusion need","Alkalosis","Dehydration only"],answer:1,why:"Metabolic acidosis from hypoperfusion."},{q:"Which raises lactate without hypoperfusion?",options:["Alcohol intoxication","Hypothermia only","Morphine","Normal saline"],answer:0,why:"Ethanol metabolism raises lactate."},{q:"Normal saline resuscitation tends to:",options:["Improve base deficit","Worsen base deficit via hyperchloraemia","Raise calcium","Lower chloride"],answer:1,why:"Hyperchloraemic acidosis."},{q:"Citrate in transfused blood causes:",options:["Hypercalcaemia","Hypocalcaemia","Hypokalaemia","Hyponatraemia"],answer:1,why:"Binds calcium."},{q:"Crush injury labs typically show:",options:["Low potassium, low CK","High potassium, high CK, myoglobinuria","High calcium","Alkalosis"],answer:1,why:"Muscle breakdown."},{q:"Platelet target in traumatic brain injury haemorrhage:",options:["> 20","> 50","> 100","> 400 \xD7 10\u2079/L"],answer:2,why:"Higher threshold for intracranial bleeding."},{q:"TEG showing weak clot strength from low fibrinogen is treated with:",options:["Platelets","Fibrinogen concentrate or cryoprecipitate","TXA only","Heparin"],answer:1,why:"Targeted therapy."},{q:"Ionised calcium target in massive transfusion:",options:["> 0.5","> 1.1 mmol/L","> 2.5","Not monitored"],answer:1,why:"Supports coagulation and contractility."},{q:"Haemoglobin in early haemorrhage:",options:["Falls immediately","Lags behind blood loss","Rises","Is diagnostic"],answer:1,why:"Concentration unchanged until dilution."},{q:"Worsening base deficit despite resuscitation suggests:",options:["Recovery","Ongoing bleeding","Overhydration","Lab error always"],answer:1,why:"Persistent hypoperfusion."},{q:"Early burn electrolyte abnormality:",options:["Hypokalaemia","Hyperkalaemia from cell lysis","Hypernatraemia","Hypercalcaemia"],answer:1,why:"Cell destruction releases potassium."},{q:"INR threshold commonly targeted in major haemorrhage:",options:["< 3","< 1.5","< 0.5","> 2"],answer:1,why:"Correct coagulopathy."}],sources:[{title:"European guideline on management of major bleeding and coagulopathy following trauma (6th ed., 2023)",url:"https://ccforum.biomedcentral.com/articles/10.1186/s13054-023-04327-7"},{title:"StatPearls: Trauma-induced coagulopathy",url:"https://www.ncbi.nlm.nih.gov/books/?term=Trauma-induced+coagulopathy+StatPearls"}]},Ve={id:"fpc-trauma-pharm",domain:"trauma",ref:"VII.3",title:"Trauma pharmacology: TXA, analgesia, RSI, reversal and antibiotics",summary:"Tranexamic acid, analgesia and sedation in injured patients, induction choices in haemorrhagic shock and head injury, anticoagulant reversal, calcium, and antibiotics for open fractures.",objectives:["Give TXA with correct timing and dose.","Choose analgesic and induction agents that preserve perfusion.","Reverse anticoagulants and give prophylactic antibiotics appropriately."],sections:[{id:"txa",title:"Tranexamic acid",core:!0,body:["TXA is an antifibrinolytic: it blocks the lysine-binding sites on plasminogen, preventing clot breakdown. In bleeding trauma patients it reduced death from bleeding when given within 3 hours of injury, with the greatest benefit in the first hour; given after 3 hours it showed no benefit and possible harm. The adult regimen used in major trials is 1 g IV over 10 minutes followed by 1 g over 8 hours; some prehospital systems give a 2 g bolus.","TXA is also used in traumatic brain injury (mild to moderate TBI within 3 hours) and postpartum haemorrhage. Side effects include rare seizures at high doses and theoretical thrombosis. Record the time of injury and the time of administration \u2014 the receiving team needs both."]},{id:"analgesia",title:"Analgesia and sedation",core:!0,body:["Pain worsens physiology and outcomes; treat it. Fentanyl (1 mcg/kg IV/IN, titrated) has a rapid onset and less histamine release and hypotension than morphine. Ketamine at analgesic doses (0.1\u20130.3 mg/kg IV) preserves blood pressure and airway reflexes and works well in shocked or hypotensive patients and for splinting and extrication. Morphine causes histamine release and hypotension in hypovolaemia. Regional anaesthesia (for example, fascia iliaca block for hip fractures) reduces opioid need where trained.","Avoid NSAIDs in bleeding or renal injury. In head injury, avoid oversedation that obscures neurological examination unless the patient is intubated; avoid hypotension at all costs."]},{id:"rsi",title:"Airway drugs in trauma",core:!0,body:["Haemorrhagic shock: resuscitate with blood before induction where possible; use a reduced dose of ketamine or etomidate; keep the paralytic dose full (rocuronium 1.2 mg/kg or more; succinylcholine 1.5\u20132 mg/kg if not contraindicated). Post-intubation hypotension is common \u2014 positive pressure reduces venous return in an empty circulation.","Traumatic brain injury: avoid hypotension (a single systolic below 90 or 110 in some guidelines worsens outcome) and hypoxia. Ketamine is acceptable and maintains pressure. Succinylcholine is safe early after injury (hyperkalaemia risk appears after about 24\u201372 hours with burns, crush and denervation). An opioid helps blunt the pressor response to laryngoscopy if blood pressure allows."],table:{caption:"Drug choices by scenario",head:["Scenario","Induction","Paralytic","Analgesia"],rows:[["Haemorrhagic shock","Ketamine (reduced)","Rocuronium full dose","Ketamine, fentanyl (small)"],["Isolated TBI, normotensive","Ketamine or etomidate","Rocuronium or succinylcholine","Fentanyl"],["Burns > 24\u201372 h","Ketamine","Rocuronium (no succinylcholine)","Fentanyl, ketamine"],["Crush with hyperkalaemia","Ketamine","Rocuronium","Fentanyl"]]}},{id:"reversal",title:"Anticoagulants, calcium and antibiotics",body:["Older trauma patients frequently take anticoagulants or antiplatelets; even minor head injuries can bleed. Warfarin: 4-factor PCC plus IV vitamin K. Dabigatran: idarucizumab. Factor Xa inhibitors: andexanet alfa or PCC per protocol. Heparin: protamine. Antiplatelet reversal is limited; platelet transfusion is selective.","Calcium: give early in massive transfusion (for example calcium chloride 1 g with every few units, or per protocol). Open fractures: give IV antibiotics (commonly a first-generation cephalosporin such as cefazolin, with gram-negative coverage for heavily contaminated wounds per protocol) as early as possible \u2014 ideally within an hour \u2014 and update tetanus status."],example:{case:"An 82-year-old on apixaban falls and hits her head: GCS 14, headache, vomiting once.",steps:['High risk of intracranial haemorrhage despite a "minor" mechanism.',"Transport to a centre with CT and neurosurgery.","Reversal per protocol once haemorrhage is confirmed (or empirically if deteriorating).","Avoid hypotension; repeat neuro checks frequently."]}}],keyPoints:["TXA 1 g over 10 min then 1 g over 8 h, within 3 h of injury (earlier is better).","Fentanyl or analgesic ketamine for shocked patients; avoid morphine-induced hypotension and NSAIDs.","Haemorrhagic shock: reduced induction dose, full paralytic dose, blood first.","TBI: avoid any hypotension or hypoxia; succinylcholine is safe early.","Reverse anticoagulants per agent; give calcium in massive transfusion; antibiotics within an hour for open fractures."],pearls:["Record injury time and TXA time.","Anticoagulated elders with minor head injury need imaging."],pitfalls:["TXA beyond 3 hours.","Full-dose induction in a bleeding patient."],live:[{id:"moa-txa",label:"Tranexamic acid: mechanism"},{id:"moa-ketamine",label:"Ketamine: mechanism"},{id:"moa-pcc",label:"PCC: mechanism"}],questions:[{q:"TXA should be given within:",options:["1 day","3 hours of injury","12 hours","Any time"],answer:1,why:"Later use showed harm."},{q:"Standard trauma TXA regimen:",options:["100 mg once","1 g over 10 min then 1 g over 8 h","5 g bolus","1 g daily for 7 days"],answer:1,why:"CRASH-2 regimen."},{q:"TXA works by:",options:["Activating factor VII","Blocking plasminogen lysine-binding sites","Binding heparin","Platelet activation"],answer:1,why:"Antifibrinolytic."},{q:"Analgesic least likely to cause hypotension in a hypovolaemic patient:",options:["Morphine","Ketamine","Propofol","Midazolam"],answer:1,why:"Sympathomimetic."},{q:"Analgesic-dose ketamine:",options:["1\u20132 mg/kg","0.1\u20130.3 mg/kg","5 mg/kg","10 mg/kg"],answer:1,why:"Sub-dissociative."},{q:"In haemorrhagic shock RSI, the paralytic dose should be:",options:["Halved","Full or increased","Omitted","Doubled induction instead"],answer:1,why:"Slow circulation delays onset."},{q:"Succinylcholine in acute TBI within hours of injury:",options:["Contraindicated","Acceptable","Causes immediate hyperkalaemia always","Raises ICP permanently"],answer:1,why:"Up-regulation develops later."},{q:"Succinylcholine becomes dangerous in burns after about:",options:["1 hour","24\u201372 hours","6 months only","Never"],answer:1,why:"Receptor up-regulation."},{q:"A single SBP below about ___ worsens TBI outcomes:",options:["150","90","60","200"],answer:1,why:"Avoid hypotension."},{q:"Warfarin reversal in trauma haemorrhage:",options:["Protamine","PCC + IV vitamin K","Idarucizumab","Platelets"],answer:1,why:"Rapid factor replacement."},{q:"Open fracture antibiotics should start:",options:["Within 24 h","As early as possible, ideally within 1 h","Only after surgery","Not needed"],answer:1,why:"Reduces infection."},{q:"NSAIDs in a bleeding trauma patient:",options:["First-line","Avoid","Required","Neutral"],answer:1,why:"Impair platelets and kidneys."},{q:"Calcium in massive transfusion is given:",options:["Never","Early and repeatedly","Only if K\u207A low","After 20 units"],answer:1,why:"Citrate-induced hypocalcaemia."},{q:"Morphine may cause hypotension through:",options:["Bradycardia only","Histamine release and venodilation","Hyperkalaemia","Vasoconstriction"],answer:1,why:"Particularly in hypovolaemia."},{q:"Dabigatran reversal:",options:["Andexanet","Idarucizumab","Protamine","Vitamin K"],answer:1,why:"Specific antibody fragment."}],sources:[{title:"CRASH-2 trial. Lancet (2010)",url:"https://pubmed.ncbi.nlm.nih.gov/20554319/"},{title:"CRASH-3: TXA in traumatic brain injury. Lancet (2019)",url:"https://pubmed.ncbi.nlm.nih.gov/31623894/"},{title:"Brain Trauma Foundation guidelines (4th ed.)",url:"https://braintrauma.org/coma/guidelines"}]};var Le={id:"fpc-trauma-monitor",domain:"trauma",ref:"VII.4",title:"Monitoring the injured patient in transport",summary:"What to watch and why: blood pressure and shock index, capnography as a perfusion signal, temperature, compartment and pelvic checks, chest tubes, and the limits of monitors in a moving aircraft.",objectives:["Choose and interpret monitoring that detects ongoing haemorrhage early.","Use EtCO\u2082, shock index and temperature as resuscitation markers.","Monitor chest drains, splints, tourniquets and binders during transport."],sections:[{id:"haemo",title:"Haemodynamic monitoring",core:!0,body:["Non-invasive blood pressure cuffs are slow, fail with vibration and motion, and become unreliable at low pressures \u2014 exactly when accuracy matters. An arterial line gives beat-to-beat pressure and a waveform; in a patient already lined at the referring hospital, keep it transduced, levelled at the phlebostatic axis and zeroed after any change in altitude or position. Pulse pressure variation on an arterial trace in a ventilated patient suggests fluid (blood) responsiveness.","Shock index \u2014 heart rate divided by systolic pressure \u2014 above about 1.0 suggests significant blood loss even when the systolic pressure looks acceptable. Young, fit patients compensate until late; older patients and those on beta-blockers may not mount a tachycardia at all. Trends tell more than single values: a rising heart rate and a narrowing pulse pressure across the flight are a warning.",'Permissive hypotension is a deliberate target in penetrating torso trauma without head injury: a systolic around 80\u201390 mmHg (or a palpable radial pulse and mentation) until surgical control, to avoid "popping the clot". It does not apply to traumatic brain injury, where a systolic of at least 100\u2013110 is the aim.']},{id:"etco2",title:"Capnography, oxygenation and temperature",core:!0,body:["In an intubated patient with stable ventilation, end-tidal CO\u2082 reflects cardiac output: a falling EtCO\u2082 with no change in ventilator settings suggests falling perfusion \u2014 ongoing bleeding, tension pneumothorax, tamponade or a pulmonary embolism. An abrupt drop to near zero is tube displacement or arrest until proven otherwise. In TBI, aim for normocapnia (EtCO\u2082 about 35\u201340 mmHg, confirmed against a blood gas, as the arterial\u2013end-tidal gap widens in shock).","Pulse oximetry fails in cold, vasoconstricted, shocked patients; a poor plethysmograph is itself a sign of hypoperfusion. Try an ear or forehead probe. Carbon monoxide gives falsely normal SpO\u2082 readings.","Measure core temperature from the start and repeatedly. Hypothermia below 35 \xB0C worsens coagulopathy and acidosis; aircraft cabins, rotor wash, wet clothes, cold blood products and exposure for examination all drain heat. A temperature probe is as important as a blood pressure cuff in major trauma."]},{id:"devices",title:"Devices and limbs",core:!0,body:["Chest drains: record output at handover and in flight. More than 1500 mL initially, or more than about 200 mL/hour for 2\u20134 hours, suggests the need for thoracotomy. Check the system is patent, unclamped and below the chest; bubbling (air leak) and tidalling (swing) tell you the tube is in the pleural space. A sudden stop in drainage with deterioration may mean a clotted tube and a re-accumulating haemothorax.","Tourniquets: note the time applied, check that distal bleeding and pulses have stopped, and do not loosen them in flight. Pelvic binders: confirm position over the greater trochanters, not the iliac crests. Splints: check distal pulses, sensation and capillary refill before and after every move. Compartment syndrome \u2014 pain out of proportion, pain on passive stretch, tense compartments \u2014 progresses in transport; pulses are lost late.","Altitude changes the behaviour of air-filled devices: endotracheal tube cuffs, pneumatic splints and MAST garments expand on ascent. Check cuff pressures and splint tightness during climb and soften them as needed; reinflate on descent."],table:{caption:"Monitoring targets in major trauma (adult)",head:["Parameter","Target"],rows:[["SBP \u2014 penetrating torso, no TBI","80\u201390 mmHg until haemorrhage control"],["SBP \u2014 TBI","\u2265 100\u2013110 mmHg"],["SpO\u2082","\u2265 94 % (avoid hypoxia)"],["EtCO\u2082 \u2014 TBI","35\u201340 mmHg (check against PaCO\u2082)"],["Temperature","> 36 \xB0C"],["Urine output","\u2265 0.5 mL/kg/h"],["Shock index","< 1.0"]]}}],keyPoints:['Shock index > 1.0 suggests significant haemorrhage despite a "normal" BP.',"Falling EtCO\u2082 with constant ventilation suggests falling cardiac output.","Permissive hypotension for penetrating torso trauma, never for TBI.","Chest tube output > 1500 mL initially or > 200 mL/h suggests thoracotomy.","Measure core temperature from the start; expanding air in cuffs and splints on ascent."],pearls:["A poor pleth trace is itself a perfusion sign.","Zero the arterial line after altitude changes."],pitfalls:["Trusting NIBP in vibration and shock.",'Loosening a tourniquet in flight to "check".'],live:[{id:"ln-art",label:"The arterial line"},{id:"ln-level",label:"Levelling and zeroing"},{id:"wf-chest-tube",label:"Chest drain workflow"}],questions:[{q:"Shock index is calculated as:",options:["SBP \xF7 HR","HR \xF7 SBP","MAP \xF7 HR","HR \xD7 SBP"],answer:1,why:"Above about 1.0 is concerning."},{q:"A falling EtCO\u2082 with unchanged ventilation suggests:",options:["Hyperventilation","Falling cardiac output","Improving perfusion","Fever"],answer:1,why:"CO\u2082 delivery to lungs drops."},{q:"Permissive hypotension is appropriate for:",options:["Isolated TBI","Penetrating torso trauma without TBI","Spinal cord injury","Elderly falls"],answer:1,why:"Avoids disrupting clot before control."},{q:"SBP target in TBI:",options:["70","\u2265 100\u2013110 mmHg","80\u201390","< 90"],answer:1,why:"Hypotension worsens secondary injury."},{q:"Initial chest tube output suggesting thoracotomy:",options:["200 mL","> 1500 mL","500 mL","Any blood"],answer:1,why:"Massive haemothorax."},{q:"Pelvic binders should sit over:",options:["Iliac crests","Greater trochanters","Umbilicus","Knees"],answer:1,why:"Effective reduction of pelvic volume."},{q:"On ascent, ETT cuffs and air splints:",options:["Shrink","Expand","Unchanged","Leak always"],answer:1,why:"Boyle's law."},{q:"An early sign of compartment syndrome:",options:["Absent pulse","Pain on passive stretch","Pallor only","Paralysis"],answer:1,why:"Pulselessness is late."},{q:"Hypothermia threshold that worsens coagulopathy:",options:["< 38 \xB0C","< 35 \xB0C","< 30 \xB0C only","None"],answer:1,why:"Enzyme function falls."},{q:"Pulse oximetry in a cold, shocked patient:",options:["Always accurate","Often unreliable","Over-reads hypoxia","Measures CO"],answer:1,why:"Poor peripheral perfusion."},{q:"Sudden cessation of chest drain output with deterioration:",options:["Recovery","Possible clotted tube and re-accumulation","Normal","Air leak"],answer:1,why:"Check the tube."},{q:"An abrupt EtCO\u2082 drop to near zero:",options:["Hyperventilation","Tube displacement or arrest","Fever","Sedation"],answer:1,why:"Check tube and pulse."},{q:"A tourniquet applied before your arrival should be:",options:["Loosened to check bleeding","Left on, time noted, checked for effectiveness","Removed","Replaced with a dressing"],answer:1,why:"Conversion is a hospital decision."},{q:"Pulse pressure variation in a ventilated patient suggests:",options:["Fluid responsiveness","Pneumothorax","Overload","Arrhythmia"],answer:0,why:"Preload dependence."},{q:"Urine output target in resuscitation (adult, non-burn):",options:["0.1 mL/kg/h","\u2265 0.5 mL/kg/h","5 mL/kg/h","None"],answer:1,why:"Marker of end-organ perfusion."}],sources:[{title:"StatPearls: Permissive hypotension",url:"https://www.ncbi.nlm.nih.gov/books/?term=Permissive+hypotension+StatPearls"},{title:"StatPearls: Shock index",url:"https://www.ncbi.nlm.nih.gov/books/?term=Shock+index+StatPearls"}]},He={id:"fpc-trauma-surgical",domain:"trauma",ref:"VII.5",title:"Surgical interventions: decompression, drains, escharotomy and fasciotomy",summary:"Procedures a flight crew performs or must understand: needle and finger thoracostomy, chest tubes, pericardiocentesis, escharotomy and fasciotomy, REBOA, damage control surgery and resuscitative thoracotomy.",objectives:["Recognise tension pneumothorax and decompress it correctly.","Describe indications and landmarks for chest drains, escharotomy and pericardiocentesis.","Explain damage control surgery and when REBOA or thoracotomy apply."],sections:[{id:"decompress",title:"Chest decompression",core:!0,body:["Tension pneumothorax is a clinical diagnosis: respiratory distress or, in ventilated patients, rising airway pressures and falling SpO\u2082, with hypotension, absent breath sounds on one side and, late, tracheal deviation and distended neck veins. Do not wait for imaging. In ventilated patients, positive pressure turns a simple pneumothorax into a tension quickly \u2014 after intubation, suspect it first when the patient deteriorates.","Needle decompression: a long (at least 8 cm in most adults) large-bore catheter at the 4th or 5th intercostal space in the anterior or mid-axillary line, or the 2nd intercostal space mid-clavicular line. The lateral site has a thinner chest wall and lower failure rates. Needles kink, dislodge and block, so recurrence after needle decompression should prompt finger thoracostomy or a chest tube.","Finger (simple) thoracostomy in ventilated patients: an incision and blunt dissection over the top of the rib in the 4th\u20135th space, mid-axillary line, into the pleura, sweeping with a finger. It is definitive decompression; a chest tube can follow. In spontaneously breathing patients an open thoracostomy creates an open pneumothorax, so a chest tube is placed instead."]},{id:"drains",title:"Chest tubes, pericardiocentesis and escharotomy",core:!0,body:['Chest tubes go in the "triangle of safety" \u2014 bordered by the lateral edge of pectoralis major, the anterior edge of latissimus dorsi and a line at the level of the nipple (5th intercostal space) \u2014 above the rib to avoid the neurovascular bundle. Use a large tube for haemothorax. Before flight, secure it well, connect it to a closed system or one-way valve, and never clamp it in a patient with an air leak.',"Pericardial tamponade after penetrating chest trauma needs surgical decompression (thoracotomy or pericardial window); needle pericardiocentesis is a temporising measure because clotted blood often will not aspirate. Under ultrasound guidance, the subxiphoid approach aims toward the left shoulder.","Escharotomy releases circumferential full-thickness burns that restrict chest movement (rising airway pressures, failing ventilation) or limb perfusion. Incisions run through the eschar in the mid-lateral and mid-medial lines of limbs and, for the chest, along the anterior axillary lines joined across the costal margin. Fasciotomy, by contrast, opens the fascia for compartment syndrome and is a surgical procedure."]},{id:"damage",title:"Damage control and last-ditch interventions",core:!0,body:["Damage control surgery stops bleeding and contamination with the shortest possible operation \u2014 packing, shunts, stapling bowel \u2014 then moves to ICU for warming, correction of coagulopathy and acidosis, with definitive repair 24\u201348 hours later. It exists because the lethal triad kills patients during long operations. Damage control resuscitation is its partner: permissive hypotension, early balanced blood products, minimal crystalloid and TXA.","REBOA (resuscitative endovascular balloon occlusion of the aorta) inflates a balloon via the femoral artery: zone I (descending thoracic aorta) for abdominal haemorrhage, zone III (infrarenal) for pelvic haemorrhage. It buys minutes at the cost of ischaemia below the balloon and is used only in specific systems.","Resuscitative thoracotomy \u2014 opening the chest to relieve tamponade, cross-clamp the aorta and control bleeding \u2014 is most effective for penetrating chest trauma with recent loss of signs of life. Survival after blunt trauma arrest is very low."],list:{caption:"Traumatic arrest: treat the reversible causes",items:["Hypovolaemia \u2014 control haemorrhage, blood","Hypoxia \u2014 airway and ventilation","Tension pneumothorax \u2014 bilateral decompression","Tamponade \u2014 thoracotomy or pericardiocentesis"]}},{id:"case",title:"Transport case: the ventilated patient who crashes",body:["A 25-year-old with left rib fractures was intubated at a rural hospital. Ten minutes into flight: peak pressure rises from 24 to 42 cmH\u2082O, SpO\u2082 falls to 82 %, BP 70/40, left breath sounds absent."],example:{case:"Act.",steps:["DOPES: tube position confirmed by waveform capnography; no obstruction with suction.","Tension pneumothorax on the left \u2014 needle decompression (lateral 4th\u20135th ICS) or finger thoracostomy.","If it recurs or the needle blocks, finger thoracostomy; then a chest tube when conditions allow.","Reassess pressures, SpO\u2082 and BP; consider bilateral decompression if a traumatic arrest follows."]}}],keyPoints:["Tension pneumothorax is clinical \u2014 treat without imaging.","Lateral (4th\u20135th ICS, AAL/MAL) decompression has lower failure rates.","Finger thoracostomy in ventilated patients; chest tube in spontaneously breathing.","Escharotomy for circumferential full-thickness burns restricting ventilation or perfusion.","Damage control: short operation, ICU correction, return later."],pearls:["After intubation, deterioration = tension until proven otherwise.","Clotted blood in tamponade often won't aspirate."],pitfalls:["A needle that is too short for the chest wall.","Clamping a chest tube with an air leak."],live:[{id:"vent-tension-ptx",label:"Tension pneumothorax on the ventilator"},{id:"vent-needle",label:"Needle decompression"}],questions:[{q:"Tension pneumothorax is diagnosed:",options:["By chest X-ray only","Clinically","By CT","By ABG"],answer:1,why:"Do not delay for imaging."},{q:"Needle decompression site with lower failure rates:",options:["2nd ICS MCL","4th\u20135th ICS anterior/mid-axillary line","8th ICS posterior","Subxiphoid"],answer:1,why:"Thinner chest wall laterally."},{q:"Finger thoracostomy is suited to:",options:["Spontaneously breathing patients","Ventilated patients","Children only","Tamponade"],answer:1,why:"Positive pressure keeps lung inflated."},{q:"Chest tubes enter:",options:["Below the rib","Above the rib","Through the rib","At the nipple medially"],answer:1,why:"Avoid the neurovascular bundle."},{q:"The triangle of safety lies between:",options:["Sternum and clavicle","Pectoralis major, latissimus dorsi, and the 5th ICS line","Scapula and spine","Diaphragm and liver"],answer:1,why:"Landmarks for drains."},{q:"Definitive treatment for traumatic tamponade:",options:["Fluids","Surgical decompression","Diuretics","Pericardiocentesis alone always"],answer:1,why:"Clotted blood may not aspirate."},{q:"Escharotomy is indicated for:",options:["Superficial burns","Circumferential full-thickness burns restricting ventilation or perfusion","Partial burns of the face","Any burn > 10 %"],answer:1,why:"Releases constriction."},{q:"Damage control surgery aims to:",options:["Complete all repairs","Control bleeding and contamination briefly, then correct physiology","Avoid surgery","Delay all care"],answer:1,why:"Avoid the lethal triad."},{q:"REBOA zone III occlusion targets:",options:["Abdominal bleeding","Pelvic haemorrhage","Head injury","Chest bleeding"],answer:1,why:"Infrarenal aorta."},{q:"Resuscitative thoracotomy is most effective in:",options:["Blunt arrest > 15 min","Penetrating chest trauma with recent loss of signs of life","Isolated TBI","Burns"],answer:1,why:"Highest survival."},{q:"A recurrent tension after needle decompression:",options:["Repeat needle forever","Proceed to finger thoracostomy or chest tube","Ignore","Clamp"],answer:1,why:"Needles block and dislodge."},{q:"Compartment syndrome treatment:",options:["Escharotomy","Fasciotomy","Elevation alone","Ice"],answer:1,why:"Opens the fascia."},{q:"In traumatic arrest, the reversible causes prioritised are:",options:["Hypoglycaemia","Hypovolaemia, hypoxia, tension, tamponade","Hyperkalaemia","Toxins"],answer:1,why:"Treat these first."},{q:"Damage control resuscitation includes:",options:["High-volume crystalloid","Permissive hypotension, early balanced blood, TXA","Vasopressors first","Delay transfusion"],answer:1,why:"Partner to damage control surgery."},{q:"Minimum needle length for adult decompression (commonly cited):",options:["2.5 cm","\u2265 8 cm","1 cm","20 cm"],answer:1,why:"Shorter needles often fail."}],sources:[{title:"StatPearls: Tension pneumothorax",url:"https://www.ncbi.nlm.nih.gov/books/?term=Tension+pneumothorax+StatPearls"},{title:"StatPearls: Escharotomy",url:"https://www.ncbi.nlm.nih.gov/books/?term=Escharotomy+StatPearls"},{title:"StatPearls: Damage control resuscitation",url:"https://www.ncbi.nlm.nih.gov/books/?term=Damage+control+resuscitation+StatPearls"}]},Oe={id:"fpc-trauma-blood",domain:"trauma",ref:"VII.6",title:"Blood product administration and massive transfusion",summary:"Prehospital blood, whole blood, balanced 1:1:1 resuscitation, massive transfusion protocols, warming, compatibility and transfusion reactions in the injured patient.",objectives:["Describe balanced resuscitation and the evidence behind it.","Activate and run a massive transfusion protocol in transport.","Recognise and manage transfusion complications."],sections:[{id:"balanced",title:"Balanced resuscitation",core:!0,body:["Haemorrhaging patients lose whole blood, and replacing it with crystalloid dilutes clotting factors, platelets and oxygen-carrying capacity while worsening acidosis and hypothermia. Damage control resuscitation replaces like with like: red cells, plasma and platelets in roughly 1:1:1 ratio, or low-titre group O whole blood where available. Crystalloid is minimised.","The PROPPR trial compared 1:1:1 with 1:1:2 ratios; there was no difference in 24-hour or 30-day mortality, but more patients achieved haemostasis and fewer died from exsanguination in the first 24 hours in the 1:1:1 group. The PAMPer trial found that prehospital plasma during air medical transport reduced 30-day mortality in patients at risk of haemorrhagic shock, and later analyses suggest prehospital red cells with plasma may be most beneficial.","Whole blood \u2014 low-titre group O (with low anti-A and anti-B titres) \u2014 provides all components in one bag, is used increasingly by civilian air services and the military, and simplifies logistics in an aircraft."]},{id:"mtp",title:"Massive transfusion protocols",core:!0,body:["Massive transfusion is often defined as 10 or more units of red cells in 24 hours, or more than 3\u20134 units in an hour. Prediction scores trigger the protocol early: the ABC score gives one point each for penetrating mechanism, SBP \u2264 90, HR \u2265 120 and positive FAST \u2014 two or more predicts massive transfusion. Shock index above 1.0 is also used.","In flight: use group O red cells (O-negative for women of childbearing age where supply allows; O-positive is acceptable for men and for older women), group AB or low-titre A plasma, and warm every product with an inline fluid warmer. Give calcium early. Document unit numbers, times and vital signs; the blood bank needs the paperwork back.","Pressure infusers and rapid infusers speed delivery. Use large-bore peripheral access or intraosseous access (humeral IO is faster than tibial); flow through IO is slower than through a large peripheral cannula."],table:{caption:"Product compatibility for emergency release",head:["Product","Universal donor","Notes"],rows:[["Red cells","O (O-negative for childbearing females)","Recipient plasma antibodies matter less in emergency"],["Plasma","AB (or low-titre A)","Donor plasma antibodies matter"],["Platelets","Any group, ideally type-specific","Stored warm, short shelf life"],["Cryoprecipitate","Any group","Fibrinogen, factor VIII, vWF"],["Whole blood","Low-titre group O","All components in one"]]}},{id:"reactions",title:"Transfusion complications",core:!0,body:["Acute haemolytic reaction (ABO incompatibility): fever, hypotension, back or chest pain, haemoglobinuria and DIC \u2014 stop the transfusion, support circulation and send the bag back. Febrile non-haemolytic reactions are common and benign but are diagnosed only after excluding haemolysis and sepsis. Allergic reactions range from urticaria (antihistamine; may continue) to anaphylaxis (stop; epinephrine).","Transfusion-related acute lung injury (TRALI) presents within 6 hours as non-cardiogenic pulmonary oedema with hypoxia and often hypotension; transfusion-associated circulatory overload (TACO) presents as cardiogenic oedema with hypertension in patients with poor cardiac reserve. Massive transfusion also brings hypothermia, hypocalcaemia, hyperkalaemia and dilutional coagulopathy."]}],keyPoints:["Replace whole blood loss with balanced products or whole blood; minimise crystalloid.","PROPPR: 1:1:1 improved haemostasis and early exsanguination deaths.","PAMPer: prehospital plasma in air transport reduced 30-day mortality.","ABC score \u2265 2 predicts massive transfusion.","O red cells, AB plasma; warm everything; give calcium; document units."],pearls:["Low-titre group O whole blood simplifies aircraft logistics.","Humeral IO flows faster than tibial."],pitfalls:['Crystalloid "bridging" until blood arrives.',"Cold products straight from the cooler."],live:[{id:"lines-haemorrhage-transfusion",label:"Haemorrhage and transfusion"},{id:"wf-blood",label:"Giving blood: workflow"},{id:"moa-calcium",label:"Calcium: mechanism"}],questions:[{q:"Balanced resuscitation targets a ratio of plasma:platelets:red cells of about:",options:["1:1:1","1:4:10","0:0:1","3:1:1"],answer:0,why:"Replaces whole blood."},{q:"PROPPR showed 1:1:1 compared with 1:1:2:",options:["Higher 30-day mortality","Better haemostasis and fewer early exsanguination deaths","More TRALI","No difference in anything"],answer:1,why:"24-h exsanguination reduced."},{q:"PAMPer studied:",options:["Prehospital plasma in air transport","TXA","Whole blood in children","Crystalloid"],answer:0,why:"Reduced 30-day mortality."},{q:"Universal donor plasma:",options:["O","AB","A only","B"],answer:1,why:"No anti-A or anti-B."},{q:"ABC score components include:",options:["Age, BP, GCS","Penetrating mechanism, SBP \u2264 90, HR \u2265 120, positive FAST","Lactate, Hb, INR","Temperature, RR, SpO\u2082"],answer:1,why:"\u2265 2 predicts MT."},{q:"Massive transfusion is often defined as:",options:["2 units in 24 h","\u2265 10 units red cells in 24 h","1 unit/h","20 units in a week"],answer:1,why:"Common definition."},{q:"O-negative red cells are prioritised for:",options:["Older men","Women of childbearing age","Children only","Everyone always"],answer:1,why:"Prevent Rh sensitisation."},{q:"TRALI presents as:",options:["Hypertension and cardiogenic oedema","Non-cardiogenic pulmonary oedema within 6 h","Rash only","Hyperkalaemia"],answer:1,why:"Antibody-mediated lung injury."},{q:"TACO differs from TRALI by:",options:["Hypertension and volume overload","Fever","Hypotension","Occurring only with platelets"],answer:0,why:"Cardiogenic."},{q:"First step in a suspected acute haemolytic reaction:",options:["Slow the rate","Stop the transfusion","Give more blood","Antihistamine only"],answer:1,why:"Stop exposure."},{q:"Cryoprecipitate provides mainly:",options:["Red cells","Fibrinogen, factor VIII, vWF","Platelets","Albumin"],answer:1,why:"Concentrated factors."},{q:"Blood products in flight should be:",options:["Given cold","Warmed inline","Diluted with saline","Given via pressure only"],answer:1,why:"Prevent hypothermia."},{q:"Platelets are stored:",options:["Frozen","At room temperature with agitation","Refrigerated","Dried"],answer:1,why:"Short shelf life."},{q:"Low-titre group O whole blood:",options:["Contains only plasma","Provides all components in one unit","Requires crossmatch","Is never used civilianly"],answer:1,why:"Increasingly used by air services."},{q:"A complication of massive transfusion:",options:["Hypercalcaemia","Hypocalcaemia","Hypothermia never","Thrombocytosis"],answer:1,why:"Citrate binding."}],sources:[{title:"PROPPR trial. JAMA (2015)",url:"https://pubmed.ncbi.nlm.nih.gov/25647203/"},{title:"PAMPer trial. NEJM (2018)",url:"https://pubmed.ncbi.nlm.nih.gov/30044935/"},{title:"StatPearls: Massive transfusion",url:"https://www.ncbi.nlm.nih.gov/books/?term=Massive+transfusion+StatPearls"}]};var Ee={id:"fpc-lethal-triad",domain:"trauma",ref:"VII.7",title:"The lethal triad: hypothermia, acidosis and coagulopathy",summary:"How hypothermia, acidosis and coagulopathy feed each other in bleeding patients, why hypocalcaemia is now called the fourth corner, and how a transport crew breaks the cycle.",objectives:["Explain the mechanism by which each corner of the triad worsens the others.","Prevent and treat hypothermia throughout transport.","Apply damage control resuscitation to interrupt the cycle."],sections:[{id:"cycle",title:"A self-reinforcing cycle",core:!0,body:["Haemorrhage reduces oxygen delivery; cells switch to anaerobic metabolism and produce lactate, causing metabolic acidosis. Acidosis impairs the clotting enzymes \u2014 at a pH of 7.2 factor activity falls substantially \u2014 and reduces cardiac contractility and response to catecholamines. Poor perfusion and exposure cause hypothermia, which slows the enzymatic clotting cascade and platelet function further. Coagulopathy means more bleeding, which means more shock, more acidosis and more cooling.","Each corner is independently associated with death; together, mortality climbs steeply. Hypothermia below 32 \xB0C in trauma has historically been associated with very high mortality \u2014 far worse than the same temperature in accidental (non-trauma) hypothermia, because the cause is ongoing haemorrhage.",'Hypocalcaemia is increasingly described as a fourth corner (the "lethal diamond"). Ionised calcium is a cofactor for several clotting factors and for myocardial contraction; it falls with shock and with citrate in transfused blood. Low ionised calcium on arrival predicts mortality and transfusion need.']},{id:"warm",title:"Hypothermia prevention",core:!0,body:["Heat loss begins at the scene: cold ground, wet clothes, wind and exposure for assessment. Remove wet clothing, cover the patient, including the head, with insulating and reflective layers, use active warming blankets or chemical heat packs (not directly on skin), keep the cabin warm and warm every infused fluid and blood product.","Measure core temperature early and repeatedly \u2014 oesophageal, bladder or a reliable tympanic probe. A patient who arrives warmer than they left is a sign of good care. Avoid passive cooling during long ground waits for the aircraft. Rotor wash during loading strips heat rapidly; package the patient before walking to the aircraft.","Mild induced or permissive hypothermia has no role in bleeding trauma patients; the exception is selected post-cardiac-arrest care, which is not haemorrhagic."]},{id:"break",title:"Breaking the cycle",core:!0,body:["Stop the bleeding: tourniquets, packing, pelvic binders, and rapid transport to surgical or interventional control. Every intervention that does not stop bleeding buys time at best.","Restore perfusion and clotting with blood, not saline: balanced red cells, plasma and platelets (or whole blood), TXA within 3 hours, fibrinogen replacement guided by levels or viscoelastic tests, and calcium. Sodium bicarbonate does not fix the cause of acidosis and is not routine; the acidosis corrects as perfusion returns.","Accept permissive hypotension in penetrating torso trauma without head injury, avoid large crystalloid volumes that dilute clotting factors and cool the patient, and keep the patient warm. Vasopressors are not first-line in haemorrhagic shock; in some systems, small doses support pressure once volume is replaced or in combined TBI."],table:{caption:"The triad (and diamond) at a glance",head:["Corner","Threshold","Effect","Fix"],rows:[["Hypothermia","< 35 \xB0C","Slows clotting enzymes and platelets","Insulate, active warming, warm products"],["Acidosis","pH < 7.2, BD worse than \u22126","Impairs clotting factors and contractility","Restore perfusion with blood"],["Coagulopathy","INR > 1.5, fibrinogen < 1.5\u20132","More bleeding","1:1:1 / whole blood, fibrinogen, TXA"],["Hypocalcaemia","iCa < 1.1 mmol/L","Coagulopathy and poor contractility","Calcium chloride or gluconate"]]}},{id:"case",title:"Transport case: the long extrication",body:["A farmer is trapped under a tractor for 90 minutes in rain at 8 \xB0C. On release: BP 80/50, HR 128, temperature 34.0 \xB0C, open femur fracture with ongoing bleeding. Two litres of saline were given by ground crews."],example:{case:"Interrupt the triad.",steps:["Tourniquet proximal to the open femur wound; traction splint once bleeding is controlled.","Stop crystalloid; give warmed blood products (or whole blood), TXA and calcium.","Remove wet clothing, insulate, active warming; warm the cabin.","Anticipate coagulopathy from dilution and cold; communicate the MTP need to the receiving centre early.","Consider crush physiology (hyperkalaemia) after prolonged entrapment."]}}],keyPoints:["Hypothermia, acidosis and coagulopathy each worsen the others.","Hypocalcaemia is the fourth corner \u2014 give calcium.","Trauma hypothermia is far deadlier than accidental hypothermia at the same temperature.","Warm every patient and every product from the scene onward.","Break the cycle with haemorrhage control and blood, not saline or bicarbonate."],pearls:["Package before walking through rotor wash.","Acidosis corrects with perfusion."],pitfalls:["Litres of cold crystalloid.","Not measuring temperature until arrival."],live:[{id:"lines-haemorrhage-transfusion",label:"Haemorrhage and transfusion"},{id:"labs-coag",label:"Clotting labs and reversal"}],questions:[{q:"The classic lethal triad:",options:["Hypoxia, hypotension, hypercapnia","Hypothermia, acidosis, coagulopathy","Fever, tachycardia, leucocytosis","Hypoglycaemia, hyponatraemia, hyperkalaemia"],answer:1,why:"Self-reinforcing cycle."},{q:"The proposed fourth corner:",options:["Hypercalcaemia","Hypocalcaemia","Hypernatraemia","Hyperglycaemia"],answer:1,why:"Lethal diamond."},{q:"Acidosis worsens bleeding by:",options:["Increasing platelets","Impairing clotting enzyme function","Increasing fibrinogen","Causing vasoconstriction"],answer:1,why:"Enzyme activity is pH dependent."},{q:"Hypothermia impairs coagulation because:",options:["Clotting is enzymatic and slows with cold","Platelets multiply","Fibrinogen rises","It has no effect"],answer:0,why:"Enzyme kinetics."},{q:"Sodium bicarbonate for trauma acidosis:",options:["First-line","Not routine; restore perfusion","Mandatory below pH 7.3","Replaces blood"],answer:1,why:"Treat the cause."},{q:"Large crystalloid volumes in haemorrhage:",options:["Prevent coagulopathy","Dilute clotting factors and cool the patient","Correct acidosis","Are recommended"],answer:1,why:"Worsen the triad."},{q:"Ionised calcium target:",options:["> 0.5","> 1.1 mmol/L","> 3.0","Not needed"],answer:1,why:"Supports clotting and contractility."},{q:"Trauma hypothermia compared with accidental hypothermia at the same temperature:",options:["Less deadly","Much more deadly","Identical","Protective"],answer:1,why:"Driven by haemorrhage."},{q:"Heat packs should be placed:",options:["Directly on skin","Not directly on skin","Only on feet","Never used"],answer:1,why:"Risk of burns."},{q:"Therapeutic hypothermia in bleeding trauma:",options:["Recommended","No role","Standard for all","Only in children"],answer:1,why:"Worsens coagulopathy."},{q:"Vasopressors in haemorrhagic shock are:",options:["First-line","Not first-line; blood and haemorrhage control first","Contraindicated always","Replace transfusion"],answer:1,why:"Volume first."},{q:"A temperature threshold for hypothermia worsening coagulopathy:",options:["< 37.5 \xB0C","< 35 \xB0C","< 25 \xB0C","< 39 \xB0C"],answer:1,why:"Common threshold."},{q:"Damage control surgery exists because:",options:["Surgeons prefer short cases","Long operations allow the triad to kill","It is cheaper","Imaging is unavailable"],answer:1,why:"Correct physiology first."},{q:"Rotor wash during loading:",options:["Warms the patient","Strips heat rapidly","Has no effect","Reduces bleeding"],answer:1,why:"Package first."},{q:"pH at which clotting factor activity falls substantially:",options:["7.45","7.2","7.6","7.35"],answer:1,why:"Acidosis threshold."}],sources:[{title:"StatPearls: Trauma lethal triad",url:"https://www.ncbi.nlm.nih.gov/books/?term=Trauma+lethal+triad+StatPearls"},{title:"Ditzel RM et al. A review of transfusion- and trauma-induced hypocalcemia. J Trauma Acute Care Surg (2020)",url:"https://pubmed.ncbi.nlm.nih.gov/?term=Ditzel+transfusion+trauma-induced+hypocalcemia+2020"}]},Be={id:"fpc-burn-fluids",domain:"trauma",ref:"VII.8",title:"Burn fluid resuscitation",summary:"Estimating total body surface area, the Parkland and modified Brooke formulas, titrating to urine output, fluid creep, and transport timing in the burned patient.",objectives:["Estimate %TBSA using the rule of nines, Lund\u2013Browder and the palm method.","Calculate burn fluid requirements and the first-8-hour rate.","Titrate fluids to urine output and avoid over-resuscitation."],sections:[{id:"tbsa",title:"Estimating burn size",core:!0,body:["Only partial-thickness (second-degree) and full-thickness (third-degree) burns count toward total body surface area (TBSA); superficial (first-degree) erythema does not. The adult rule of nines assigns 9 % to the head, 9 % to each arm, 18 % to the front of the trunk, 18 % to the back, 18 % to each leg and 1 % to the perineum.","Children have proportionally larger heads and smaller legs: in infants the head is about 18 % and each leg about 14 %. The Lund\u2013Browder chart adjusts for age and is the most accurate method. For scattered burns, the patient's palm including the fingers is about 1 % TBSA.","Referring hospitals frequently overestimate TBSA \u2014 often by including superficial erythema \u2014 which leads to over-resuscitation. Recalculate yourself before setting the fluid rate."],table:{caption:"Rule of nines",head:["Region","Adult","Infant"],rows:[["Head and neck","9 %","18 %"],["Each arm","9 %","9 %"],["Anterior trunk","18 %","18 %"],["Posterior trunk","18 %","18 %"],["Each leg","18 %","14 %"],["Perineum","1 %","\u2014"]]}},{id:"formulas",title:"Fluid formulas",core:!0,body:["Burns of about 20 % TBSA or more in adults (10\u201315 % in children) cause a systemic capillary leak and need formal resuscitation. The Parkland formula estimates 4 mL \xD7 weight (kg) \xD7 %TBSA of lactated Ringer's over the first 24 hours from the time of injury, half in the first 8 hours and half in the next 16. Current ABA guidance starts lower \u2014 2 mL/kg/%TBSA in adults (the modified Brooke), 3 mL in children and 4 mL for electrical injuries \u2014 and titrates.","The clock starts at the time of the burn, not at arrival. If fluid was delayed, the first-half volume is given over the remaining hours of the first 8. Children under about 30 kg also need maintenance fluid containing dextrose, as their glycogen stores are small.","A worked example: an 80 kg adult with 40 % TBSA burns at 2 mL/kg/%. Total = 2 \xD7 80 \xD7 40 = 6400 mL in 24 hours. Half (3200 mL) in the first 8 hours = 400 mL/hour. If 2 hours have passed with only 500 mL given, the remaining 2700 mL goes over 6 hours = 450 mL/hour, then adjust to urine output."],example:{case:"A 70 kg adult, 50 % TBSA flame burns, injured 1 hour ago, no fluid yet. Using the Parkland 4 mL formula, what is the first-8-hour rate?",steps:["Total = 4 \xD7 70 \xD7 50 = 14 000 mL.","First half = 7000 mL, due by hour 8 from injury.","7 hours remain, so 7000 \xF7 7 = 1000 mL/hour.","Then titrate to urine output \u2014 formulas are a starting point, not a prescription."]}},{id:"titrate",title:"Titrating and avoiding fluid creep",core:!0,body:["Urine output is the main endpoint: 0.5 mL/kg/hour in adults (about 30\u201350 mL/hour), 1 mL/kg/hour in children under 30 kg, and 1\u20131.5 mL/kg/hour (or until the urine clears) in electrical injury with myoglobinuria. Place a urinary catheter for any major burn. Adjust the rate by about 20\u201330 % each hour toward the target rather than giving boluses.",'"Fluid creep" \u2014 receiving far more than the formula predicts \u2014 is common and harmful: abdominal compartment syndrome, extremity compartment syndromes, worsened airway oedema, pulmonary oedema and conversion of burn depth. Albumin (colloid rescue) after 8\u201312 hours and careful titration reduce volume in patients trending toward over-resuscitation.',"Transport considerations: secure two large-bore IVs (through burned skin if necessary, or IO), start the pump at the calculated rate, cover burns with clean dry dressings (not wet \u2014 hypothermia), keep the cabin warm and record the time of injury and total volumes given."]}],keyPoints:["Count only partial- and full-thickness burns in TBSA.","Adult rule of nines; infant head 18 %, leg 14 %; palm \u2248 1 %.","Start at 2 mL/kg/%TBSA (adults), 3 mL (children), 4 mL (electrical); half in the first 8 h from injury.","Titrate to urine output 0.5 mL/kg/h adults, 1 mL/kg/h children.","Avoid fluid creep; children need maintenance dextrose."],pearls:["The clock starts at the time of the burn.","Recalculate the referring hospital's TBSA."],pitfalls:["Counting superficial erythema.","Boluses instead of hourly rate changes."],questions:[{q:"Which burns count toward TBSA for fluid calculation?",options:["Superficial only","Partial- and full-thickness","All erythema","Full-thickness only"],answer:1,why:"Superficial burns are excluded."},{q:"Adult rule of nines: one entire leg is:",options:["9 %","18 %","14 %","27 %"],answer:1,why:"Front and back of leg."},{q:"Infant head percentage:",options:["9 %","18 %","4.5 %","27 %"],answer:1,why:"Proportionally larger head."},{q:"The palm including fingers approximates:",options:["5 %","1 %","10 %","0.1 %"],answer:1,why:"Scattered burns."},{q:"Parkland formula:",options:["2 mL \xD7 kg \xD7 %TBSA over 8 h","4 mL \xD7 kg \xD7 %TBSA over 24 h, half in the first 8 h","10 mL/kg bolus","1 mL \xD7 kg \xD7 %TBSA"],answer:1,why:"Classic formula."},{q:"The first 8 hours are counted from:",options:["Hospital arrival","Time of injury","Start of IV","Intubation"],answer:1,why:"Leak begins at injury."},{q:"An 80 kg adult, 30 % TBSA, 2 mL formula. 24-hour total?",options:["2400 mL","4800 mL","9600 mL","1200 mL"],answer:1,why:"2 \xD7 80 \xD7 30 = 4800 mL."},{q:"Urine output target in adult burns:",options:["0.1 mL/kg/h","0.5 mL/kg/h","3 mL/kg/h","5 mL/kg/h"],answer:1,why:"About 30\u201350 mL/h."},{q:"Urine output target in children < 30 kg:",options:["0.5 mL/kg/h","1 mL/kg/h","2.5 mL/kg/h","0.2 mL/kg/h"],answer:1,why:"Higher target for children."},{q:"Electrical burns with myoglobinuria start at:",options:["2 mL/kg/%TBSA","4 mL/kg/%TBSA, urine 1\u20131.5 mL/kg/h","1 mL/kg/%TBSA","No fluid"],answer:1,why:"Protect kidneys."},{q:"Fluid creep can cause:",options:["Abdominal compartment syndrome","Improved outcomes","Hypernatraemia only","Bradycardia"],answer:0,why:"Over-resuscitation harms."},{q:"Small children on burn resuscitation also need:",options:["Maintenance fluid with dextrose","Hypertonic saline","No extra fluid","Bicarbonate"],answer:0,why:"Limited glycogen stores."},{q:"Rate adjustments are typically:",options:["Large boluses","Hourly changes of about 20\u201330 % toward target","Fixed for 24 h","Stopped at 8 h"],answer:1,why:"Titrate toward the urine output target."},{q:"Burns in transport are best covered with:",options:["Wet saline dressings","Clean dry dressings","Ice","Ointment only"],answer:1,why:"Avoid hypothermia."},{q:"Preferred resuscitation fluid for burns:",options:["D5W","Lactated Ringer's","Hypertonic saline","0.45 % saline"],answer:1,why:"Balanced crystalloid."}],sources:[{title:"American Burn Association: Guidelines for burn patient referral and Advanced Burn Life Support",url:"https://ameriburn.org/resources/burnreferral/"},{title:"StatPearls: Burn resuscitation and early management",url:"https://www.ncbi.nlm.nih.gov/books/?term=Burn+resuscitation+and+early+management+StatPearls"}]};var Me={id:"fpc-burns",domain:"trauma",ref:"VII.9",title:"Burns: thermal, electrical, chemical and radiological",summary:"Burn depth, referral criteria, the burn primary survey, and the specific dangers of electrical, chemical and radiation injuries.",objectives:["Classify burn depth and apply burn centre referral criteria.","Manage the airway, breathing and circulation of a major burn.","Recognise the distinctive hazards of electrical, chemical and radiological burns."],sections:[{id:"depth",title:"Depth and referral",core:!0,body:["Superficial (first-degree) burns involve the epidermis only: red, painful, no blisters. Superficial partial-thickness burns are blistered, moist, pink and very painful, and blanch. Deep partial-thickness burns are paler, less painful, and blanch slowly or not at all. Full-thickness (third-degree) burns are white, leathery or charred, insensate and dry; they do not heal without grafting. Fourth-degree burns extend to muscle, tendon or bone.","Burn centre referral criteria (ABA) include partial-thickness burns over 10 % TBSA, any full-thickness burn, burns to the face, hands, feet, genitalia, perineum or major joints, electrical (including lightning) and chemical burns, inhalation injury, burns with concomitant trauma (where the burn poses the greater risk), patients with significant pre-existing illness, and children in hospitals without paediatric capability.","If trauma injuries pose the greater immediate risk, the patient may need a trauma centre first. Burns do not cause early hypotension \u2014 shock in the first hour suggests another injury (bleeding) or cyanide or carbon monoxide poisoning."]},{id:"survey",title:"The burn primary survey",core:!0,body:["Stop the burning: remove clothing and jewellery, cool the burn with cool running water for up to 20 minutes if within 3 hours (avoiding ice and avoiding hypothermia in large burns), then cover with clean dry dressings.","Airway: look for inhalation injury (see the toxic inhalation lesson); the airway can swell over hours, and a long flight is a reason to secure it early if signs are present. Use an uncut, large tube (ideally 7.5\u20138.0 or larger) to allow bronchoscopy, and secure it without circumferential ties that compress swelling tissue. Breathing: circumferential chest burns may need escharotomy. Circulation: two large-bore lines, fluids per formula, urinary catheter. Disability and exposure: assess, then keep the patient warm \u2014 burned skin cannot regulate heat.","Analgesia is essential and often needs large opioid doses or ketamine. Succinylcholine is safe in the first 24 hours; after that, use rocuronium because of hyperkalaemia risk. Tetanus prophylaxis is given; prophylactic systemic antibiotics are not."]},{id:"electrical",title:"Electrical, chemical and radiation burns",core:!0,body:["Electrical injuries: visible skin wounds (entry and exit) underestimate the damage \u2014 current travels through deep tissues, causing muscle necrosis, compartment syndrome and rhabdomyolysis. High-voltage (over 1000 V) injuries cause arrhythmias, cardiac arrest, spinal injuries from falls or tetanic contraction, and myoglobinuria. Monitor the ECG; give fluids to a urine output of 1\u20131.5 mL/kg/hour if the urine is dark. Lightning causes asystole and respiratory arrest; reverse triage applies at multi-casualty lightning strikes \u2014 treat the apparently dead first, as they often respond to ventilation.","Chemical burns: protect yourself first. Brush off dry powders, then irrigate with copious water for a long time (alkalis penetrate more deeply than acids and need prolonged irrigation). Hydrofluoric acid causes severe pain, deep tissue injury and potentially fatal hypocalcaemia and hypomagnesaemia \u2014 treat with calcium gluconate gel topically and calcium IV, and monitor the ECG. Phenol is removed with polyethylene glycol where available. Do not neutralise chemicals with other chemicals on the skin.","Radiological injuries: decontaminate by removing clothing (which removes most external contamination) and washing. Life-threatening injuries take priority over decontamination. Acute radiation syndrome produces nausea and vomiting within hours, and the time to onset of vomiting estimates the dose. Contact the receiving facility early so it can prepare."],table:{caption:"Burn depth",head:["Depth","Appearance","Sensation","Heals"],rows:[["Superficial","Red, dry, no blisters","Painful","Days"],["Superficial partial","Blisters, moist, pink, blanches","Very painful","2\u20133 weeks"],["Deep partial","Pale, mottled, slow/no blanch","Reduced","Weeks; may need graft"],["Full thickness","White, leathery, charred","Insensate","Needs graft"]]}}],keyPoints:["Full-thickness burns are leathery and insensate; superficial burns are not counted in TBSA.","Early hypotension in burns suggests other injury, CO or cyanide.","Secure the airway early when inhalation signs are present before a long transport.","Electrical burns hide deep muscle damage \u2014 monitor ECG and urine.","Hydrofluoric acid: calcium gluconate gel and IV calcium."],pearls:["Reverse triage at lightning strikes.","Clothing removal removes most radiological contamination."],pitfalls:["Wet dressings and hypothermia.","Judging electrical injury by the skin wounds."],live:[{id:"moa-calcium",label:"Calcium: mechanism"},{id:"moa-fentanyl",label:"Fentanyl: mechanism"}],questions:[{q:"A white, leathery, insensate burn is:",options:["Superficial","Superficial partial","Full-thickness","First-degree"],answer:2,why:"Nerve endings destroyed."},{q:"A burn centre referral criterion:",options:["5 % superficial burn","Burns to hands, face, feet or genitalia","Sunburn","Any blister"],answer:1,why:"Functional areas."},{q:"Hypotension within the first hour of a burn suggests:",options:["Burn shock","Another cause \u2014 bleeding, CO, cyanide","Normal response","Dehydration"],answer:1,why:"Burn shock develops over hours."},{q:"Cooling a burn:",options:["Ice for 1 hour","Cool running water up to 20 minutes","Butter","Never"],answer:1,why:"Within 3 hours of injury."},{q:"Succinylcholine after 24 hours from a major burn:",options:["Safe","Avoid \u2014 hyperkalaemia risk","Preferred","Required"],answer:1,why:"Receptor up-regulation."},{q:"Electrical injury damage is:",options:["Accurately shown by skin wounds","Often far deeper than skin wounds suggest","Superficial only","Never cardiac"],answer:1,why:"Current travels through tissue."},{q:"Urine output target with myoglobinuria:",options:["0.3 mL/kg/h","1\u20131.5 mL/kg/h","0.5 mL/kg/h","5 mL/kg/h"],answer:1,why:"Prevents AKI."},{q:"Reverse triage at a lightning strike means:",options:["Treat the walking first","Treat the apparently dead first","Ignore arrested patients","Treat children last"],answer:1,why:"Respiratory arrest responds to ventilation."},{q:"Alkali burns compared with acid burns:",options:["Less severe","Penetrate more deeply; need prolonged irrigation","Need neutralisation","Need no irrigation"],answer:1,why:"Liquefactive necrosis."},{q:"Hydrofluoric acid burns cause:",options:["Hypercalcaemia","Severe hypocalcaemia","Hyperglycaemia","Hypernatraemia"],answer:1,why:"Fluoride binds calcium."},{q:"First step for a dry chemical powder:",options:["Water immediately","Brush off, then irrigate","Neutralise","Cover"],answer:1,why:"Some powders react with water."},{q:"Removing clothing in radiological contamination:",options:["Has no effect","Removes most external contamination","Is contraindicated","Spreads radiation"],answer:1,why:"Simple decontamination."},{q:"Endotracheal tube choice in major burns:",options:["Small and cut short","Large and uncut","Supraglottic only","Nasal always"],answer:1,why:"Allows bronchoscopy and swelling."},{q:"Prophylactic systemic antibiotics in acute burns:",options:["Routine","Not recommended","Required for all","Only IV"],answer:1,why:"No benefit; resistance."},{q:"A deep partial-thickness burn:",options:["Blanches briskly","Is pale, with reduced sensation","Has no blisters ever","Heals in days"],answer:1,why:"Deeper dermis involved."}],sources:[{title:"American Burn Association: Burn centre referral criteria",url:"https://ameriburn.org/resources/burnreferral/"},{title:"StatPearls: Electrical injuries",url:"https://www.ncbi.nlm.nih.gov/books/?term=Electrical+injuries+StatPearls"},{title:"StatPearls: Chemical burns",url:"https://www.ncbi.nlm.nih.gov/books/?term=Chemical+burns+StatPearls"}]},Ne={id:"fpc-toxic-inhalation",domain:"trauma",ref:"VII.10",title:"Toxic inhalation: airway burns, carbon monoxide and cyanide",summary:"Thermal airway injury, smoke inhalation, carbon monoxide and cyanide poisoning, and the decision to intubate before a long flight.",objectives:["Identify signs of inhalation injury and decide when to intubate.","Diagnose and treat carbon monoxide poisoning, including the limits of pulse oximetry.","Recognise and treat cyanide toxicity in smoke inhalation."],sections:[{id:"airway",title:"Inhalation injury and the airway",core:!0,body:["Heat injury is mostly confined to the upper airway, because the upper airway is an efficient heat exchanger; steam is the exception and can burn below the cords. Below the glottis, damage comes from chemicals in smoke \u2014 aldehydes, acrolein, ammonia and particulates \u2014 causing bronchospasm, mucosal sloughing, casts and pneumonia over hours to days.","Signs include a history of an enclosed-space fire, facial and neck burns, singed nasal hair, carbonaceous sputum, soot in the mouth, hoarseness, stridor, wheeze and respiratory distress. Hoarseness and stridor indicate airway narrowing \u2014 swelling continues for 24\u201348 hours and fluid resuscitation accelerates it.","Intubate early for stridor, hoarseness with deep facial burns, full-thickness burns of the face or neck, extensive burns (often > 40 % TBSA), altered consciousness or respiratory failure. Prophylactic intubation of every patient with soot or singed hair is not required \u2014 many have no significant injury \u2014 but a long flight with no ability to intervene safely shifts the threshold earlier. A difficult airway plan (including surgical) is essential; swelling makes later attempts much harder."]},{id:"co",title:"Carbon monoxide",core:!0,body:["Carbon monoxide binds haemoglobin with about 200\u2013250 times the affinity of oxygen, reducing oxygen-carrying capacity and shifting the oxygen\u2013haemoglobin dissociation curve to the left so that tissues receive even less. It also binds cytochrome oxidase and myoglobin, impairing cellular respiration and the heart.","Standard pulse oximetry cannot distinguish carboxyhaemoglobin from oxyhaemoglobin and reads falsely normal. Measure COHb by co-oximetry (blood gas) or a multi-wavelength pulse CO-oximeter. Symptoms \u2014 headache, nausea, confusion, syncope, seizures, coma, ischaemic chest pain \u2014 correlate imperfectly with levels; smokers carry up to about 10 % at baseline.","Treat with 100 % oxygen by non-rebreather or ventilator: the half-life of COHb falls from about 4\u20136 hours on room air to 60\u201390 minutes on 100 % oxygen, and about 20\u201330 minutes with hyperbaric oxygen. Hyperbaric therapy is considered for loss of consciousness, neurological deficits, cardiac ischaemia, pregnancy with elevated COHb, or very high levels, but the transport risk must be weighed against the benefit, particularly with other injuries."]},{id:"cn",title:"Cyanide",core:!0,body:["Burning plastics, wool, silk and synthetic materials release hydrogen cyanide. Cyanide blocks cytochrome c oxidase, halting aerobic metabolism: cells cannot use oxygen even when it is delivered. The result is severe lactic acidosis, altered consciousness, seizures, hypotension, bradycardia and arrest. Venous blood may look bright red because tissues have stopped extracting oxygen.","Suspect cyanide in a smoke-inhalation patient with altered consciousness, hypotension, or a lactate above about 8\u201310 mmol/L. Waiting for a cyanide level is not an option. Hydroxocobalamin 5 g IV over 15 minutes (70 mg/kg in children), repeated once if needed, binds cyanide to form cyanocobalamin, which the kidneys excrete. It turns skin and urine red and interferes with colorimetric lab tests and some co-oximetry readings, so draw bloods first if you can.","Avoid the older nitrite-based kits in smoke inhalation: nitrites create methaemoglobin, which further reduces oxygen-carrying capacity in a patient already poisoned by carbon monoxide. Sodium thiosulfate is a slower adjunct."],table:{caption:"Carbon monoxide vs cyanide",head:["","Carbon monoxide","Cyanide"],rows:[["Source","Incomplete combustion","Burning plastics, synthetics"],["Mechanism","Binds Hb (and cytochrome oxidase)","Blocks cytochrome oxidase"],["SpO\u2082","Falsely normal","Usually normal"],["Key lab","COHb by co-oximetry","Lactate > 8\u201310"],["Treatment","100 % O\u2082 (\xB1 hyperbaric)","Hydroxocobalamin 5 g IV"]]}},{id:"case",title:"Transport case: the house fire",body:["A 45-year-old pulled from a burning apartment: GCS 10, hoarse voice, soot in the mouth, singed eyebrows, 25 % TBSA burns. BP 86/52, SpO\u2082 99 % on a non-rebreather, lactate 11, COHb 28 %. The flight to the burn centre is 70 minutes."],example:{case:"Plan.",steps:["Airway: hoarseness, soot, altered consciousness and a long flight \u2014 intubate before departure with a large uncut tube; prepare a surgical airway backup.","CO: SpO\u2082 99 % is false; continue 100 % FiO\u2082 on the ventilator.","Cyanide: hypotension and lactate 11 \u2014 hydroxocobalamin 5 g IV now (draw bloods first).","Fluids per formula from time of injury; keep warm; urinary catheter.","Hyperbaric therapy is considered at the receiving centre if available and appropriate."]}}],keyPoints:["Heat burns the upper airway; smoke chemicals injure the lower airway.","Hoarseness and stridor mean narrowing \u2014 intubate early before long flights.","Standard SpO\u2082 reads falsely normal in CO poisoning \u2014 use co-oximetry.","100 % O\u2082 shortens COHb half-life to 60\u201390 min.","Smoke inhalation with high lactate or hypotension: hydroxocobalamin; avoid nitrites."],pearls:["Use a large, uncut tube.","Draw bloods before hydroxocobalamin."],pitfalls:["Reassurance from SpO\u2082 of 99 %.","Waiting for a cyanide level."],live:[{id:"o2path",label:"The oxygen pathway"}],questions:[{q:"Thermal injury is usually confined to the upper airway because:",options:["The lower airway is armoured","The upper airway dissipates heat effectively","Patients hold their breath","Smoke is cool"],answer:1,why:"Steam is the exception."},{q:"An indication for early intubation in inhalation injury:",options:["Singed nasal hair alone","Stridor or hoarseness with deep facial burns","Any soot on the face","Cough"],answer:1,why:"Signs of airway narrowing."},{q:"Standard pulse oximetry in CO poisoning:",options:["Reads low","Reads falsely normal","Is accurate","Fails to read"],answer:1,why:"Cannot distinguish COHb."},{q:"CO affinity for haemoglobin compared with oxygen:",options:["Equal","About 200\u2013250 times greater","2 times","Lower"],answer:1,why:"Displaces oxygen."},{q:"COHb half-life on 100 % oxygen:",options:["4\u20136 hours","60\u201390 minutes","5 minutes","24 hours"],answer:1,why:"Faster elimination."},{q:"CO shifts the oxygen\u2013haemoglobin curve:",options:["Right","Left","No change","Down only"],answer:1,why:"Reduces tissue unloading."},{q:"Cyanide causes toxicity by:",options:["Binding haemoglobin","Blocking cytochrome c oxidase","Causing bronchospasm","Inhibiting acetylcholinesterase"],answer:1,why:"Cells cannot use oxygen."},{q:"A lab finding suggesting cyanide toxicity in smoke inhalation:",options:["Lactate > 8\u201310 mmol/L","Low glucose","High calcium","Normal lactate"],answer:0,why:"Anaerobic metabolism."},{q:"Adult hydroxocobalamin dose:",options:["500 mg","5 g IV over 15 min","50 g","5 mg"],answer:1,why:"May repeat once."},{q:"Nitrite-based cyanide kits are avoided in smoke inhalation because:",options:["They are expensive","They create methaemoglobin, worsening oxygen carriage with CO","They are slow","They cause hypertension"],answer:1,why:"Compounding hypoxia."},{q:"Hydroxocobalamin side effect:",options:["Blue skin","Red skin and urine; lab interference","Hypoglycaemia","Seizures"],answer:1,why:"Colour interference."},{q:"Baseline COHb in smokers can reach about:",options:["0 %","10 %","40 %","60 %"],answer:1,why:"Interpretation context."},{q:"Lower airway injury in smoke inhalation is mainly caused by:",options:["Heat","Chemical irritants","Infection on day 1","Cold"],answer:1,why:"Aldehydes, acrolein, particulates."},{q:"Airway swelling after burns peaks around:",options:["Minutes","24\u201348 hours","2 weeks","Never"],answer:1,why:"Fluid resuscitation worsens oedema."},{q:"A hyperbaric oxygen consideration in CO poisoning:",options:["Mild headache only","Loss of consciousness, neurological deficits, pregnancy","Any smoker","COHb 3 %"],answer:1,why:"Weigh against transport risk."}],sources:[{title:"StatPearls: Carbon monoxide toxicity",url:"https://www.ncbi.nlm.nih.gov/books/?term=Carbon+monoxide+toxicity+StatPearls"},{title:"StatPearls: Cyanide toxicity",url:"https://www.ncbi.nlm.nih.gov/books/?term=Cyanide+toxicity+StatPearls"},{title:"StatPearls: Inhalation injury",url:"https://www.ncbi.nlm.nih.gov/books/?term=Inhalation+injury+StatPearls"}]};var y=(a,i,n,r)=>({id:a,title:i,body:n,example:r}),De={"fpc-trauma-dx":{questions:[],sections:[y("special","Populations the primary survey misreads",["Older adults compensate poorly and hide shock. A systolic of 110 in a 75-year-old may be hypotension for that patient, beta-blockers blunt tachycardia, and anticoagulants turn minor falls into major bleeds. Many field triage guidelines treat a systolic below 110 in patients over 65 as a physiological trigger, and ground-level falls in anticoagulated elders as a reason for trauma-centre evaluation.","Children maintain blood pressure until they have lost a large share of their circulating volume, then decompensate abruptly; tachycardia, delayed capillary refill and altered mentation are the earlier signs. Pregnant patients have a physiological rise in heart rate and fall in blood pressure, an expanded blood volume that masks loss, and a uterus that compresses the vena cava when supine after about 20 weeks \u2014 tilt or manually displace the uterus to the left. The fetus is often the first to show maternal shock.",'Penetrating injuries hide their trajectory. A small wound in the chest below the nipple line may involve the abdomen; a wound in the "box" (between the nipples, clavicles and costal margins) threatens the heart. Log-roll and examine the back, axillae, perineum and scalp \u2014 injuries missed in the primary survey are found there.'],{case:"A 79-year-old on a beta-blocker and warfarin, struck as a pedestrian: HR 76, BP 112/70, GCS 15, left chest wall pain.",steps:['A "normal" heart rate and pressure may be shock in this patient; shock index alone is unreliable with beta-blockade.',"eFAST, lactate and INR if available; anticipate rib fractures with pulmonary contusion and delayed deterioration.","Trauma-centre destination; consider reversal for active bleeding; analgesia to allow effective breathing."]})]},"fpc-trauma-labs":{questions:[],sections:[y("poc","Point-of-care testing in the aircraft",["Handheld analysers give blood gases, lactate, electrolytes, ionised calcium and haemoglobin in minutes and are carried by many air services. Use them to answer specific questions: is the base deficit worsening (ongoing bleeding), is the ionised calcium falling (more calcium), is the potassium rising (crush, massive transfusion), and is the glucose dangerous in a head injury?","Point-of-care INR devices are designed for warfarin monitoring and are unreliable in trauma-induced coagulopathy; a normal result does not exclude coagulopathy. Analysers have operating temperature and altitude limits and need quality control; low cabin temperatures and pressure changes can produce errors. Document the time of every sample relative to products given \u2014 a haemoglobin after three units of blood means something different from one before.","Trends beat single values. A lactate that falls from 7 to 4 over an hour of resuscitation is reassuring even though it is still raised; a lactate that climbs while the blood pressure looks stable means the patient is still bleeding."])]},"fpc-trauma-pharm":{questions:[],sections:[y("case","Transport case: the trapped motorcyclist",["A 30-year-old motorcyclist with an open tibial fracture and a deformed femur, trapped for 40 minutes. HR 118, BP 98/60, GCS 15, screaming in pain. Injury occurred 70 minutes ago.","This patient needs analgesia that does not drop the pressure, TXA inside the time window, antibiotics for the open fracture, and a plan for sedation if the airway must be secured."],{case:"Choose the drugs.",steps:["TXA 1 g IV over 10 minutes now (70 minutes after injury \u2014 within 3 hours), then infusion; document the times.","Analgesia: ketamine 0.1\u20130.3 mg/kg IV, or fentanyl in small titrated doses; avoid morphine boluses in a patient with borderline pressure.","Cefazolin IV for the open fracture as early as possible; tetanus status noted for the receiving team.","If intubation becomes necessary: blood first, reduced-dose ketamine, full-dose rocuronium."]})]},"fpc-trauma-monitor":{questions:[],sections:[y("case","Transport case: the quiet deterioration",["A 22-year-old with a stab wound to the left upper abdomen, intubated at the referring hospital. At departure: HR 104, BP 104/68 (arterial line), EtCO\u2082 36 mmHg, temperature 35.8 \xB0C. Thirty minutes later: HR 122, BP 96/70, EtCO\u2082 27 mmHg, same ventilator settings, temperature 35.1 \xB0C.","Every number has moved in the same direction: rising heart rate, narrowing pulse pressure (34 down to 26), a falling EtCO\u2082 with unchanged ventilation, and cooling. The systolic is still above 90, but the trends say he is bleeding."],{case:"Act on the trends.",steps:["Shock index has risen from 1.0 to 1.27; treat as ongoing haemorrhage.","Blood products warmed inline; TXA if not given and within 3 hours; calcium.","Active warming; check the abdomen and repeat eFAST if feasible.","Pre-alert the receiving centre for direct transfer to theatre."]})]},"fpc-trauma-surgical":{questions:[],sections:[y("aftercare","Caring for procedures in flight",["Every procedure creates something to monitor. After needle decompression, mark the time and site, and reassess breath sounds, airway pressures and blood pressure every few minutes; catheters kink when the patient is moved onto the stretcher. After finger thoracostomy, cover the wound with a loose dressing in ventilated patients and re-sweep with a sterile gloved finger if the patient deteriorates again.","Chest drains: keep the collection system below the chest and upright, secure it to the stretcher, and never clamp it during transport. Heimlich (one-way flutter) valves are useful in aircraft because they do not depend on a water seal staying upright, but they can clog with blood in a haemothorax.","Escharotomy and fasciotomy wounds bleed; dress them and include them in your blood-loss estimate. After any procedure, check distal perfusion, document what was done and by whom, and hand over the exact device sizes and positions."])]},"fpc-trauma-blood":{questions:[],sections:[y("logistics","Carrying blood on an aircraft",["Blood products carried on aircraft live in validated coolers that hold red cells and plasma between 1 and 6 \xB0C for a defined time; temperature loggers prove the cold chain, and products outside range are returned and discarded rather than given. Units rotate back to the blood bank before expiry so that nothing is wasted \u2014 air services and hospital blood banks agree this in a written policy.","Before giving any unit, two crew members check the product, unit number, expiry date and group against the documentation. In the emergency release setting the patient's identity may be unknown; use the trauma alias and band the patient so that later samples can be matched. Draw a pre-transfusion sample (group and screen) before the first unit where possible, because transfused group O cells make later grouping harder.","Plasma must be thawed in advance (liquid or pre-thawed plasma lasts about 5 days refrigerated), and platelets need room-temperature storage with agitation, which is why few aircraft carry them. Freeze-dried plasma and fibrinogen concentrate are stable at room temperature and are used by some military and civilian services."]),y("case","Transport case: running a massive transfusion in the air",["A 41-year-old with a gunshot wound to the pelvis: HR 140, BP 72/40, positive FAST. The aircraft carries two units of low-titre O whole blood, two units of O-positive red cells and two units of thawed plasma.","ABC score: penetrating (1), SBP \u2264 90 (1), HR \u2265 120 (1), positive FAST (1) = 4. Massive transfusion is likely; activate the receiving centre's protocol from the air."],{case:"Sequence the products.",steps:["Whole blood first through a warmer by pressure infuser; then red cells and plasma together at 1:1.","Calcium after the first two units, then per protocol; TXA if within 3 hours.","Target a systolic around 80\u201390 (penetrating, no TBI) or a radial pulse and mentation \u2014 not a normal pressure.","Record unit numbers and times; request products to meet the aircraft; plan for direct transfer to theatre or interventional radiology."]})]},"fpc-lethal-triad":{questions:[],sections:[y("monitor","Measuring the triad in transport",["You cannot treat what you do not measure. Core temperature is best measured by an oesophageal probe in intubated patients or a bladder probe; tympanic infrared thermometers read low in cold, windy conditions, and skin temperature tells you little. Record temperature at departure, every 15 minutes in flight and at handover.","Acidosis is tracked with lactate and base deficit on a point-of-care analyser, and indirectly by EtCO\u2082 trends. Coagulopathy is harder to measure in the air; anticipate it from the mechanism, the volume of crystalloid already given, the temperature and the pH, and treat empirically with plasma and fibrinogen rather than waiting for laboratory confirmation.","Handover should state each corner explicitly: temperature, pH or base deficit, products and volumes given, calcium given, TXA time, and the last ionised calcium. Receiving teams often lose track of what was given before arrival."])]},"fpc-burn-fluids":{questions:[],sections:[y("case","Transport case: the referring hospital's estimate",["A 30 kg child scalded 3 hours ago. The referring hospital reports 35 % TBSA and has given 1.5 L of normal saline. On your examination, much of the area is superficial erythema; partial- and full-thickness burns cover the front of the trunk and the right arm (about 18 % + 9 % = 27 %).","Recalculating matters. At 3 mL/kg/%TBSA: 3 \xD7 30 \xD7 27 = 2430 mL over 24 hours, 1215 mL in the first 8 hours from injury. The child has already received 1500 mL \u2014 more than the first-half volume \u2014 so the rate should drop to maintenance plus titration to urine output, not continue at the referring rate."],{case:"What do you set up?",steps:["Switch to lactated Ringer's; add maintenance fluid with dextrose for a child of this size.","Urinary catheter; target 1 mL/kg/h (about 30 mL/h).","Adjust the rate hourly by 20\u201330 % toward the target; watch for fluid creep (abdominal distension, rising airway pressures).","Keep warm; analgesia; hand over the corrected TBSA and total volumes."]})]},"fpc-burns":{questions:[],sections:[y("case","Transport case: the high-voltage line worker",["A 35-year-old line worker contacted a 13 000 V line and fell 4 metres. Small charred wounds on the right hand and left foot; GCS 15; HR 110 with frequent ectopics; dark brown urine in the catheter bag. The right forearm is tense and painful on passive finger extension.","The skin wounds are small, but the current passed hand to foot through muscle and possibly the heart. The fall adds spinal and blunt injury risk."],{case:"Manage.",steps:["Continuous ECG; treat arrhythmias per ACLS; a 12-lead before departure.","Spinal motion restriction given the fall; full trauma survey.","Fluids for myoglobinuria at 4 mL/kg/%TBSA as a start, titrated to urine output of 1\u20131.5 mL/kg/h until the urine clears.","Suspected forearm compartment syndrome \u2014 notify the burn surgeon for fasciotomy; elevate to heart level, not above.","Check potassium; avoid succinylcholine if rhabdomyolysis or hyperkalaemia is suspected."]})]},"fpc-toxic-inhalation":{questions:[],sections:[y("vent","Ventilating the smoke-injured lung",["Inhalation injury produces bronchospasm, mucus plugging, casts of sloughed mucosa and, over hours, ARDS. Use lung-protective ventilation (tidal volumes around 6\u20138 mL/kg of predicted body weight, plateau pressure under 30 cmH\u2082O) with enough PEEP to keep alveoli open, and keep FiO\u2082 at 100 % until carbon monoxide has cleared.","Rising peak pressures with a normal plateau suggest airway resistance \u2014 bronchospasm, secretions or a cast in the tube: suction, give bronchodilators, and consider tube obstruction. Rising peak and plateau pressures suggest stiff lungs, pneumothorax or a tight circumferential chest burn that needs escharotomy.","Nebulised heparin and N-acetylcysteine are used in some burn centres to reduce cast formation, but evidence is mixed and they are a receiving-centre decision. In transport, the priorities are a secure large tube, suction, bronchodilators and careful pressure monitoring."])]}};var C=(a,i)=>i[a.id]?{...a,sections:[...a.sections,...i[a.id].sections],questions:[...a.questions,...i[a.id].questions]}:a,Fe=[O,E,B,M,N,D,F,j,W,G,z,U,K,_].map(a=>C(a,Q)).concat([...[X,Y,J,$,Z,ee,ae,ie,te,oe,ne,re,se,le,ce].map(a=>C(a,de)),...[he,pe,fe,me,ye,ge,be,we,ve,ke,Ae,Pe,ue,xe,Ce,Ie,Se].map(a=>C(a,Te)),...[Re,qe,Ve,Le,He,Oe,Ee,Be,Me,Ne].map(a=>C(a,De))]),je=Object.fromEntries(Fe.map(a=>[a.id,a])),I=a